values
('rom-3-10','rom','로마서',3,10,'기록된 바 의인은 없나니 하나도 없으며',28001),
('rom-3-11','rom','로마서',3,11,'깨닫는 자도 없고 하나님을 찾는 자도 없고',28002),
('rom-3-12','rom','로마서',3,12,'다 치우쳐 함께 무익하게 되고 선을 행하는 자는 없나니 하나도 없도다',28003),
('rom-3-13','rom','로마서',3,13,'그들의 목구멍은 열린 무덤이요 그 혀로는 속임을 일삼으며 그 입술에는 독사의 독이 있고',28004),
('rom-3-14','rom','로마서',3,14,'그 입에는 저주와 악독이 가득하고',28005),
('rom-3-15','rom','로마서',3,15,'그 발은 피 흘리는 데 빠른지라',28006),
('rom-3-16','rom','로마서',3,16,'파멸과 고생이 그 길에 있어',28007),
('rom-3-17','rom','로마서',3,17,'평강의 길을 알지 못하였고',28008),
('rom-3-18','rom','로마서',3,18,'그들의 눈 앞에 하나님을 두려워함이 없느니라 함과 같으니라',28009),
('rom-3-19','rom','로마서',3,19,'우리가 알거니와 무릇 율법이 말하는 바는 율법 아래에 있는 자들에게 말하는 것이니 이는 모든 입을 막고 온 세상으로 하나님의 심판 아래에 있게 하려 함이라',28010),
('rom-3-20','rom','로마서',3,20,'그러므로 율법의 행위로 그의 앞에 의롭다 하심을 얻을 육체가 없나니 율법으로는 죄를 깨달음이니라',28011),
('rom-3-21','rom','로마서',3,21,'이제는 율법 외에 하나님의 한 의가 나타났으니 율법과 선지자들에게 증거를 받은 것이라',28012),
('rom-3-22','rom','로마서',3,22,'곧 예수 그리스도를 믿음으로 말미암아 모든 믿는 자에게 미치는 하나님의 의니 차별이 없느니라',28013),
('rom-3-23','rom','로마서',3,23,'모든 사람이 죄를 범하였으매 하나님의 영광에 이르지 못하더니',28014),
('rom-3-24','rom','로마서',3,24,'그리스도 예수 안에 있는 속량으로 말미암아 하나님의 은혜로 값 없이 의롭다 하심을 얻은 자 되었느니라',28015),
('rom-3-25','rom','로마서',3,25,'이 예수를 하나님이 그의 피로써 믿음으로 말미암는 화목제물로 세우셨으니 이는 하나님께서 길이 참으시는 중에 전에 지은 죄를 간과하심으로 자기의 의로우심을 나타내려 하심이니',28016),
('rom-3-26','rom','로마서',3,26,'곧 이 때에 자기의 의로우심을 나타내사 자기도 의로우시며 또한 예수 믿는 자를 의롭다 하려 하심이라',28017),
('rom-3-27','rom','로마서',3,27,'그런즉 자랑할 데가 어디냐 있을 수가 없느니라 무슨 법으로냐 행위로냐 아니라 오직 믿음의 법으로니라',28018),
('rom-3-28','rom','로마서',3,28,'그러므로 사람이 의롭다 하심을 얻는 것은 율법의 행위에 있지 않고 믿음으로 되는 줄 우리가 인정하노라',28019),
('rom-3-29','rom','로마서',3,29,'하나님은 다만 유대인의 하나님이시냐 또한 이방인의 하나님은 아니시냐 진실로 이방인의 하나님도 되시느니라',28020),
('rom-3-30','rom','로마서',3,30,'할례자도 믿음으로 말미암아 또한 무할례자도 믿음으로 말미암아 의롭다 하실 하나님은 한 분이시니라',28021),
('rom-3-31','rom','로마서',3,31,'그런즉 우리가 믿음으로 말미암아 율법을 파기하느냐 그럴 수 없느니라 도리어 율법을 굳게 세우느니라',28022),
('rom-4-1','rom','로마서',4,1,'그런즉 육신으로 우리 조상인 아브라함이 무엇을 얻었다 하리요',28023),
('rom-4-2','rom','로마서',4,2,'만일 아브라함이 행위로써 의롭다 하심을 받았으면 자랑할 것이 있으려니와 하나님 앞에서는 없느니라',28024),
('rom-4-3','rom','로마서',4,3,'성경이 무엇을 말하느냐 아브라함이 하나님을 믿으매 그것이 그에게 의로 여겨진 바 되었느니라',28025),
('rom-4-4','rom','로마서',4,4,'일하는 자에게는 그 삯이 은혜로 여겨지지 아니하고 보수로 여겨지거니와',28026),
('rom-4-5','rom','로마서',4,5,'일을 아니할지라도 경건하지 아니한 자를 의롭다 하시는 이를 믿는 자에게는 그의 믿음을 의로 여기시나니',28027),
('rom-4-6','rom','로마서',4,6,'일한 것이 없이 하나님께 의로 여기심을 받는 사람의 복에 대하여 다윗이 말한 바',28028),
('rom-4-7','rom','로마서',4,7,'불법이 사함을 받고 죄가 가리어짐을 받는 사람들은 복이 있고',28029),
('rom-4-8','rom','로마서',4,8,'주께서 그 죄를 인정하지 아니하실 사람은 복이 있도다 함과 같으니라',28030),
('rom-4-9','rom','로마서',4,9,'그런즉 이 복이 할례자에게냐 혹은 무할례자에게도냐 무릇 우리가 말하기를 아브라함에게는 그 믿음이 의로 여겨졌다 하노라',28031),
('rom-4-10','rom','로마서',4,10,'그런즉 그것이 어떻게 여겨졌느냐 할례시냐 무할례시냐 할례시가 아니요 무할례시니라',28032),
('rom-4-11','rom','로마서',4,11,'그가 할례의 표를 받은 것은 무할례시에 믿음으로 된 의를 인친 것이니 이는 무할례자로서 믿는 모든 자의 조상이 되어 그들도 의로 여기심을 얻게 하려 하심이라',28033),
('rom-4-12','rom','로마서',4,12,'또한 할례자의 조상이 되었나니 곧 할례 받을 자에게뿐 아니라 우리 조상 아브라함이 무할례시에 가졌던 믿음의 자취를 따르는 자들에게도 그러하니라',28034),
('rom-4-13','rom','로마서',4,13,'아브라함이나 그 후손에게 세상의 상속자가 되리라고 하신 언약은 율법으로 말미암은 것이 아니요 오직 믿음의 의로 말미암은 것이니라',28035),
('rom-4-14','rom','로마서',4,14,'만일 율법에 속한 자들이 상속자이면 믿음은 헛것이 되고 약속은 파기되었느니라',28036),
('rom-4-15','rom','로마서',4,15,'율법은 진노를 이루게 하나니 율법이 없는 곳에는 범법도 없느니라',28037),
('rom-4-16','rom','로마서',4,16,'그러므로 상속자가 되는 그것이 은혜에 속하기 위하여 믿음으로 되나니 이는 그 약속을 그 모든 후손에게 굳게 하려 하심이라 율법에 속한 자에게뿐만 아니라 아브라함의 믿음에 속한 자에게도 그러하니 아브라함은 우리 모든 사람의 조상이라',28038),
('rom-4-17','rom','로마서',4,17,'기록된 바 내가 너를 많은 민족의 조상으로 세웠다 하심과 같으니 그가 믿은 바 하나님은 죽은 자를 살리시며 없는 것을 있는 것으로 부르시는 이시니라',28039),
('rom-4-18','rom','로마서',4,18,'아브라함이 바랄 수 없는 중에 바라고 믿었으니 이는 네 후손이 이같으리라 하신 말씀대로 많은 민족의 조상이 되게 하려 하심이라',28040),
('rom-4-19','rom','로마서',4,19,'그가 백 세나 되어 자기 몸이 죽은 것 같고 사라의 태가 죽은 것 같음을 알고도 믿음이 약하여지지 아니하고',28041),
('rom-4-20','rom','로마서',4,20,'믿음이 없어 하나님의 약속을 의심하지 않고 믿음으로 견고하여져서 하나님께 영광을 돌리며',28042),
('rom-4-21','rom','로마서',4,21,'약속하신 그것을 또한 능히 이루실 줄을 확신하였으니',28043),
('rom-4-22','rom','로마서',4,22,'그러므로 그것이 그에게 의로 여겨졌느니라',28044),
('rom-4-23','rom','로마서',4,23,'그에게 의로 여겨졌다 기록된 것은 아브라함만 위한 것이 아니요',28045),
('rom-4-24','rom','로마서',4,24,'의로 여기심을 받을 우리도 위함이니 곧 예수 우리 주를 죽은 자 가운데서 살리신 이를 믿는 자니라',28046),
('rom-4-25','rom','로마서',4,25,'예수는 우리가 범죄한 것 때문에 내줌이 되고 또한 우리를 의롭다 하시기 위하여 살아나셨느니라',28047),
('rom-5-1','rom','로마서',5,1,'그러므로 우리가 믿음으로 의롭다 하심을 받았으니 우리 주 예수 그리스도로 말미암아 하나님과 화평을 누리자',28048),
('rom-5-2','rom','로마서',5,2,'또한 그로 말미암아 우리가 믿음으로 서 있는 이 은혜에 들어감을 얻었으며 하나님의 영광을 바라고 즐거워하느니라',28049),
('rom-5-3','rom','로마서',5,3,'다만 이뿐 아니라 우리가 환난 중에도 즐거워하나니 이는 환난은 인내를,',28050),
('rom-5-4','rom','로마서',5,4,'인내는 연단을, 연단은 소망을 이루는 줄 앎이로다',28051),
('rom-5-5','rom','로마서',5,5,'소망이 우리를 부끄럽게 하지 아니함은 우리에게 주신 성령으로 말미암아 하나님의 사랑이 우리 마음에 부은 바 됨이니',28052),
('rom-5-6','rom','로마서',5,6,'우리가 아직 연약할 때에 기약대로 그리스도께서 경건하지 않은 자를 위하여 죽으셨도다',28053),
('rom-5-7','rom','로마서',5,7,'의인을 위하여 죽는 자가 쉽지 않고 선인을 위하여 용감히 죽는 자가 혹 있거니와',28054),
('rom-5-8','rom','로마서',5,8,'우리가 아직 죄인 되었을 때에 그리스도께서 우리를 위하여 죽으심으로 하나님께서 우리에 대한 자기의 사랑을 확증하셨느니라',28055),
('rom-5-9','rom','로마서',5,9,'그러면 이제 우리가 그의 피로 말미암아 의롭다 하심을 받았으니 더욱 그로 말미암아 진노하심에서 구원을 받을 것이니',28056),
('rom-5-10','rom','로마서',5,10,'곧 우리가 원수 되었을 때에 그의 아들의 죽으심으로 말미암아 하나님과 화목하게 되었은즉 화목하게 된 자로서는 더욱 그의 살아나심으로 말미암아 구원을 받을 것이니라',28057),
('rom-5-11','rom','로마서',5,11,'그뿐 아니라 이제 우리로 화목하게 하신 우리 주 예수 그리스도로 말미암아 하나님 안에서 또한 즐거워하느니라',28058),
('rom-5-12','rom','로마서',5,12,'그러므로 한 사람으로 말미암아 죄가 세상에 들어오고 죄로 말미암아 사망이 들어왔나니 이와 같이 모든 사람이 죄를 지었으므로 사망이 모든 사람에게 이르렀느니라',28059),
('rom-5-13','rom','로마서',5,13,'죄가 율법 있기 전에도 세상에 있었으나 율법이 없었을 때에는 죄를 죄로 여기지 아니하였느니라',28060),
('rom-5-14','rom','로마서',5,14,'그러나 아담으로부터 모세까지 아담의 범죄와 같은 죄를 짓지 아니한 자들까지도 사망이 왕 노릇 하였나니 아담은 오실 자의 모형이라',28061),
('rom-5-15','rom','로마서',5,15,'그러나 이 은사는 그 범죄와 같지 아니하니 곧 한 사람의 범죄를 인하여 많은 사람이 죽었은즉 더욱 하나님의 은혜와 또한 한 사람 예수 그리스도의 은혜로 말미암은 선물은 많은 사람에게 넘쳤느니라',28062),
('rom-5-16','rom','로마서',5,16,'또 이 선물은 범죄한 한 사람으로 말미암은 것과 같지 아니하니 심판은 한 사람으로 말미암아 정죄에 이르렀으나 은사는 많은 범죄로 말미암아 의롭다 하심에 이름이니라',28063),
('rom-5-17','rom','로마서',5,17,'한 사람의 범죄로 말미암아 사망이 그 한 사람을 통하여 왕 노릇 하였은즉 더욱 은혜와 의의 선물을 넘치게 받는 자들은 한 분 예수 그리스도를 통하여 생명 안에서 왕 노릇 하리로다',28064),
('rom-5-18','rom','로마서',5,18,'그런즉 한 범죄로 많은 사람이 정죄에 이른 것 같이 한 의로운 행위로 말미암아 많은 사람이 의롭다 하심을 받아 생명에 이르렀느니라',28065),
('rom-5-19','rom','로마서',5,19,'한 사람이 순종하지 아니함으로 많은 사람이 죄인 된 것 같이 한 사람이 순종하심으로 많은 사람이 의인이 되리라',28066),
('rom-5-20','rom','로마서',5,20,'율법이 들어온 것은 범죄를 더하게 하려 함이라 그러나 죄가 더한 곳에 은혜가 더욱 넘쳤나니',28067),
('rom-5-21','rom','로마서',5,21,'이는 죄가 사망 안에서 왕 노릇 한 것 같이 은혜도 또한 의로 말미암아 왕 노릇 하여 우리 주 예수 그리스도로 말미암아 영생에 이르게 하려 함이라',28068),
('rom-6-1','rom','로마서',6,1,'그런즉 우리가 무슨 말을 하리요 은혜를 더하게 하려고 죄에 거하겠느냐',28069),
('rom-6-2','rom','로마서',6,2,'그럴 수 없느니라 죄에 대하여 죽은 우리가 어찌 그 가운데 더 살리요',28070),
('rom-6-3','rom','로마서',6,3,'무릇 그리스도 예수와 합하여 세례를 받은 우리는 그의 죽으심과 합하여 세례를 받은 줄을 알지 못하느냐',28071),
('rom-6-4','rom','로마서',6,4,'그러므로 우리가 그의 죽으심과 합하여 세례를 받음으로 그와 함께 장사되었나니 이는 아버지의 영광으로 말미암아 그리스도를 죽은 자 가운데서 살리심과 같이 우리로 또한 새 생명 가운데서 행하게 하려 함이라',28072),
('rom-6-5','rom','로마서',6,5,'만일 우리가 그의 죽으심과 같은 모양으로 연합한 자가 되었으면 또한 그의 부활과 같은 모양으로 연합한 자도 되리라',28073),
('rom-6-6','rom','로마서',6,6,'우리가 알거니와 우리의 옛 사람이 예수와 함께 십자가에 못 박힌 것은 죄의 몸이 죽어 다시는 우리가 죄에게 종 노릇 하지 아니하려 함이니',28074),
('rom-6-7','rom','로마서',6,7,'이는 죽은 자가 죄에서 벗어나 의롭다 하심을 얻었음이라',28075),
('rom-6-8','rom','로마서',6,8,'만일 우리가 그리스도와 함께 죽었으면 또한 그와 함께 살 줄을 믿노니',28076),
('rom-6-9','rom','로마서',6,9,'이는 그리스도께서 죽은 자 가운데서 살아나셨으매 다시 죽지 아니하시고 사망이 다시 그를 주장하지 못할 줄을 앎이로라',28077),
('rom-6-10','rom','로마서',6,10,'그가 죽으심은 죄에 대하여 단번에 죽으심이요 그가 살아 계심은 하나님께 대하여 살아 계심이니',28078),
('rom-6-11','rom','로마서',6,11,'이와 같이 너희도 너희 자신을 죄에 대하여는 죽은 자요 그리스도 예수 안에서 하나님께 대하여는 살아 있는 자로 여길지어다',28079),
('rom-6-12','rom','로마서',6,12,'그러므로 너희는 죄가 너희 죽을 몸을 지배하지 못하게 하여 몸의 사욕에 순종하지 말고',28080),
('rom-6-13','rom','로마서',6,13,'또한 너희 지체를 불의의 무기로 죄에게 내주지 말고 오직 너희 자신을 죽은 자 가운데서 다시 살아난 자 같이 하나님께 드리며 너희 지체를 의의 무기로 하나님께 드리라',28081),
('rom-6-14','rom','로마서',6,14,'죄가 너희를 주장하지 못하리니 이는 너희가 법 아래에 있지 아니하고 은혜 아래에 있음이라',28082),
('rom-6-15','rom','로마서',6,15,'그런즉 어찌하리요 우리가 법 아래에 있지 아니하고 은혜 아래에 있으니 죄를 지으리요 그럴 수 없느니라',28083),
('rom-6-16','rom','로마서',6,16,'너희 자신을 종으로 내주어 누구에게 순종하든지 그 순종함을 받는 자의 종이 되는 줄을 너희가 알지 못하느냐 혹은 죄의 종으로 사망에 이르고 혹은 순종의 종으로 의에 이르느니라',28084),
('rom-6-17','rom','로마서',6,17,'하나님께 감사하리로다 너희가 본래 죄의 종이더니 너희에게 전하여 준 바 교훈의 본을 마음으로 순종하여',28085),
('rom-6-18','rom','로마서',6,18,'죄로부터 해방되어 의에게 종이 되었느니라',28086),
('rom-6-19','rom','로마서',6,19,'너희 육신이 연약하므로 내가 사람의 예대로 말하노니 전에 너희가 너희 지체를 부정과 불법에 내주어 불법에 이른 것 같이 이제는 너희 지체를 의에게 종으로 내주어 거룩함에 이르라',28087),
('rom-6-20','rom','로마서',6,20,'너희가 죄의 종이 되었을 때에는 의에 대하여 자유로웠느니라',28088),
('rom-6-21','rom','로마서',6,21,'너희가 그 때에 무슨 열매를 얻었느냐 이제는 너희가 그 일을 부끄러워하나니 이는 그 마지막이 사망임이라',28089),
('rom-6-22','rom','로마서',6,22,'그러나 이제는 너희가 죄로부터 해방되고 하나님께 종이 되어 거룩함에 이르는 열매를 맺었으니 그 마지막은 영생이라',28090),
('rom-6-23','rom','로마서',6,23,'죄의 삯은 사망이요 하나님의 은사는 그리스도 예수 우리 주 안에 있는 영생이니라',28091),
('rom-7-1','rom','로마서',7,1,'형제들아 내가 법 아는 자들에게 말하노니 너희는 그 법이 사람이 살 동안만 그를 주관하는 줄 알지 못하느냐',28092),
('rom-7-2','rom','로마서',7,2,'남편 있는 여인이 그 남편 생전에는 법으로 그에게 매인 바 되나 만일 그 남편이 죽으면 남편의 법에서 벗어나느니라',28093),
('rom-7-3','rom','로마서',7,3,'그러므로 만일 그 남편 생전에 다른 남자에게 가면 음녀라 그러나 만일 남편이 죽으면 그 법에서 자유롭게 되나니 다른 남자에게 갈지라도 음녀가 되지 아니하느니라',28094),
('rom-7-4','rom','로마서',7,4,'그러므로 내 형제들아 너희도 그리스도의 몸으로 말미암아 율법에 대하여 죽임을 당하였으니 이는 다른 이 곧 죽은 자 가운데서 살아나신 이에게 가서 우리가 하나님을 위하여 열매를 맺게 하려 함이라',28095),
('rom-7-5','rom','로마서',7,5,'우리가 육신에 있을 때에는 율법으로 말미암는 죄의 정욕이 우리 지체 중에 역사하여 우리로 사망을 위하여 열매를 맺게 하였더니',28096),
('rom-7-6','rom','로마서',7,6,'이제는 우리가 얽매였던 것에 대하여 죽었으므로 율법에서 벗어났으니 이러므로 우리가 영의 새로운 것으로 섬길 것이요 율법 조문의 묵은 것으로 아니할지니라',28097),
('rom-7-7','rom','로마서',7,7,'그런즉 우리가 무슨 말을 하리요 율법이 죄냐 그럴 수 없느니라 율법으로 말미암지 않고는 내가 죄를 알지 못하였으니 곧 율법이 탐내지 말라 하지 아니하였더라면 내가 탐심을 알지 못하였으리라',28098),
('rom-7-8','rom','로마서',7,8,'그러나 죄가 기회를 타서 계명으로 말미암아 내 속에서 온갖 탐심을 이루었나니 이는 율법이 없으면 죄가 죽은 것임이라',28099),
('rom-7-9','rom','로마서',7,9,'전에 율법을 깨닫지 못했을 때에는 내가 살았더니 계명이 이르매 죄는 살아나고 나는 죽었도다',28100),
('rom-7-10','rom','로마서',7,10,'생명에 이르게 할 그 계명이 내게 대하여 도리어 사망에 이르게 하는 것이 되었도다',28101),
('rom-7-11','rom','로마서',7,11,'죄가 기회를 타서 계명으로 말미암아 나를 속이고 그것으로 나를 죽였는지라',28102),
('rom-7-12','rom','로마서',7,12,'이로 보건대 율법은 거룩하고 계명도 거룩하고 의로우며 선하도다',28103),
('rom-7-13','rom','로마서',7,13,'그런즉 선한 것이 내게 사망이 되었느냐 그럴 수 없느니라 오직 죄가 죄로 드러나기 위하여 선한 그것으로 말미암아 나를 죽게 만들었으니 이는 계명으로 말미암아 죄로 심히 죄 되게 하려 함이라',28104),
('rom-7-14','rom','로마서',7,14,'우리가 율법은 신령한 줄 알거니와 나는 육신에 속하여 죄 아래에 팔렸도다',28105),
('rom-7-15','rom','로마서',7,15,'내가 행하는 것을 내가 알지 못하노니 곧 내가 원하는 것은 행하지 아니하고 도리어 미워하는 것을 행함이라',28106),
('rom-7-16','rom','로마서',7,16,'만일 내가 원하지 아니하는 그것을 행하면 내가 이로써 율법이 선한 것을 시인하노니',28107),
('rom-7-17','rom','로마서',7,17,'이제는 그것을 행하는 자가 내가 아니요 내 속에 거하는 죄니라',28108),
('rom-7-18','rom','로마서',7,18,'내 속 곧 내 육신에 선한 것이 거하지 아니하는 줄을 아노니 원함은 내게 있으나 선을 행하는 것은 없노라',28109),
('rom-7-19','rom','로마서',7,19,'내가 원하는 바 선은 행하지 아니하고 도리어 원하지 아니하는 바 악을 행하는도다',28110),
('rom-7-20','rom','로마서',7,20,'만일 내가 원하지 아니하는 그것을 하면 이를 행하는 자는 내가 아니요 내 속에 거하는 죄니라',28111),
('rom-7-21','rom','로마서',7,21,'그러므로 내가 한 법을 깨달았노니 곧 선을 행하기 원하는 나에게 악이 함께 있는 것이로다',28112),
('rom-7-22','rom','로마서',7,22,'내 속사람으로는 하나님의 법을 즐거워하되',28113),
('rom-7-23','rom','로마서',7,23,'내 지체 속에서 한 다른 법이 내 마음의 법과 싸워 내 지체 속에 있는 죄의 법으로 나를 사로잡는 것을 보는도다',28114),
('rom-7-24','rom','로마서',7,24,'오호라 나는 곤고한 사람이로다 이 사망의 몸에서 누가 나를 건져내랴',28115),
('rom-7-25','rom','로마서',7,25,'우리 주 예수 그리스도로 말미암아 하나님께 감사하리로다 그런즉 내 자신이 마음으로는 하나님의 법을 육신으로는 죄의 법을 섬기노라',28116),
('rom-8-1','rom','로마서',8,1,'그러므로 이제 그리스도 예수 안에 있는 자에게는 결코 정죄함이 없나니',28117),
('rom-8-2','rom','로마서',8,2,'이는 그리스도 예수 안에 있는 생명의 성령의 법이 죄와 사망의 법에서 너를 해방하였음이라',28118),
('rom-8-3','rom','로마서',8,3,'율법이 육신으로 말미암아 연약하여 할 수 없는 그것을 하나님은 하시나니 곧 죄로 말미암아 자기 아들을 죄 있는 육신의 모양으로 보내어 육신에 죄를 정하사',28119),
('rom-8-4','rom','로마서',8,4,'육신을 따르지 않고 그 영을 따라 행하는 우리에게 율법의 요구가 이루어지게 하려 하심이니라',28120),
('rom-8-5','rom','로마서',8,5,'육신을 따르는 자는 육신의 일을, 영을 따르는 자는 영의 일을 생각하나니',28121),
('rom-8-6','rom','로마서',8,6,'육신의 생각은 사망이요 영의 생각은 생명과 평안이니라',28122),
('rom-8-7','rom','로마서',8,7,'육신의 생각은 하나님과 원수가 되나니 이는 하나님의 법에 굴복하지 아니할 뿐 아니라 할 수도 없음이라',28123),
('rom-8-8','rom','로마서',8,8,'육신에 있는 자들은 하나님을 기쁘시게 할 수 없느니라',28124),
('rom-8-9','rom','로마서',8,9,'만일 너희 속에 하나님의 영이 거하시면 너희가 육신에 있지 아니하고 영에 있나니 누구든지 그리스도의 영이 없으면 그리스도의 사람이 아니라',28125),
('rom-8-10','rom','로마서',8,10,'또 그리스도께서 너희 안에 계시면 몸은 죄로 말미암아 죽은 것이나 영은 의로 말미암아 살아 있는 것이니라',28126),
('rom-8-11','rom','로마서',8,11,'예수를 죽은 자 가운데서 살리신 이의 영이 너희 안에 거하시면 그리스도 예수를 죽은 자 가운데서 살리신 이가 너희 안에 거하시는 그의 영으로 말미암아 너희 죽을 몸도 살리시리라',28127),
('rom-8-12','rom','로마서',8,12,'그러므로 형제들아 우리가 빚진 자로되 육신에게 져서 육신대로 살 것이 아니니라',28128),
('rom-8-13','rom','로마서',8,13,'너희가 육신대로 살면 반드시 죽을 것이로되 영으로써 몸의 행실을 죽이면 살리니',28129),
('rom-8-14','rom','로마서',8,14,'무릇 하나님의 영으로 인도함을 받는 사람은 곧 하나님의 아들이라',28130),
('rom-8-15','rom','로마서',8,15,'너희는 다시 무서워하는 종의 영을 받지 아니하고 양자의 영을 받았으므로 우리가 아빠 아버지라고 부르짖느니라',28131),
('rom-8-16','rom','로마서',8,16,'성령이 친히 우리의 영과 더불어 우리가 하나님의 자녀인 것을 증언하시나니',28132),
('rom-8-17','rom','로마서',8,17,'자녀이면 또한 상속자 곧 하나님의 상속자요 그리스도와 함께 한 상속자니 우리가 그와 함께 영광을 받기 위하여 고난도 함께 받아야 할 것이니라',28133),
('rom-8-18','rom','로마서',8,18,'생각하건대 현재의 고난은 장차 우리에게 나타날 영광과 비교할 수 없도다',28134),
('rom-8-19','rom','로마서',8,19,'피조물이 고대하는 바는 하나님의 아들들이 나타나는 것이니',28135),
