('rom-8-21','rom','로마서',8,21,'그 바라는 것은 피조물도 썩어짐의 종 노릇 한 데서 해방되어 하나님의 자녀들의 영광의 자유에 이르는 것이니라',28137),
('rom-8-22','rom','로마서',8,22,'피조물이 다 이제까지 함께 탄식하며 함께 고통을 겪고 있는 것을 우리가 아느니라',28138),
('rom-8-23','rom','로마서',8,23,'그뿐 아니라 또한 우리 곧 성령의 처음 익은 열매를 받은 우리까지도 속으로 탄식하여 양자 될 것 곧 우리 몸의 속량을 기다리느니라',28139),
('rom-8-24','rom','로마서',8,24,'우리가 소망으로 구원을 얻었으매 보이는 소망이 소망이 아니니 보는 것을 누가 바라리요',28140),
('rom-8-25','rom','로마서',8,25,'만일 우리가 보지 못하는 것을 바라면 참음으로 기다릴지니라',28141),
('rom-8-26','rom','로마서',8,26,'이와 같이 성령도 우리의 연약함을 도우시나니 우리는 마땅히 기도할 바를 알지 못하나 오직 성령이 말할 수 없는 탄식으로 우리를 위하여 친히 간구하시느니라',28142),
('rom-8-27','rom','로마서',8,27,'마음을 살피시는 이가 성령의 생각을 아시나니 이는 성령이 하나님의 뜻대로 성도를 위하여 간구하심이니라',28143),
('rom-8-28','rom','로마서',8,28,'우리가 알거니와 하나님을 사랑하는 자 곧 그의 뜻대로 부르심을 입은 자들에게는 모든 것이 합력하여 선을 이루느니라',28144),
('rom-8-29','rom','로마서',8,29,'하나님이 미리 아신 자들을 또한 그 아들의 형상을 본받게 하기 위하여 미리 정하셨으니 이는 그로 많은 형제 중에서 맏아들이 되게 하려 하심이니라',28145),
('rom-8-30','rom','로마서',8,30,'또 미리 정하신 그들을 또한 부르시고 부르신 그들을 또한 의롭다 하시고 의롭다 하신 그들을 또한 영화롭게 하셨느니라',28146),
('rom-8-31','rom','로마서',8,31,'그런즉 이 일에 대하여 우리가 무슨 말 하리요 만일 하나님이 우리를 위하시면 누가 우리를 대적하리요',28147),
