('rom-11-13','rom','로마서',11,13,'내가 이방인인 너희에게 말하노라 내가 이방인의 사도인 만큼 내 직분을 영광스럽게 여기노니',28222),
('rom-11-14','rom','로마서',11,14,'이는 혹 내 골육을 아무쪼록 시기하게 하여 그들 중에서 얼마를 구원하려 함이라',28223),
('rom-11-15','rom','로마서',11,15,'그들을 버리는 것이 세상의 화목이 되거든 그 받아들이는 것이 죽은 자 가운데서 살아나는 것이 아니면 무엇이리요',28224),
('rom-11-16','rom','로마서',11,16,'제사하는 처음 익은 곡식 가루가 거룩한즉 떡덩이도 그러하고 뿌리가 거룩한즉 가지도 그러하니라',28225),
('rom-11-17','rom','로마서',11,17,'또한 가지 얼마가 꺾이었는데 돌감람나무인 네가 그들 중에 접붙임이 되어 참감람나무 뿌리의 진액을 함께 받는 자가 되었은즉',28226),
('rom-11-18','rom','로마서',11,18,'그 가지들을 향하여 자랑하지 말라 자랑할지라도 네가 뿌리를 보전하는 것이 아니요 뿌리가 너를 보전하는 것이니라',28227),
('rom-11-19','rom','로마서',11,19,'그러면 네 말이 가지들이 꺾인 것은 나로 접붙임을 받게 하려 함이라 하리니',28228),
('rom-11-20','rom','로마서',11,20,'옳도다 그들은 믿지 아니하므로 꺾이고 너는 믿으므로 섰느니라 높은 마음을 품지 말고 도리어 두려워하라',28229),
('rom-11-21','rom','로마서',11,21,'하나님이 원 가지들도 아끼지 아니하셨은즉 너도 아끼지 아니하시리라',28230),
('rom-11-22','rom','로마서',11,22,'그러므로 하나님의 인자하심과 준엄하심을 보라 넘어지는 자들에게는 준엄하심이 있으니 너희가 만일 하나님의 인자하심에 머물러 있으면 그 인자가 너희에게 있으리라 그렇지 않으면 너도 찍히는 바 되리라',28231),
('rom-11-23','rom','로마서',11,23,'그들도 믿지 아니하는 데 머무르지 아니하면 접붙임을 받으리니 이는 그들을 접붙이실 능력이 하나님께 있음이라',28232),
('rom-11-24','rom','로마서',11,24,'네가 원 돌감람나무에서 찍힘을 받고 본성을 거슬러 좋은 감람나무에 접붙임을 받았으니 원 가지인 이 사람들이야 얼마나 더 자기 감람나무에 접붙이심을 받으랴',28233),
('rom-11-25','rom','로마서',11,25,'형제들아 너희가 스스로 지혜 있다 하면서 이 신비를 너희가 모르기를 내가 원하지 아니하노니 이 신비는 이방인의 충만한 수가 들어오기까지 이스라엘의 더러는 우둔하게 된 것이라',28234),
('rom-11-26','rom','로마서',11,26,'그리하여 온 이스라엘이 구원을 받으리라 기록된 바 구원자가 시온에서 오사 야곱에게서 경건하지 않은 것을 돌이키시겠고',28235),
('rom-11-27','rom','로마서',11,27,'내가 그들의 죄를 없이 할 때에 그들에게 이루어질 내 언약이 이것이라 함과 같으니라',28236),
('rom-11-28','rom','로마서',11,28,'복음으로 하면 그들이 너희로 말미암아 원수 된 자요 택하심으로 하면 조상들로 말미암아 사랑을 입은 자라',28237),
('rom-11-29','rom','로마서',11,29,'하나님의 은사와 부르심에는 후회하심이 없느니라',28238),
('rom-11-30','rom','로마서',11,30,'너희가 전에는 하나님께 순종하지 아니하더니 이스라엘이 순종하지 아니함으로 이제 긍휼을 입었는지라',28239),
('rom-11-31','rom','로마서',11,31,'이와 같이 이 사람들이 순종하지 아니하니 이는 너희에게 베푸시는 긍휼로 이제 그들도 긍휼을 얻게 하려 하심이라',28240),
