('rom-11-33','rom','로마서',11,33,'깊도다 하나님의 지혜와 지식의 풍성함이여, 그의 판단은 헤아리지 못할 것이며 그의 길은 찾지 못할 것이로다',28242),
('rom-11-34','rom','로마서',11,34,'누가 주의 마음을 알았느냐 누가 그의 모사가 되었느냐',28243),
