('rom-12-6','rom','로마서',12,6,'우리에게 주신 은혜대로 받은 은사가 각각 다르니 혹 예언이면 믿음의 분수대로,',28251),
('rom-12-7','rom','로마서',12,7,'혹 섬기는 일이면 섬기는 일로, 혹 가르치는 자면 가르치는 일로,',28252),
