('rom-13-9','rom','로마서',13,9,'간음하지 말라, 살인하지 말라, 도둑질하지 말라, 탐내지 말라 한 것과 그 외에 다른 계명이 있을지라도 네 이웃을 네 자신과 같이 사랑하라 하신 그 말씀 가운데 다 들었느니라',28275),
('rom-13-10','rom','로마서',13,10,'사랑은 이웃에게 악을 행하지 아니하나니 그러므로 사랑은 율법의 완성이니라',28276),
