('1co-1-2','1co','고린도전서',1,2,'고린도에 있는 하나님의 교회 곧 그리스도 예수 안에서 거룩하여지고 성도라 부르심을 받은 자들과 또 각처에서 우리의 주 곧 그들과 우리의 주 되신 예수 그리스도의 이름을 부르는 모든 자들에게',28365),
('1co-1-3','1co','고린도전서',1,3,'하나님 우리 아버지와 주 예수 그리스도로부터 은혜와 평강이 있기를 원하노라',28366),
('1co-1-4','1co','고린도전서',1,4,'그리스도 예수 안에서 너희에게 주신 하나님의 은혜로 말미암아 내가 너희를 위하여 항상 하나님께 감사하노니',28367),
('1co-1-5','1co','고린도전서',1,5,'이는 너희가 그 안에서 모든 일 곧 모든 언변과 모든 지식에 풍족하므로',28368),
('1co-1-6','1co','고린도전서',1,6,'그리스도의 증거가 너희 중에 견고하게 되어',28369),
('1co-1-7','1co','고린도전서',1,7,'너희가 모든 은사에 부족함이 없이 우리 주 예수 그리스도의 나타나심을 기다림이라',28370),
('1co-1-8','1co','고린도전서',1,8,'주께서 너희를 우리 주 예수 그리스도의 날에 책망할 것이 없는 자로 끝까지 견고하게 하시리라',28371),
('1co-1-9','1co','고린도전서',1,9,'너희를 불러 그의 아들 예수 그리스도 우리 주와 더불어 교제하게 하시는 하나님은 미쁘시도다',28372),
('1co-1-10','1co','고린도전서',1,10,'형제들아 내가 우리 주 예수 그리스도의 이름으로 너희를 권하노니 모두가 같은 말을 하고 너희 가운데 분쟁이 없이 같은 마음과 같은 뜻으로 온전히 합하라',28373),
('1co-1-11','1co','고린도전서',1,11,'내 형제들아 글로에의 집 편으로 너희에 대한 말이 내게 들리니 곧 너희 가운데 분쟁이 있다는 것이라',28374),
('1co-1-12','1co','고린도전서',1,12,'내가 이것을 말하거니와 너희가 각각 이르되 나는 바울에게, 나는 아볼로에게, 나는 게바에게, 나는 그리스도에게 속한 자라 한다는 것이니',28375),
('1co-1-13','1co','고린도전서',1,13,'그리스도께서 어찌 나뉘었느냐 바울이 너희를 위하여 십자가에 못 박혔으며 바울의 이름으로 너희가 세례를 받았느냐',28376),
('1co-1-14','1co','고린도전서',1,14,'나는 그리스보와 가이오 외에는 너희 중 아무에게도 내가 세례를 베풀지 아니한 것을 감사하노니',28377),
('1co-1-15','1co','고린도전서',1,15,'이는 아무도 나의 이름으로 세례를 받았다 말하지 못하게 하려 함이라',28378),
('1co-1-16','1co','고린도전서',1,16,'내가 또한 스데바나 집 사람에게 세례를 베풀었고 그 외에는 다른 누구에게 세례를 베풀었는지 알지 못하노라',28379),
('1co-1-17','1co','고린도전서',1,17,'그리스도께서 나를 보내심은 세례를 베풀게 하려 하심이 아니요 오직 복음을 전하게 하려 하심이로되 말의 지혜로 하지 아니함은 그리스도의 십자가가 헛되지 않게 하려 함이라',28380),
('1co-1-18','1co','고린도전서',1,18,'십자가의 도가 멸망하는 자들에게는 미련한 것이요 구원을 받는 우리에게는 하나님의 능력이라',28381),
('1co-1-19','1co','고린도전서',1,19,'기록된 바 내가 지혜 있는 자들의 지혜를 멸하고 총명한 자들의 총명을 폐하리라 하였으니',28382),
('1co-1-20','1co','고린도전서',1,20,'지혜 있는 자가 어디 있느냐 선비가 어디 있느냐 이 세대에 변론가가 어디 있느냐 하나님께서 이 세상의 지혜를 미련하게 하신 것이 아니냐',28383),
('1co-1-21','1co','고린도전서',1,21,'하나님의 지혜에 있어서는 이 세상이 자기 지혜로 하나님을 알지 못하므로 하나님께서 전도의 미련한 것으로 믿는 자들을 구원하시기를 기뻐하셨도다',28384),
('1co-1-22','1co','고린도전서',1,22,'유대인은 표적을 구하고 헬라인은 지혜를 찾으나',28385),
('1co-1-23','1co','고린도전서',1,23,'우리는 십자가에 못 박힌 그리스도를 전하니 유대인에게는 거리끼는 것이요 이방인에게는 미련한 것이로되',28386),
('1co-1-24','1co','고린도전서',1,24,'오직 부르심을 받은 자들에게는 유대인이나 헬라인이나 그리스도는 하나님의 능력이요 하나님의 지혜니라',28387),
('1co-1-25','1co','고린도전서',1,25,'하나님의 어리석음이 사람보다 지혜롭고 하나님의 약하심이 사람보다 강하니라',28388),
('1co-1-26','1co','고린도전서',1,26,'형제들아 너희를 부르심을 보라 육체를 따라 지혜로운 자가 많지 아니하며 능한 자가 많지 아니하며 문벌 좋은 자가 많지 아니하도다',28389),
('1co-1-27','1co','고린도전서',1,27,'그러나 하나님께서 세상의 미련한 것들을 택하사 지혜 있는 자들을 부끄럽게 하려 하시고 세상의 약한 것들을 택하사 강한 것들을 부끄럽게 하려 하시며',28390),
('1co-1-28','1co','고린도전서',1,28,'하나님께서 세상의 천한 것들과 멸시 받는 것들과 없는 것들을 택하사 있는 것들을 폐하려 하시나니',28391),
('1co-1-29','1co','고린도전서',1,29,'이는 아무 육체도 하나님 앞에서 자랑하지 못하게 하려 하심이라',28392),
('1co-1-30','1co','고린도전서',1,30,'너희는 하나님으로부터 나서 그리스도 예수 안에 있고 예수는 하나님으로부터 나와서 우리에게 지혜와 의로움과 거룩함과 구원함이 되셨으니',28393),
('1co-1-31','1co','고린도전서',1,31,'기록된 바 자랑하는 자는 주 안에서 자랑하라 함과 같게 하려 함이라',28394),
('1co-2-1','1co','고린도전서',2,1,'형제들아 내가 너희에게 나아가 하나님의 증거를 전할 때에 말과 지혜의 아름다운 것으로 아니하였나니',28395),
('1co-2-2','1co','고린도전서',2,2,'내가 너희 중에서 예수 그리스도와 그가 십자가에 못 박히신 것 외에는 아무 것도 알지 아니하기로 작정하였음이라',28396),
('1co-2-3','1co','고린도전서',2,3,'내가 너희 가운데 거할 때에 약하고 두려워하고 심히 떨었노라',28397),
('1co-2-4','1co','고린도전서',2,4,'내 말과 내 전도함이 설득력 있는 지혜의 말로 하지 아니하고 다만 성령의 나타나심과 능력으로 하여',28398),
('1co-2-5','1co','고린도전서',2,5,'너희 믿음이 사람의 지혜에 있지 아니하고 다만 하나님의 능력에 있게 하려 하였노라',28399),
('1co-2-6','1co','고린도전서',2,6,'그러나 우리가 온전한 자들 중에서는 지혜를 말하노니 이는 이 세상의 지혜가 아니요 또 이 세상에서 없어질 통치자들의 지혜도 아니요',28400),
('1co-2-7','1co','고린도전서',2,7,'오직 은밀한 가운데 있는 하나님의 지혜를 말하는 것으로서 곧 감추어졌던 것인데 하나님이 우리의 영광을 위하여 만세 전에 미리 정하신 것이라',28401),
('1co-2-8','1co','고린도전서',2,8,'이 지혜는 이 세대의 통치자들이 한 사람도 알지 못하였나니 만일 알았더라면 영광의 주를 십자가에 못 박지 아니하였으리라',28402),
('1co-2-9','1co','고린도전서',2,9,'기록된 바 하나님이 자기를 사랑하는 자들을 위하여 예비하신 모든 것은 눈으로 보지 못하고 귀로 듣지 못하고 사람의 마음으로 생각하지도 못하였다 함과 같으니라',28403),
('1co-2-10','1co','고린도전서',2,10,'오직 하나님이 성령으로 이것을 우리에게 보이셨으니 성령은 모든 것 곧 하나님의 깊은 것까지도 통달하시느니라',28404),
('1co-2-11','1co','고린도전서',2,11,'사람의 일을 사람의 속에 있는 영 외에 누가 알리요 이와 같이 하나님의 일도 하나님의 영 외에는 아무도 알지 못하느니라',28405),
('1co-2-12','1co','고린도전서',2,12,'우리가 세상의 영을 받지 아니하고 오직 하나님으로부터 온 영을 받았으니 이는 우리로 하여금 하나님께서 우리에게 은혜로 주신 것들을 알게 하려 하심이라',28406),
('1co-2-13','1co','고린도전서',2,13,'우리가 이것을 말하거니와 사람의 지혜가 가르친 말로 아니하고 오직 성령께서 가르치신 것으로 하니 영적인 일은 영적인 것으로 분별하느니라',28407),
('1co-2-14','1co','고린도전서',2,14,'육에 속한 사람은 하나님의 성령의 일들을 받지 아니하나니 이는 그것들이 그에게는 어리석게 보임이요, 또 그는 그것들을 알 수도 없나니 그러한 일은 영적으로 분별되기 때문이라',28408),
('1co-2-15','1co','고린도전서',2,15,'신령한 자는 모든 것을 판단하나 자기는 아무에게도 판단을 받지 아니하느니라',28409),
('1co-2-16','1co','고린도전서',2,16,'누가 주의 마음을 알아서 주를 가르치겠느냐 그러나 우리가 그리스도의 마음을 가졌느니라',28410),
('1co-3-1','1co','고린도전서',3,1,'형제들아 내가 신령한 자들을 대함과 같이 너희에게 말할 수 없어서 육신에 속한 자 곧 그리스도 안에서 어린 아이들을 대함과 같이 하노라',28411),
('1co-3-2','1co','고린도전서',3,2,'내가 너희를 젖으로 먹이고 밥으로 아니하였노니 이는 너희가 감당하지 못하였음이거니와 지금도 못하리라',28412),
('1co-3-3','1co','고린도전서',3,3,'너희는 아직도 육신에 속한 자로다 너희 가운데 시기와 분쟁이 있으니 어찌 육신에 속하여 사람을 따라 행함이 아니리요',28413),
('1co-3-4','1co','고린도전서',3,4,'어떤 이는 말하되 나는 바울에게라 하고 다른 이는 나는 아볼로에게라 하니 너희가 육의 사람이 아니리요',28414),
('1co-3-5','1co','고린도전서',3,5,'그런즉 아볼로는 무엇이며 바울은 무엇이냐 그들은 주께서 각각 주신 대로 너희로 하여금 믿게 한 사역자들이니라',28415),
('1co-3-6','1co','고린도전서',3,6,'나는 심었고 아볼로는 물을 주었으되 오직 하나님께서 자라나게 하셨나니',28416),
('1co-3-7','1co','고린도전서',3,7,'그런즉 심는 이나 물 주는 이는 아무 것도 아니로되 오직 자라게 하시는 이는 하나님뿐이니라',28417),
('1co-3-8','1co','고린도전서',3,8,'심는 이와 물 주는 이는 한가지이나 각각 자기가 일한 대로 자기의 상을 받으리라',28418),
('1co-3-9','1co','고린도전서',3,9,'우리는 하나님의 동역자들이요 너희는 하나님의 밭이요 하나님의 집이니라',28419),
('1co-3-10','1co','고린도전서',3,10,'내게 주신 하나님의 은혜를 따라 내가 지혜로운 건축자와 같이 터를 닦아 두매 다른 이가 그 위에 세우나 그러나 각각 어떻게 그 위에 세울까를 조심할지니라',28420),
('1co-3-11','1co','고린도전서',3,11,'이 닦아 둔 것 외에 능히 다른 터를 닦아 둘 자가 없으니 이 터는 곧 예수 그리스도라',28421),
('1co-3-12','1co','고린도전서',3,12,'만일 누구든지 금이나 은이나 보석이나 나무나 풀이나 짚으로 이 터 위에 세우면',28422),
('1co-3-13','1co','고린도전서',3,13,'각 사람의 공적이 나타날 터인데 그 날이 공적을 밝히리니 이는 불로 나타내고 그 불이 각 사람의 공적이 어떠한 것을 시험할 것임이라',28423),
('1co-3-14','1co','고린도전서',3,14,'만일 누구든지 그 위에 세운 공적이 그대로 있으면 상을 받고',28424),
('1co-3-15','1co','고린도전서',3,15,'누구든지 그 공적이 불타면 해를 받으리니 그러나 자신은 구원을 받되 불 가운데서 받은 것 같으리라',28425),
('1co-3-16','1co','고린도전서',3,16,'너희는 너희가 하나님의 성전인 것과 하나님의 성령이 너희 안에 계시는 것을 알지 못하느냐',28426),
('1co-3-17','1co','고린도전서',3,17,'누구든지 하나님의 성전을 더럽히면 하나님이 그 사람을 멸하시리라 하나님의 성전은 거룩하니 너희도 그러하니라',28427),
('1co-3-18','1co','고린도전서',3,18,'아무도 자신을 속이지 말라 너희 중에 누구든지 이 세상에서 지혜 있는 줄로 생각하거든 어리석은 자가 되라 그리하여야 지혜로운 자가 되리라',28428),
('1co-3-19','1co','고린도전서',3,19,'이 세상 지혜는 하나님께 어리석은 것이니 기록된 바 하나님은 지혜 있는 자들로 하여금 자기 꾀에 빠지게 하시는 이라 하였고',28429),
('1co-3-20','1co','고린도전서',3,20,'또 주께서 지혜 있는 자들의 생각을 헛것으로 아신다 하셨느니라',28430),
('1co-3-21','1co','고린도전서',3,21,'그런즉 누구든지 사람을 자랑하지 말라 만물이 다 너희 것임이라',28431),
('1co-3-22','1co','고린도전서',3,22,'바울이나 아볼로나 게바나 세계나 생명이나 사망이나 지금 것이나 장래 것이나 다 너희의 것이요',28432),
('1co-3-23','1co','고린도전서',3,23,'너희는 그리스도의 것이요 그리스도는 하나님의 것이니라',28433),
('1co-4-1','1co','고린도전서',4,1,'사람이 마땅히 우리를 그리스도의 일꾼이요 하나님의 비밀을 맡은 자로 여길지어다',28434),
('1co-4-2','1co','고린도전서',4,2,'그리고 맡은 자들에게 구할 것은 충성이니라',28435),
('1co-4-3','1co','고린도전서',4,3,'너희에게나 다른 사람에게나 판단 받는 것이 내게는 매우 작은 일이라 나도 나를 판단하지 아니하노니',28436),
('1co-4-4','1co','고린도전서',4,4,'내가 자책할 아무 것도 깨닫지 못하나 이로 말미암아 의롭다 함을 얻지 못하노라 다만 나를 심판하실 이는 주시니라',28437),
('1co-4-5','1co','고린도전서',4,5,'그러므로 때가 이르기 전 곧 주께서 오시기까지 아무 것도 판단하지 말라 그가 어둠에 감추인 것들을 드러내고 마음의 뜻을 나타내시리니 그 때에 각 사람에게 하나님으로부터 칭찬이 있으리라',28438),
('1co-4-6','1co','고린도전서',4,6,'형제들아 내가 너희를 위하여 이 일에 나와 아볼로를 들어서 본을 보였으니 이는 너희로 하여금 기록된 말씀 밖으로 넘어가지 말라 한 것을 우리에게서 배워 서로 대적하여 교만한 마음을 가지지 말게 하려 함이라',28439),
('1co-4-7','1co','고린도전서',4,7,'누가 너를 남달리 구별하였느냐 네게 있는 것 중에 받지 아니한 것이 무엇이냐 네가 받았은즉 어찌하여 받지 아니한 것 같이 자랑하느냐',28440),
('1co-4-8','1co','고린도전서',4,8,'너희가 이미 배 부르며 이미 풍성하며 우리 없이도 왕이 되었도다 우리가 너희와 함께 왕 노릇 하기 위하여 참으로 너희가 왕이 되기를 원하노라',28441),
('1co-4-9','1co','고린도전서',4,9,'내가 생각하건대 하나님이 사도인 우리를 죽이기로 작정된 자 같이 끄트머리에 두셨으매 우리는 세계 곧 천사와 사람에게 구경거리가 되었노라',28442),
('1co-4-10','1co','고린도전서',4,10,'우리는 그리스도 때문에 어리석으나 너희는 그리스도 안에서 지혜롭고 우리는 약하나 너희는 강하고 너희는 존귀하나 우리는 비천하여',28443),
('1co-4-11','1co','고린도전서',4,11,'바로 이 시각까지 우리가 주리고 목마르며 헐벗고 매맞으며 정처가 없고',28444),
('1co-4-12','1co','고린도전서',4,12,'또 수고하여 친히 손으로 일을 하며 모욕을 당한즉 축복하고 박해를 받은즉 참고',28445),
('1co-4-13','1co','고린도전서',4,13,'비방을 받은즉 권면하니 우리가 지금까지 세상의 더러운 것과 만물의 찌꺼기 같이 되었도다',28446),
('1co-4-14','1co','고린도전서',4,14,'내가 너희를 부끄럽게 하려고 이것을 쓰는 것이 아니라 오직 너희를 내 사랑하는 자녀 같이 권하려 하는 것이라',28447),
('1co-4-15','1co','고린도전서',4,15,'그리스도 안에서 일만 스승이 있으되 아버지는 많지 아니하니 그리스도 예수 안에서 내가 복음으로써 너희를 낳았음이라',28448),
('1co-4-16','1co','고린도전서',4,16,'그러므로 내가 너희에게 권하노니 너희는 나를 본받는 자가 되라',28449),
('1co-4-17','1co','고린도전서',4,17,'이로 말미암아 내가 주 안에서 내 사랑하고 신실한 아들 디모데를 너희에게 보내었으니 그가 너희로 하여금 그리스도 예수 안에서 나의 행사 곧 내가 각처 각 교회에서 가르치는 것을 생각나게 하리라',28450),
('1co-4-18','1co','고린도전서',4,18,'어떤 이들은 내가 너희에게 나아가지 아니할 것 같이 스스로 교만하여졌으나',28451),
('1co-4-19','1co','고린도전서',4,19,'주께서 허락하시면 내가 너희에게 속히 나아가서 교만한 자들의 말이 아니라 오직 그 능력을 알아보겠으니',28452),
('1co-4-20','1co','고린도전서',4,20,'하나님의 나라는 말에 있지 아니하고 오직 능력에 있음이라',28453),
('1co-4-21','1co','고린도전서',4,21,'너희가 무엇을 원하느냐 내가 매를 가지고 너희에게 나아가랴 사랑과 온유한 마음으로 나아가랴',28454),
('1co-5-1','1co','고린도전서',5,1,'너희 중에 심지어 음행이 있다 함을 들으니 그런 음행은 이방인 중에서도 없는 것이라 누가 그 아버지의 아내를 취하였다 하는도다',28455),
('1co-5-2','1co','고린도전서',5,2,'그리하고도 너희가 오히려 교만하여져서 어찌하여 통한히 여기지 아니하고 그 일 행한 자를 너희 중에서 쫓아내지 아니하였느냐',28456),
('1co-5-3','1co','고린도전서',5,3,'내가 실로 몸으로는 떠나 있으나 영으로는 함께 있어서 거기 있는 것 같이 이런 일 행한 자를 이미 판단하였노라',28457),
('1co-5-4','1co','고린도전서',5,4,'주 예수의 이름으로 너희가 내 영과 함께 모여서 우리 주 예수의 능력으로',28458),
('1co-5-5','1co','고린도전서',5,5,'이런 자를 사탄에게 내주었으니 이는 육신은 멸하고 영은 주 예수의 날에 구원을 받게 하려 함이라',28459),
('1co-5-6','1co','고린도전서',5,6,'너희가 자랑하는 것이 옳지 아니하도다 적은 누룩이 온 덩어리에 퍼지는 것을 알지 못하느냐',28460),
('1co-5-7','1co','고린도전서',5,7,'너희는 누룩 없는 자인데 새 덩어리가 되기 위하여 묵은 누룩을 내버리라 우리의 유월절 양 곧 그리스도께서 희생되셨느니라',28461),
('1co-5-8','1co','고린도전서',5,8,'이러므로 우리가 명절을 지키되 묵은 누룩으로도 말고 악하고 악의에 찬 누룩으로도 말고 누룩이 없이 오직 순전함과 진실함의 떡으로 하자',28462),
('1co-5-9','1co','고린도전서',5,9,'내가 너희에게 쓴 편지에 음행하는 자들을 사귀지 말라 하였거니와',28463),
('1co-5-10','1co','고린도전서',5,10,'이 말은 이 세상의 음행하는 자들이나 탐하는 자들이나 속여 빼앗는 자들이나 우상 숭배하는 자들을 도무지 사귀지 말라 하는 것이 아니니 만일 그리하려면 너희가 세상 밖으로 나가야 할 것이라',28464),
('1co-5-11','1co','고린도전서',5,11,'이제 내가 너희에게 쓴 것은 만일 어떤 형제라 일컫는 자가 음행하거나 탐욕을 부리거나 우상 숭배를 하거나 모욕하거나 술 취하거나 속여 빼앗거든 사귀지도 말고 그런 자와는 함께 먹지도 말라 함이라',28465),
('1co-5-12','1co','고린도전서',5,12,'밖에 있는 사람들을 판단하는 것이야 내게 무슨 상관이 있으리요마는 교회 안에 있는 사람들이야 너희가 판단하지 아니하랴',28466),
('1co-5-13','1co','고린도전서',5,13,'밖에 있는 사람들은 하나님이 심판하시려니와 이 악한 사람은 너희 중에서 내쫓으라',28467),
('1co-6-1','1co','고린도전서',6,1,'너희 중에 누가 다른 이와 더불어 다툼이 있는데 구태여 불의한 자들 앞에서 고발하고 성도 앞에서 하지 아니하느냐',28468),
('1co-6-2','1co','고린도전서',6,2,'성도가 세상을 판단할 것을 너희가 알지 못하느냐 세상도 너희에게 판단을 받겠거든 지극히 작은 일 판단하기를 감당하지 못하겠느냐',28469),
('1co-6-3','1co','고린도전서',6,3,'우리가 천사를 판단할 것을 너희가 알지 못하느냐 그러하거든 하물며 세상 일이랴',28470),
('1co-6-4','1co','고린도전서',6,4,'그런즉 너희가 세상 사건이 있을 때에 교회에서 경히 여김을 받는 자들을 세우느냐',28471),
('1co-6-5','1co','고린도전서',6,5,'내가 너희를 부끄럽게 하려 하여 이 말을 하노니 너희 가운데 그 형제간의 일을 판단할 만한 지혜 있는 자가 이같이 하나도 없느냐',28472),
('1co-6-6','1co','고린도전서',6,6,'형제가 형제와 더불어 고발할 뿐더러 믿지 아니하는 자들 앞에서 하느냐',28473),
('1co-6-7','1co','고린도전서',6,7,'너희가 피차 고발함으로 너희 가운데 이미 뚜렷한 허물이 있나니 차라리 불의를 당하는 것이 낫지 아니하며 차라리 속는 것이 낫지 아니하냐',28474),
('1co-6-8','1co','고린도전서',6,8,'너희는 불의를 행하고 속이는구나 그는 너희 형제로다',28475),
('1co-6-9','1co','고린도전서',6,9,'불의한 자가 하나님의 나라를 유업으로 받지 못할 줄을 알지 못하느냐 미혹을 받지 말라 음행하는 자나 우상 숭배하는 자나 간음하는 자나 탐색하는 자나 남색하는 자나',28476),
('1co-6-10','1co','고린도전서',6,10,'도적이나 탐욕을 부리는 자나 술 취하는 자나 모욕하는 자나 속여 빼앗는 자들은 하나님의 나라를 유업으로 받지 못하리라',28477),
('1co-6-11','1co','고린도전서',6,11,'너희 중에 이와 같은 자들이 있더니 주 예수 그리스도의 이름과 우리 하나님의 성령 안에서 씻음과 거룩함과 의롭다 하심을 받았느니라',28478),
('1co-6-12','1co','고린도전서',6,12,'모든 것이 내게 가하나 다 유익한 것이 아니요 모든 것이 내게 가하나 내가 무엇에든지 얽매이지 아니하리라',28479),
('1co-6-13','1co','고린도전서',6,13,'음식은 배를 위하여 있고 배는 음식을 위하여 있으나 하나님은 이것 저것을 다 폐하시리라 몸은 음란을 위하여 있지 않고 오직 주를 위하여 있으며 주는 몸을 위하여 계시느니라',28480),
('1co-6-14','1co','고린도전서',6,14,'하나님이 주를 다시 살리셨고 또한 그의 권능으로 우리를 다시 살리시리라',28481),
('1co-6-15','1co','고린도전서',6,15,'너희 몸이 그리스도의 지체인 줄을 알지 못하느냐 내가 그리스도의 지체를 가지고 창녀의 지체를 만들겠느냐 결코 그럴 수 없느니라',28482),
('1co-6-16','1co','고린도전서',6,16,'창녀와 합하는 자는 그와 한 몸인 줄을 알지 못하느냐 일렀으되 둘이 한 육체가 된다 하셨나니',28483),
('1co-6-17','1co','고린도전서',6,17,'주와 합하는 자는 한 영이니라',28484),
('1co-6-18','1co','고린도전서',6,18,'음행을 피하라 사람이 범하는 죄마다 몸 밖에 있거니와 음행하는 자는 자기 몸에 죄를 범하느니라',28485),
('1co-6-19','1co','고린도전서',6,19,'너희 몸은 너희가 하나님께로부터 받은 바 너희 가운데 계신 성령의 전인 줄을 알지 못하느냐 너희는 너희 자신의 것이 아니라',28486),
('1co-6-20','1co','고린도전서',6,20,'값으로 산 것이 되었으니 그런즉 너희 몸으로 하나님께 영광을 돌리라',28487),
('1co-7-1','1co','고린도전서',7,1,'너희가 쓴 문제에 대하여 말하면 남자가 여자를 가까이 아니함이 좋으나',28488),
('1co-7-2','1co','고린도전서',7,2,'음행을 피하기 위하여 남자마다 자기 아내를 두고 여자마다 자기 남편을 두라',28489),
('1co-7-3','1co','고린도전서',7,3,'남편은 그 아내에 대한 의무를 다하고 아내도 그 남편에게 그렇게 할지라',28490),
('1co-7-4','1co','고린도전서',7,4,'아내는 자기 몸을 주장하지 못하고 오직 그 남편이 하며 남편도 그와 같이 자기 몸을 주장하지 못하고 오직 그 아내가 하나니',28491),
('1co-7-5','1co','고린도전서',7,5,'서로 분방하지 말라 다만 기도할 틈을 얻기 위하여 합의상 얼마 동안은 하되 다시 합하라 이는 너희가 절제 못함으로 말미암아 사탄이 너희를 시험하지 못하게 하려 함이라',28492),
('1co-7-6','1co','고린도전서',7,6,'그러나 내가 이 말을 함은 허락이요 명령은 아니니라',28493),
('1co-7-7','1co','고린도전서',7,7,'나는 모든 사람이 나와 같기를 원하노라 그러나 각각 하나님께 받은 자기의 은사가 있으니 이 사람은 이러하고 저 사람은 저러하니라',28494),
('1co-7-8','1co','고린도전서',7,8,'내가 결혼하지 아니한 자들과 과부들에게 이르노니 나와 같이 그냥 지내는 것이 좋으니라',28495),
('1co-7-9','1co','고린도전서',7,9,'만일 절제할 수 없거든 결혼하라 정욕이 불 같이 타는 것보다 결혼하는 것이 나으니라',28496),
('1co-7-10','1co','고린도전서',7,10,'결혼한 자들에게 내가 명하노니 (명하는 자는 내가 아니요 주시라) 여자는 남편에게서 갈라서지 말고',28497),
('1co-7-11','1co','고린도전서',7,11,'(만일 갈라섰으면 그대로 지내든지 다시 그 남편과 화합하든지 하라) 남편도 아내를 버리지 말라',28498),
('1co-7-12','1co','고린도전서',7,12,'그 나머지 사람들에게 내가 말하노니 (이는 주의 명령이 아니라) 만일 어떤 형제에게 믿지 아니하는 아내가 있어 남편과 함께 살기를 좋아하거든 그를 버리지 말며',28499),
('1co-7-13','1co','고린도전서',7,13,'어떤 여자에게 믿지 아니하는 남편이 있어 아내와 함께 살기를 좋아하거든 그 남편을 버리지 말라',28500),
('1co-7-14','1co','고린도전서',7,14,'믿지 아니하는 남편이 아내로 말미암아 거룩하게 되고 믿지 아니하는 아내가 남편으로 말미암아 거룩하게 되나니 그렇지 아니하면 너희 자녀도 깨끗하지 못하니라 그러나 이제 거룩하니라',28501),
('1co-7-15','1co','고린도전서',7,15,'혹 믿지 아니하는 자가 갈리거든 갈리게 하라 형제나 자매나 이런 일에 구애될 것이 없느니라 그러나 하나님은 화평 중에서 너희를 부르셨느니라',28502),
('1co-7-16','1co','고린도전서',7,16,'아내 된 자여 네가 남편을 구원할는지 어찌 알 수 있으며 남편 된 자여 네가 네 아내를 구원할는지 어찌 알 수 있으리요',28503),
('1co-7-17','1co','고린도전서',7,17,'오직 주께서 각 사람에게 나눠 주신 대로 하나님이 각 사람을 부르신 그대로 행하라 내가 모든 교회에서 이와 같이 명하노라',28504),
('1co-7-18','1co','고린도전서',7,18,'할례자로서 부르심을 받은 자가 있느냐 무할례자가 되지 말며 무할례자로 부르심을 받은 자가 있느냐 할례를 받지 말라',28505),
('1co-7-19','1co','고린도전서',7,19,'할례 받는 것도 아무 것도 아니요 할례 받지 아니하는 것도 아무 것도 아니로되 오직 하나님의 계명을 지킬 따름이니라',28506),
('1co-7-20','1co','고린도전서',7,20,'각 사람은 부르심을 받은 그 부르심 그대로 지내라',28507),
('1co-7-21','1co','고린도전서',7,21,'네가 종으로 있을 때에 부르심을 받았느냐 염려하지 말라 그러나 네가 자유롭게 될 수 있거든 그것을 이용하라',28508),
('1co-7-22','1co','고린도전서',7,22,'주 안에서 부르심을 받은 자는 종이라도 주께 속한 자유인이요 또 그와 같이 자유인으로 있을 때에 부르심을 받은 자는 그리스도의 종이니라',28509),
('1co-7-23','1co','고린도전서',7,23,'너희는 값으로 사신 것이니 사람들의 종이 되지 말라',28510),
('1co-7-24','1co','고린도전서',7,24,'형제들아 너희는 각각 부르심을 받은 그대로 하나님과 함께 거하라',28511),
('1co-7-25','1co','고린도전서',7,25,'처녀에 대하여는 내가 주께 받은 계명이 없으되 주의 자비하심을 받아서 충성스러운 자가 된 내가 의견을 말하노니',28512),
('1co-7-26','1co','고린도전서',7,26,'내 생각에는 이것이 좋으니 곧 임박한 환난으로 말미암아 사람이 그냥 지내는 것이 좋으니라',28513),
('1co-7-27','1co','고린도전서',7,27,'네가 아내에게 매였느냐 놓이기를 구하지 말며 아내에게서 놓였느냐 아내를 구하지 말라',28514),
('1co-7-28','1co','고린도전서',7,28,'그러나 장가 가도 죄 짓는 것이 아니요 처녀가 시집 가도 죄 짓는 것이 아니로되 이런 이들은 육신에 고난이 있으리니 나는 너희를 아끼노라',28515),
('1co-7-29','1co','고린도전서',7,29,'형제들아 내가 이 말을 하노니 그 때가 단축하여진 고로 이후부터 아내 있는 자들은 없는 자 같이 하며',28516),
('1co-7-30','1co','고린도전서',7,30,'우는 자들은 울지 않는 자 같이 하며 기쁜 자들은 기쁘지 않은 자 같이 하며 매매하는 자들은 없는 자 같이 하며',28517),
('1co-7-31','1co','고린도전서',7,31,'세상 물건을 쓰는 자들은 다 쓰지 못하는 자 같이 하라 이 세상의 외형은 지나감이니라',28518),
('1co-7-32','1co','고린도전서',7,32,'너희가 염려 없기를 원하노라 장가 가지 않은 자는 주의 일을 염려하여 어찌하여야 주를 기쁘시게 할까 하되',28519),
('1co-7-33','1co','고린도전서',7,33,'장가 간 자는 세상 일을 염려하여 어찌하여야 아내를 기쁘게 할까 하여',28520),
('1co-7-34','1co','고린도전서',7,34,'마음이 갈라지며 시집 가지 않은 자와 처녀는 주의 일을 염려하여 몸과 영을 다 거룩하게 하려 하되 시집 간 자는 세상 일을 염려하여 어찌하여야 남편을 기쁘게 할까 하느니라',28521),
('1co-7-35','1co','고린도전서',7,35,'내가 이것을 말함은 너희의 유익을 위함이요 너희에게 올무를 놓으려 함이 아니니 오직 너희로 하여금 이치에 합당하게 하여 흐트러짐이 없이 주를 섬기게 하려 함이라',28522),
('1co-7-36','1co','고린도전서',7,36,'그러므로 만일 누가 자기의 약혼녀에 대한 행동이 합당하지 못한 줄로 생각할 때에 그 약혼녀의 혼기도 지나고 그같이 할 필요가 있거든 원하는 대로 하라 그것은 죄 짓는 것이 아니니 그들로 결혼하게 하라',28523),
('1co-7-37','1co','고린도전서',7,37,'그러나 그가 마음을 정하고 또 부득이한 일도 없고 자기 뜻대로 할 권리가 있어서 그 약혼녀를 그대로 두기로 하여도 잘하는 것이니라',28524),
('1co-7-38','1co','고린도전서',7,38,'그러므로 결혼하는 자도 잘하거니와 결혼하지 아니하는 자는 더 잘하는 것이니라',28525),
('1co-7-39','1co','고린도전서',7,39,'아내는 그 남편이 살아 있는 동안에 매여 있다가 남편이 죽으면 자유로워 자기 뜻대로 시집 갈 것이나 주 안에서만 할 것이니라',28526),
('1co-7-40','1co','고린도전서',7,40,'그러나 내 뜻에는 그냥 지내는 것이 더욱 복이 있으리로다 나도 또한 하나님의 영을 받은 줄로 생각하노라',28527),
('1co-8-1','1co','고린도전서',8,1,'우상의 제물에 대하여는 우리가 다 지식이 있는 줄을 아나 지식은 교만하게 하며 사랑은 덕을 세우나니',28528),
('1co-8-2','1co','고린도전서',8,2,'만일 누구든지 무엇을 아는 줄로 생각하면 아직도 마땅히 알 것을 알지 못하는 것이요',28529),
('1co-8-3','1co','고린도전서',8,3,'또 누구든지 하나님을 사랑하면 그 사람은 하나님도 알아 주시느니라',28530),
('1co-8-4','1co','고린도전서',8,4,'그러므로 우상의 제물을 먹는 일에 대하여는 우리가 우상은 세상에 아무 것도 아니며 또한 하나님은 한 분밖에 없는 줄 아노라',28531),
('1co-8-5','1co','고린도전서',8,5,'비록 하늘에나 땅에나 신이라 불리는 자가 있어 많은 신과 많은 주가 있으나',28532),
('1co-8-6','1co','고린도전서',8,6,'그러나 우리에게는 한 하나님 곧 아버지가 계시니 만물이 그에게서 났고 우리도 그를 위하여 있고 또한 한 주 예수 그리스도께서 계시니 만물이 그로 말미암고 우리도 그로 말미암아 있느니라',28533),
('1co-8-7','1co','고린도전서',8,7,'그러나 이 지식은 모든 사람에게 있는 것은 아니므로 어떤 이들은 지금까지 우상에 대한 습관이 있어 우상의 제물로 알고 먹는 고로 그들의 양심이 약하여지고 더러워지느니라',28534),
('1co-8-8','1co','고린도전서',8,8,'음식은 우리를 하나님 앞에 내세우지 못하나니 우리가 먹지 않는다고 해서 더 못사는 것도 아니고 먹는다고 해서 더 잘사는 것도 아니니라',28535),
('1co-8-9','1co','고린도전서',8,9,'그런즉 너희의 자유가 믿음이 약한 자들에게 걸려 넘어지게 하는 것이 되지 않도록 조심하라',28536),
('1co-8-10','1co','고린도전서',8,10,'지식 있는 네가 우상의 집에 앉아 먹는 것을 누구든지 보면 그 믿음이 약한 자들의 양심이 담력을 얻어 우상의 제물을 먹게 되지 않겠느냐',28537),
('1co-8-11','1co','고린도전서',8,11,'그러면 네 지식으로 그 믿음이 약한 자가 멸망하나니 그는 그리스도께서 위하여 죽으신 형제라',28538),
('1co-8-12','1co','고린도전서',8,12,'이같이 너희가 형제에게 죄를 지어 그 약한 양심을 상하게 하는 것이 곧 그리스도에게 죄를 짓는 것이니라',28539),
('1co-8-13','1co','고린도전서',8,13,'그러므로 만일 음식이 내 형제를 실족하게 한다면 나는 영원히 고기를 먹지 아니하여 내 형제를 실족하지 않게 하리라',28540),
('1co-9-1','1co','고린도전서',9,1,'내가 자유인이 아니냐 사도가 아니냐 예수 우리 주를 보지 못하였느냐 주 안에서 행한 나의 일이 너희가 아니냐',28541),
('1co-9-2','1co','고린도전서',9,2,'다른 사람들에게는 내가 사도가 아닐지라도 너희에게는 사도이니 나의 사도 됨을 주 안에서 인친 것이 너희라',28542),
('1co-9-3','1co','고린도전서',9,3,'나를 비판하는 자들에게 변명할 것이 이것이니',28543),
('1co-9-4','1co','고린도전서',9,4,'우리가 먹고 마실 권리가 없겠느냐',28544),
('1co-9-5','1co','고린도전서',9,5,'우리가 다른 사도들과 주의 형제들과 게바와 같이 믿음의 자매 된 아내를 데리고 다닐 권리가 없겠느냐',28545),
('1co-9-6','1co','고린도전서',9,6,'어찌 나와 바나바만 일하지 아니할 권리가 없겠느냐',28546),
('1co-9-7','1co','고린도전서',9,7,'누가 자기 비용으로 군 복무를 하겠느냐 누가 포도를 심고 그 열매를 먹지 않겠느냐 누가 양 떼를 기르고 그 양 떼의 젖을 먹지 않겠느냐',28547),
('1co-9-8','1co','고린도전서',9,8,'내가 사람의 예대로 이것을 말하느냐 율법도 이것을 말하지 아니하느냐',28548),
('1co-9-9','1co','고린도전서',9,9,'모세의 율법에 곡식을 밟아 떠는 소에게 망을 씌우지 말라 기록하였으니 하나님께서 어찌 소들을 위하여 염려하심이냐',28549),
('1co-9-10','1co','고린도전서',9,10,'오로지 우리를 위하여 말씀하심이 아니냐 과연 우리를 위하여 기록된 것이니 밭 가는 자는 소망을 가지고 갈며 곡식 떠는 자는 함께 얻을 소망을 가지고 떠는 것이라',28550),
('1co-9-11','1co','고린도전서',9,11,'우리가 너희에게 신령한 것을 뿌렸은즉 너희의 육적인 것을 거두기로 과하다 하겠느냐',28551),
('1co-9-12','1co','고린도전서',9,12,'다른 이들도 너희에게 이런 권리를 가졌거든 하물며 우리일까보냐 그러나 우리가 이 권리를 쓰지 아니하고 범사에 참는 것은 그리스도의 복음에 아무 장애가 없게 하려 함이로다',28552),
('1co-9-13','1co','고린도전서',9,13,'성전의 일을 하는 이들은 성전에서 나는 것을 먹으며 제단에서 섬기는 이들은 제단과 함께 나누는 것을 너희가 알지 못하느냐',28553),
('1co-9-14','1co','고린도전서',9,14,'이와 같이 주께서도 복음 전하는 자들이 복음으로 말미암아 살리라 명하셨느니라',28554),
('1co-9-15','1co','고린도전서',9,15,'그러나 내가 이것을 하나도 쓰지 아니하였고 또 이 말을 쓰는 것은 내게 이같이 하여 달라는 것이 아니라 내가 차라리 죽을지언정 누구든지 내 자랑하는 것을 헛된 데로 돌리지 못하게 하리라',28555),
('1co-9-16','1co','고린도전서',9,16,'내가 복음을 전할지라도 자랑할 것이 없음은 내가 부득불 할 일임이라 만일 복음을 전하지 아니하면 내게 화가 있을 것이로다',28556),
('1co-9-17','1co','고린도전서',9,17,'내가 내 자의로 이것을 행하면 상을 얻으려니와 내가 자의로 아니한다 할지라도 나는 사명을 받았노라',28557),
('1co-9-18','1co','고린도전서',9,18,'그런즉 내 상이 무엇이냐 내가 복음을 전할 때에 값없이 전하고 복음으로 말미암아 내게 있는 권리를 다 쓰지 아니하는 이것이로다',28558),
('1co-9-19','1co','고린도전서',9,19,'내가 모든 사람에게서 자유로우나 스스로 모든 사람에게 종이 된 것은 더 많은 사람을 얻고자 함이라',28559),
('1co-9-20','1co','고린도전서',9,20,'유대인들에게 내가 유대인과 같이 된 것은 유대인들을 얻고자 함이요 율법 아래에 있는 자들에게는 내가 율법 아래에 있지 아니하나 율법 아래에 있는 자 같이 된 것은 율법 아래에 있는 자들을 얻고자 함이요',28560),
('1co-9-21','1co','고린도전서',9,21,'율법 없는 자에게는 내가 하나님께는 율법 없는 자가 아니요 도리어 그리스도의 율법 아래에 있는 자이나 율법 없는 자와 같이 된 것은 율법 없는 자들을 얻고자 함이라',28561),
('1co-9-22','1co','고린도전서',9,22,'약한 자들에게 내가 약한 자와 같이 된 것은 약한 자들을 얻고자 함이요 내가 여러 사람에게 여러 모습이 된 것은 아무쪼록 몇 사람이라도 구원하고자 함이니',28562),
('1co-9-23','1co','고린도전서',9,23,'내가 복음을 위하여 모든 것을 행함은 복음에 참여하고자 함이라',28563),
('1co-9-24','1co','고린도전서',9,24,'운동장에서 달음질하는 자들이 다 달릴지라도 오직 상을 받는 사람은 한 사람인 줄을 너희가 알지 못하느냐 너희도 상을 받도록 이와 같이 달음질하라',28564),
('1co-9-25','1co','고린도전서',9,25,'이기기를 다투는 자마다 모든 일에 절제하나니 그들은 썩을 승리자의 관을 얻고자 하되 우리는 썩지 아니할 것을 얻고자 하노라',28565),
('1co-9-26','1co','고린도전서',9,26,'그러므로 나는 달음질하기를 향방 없는 것 같이 아니하고 싸우기를 허공을 치는 것 같이 아니하며',28566),
('1co-9-27','1co','고린도전서',9,27,'내가 내 몸을 쳐 복종하게 함은 내가 남에게 전파한 후에 자신이 도리어 버림을 당할까 두려워함이로다',28567),
('1co-10-1','1co','고린도전서',10,1,'형제들아 나는 너희가 알지 못하기를 원하지 아니하노니 우리 조상들이 다 구름 아래에 있고 바다 가운데로 지나며',28568),
('1co-10-2','1co','고린도전서',10,2,'모세에게 속하여 다 구름과 바다에서 세례를 받고',28569),
('1co-10-3','1co','고린도전서',10,3,'다 같은 신령한 음식을 먹으며',28570),
('1co-10-4','1co','고린도전서',10,4,'다 같은 신령한 음료를 마셨으니 이는 그들을 따르는 신령한 반석으로부터 마셨으매 그 반석은 곧 그리스도시라',28571),
('1co-10-5','1co','고린도전서',10,5,'그러나 그들의 다수를 하나님이 기뻐하지 아니하셨으므로 그들이 광야에서 멸망을 받았느니라',28572),
('1co-10-6','1co','고린도전서',10,6,'이러한 일은 우리의 본보기가 되어 우리로 하여금 그들이 악을 즐겨 한 것 같이 즐겨 하는 자가 되지 않게 하려 함이니',28573),
('1co-10-7','1co','고린도전서',10,7,'그들 가운데 어떤 사람들과 같이 너희는 우상 숭배하는 자가 되지 말라 기록된 바 백성이 앉아서 먹고 마시며 일어나서 뛰논다 함과 같으니라',28574),
('1co-10-8','1co','고린도전서',10,8,'그들 중의 어떤 사람들이 음행하다가 하루에 이만 삼천 명이 죽었나니 우리는 그들과 같이 음행하지 말자',28575),
('1co-10-9','1co','고린도전서',10,9,'그들 가운데 어떤 사람들이 주를 시험하다가 뱀에게 멸망하였나니 우리는 그들과 같이 시험하지 말자',28576),
('1co-10-10','1co','고린도전서',10,10,'그들 가운데 어떤 사람들이 원망하다가 멸망시키는 자에게 멸망하였나니 너희는 그들과 같이 원망하지 말라',28577),
('1co-10-11','1co','고린도전서',10,11,'그들에게 일어난 이런 일은 본보기가 되고 또한 말세를 만난 우리를 깨우치기 위하여 기록되었느니라',28578),
('1co-10-12','1co','고린도전서',10,12,'그런즉 선 줄로 생각하는 자는 넘어질까 조심하라',28579),
