('1co-10-16','1co','고린도전서',10,16,'우리가 축복하는 바 축복의 잔은 그리스도의 피에 참여함이 아니며 우리가 떼는 떡은 그리스도의 몸에 참여함이 아니냐',28583),
('1co-10-17','1co','고린도전서',10,17,'떡이 하나요 많은 우리가 한 몸이니 이는 우리가 다 한 떡에 참여함이라',28584),
