('1co-16-22','1co','고린도전서',16,22,'만일 누구든지 주를 사랑하지 아니하면 저주를 받을지어다 우리 주여 오시옵소서',28798),
('1co-16-23','1co','고린도전서',16,23,'주 예수 그리스도의 은혜가 너희와 함께 하고',28799),
('1co-16-24','1co','고린도전서',16,24,'나의 사랑이 그리스도 예수 안에서 너희 무리와 함께 할지어다',28800),
('2co-1-1','2co','고린도후서',1,1,'하나님의 뜻으로 말미암아 그리스도 예수의 사도 된 바울과 형제 디모데는 고린도에 있는 하나님의 교회와 또 온 아가야에 있는 모든 성도에게',28801),
('2co-1-2','2co','고린도후서',1,2,'하나님 우리 아버지와 주 예수 그리스도로부터 은혜와 평강이 있기를 원하노라',28802),
('2co-1-3','2co','고린도후서',1,3,'찬송하리로다 그는 우리 주 예수 그리스도의 하나님이시요 자비의 아버지시요 모든 위로의 하나님이시며',28803),
('2co-1-4','2co','고린도후서',1,4,'우리의 모든 환난 중에서 우리를 위로하사 우리로 하여금 하나님께 받는 위로로써 모든 환난 중에 있는 자들을 능히 위로하게 하시는 이시로다',28804),
('2co-1-5','2co','고린도후서',1,5,'그리스도의 고난이 우리에게 넘친 것 같이 우리가 받는 위로도 그리스도로 말미암아 넘치는도다',28805),
('2co-1-6','2co','고린도후서',1,6,'우리가 환난 당하는 것도 너희가 위로와 구원을 받게 하려는 것이요 우리가 위로를 받는 것도 너희가 위로를 받게 하려는 것이니 이 위로가 너희 속에 역사하여 우리가 받는 것 같은 고난을 너희도 견디게 하느니라',28806),
('2co-1-7','2co','고린도후서',1,7,'너희를 위한 우리의 소망이 견고함은 너희가 고난에 참여하는 자가 된 것 같이 위로에도 그러할 줄을 앎이라',28807),
('2co-1-8','2co','고린도후서',1,8,'형제들아 우리가 아시아에서 당한 환난을 너희가 모르기를 원하지 아니하노니 힘에 겹도록 심한 고난을 당하여 살 소망까지 끊어지고',28808),
('2co-1-9','2co','고린도후서',1,9,'우리는 우리 자신이 사형 선고를 받은 줄 알았으니 이는 우리로 자기를 의지하지 말고 오직 죽은 자를 다시 살리시는 하나님만 의지하게 하심이라',28809),
('2co-1-10','2co','고린도후서',1,10,'그가 이같이 큰 사망에서 우리를 건지셨고 또 건지실 것이며 이후에도 건지시기를 그에게 바라노라',28810),
('2co-1-11','2co','고린도후서',1,11,'너희도 우리를 위하여 간구함으로 도우라 이는 우리가 많은 사람의 기도로 얻은 은사로 말미암아 많은 사람이 우리를 위하여 감사하게 하려 함이라',28811),
('2co-1-12','2co','고린도후서',1,12,'우리가 세상에서 특별히 너희에 대하여 하나님의 거룩함과 진실함으로 행하되 육체의 지혜로 하지 아니하고 하나님의 은혜로 행함은 우리 양심이 증언하는 바니 이것이 우리의 자랑이라',28812),
('2co-1-13','2co','고린도후서',1,13,'오직 너희가 읽고 아는 것 외에 우리가 다른 것을 쓰지 아니하노니 너희가 완전히 알기를 내가 바라는 것은',28813),
('2co-1-14','2co','고린도후서',1,14,'너희가 우리를 부분적으로 알았으나 우리 주 예수의 날에는 너희가 우리의 자랑이 되고 우리가 너희의 자랑이 되는 그것이라',28814),
('2co-1-15','2co','고린도후서',1,15,'내가 이 확신을 가지고 너희로 두 번 은혜를 얻게 하기 위하여 먼저 너희에게 이르렀다가',28815),
('2co-1-16','2co','고린도후서',1,16,'너희를 지나 마게도냐로 갔다가 다시 마게도냐에서 너희에게 가서 너희의 도움으로 유대로 가기를 계획하였으니',28816),
('2co-1-17','2co','고린도후서',1,17,'이렇게 계획할 때에 어찌 경솔히 하였으리요 혹 계획하기를 육체를 따라 계획하여 예 예 하면서 아니라 아니라 하는 일이 내게 있겠느냐',28817),
('2co-1-18','2co','고린도후서',1,18,'하나님은 미쁘시니라 우리가 너희에게 한 말은 예 하고 아니라 함이 없노라',28818),
('2co-1-19','2co','고린도후서',1,19,'우리 곧 나와 실루아노와 디모데로 말미암아 너희 가운데 전파된 하나님의 아들 예수 그리스도는 예 하고 아니라 함이 되지 아니하셨으니 그에게는 예만 되었느니라',28819),
('2co-1-20','2co','고린도후서',1,20,'하나님의 약속은 얼마든지 그리스도 안에서 예가 되니 그런즉 그로 말미암아 우리가 아멘 하여 하나님께 영광을 돌리게 되느니라',28820),
('2co-1-21','2co','고린도후서',1,21,'우리를 너희와 함께 그리스도 안에서 굳건하게 하시고 우리에게 기름을 부으신 이는 하나님이시니',28821),
('2co-1-22','2co','고린도후서',1,22,'그가 또한 우리에게 인치시고 보증으로 우리 마음에 성령을 주셨느니라',28822),
('2co-1-23','2co','고린도후서',1,23,'내가 내 목숨을 걸고 하나님을 불러 증언하시게 하노니 내가 다시 고린도에 가지 아니한 것은 너희를 아끼려 함이라',28823),
('2co-1-24','2co','고린도후서',1,24,'우리가 너희 믿음을 주관하려는 것이 아니요 오직 너희 기쁨을 돕는 자가 되려 함이니 이는 너희가 믿음에 섰음이라',28824),
('2co-2-1','2co','고린도후서',2,1,'내가 다시는 너희에게 근심 중에 나아가지 아니하기로 스스로 결심하였노니',28825),
('2co-2-2','2co','고린도후서',2,2,'내가 너희를 근심하게 한다면 내가 근심하게 한 자밖에 나를 기쁘게 할 자가 누구냐',28826),
('2co-2-3','2co','고린도후서',2,3,'내가 이같이 쓴 것은 내가 갈 때에 마땅히 나를 기쁘게 할 자로부터 도리어 근심을 얻을까 염려함이요 또 너희 모두에 대한 나의 기쁨이 너희 모두의 기쁨인 줄 확신함이로라',28827),
('2co-2-4','2co','고린도후서',2,4,'내가 마음에 큰 눌림과 걱정이 있어 많은 눈물로 너희에게 썼노니 이는 너희로 근심하게 하려 한 것이 아니요 오직 내가 너희를 향하여 넘치는 사랑이 있음을 너희로 알게 하려 함이라',28828),
('2co-2-5','2co','고린도후서',2,5,'근심하게 한 자가 있었을지라도 나를 근심하게 한 것이 아니요 어느 정도 너희 모두를 근심하게 한 것이니 어느 정도라 함은 내가 너무 지나치게 말하지 아니하려 함이라',28829),
('2co-2-6','2co','고린도후서',2,6,'이러한 사람은 많은 사람에게서 벌 받는 것이 마땅하도다',28830),
('2co-2-7','2co','고린도후서',2,7,'그런즉 너희는 차라리 그를 용서하고 위로할 것이니 그가 너무 많은 근심에 잠길까 두려워하노라',28831),
('2co-2-8','2co','고린도후서',2,8,'그러므로 너희를 권하노니 사랑을 그들에게 나타내라',28832),
('2co-2-9','2co','고린도후서',2,9,'너희가 범사에 순종하는지 그 증거를 알고자 하여 내가 이것을 너희에게 썼노라',28833),
('2co-2-10','2co','고린도후서',2,10,'너희가 무슨 일에든지 누구를 용서하면 나도 그리하고 내가 만일 용서한 일이 있으면 용서한 그것은 너희를 위하여 그리스도 앞에서 한 것이니',28834),
('2co-2-11','2co','고린도후서',2,11,'이는 우리로 사탄에게 속지 않게 하려 함이라 우리는 그 계책을 알지 못하는 바가 아니로라',28835),
('2co-2-12','2co','고린도후서',2,12,'내가 그리스도의 복음을 위하여 드로아에 이르매 주 안에서 문이 내게 열렸으되',28836),
('2co-2-13','2co','고린도후서',2,13,'내가 내 형제 디도를 만나지 못하므로 내 심령이 편하지 못하여 그들을 작별하고 마게도냐로 갔노라',28837),
('2co-2-14','2co','고린도후서',2,14,'항상 우리를 그리스도 안에서 이기게 하시고 우리로 말미암아 각처에서 그리스도를 아는 냄새를 나타내시는 하나님께 감사하노라',28838),
('2co-2-15','2co','고린도후서',2,15,'우리는 구원 받는 자들에게나 망하는 자들에게나 하나님 앞에서 그리스도의 향기니',28839),
('2co-2-16','2co','고린도후서',2,16,'이 사람에게는 사망으로부터 사망에 이르는 냄새요 저 사람에게는 생명으로부터 생명에 이르는 냄새라 누가 이 일을 감당하리요',28840),
('2co-2-17','2co','고린도후서',2,17,'우리는 수많은 사람들처럼 하나님의 말씀을 혼잡하게 하지 아니하고 곧 순전함으로 하나님께 받은 것 같이 하나님 앞에서와 그리스도 안에서 말하노라',28841),
('2co-3-1','2co','고린도후서',3,1,'우리가 다시 자천하기를 시작하겠느냐 우리가 어찌 어떤 사람처럼 추천서를 너희에게 부치거나 혹은 너희에게 받거나 할 필요가 있느냐',28842),
('2co-3-2','2co','고린도후서',3,2,'너희는 우리의 편지라 우리 마음에 썼고 뭇 사람이 알고 읽는 바라',28843),
