('2co-3-6','2co','고린도후서',3,6,'그가 또한 우리를 새 언약의 일꾼 되기에 만족하게 하셨으니 율법 조문으로 하지 아니하고 오직 영으로 함이니 율법 조문은 죽이는 것이요 영은 살리는 것이니라',28847),
('2co-3-7','2co','고린도후서',3,7,'돌에 써서 새긴 죽게 하는 율법 조문의 직분도 영광이 있어 이스라엘 자손들은 모세의 얼굴의 없어질 영광 때문에도 그 얼굴을 주목하지 못하였거든',28848),
('2co-3-8','2co','고린도후서',3,8,'하물며 영의 직분은 더욱 영광이 있지 아니하겠느냐',28849),
('2co-3-9','2co','고린도후서',3,9,'정죄의 직분도 영광이 있은즉 의의 직분은 영광이 더욱 넘치리라',28850),
('2co-3-10','2co','고린도후서',3,10,'영광되었던 것이 더 큰 영광으로 말미암아 이에 영광될 것이 없으나',28851),
('2co-3-11','2co','고린도후서',3,11,'없어질 것도 영광으로 말미암았은즉 길이 있을 것은 더욱 영광 가운데 있느니라',28852),
('2co-3-12','2co','고린도후서',3,12,'우리가 이같은 소망이 있으므로 담대히 말하노니',28853),
('2co-3-13','2co','고린도후서',3,13,'우리는 모세가 이스라엘 자손들에게 장차 없어질 것의 결국을 주목하지 못하게 하려고 수건을 그 얼굴에 쓴 것 같이 아니하노라',28854),
('2co-3-14','2co','고린도후서',3,14,'그러나 그들의 마음이 완고하여 오늘까지도 구약을 읽을 때에 그 수건이 벗겨지지 아니하고 있으니 그 수건은 그리스도 안에서 없어질 것이라',28855),
('2co-3-15','2co','고린도후서',3,15,'오늘까지 모세의 글을 읽을 때에 수건이 그 마음을 덮었도다',28856),
('2co-3-16','2co','고린도후서',3,16,'그러나 언제든지 주께로 돌아가면 그 수건이 벗겨지리라',28857),
('2co-3-17','2co','고린도후서',3,17,'주는 영이시니 주의 영이 계신 곳에는 자유가 있느니라',28858),
('2co-3-18','2co','고린도후서',3,18,'우리가 다 수건을 벗은 얼굴로 거울을 보는 것 같이 주의 영광을 보매 그와 같은 형상으로 변화하여 영광에서 영광에 이르니 곧 주의 영으로 말미암음이니라',28859),
('2co-4-1','2co','고린도후서',4,1,'그러므로 우리가 이 직분을 받아 긍휼하심을 입은 대로 낙심하지 아니하고',28860),
('2co-4-2','2co','고린도후서',4,2,'이에 숨은 부끄러움의 일을 버리고 속임으로 행하지 아니하며 하나님의 말씀을 혼잡하게 하지 아니하고 오직 진리를 나타냄으로 하나님 앞에서 각 사람의 양심에 대하여 스스로 추천하노라',28861),
('2co-4-3','2co','고린도후서',4,3,'만일 우리의 복음이 가리었으면 망하는 자들에게 가리어진 것이라',28862),
('2co-4-4','2co','고린도후서',4,4,'그 중에 이 세상의 신이 믿지 아니하는 자들의 마음을 혼미하게 하여 그리스도의 영광의 복음의 광채가 비치지 못하게 함이니 그리스도는 하나님의 형상이니라',28863),
('2co-4-5','2co','고린도후서',4,5,'우리는 우리를 전파하는 것이 아니라 오직 그리스도 예수의 주 되신 것과 또 예수를 위하여 우리가 너희의 종 된 것을 전파함이라',28864),
('2co-4-6','2co','고린도후서',4,6,'어두운 데에 빛이 비치라 말씀하셨던 그 하나님께서 예수 그리스도의 얼굴에 있는 하나님의 영광을 아는 빛을 우리 마음에 비추셨느니라',28865),
('2co-4-7','2co','고린도후서',4,7,'우리가 이 보배를 질그릇에 가졌으니 이는 심히 큰 능력은 하나님께 있고 우리에게 있지 아니함을 알게 하려 함이라',28866),
('2co-4-8','2co','고린도후서',4,8,'우리가 사방으로 우겨쌈을 당하여도 싸이지 아니하며 답답한 일을 당하여도 낙심하지 아니하며',28867),
('2co-4-9','2co','고린도후서',4,9,'박해를 받아도 버린 바 되지 아니하며 거꾸러뜨림을 당하여도 망하지 아니하고',28868),
('2co-4-10','2co','고린도후서',4,10,'우리가 항상 예수의 죽음을 몸에 짊어짐은 예수의 생명이 또한 우리 몸에 나타나게 하려 함이라',28869),
('2co-4-11','2co','고린도후서',4,11,'우리 살아 있는 자가 항상 예수를 위하여 죽음에 넘겨짐은 예수의 생명이 또한 우리 죽을 육체에 나타나게 하려 함이라',28870),
('2co-4-12','2co','고린도후서',4,12,'그런즉 사망은 우리 안에서 역사하고 생명은 너희 안에서 역사하느니라',28871),
('2co-4-13','2co','고린도후서',4,13,'기록된 바 내가 믿었으므로 말하였다 한 것 같이 우리가 같은 믿음의 마음을 가졌으니 우리도 믿었으므로 또한 말하노라',28872),
('2co-4-14','2co','고린도후서',4,14,'주 예수를 다시 살리신 이가 예수와 함께 우리도 다시 살리사 너희와 함께 그 앞에 서게 하실 줄을 아노라',28873),
('2co-4-15','2co','고린도후서',4,15,'이는 모든 것이 너희를 위함이니 많은 사람의 감사로 말미암아 은혜가 더하여 넘쳐서 하나님께 영광을 돌리게 하려 함이라',28874),
('2co-4-16','2co','고린도후서',4,16,'그러므로 우리가 낙심하지 아니하노니 우리의 겉사람은 낡아지나 우리의 속사람은 날로 새로워지도다',28875),
('2co-4-17','2co','고린도후서',4,17,'우리가 잠시 받는 환난의 경한 것이 지극히 크고 영원한 영광의 중한 것을 우리에게 이루게 함이니',28876),
('2co-4-18','2co','고린도후서',4,18,'우리가 주목하는 것은 보이는 것이 아니요 보이지 않는 것이니 보이는 것은 잠깐이요 보이지 않는 것은 영원함이라',28877),
('2co-5-1','2co','고린도후서',5,1,'만일 땅에 있는 우리의 장막 집이 무너지면 하나님께서 지으신 집 곧 손으로 지은 것이 아니요 하늘에 있는 영원한 집이 우리에게 있는 줄 아느니라',28878),
('2co-5-2','2co','고린도후서',5,2,'참으로 우리가 여기 있어 탄식하며 하늘로부터 오는 우리 처소로 덧입기를 간절히 사모하노라',28879),
('2co-5-3','2co','고린도후서',5,3,'이렇게 입음은 우리가 벗은 자들로 발견되지 않으려 함이라',28880),
('2co-5-4','2co','고린도후서',5,4,'참으로 이 장막에 있는 우리가 짐진 것 같이 탄식하는 것은 벗고자 함이 아니요 오히려 덧입고자 함이니 죽을 것이 생명에 삼킨 바 되게 하려 함이라',28881),
('2co-5-5','2co','고린도후서',5,5,'곧 이것을 우리에게 이루게 하시고 보증으로 성령을 우리에게 주신 이는 하나님이시니라',28882),
('2co-5-6','2co','고린도후서',5,6,'그러므로 우리가 항상 담대하여 몸으로 있을 때에는 주와 따로 있는 줄을 아노니',28883),
('2co-5-7','2co','고린도후서',5,7,'이는 우리가 믿음으로 행하고 보는 것으로 행하지 아니함이로라',28884),
('2co-5-8','2co','고린도후서',5,8,'우리가 담대하여 원하는 바는 차라리 몸을 떠나 주와 함께 있는 그것이라',28885),
('2co-5-9','2co','고린도후서',5,9,'그런즉 우리는 몸으로 있든지 떠나든지 주를 기쁘시게 하는 자가 되기를 힘쓰노라',28886),
('2co-5-10','2co','고린도후서',5,10,'이는 우리가 다 반드시 그리스도의 심판대 앞에 나타나게 되어 각각 선악간에 그 몸으로 행한 것을 따라 받으려 함이라',28887),
('2co-5-11','2co','고린도후서',5,11,'우리는 주의 두려우심을 알므로 사람들을 권면하거니와 우리가 하나님 앞에 알리어졌으니 또 너희의 양심에도 알리어지기를 바라노라',28888),
('2co-5-12','2co','고린도후서',5,12,'우리가 다시 너희에게 자천하는 것이 아니요 오직 우리로 말미암아 자랑할 기회를 너희에게 주어 마음으로 하지 않고 외모로 자랑하는 자들에게 대답하게 하려 하는 것이라',28889),
('2co-5-13','2co','고린도후서',5,13,'우리가 만일 미쳤어도 하나님을 위한 것이요 정신이 온전하여도 너희를 위한 것이니',28890),
('2co-5-14','2co','고린도후서',5,14,'그리스도의 사랑이 우리를 강권하시는도다 우리가 생각하건대 한 사람이 모든 사람을 대신하여 죽었은즉 모든 사람이 죽은 것이라',28891),
('2co-5-15','2co','고린도후서',5,15,'그가 모든 사람을 대신하여 죽으심은 살아 있는 자들로 하여금 다시는 그들 자신을 위하여 살지 않고 오직 그들을 대신하여 죽었다가 다시 살아나신 이를 위하여 살게 하려 함이라',28892),
('2co-5-16','2co','고린도후서',5,16,'그러므로 우리가 이제부터는 어떤 사람도 육신을 따라 알지 아니하노라 비록 우리가 그리스도도 육신을 따라 알았으나 이제부터는 그같이 알지 아니하노라',28893),
('2co-5-17','2co','고린도후서',5,17,'그런즉 누구든지 그리스도 안에 있으면 새로운 피조물이라 이전 것은 지나갔으니 보라 새 것이 되었도다',28894),
('2co-5-18','2co','고린도후서',5,18,'모든 것이 하나님께로서 났으며 그가 그리스도로 말미암아 우리를 자기와 화목하게 하시고 또 우리에게 화목하게 하는 직분을 주셨으니',28895),
('2co-5-19','2co','고린도후서',5,19,'곧 하나님께서 그리스도 안에 계시사 세상을 자기와 화목하게 하시며 그들의 죄를 그들에게 돌리지 아니하시고 화목하게 하는 말씀을 우리에게 부탁하셨느니라',28896),
('2co-5-20','2co','고린도후서',5,20,'그러므로 우리가 그리스도를 대신하여 사신이 되어 하나님이 우리를 통하여 너희를 권면하시는 것 같이 그리스도를 대신하여 간청하노니 너희는 하나님과 화목하라',28897),
('2co-5-21','2co','고린도후서',5,21,'하나님이 죄를 알지도 못하신 이를 우리를 대신하여 죄로 삼으신 것은 우리로 하여금 그 안에서 하나님의 의가 되게 하려 하심이라',28898),
('2co-6-1','2co','고린도후서',6,1,'우리가 하나님과 함께 일하는 자로서 너희를 권하노니 하나님의 은혜를 헛되이 받지 말라',28899),
('2co-6-2','2co','고린도후서',6,2,'이르시되 내가 은혜 베풀 때에 너에게 듣고 구원의 날에 너를 도왔다 하셨으니 보라 지금은 은혜 받을 만한 때요 보라 지금은 구원의 날이로다',28900),
('2co-6-3','2co','고린도후서',6,3,'우리가 이 직분이 비방을 받지 않게 하려고 무엇에든지 아무에게도 거리끼지 않게 하고',28901),
('2co-6-4','2co','고린도후서',6,4,'오직 모든 일에 하나님의 일꾼으로 자천하여 많이 견디는 것과 환난과 궁핍과 고난과',28902),
('2co-6-5','2co','고린도후서',6,5,'매 맞음과 갇힘과 난동과 수고로움과 자지 못함과 먹지 못함 가운데서도',28903),
('2co-6-6','2co','고린도후서',6,6,'깨끗함과 지식과 오래 참음과 자비함과 성령의 감화와 거짓이 없는 사랑과',28904),
('2co-6-7','2co','고린도후서',6,7,'진리의 말씀과 하나님의 능력으로 의의 무기를 좌우에 가지고',28905),
('2co-6-8','2co','고린도후서',6,8,'영광과 욕됨으로 그러했으며 악한 이름과 아름다운 이름으로 그러했느니라 우리는 속이는 자 같으나 참되고',28906),
('2co-6-9','2co','고린도후서',6,9,'무명한 자 같으나 유명한 자요 죽은 자 같으나 보라 우리가 살아 있고 징계를 받는 자 같으나 죽임을 당하지 아니하고',28907),
('2co-6-10','2co','고린도후서',6,10,'근심하는 자 같으나 항상 기뻐하고 가난한 자 같으나 많은 사람을 부요하게 하고 아무 것도 없는 자 같으나 모든 것을 가진 자로다',28908),
('2co-6-11','2co','고린도후서',6,11,'고린도인들이여 너희를 향하여 우리의 입이 열리고 우리의 마음이 넓어졌으니',28909),
('2co-6-12','2co','고린도후서',6,12,'너희가 우리 안에서 좁아진 것이 아니라 오직 너희 심정에서 좁아진 것이니라',28910),
('2co-6-13','2co','고린도후서',6,13,'내가 자녀에게 말하듯 하노니 보답하는 것으로 너희도 마음을 넓히라',28911),
('2co-6-14','2co','고린도후서',6,14,'너희는 믿지 않는 자와 멍에를 함께 메지 말라 의와 불법이 어찌 함께 하며 빛과 어둠이 어찌 사귀며',28912),
('2co-6-15','2co','고린도후서',6,15,'그리스도와 벨리알이 어찌 조화되며 믿는 자와 믿지 않는 자가 어찌 상관하며',28913),
('2co-6-16','2co','고린도후서',6,16,'하나님의 성전과 우상이 어찌 일치가 되리요 우리는 살아 계신 하나님의 성전이라 이와 같이 하나님께서 이르시되 내가 그들 가운데 거하며 두루 행하여 나는 그들의 하나님이 되고 그들은 나의 백성이 되리라',28914),
('2co-6-17','2co','고린도후서',6,17,'그러므로 너희는 그들 중에서 나와서 따로 있고 부정한 것을 만지지 말라 내가 너희를 영접하여',28915),
('2co-6-18','2co','고린도후서',6,18,'너희에게 아버지가 되고 너희는 내게 자녀가 되리라 전능하신 주의 말씀이니라 하셨느니라',28916),
('2co-7-1','2co','고린도후서',7,1,'그런즉 사랑하는 자들아 이 약속을 가진 우리는 하나님을 두려워하는 가운데서 거룩함을 온전히 이루어 육과 영의 온갖 더러운 것에서 자신을 깨끗하게 하자',28917),
('2co-7-2','2co','고린도후서',7,2,'마음으로 우리를 영접하라 우리는 아무에게도 불의를 행하지 않고 아무에게도 해롭게 하지 않고 아무에게서도 속여 빼앗은 일이 없노라',28918),
('2co-7-3','2co','고린도후서',7,3,'내가 이 말을 하는 것은 너희를 정죄하려고 하는 것이 아니라 내가 이전에 말하였거니와 너희가 우리 마음에 있어 함께 죽고 함께 살게 하고자 함이라',28919),
('2co-7-4','2co','고린도후서',7,4,'나는 너희를 향하여 담대한 것도 많고 너희를 위하여 자랑하는 것도 많으니 내가 우리의 모든 환난 가운데서도 위로가 가득하고 기쁨이 넘치는도다',28920),
('2co-7-5','2co','고린도후서',7,5,'우리가 마게도냐에 이르렀을 때에도 우리 육체가 편하지 못하였고 사방으로 환난을 당하여 밖으로는 다툼이요 안으로는 두려움이었노라',28921),
('2co-7-6','2co','고린도후서',7,6,'그러나 낙심한 자들을 위로하시는 하나님이 디도가 옴으로 우리를 위로하셨으니',28922),
('2co-7-7','2co','고린도후서',7,7,'그가 온 것뿐 아니요 오직 그가 너희에게서 받은 그 위로로 위로하고 너희의 사모함과 애통함과 나를 위하여 열심 있는 것을 우리에게 보고함으로 나를 더욱 기쁘게 하였느니라',28923),
('2co-7-8','2co','고린도후서',7,8,'그러므로 내가 편지로 너희를 근심하게 한 것을 후회하였으나 지금은 후회하지 아니함은 그 편지가 너희로 잠시만 근심하게 한 줄을 앎이라',28924),
('2co-7-9','2co','고린도후서',7,9,'내가 지금 기뻐함은 너희로 근심하게 한 까닭이 아니요 도리어 너희가 근심함으로 회개함에 이른 까닭이라 너희가 하나님의 뜻대로 근심하게 된 것은 우리에게서 아무 해도 받지 않게 하려 함이라',28925),
('2co-7-10','2co','고린도후서',7,10,'하나님의 뜻대로 하는 근심은 후회할 것이 없는 구원에 이르게 하는 회개를 이루는 것이요 세상 근심은 사망을 이루는 것이니라',28926),
('2co-7-11','2co','고린도후서',7,11,'보라 하나님의 뜻대로 하게 된 이 근심이 너희로 얼마나 간절하게 하며 얼마나 변증하게 하며 얼마나 분하게 하며 얼마나 두렵게 하며 얼마나 사모하게 하며 얼마나 열심 있게 하며 얼마나 벌하게 하였는가 너희가 그 일에 대하여 일체 너희 자신의 깨끗함을 나타내었느니라',28927),
('2co-7-12','2co','고린도후서',7,12,'그런즉 내가 너희에게 쓴 것은 그 불의를 행한 자를 위한 것도 아니요 그 불의를 당한 자를 위한 것도 아니요 오직 우리를 위한 너희의 간절함이 하나님 앞에서 너희에게 나타나게 하려 함이로라',28928),
('2co-7-13','2co','고린도후서',7,13,'이로 말미암아 우리가 위로를 받았고 우리가 받은 위로 위에 디도의 기쁨으로 우리가 더욱 많이 기뻐함은 그의 마음이 너희 무리로 말미암아 안심함을 얻었음이라',28929),
('2co-7-14','2co','고린도후서',7,14,'내가 그에게 너희를 위하여 자랑한 것이 있더라도 부끄럽지 아니하니 우리가 너희에게 이른 말이 다 참된 것 같이 디도 앞에서 우리가 자랑한 것도 참되게 되었도다',28930),
('2co-7-15','2co','고린도후서',7,15,'그가 너희 모든 사람들이 두려움과 떪으로 자기를 영접하여 순종한 것을 생각하고 너희를 향하여 그의 심정이 더욱 깊었으니',28931),
('2co-7-16','2co','고린도후서',7,16,'내가 범사에 너희를 신뢰하게 된 것을 기뻐하노라',28932),
('2co-8-1','2co','고린도후서',8,1,'형제들아 하나님께서 마게도냐 교회들에게 주신 은혜를 우리가 너희에게 알리노니',28933),
('2co-8-2','2co','고린도후서',8,2,'환난의 많은 시련 가운데서 그들의 넘치는 기쁨과 극심한 가난이 그들의 풍성한 연보를 넘치도록 하게 하였느니라',28934),
('2co-8-3','2co','고린도후서',8,3,'내가 증언하노니 그들이 힘대로 할 뿐 아니라 힘에 지나도록 자원하여',28935),
('2co-8-4','2co','고린도후서',8,4,'이 은혜와 성도 섬기는 일에 참여함에 대하여 우리에게 간절히 구하니',28936),
('2co-8-5','2co','고린도후서',8,5,'우리가 바라던 것뿐 아니라 그들이 먼저 자신을 주께 드리고 또 하나님의 뜻을 따라 우리에게 주었도다',28937),
('2co-8-6','2co','고린도후서',8,6,'그러므로 우리가 디도를 권하여 그가 이미 너희 가운데서 시작하였은즉 이 은혜를 그대로 성취하게 하라 하였노라',28938),
('2co-8-7','2co','고린도후서',8,7,'오직 너희는 믿음과 말과 지식과 모든 간절함과 우리를 사랑하는 이 모든 일에 풍성한 것 같이 이 은혜에도 풍성하게 할지니라',28939),
('2co-8-8','2co','고린도후서',8,8,'내가 명령으로 하는 말이 아니요 오직 다른 이들의 간절함을 가지고 너희의 사랑의 진실함을 증명하고자 함이로라',28940),
('2co-8-9','2co','고린도후서',8,9,'우리 주 예수 그리스도의 은혜를 너희가 알거니와 부요하신 이로서 너희를 위하여 가난하게 되심은 그의 가난함으로 말미암아 너희를 부요하게 하려 하심이라',28941),
('2co-8-10','2co','고린도후서',8,10,'이 일에 관하여 나의 뜻을 알리노니 이 일은 너희에게 유익함이라 너희가 일 년 전에 행하기를 먼저 시작할 뿐 아니라 원하기도 하였은즉',28942),
('2co-8-11','2co','고린도후서',8,11,'이제는 하던 일을 성취할지니 마음에 원하던 것과 같이 완성하되 있는 대로 하라',28943),
('2co-8-12','2co','고린도후서',8,12,'할 마음만 있으면 있는 대로 받으실 터이요 없는 것은 받지 아니하시리라',28944),
('2co-8-13','2co','고린도후서',8,13,'이는 다른 사람들은 평안하게 하고 너희는 곤고하게 하려는 것이 아니요 균등하게 하려 함이니',28945),
('2co-8-14','2co','고린도후서',8,14,'이제 너희의 넉넉한 것으로 그들의 부족한 것을 보충함은 후에 그들의 넉넉한 것으로 너희의 부족한 것을 보충하여 균등하게 하려 함이라',28946),
('2co-8-15','2co','고린도후서',8,15,'기록된 것 같이 많이 거둔 자도 남지 아니하였고 적게 거둔 자도 모자라지 아니하였느니라',28947),
('2co-8-16','2co','고린도후서',8,16,'너희를 위하여 같은 간절함을 디도의 마음에도 주시는 하나님께 감사하노니',28948),
('2co-8-17','2co','고린도후서',8,17,'그가 권함을 받고 더욱 간절함으로 자원하여 너희에게 나아갔고',28949),
('2co-8-18','2co','고린도후서',8,18,'또 그와 함께 그 형제를 보내었으니 이 사람은 복음으로써 모든 교회에서 칭찬을 받는 자요',28950),
('2co-8-19','2co','고린도후서',8,19,'이뿐 아니라 그는 동일한 주의 영광과 우리의 원을 나타내기 위하여 여러 교회의 택함을 받아 우리가 맡은 은혜의 일로 우리와 동행하는 자라',28951),
('2co-8-20','2co','고린도후서',8,20,'이것을 조심함은 우리가 맡은 이 거액의 연보에 대하여 아무도 우리를 비방하지 못하게 하려 함이니',28952),
('2co-8-21','2co','고린도후서',8,21,'이는 우리가 주 앞에서뿐 아니라 사람 앞에서도 선한 일에 조심하려 함이라',28953),
('2co-8-22','2co','고린도후서',8,22,'또 그들과 함께 우리의 한 형제를 보내었노니 우리는 그가 여러 가지 일에 간절한 것을 여러 번 확인하였거니와 이제 그가 너희를 크게 믿으므로 더욱 간절하니라',28954),
('2co-8-23','2co','고린도후서',8,23,'디도로 말하면 나의 동료요 너희를 위한 나의 동역자요 우리 형제들로 말하면 여러 교회의 사자들이요 그리스도의 영광이니라',28955),
('2co-8-24','2co','고린도후서',8,24,'그러므로 너희는 여러 교회 앞에서 너희의 사랑과 너희에 대한 우리 자랑의 증거를 그들에게 보이라',28956),
('2co-9-1','2co','고린도후서',9,1,'성도를 섬기는 일에 대하여는 내가 너희에게 쓸 필요가 없나니',28957),
('2co-9-2','2co','고린도후서',9,2,'이는 내가 너희의 원함을 앎이라 내가 너희를 위하여 마게도냐인들에게 아가야에서는 일 년 전부터 준비하였다는 것을 자랑하였는데 과연 너희의 열심이 퍽 많은 사람들을 분발하게 하였느니라',28958),
('2co-9-3','2co','고린도후서',9,3,'그런데 이 형제들을 보낸 것은 이 일에 너희를 위한 우리의 자랑이 헛되지 않고 내가 말한 것 같이 준비하게 하려 함이라',28959),
('2co-9-4','2co','고린도후서',9,4,'혹 마게도냐인들이 나와 함께 가서 너희가 준비하지 아니한 것을 보면 너희는 고사하고 우리가 이 믿던 것에 부끄러움을 당할까 두려워하노라',28960),
('2co-9-5','2co','고린도후서',9,5,'그러므로 내가 이 형제들로 먼저 너희에게 가서 너희가 전에 약속한 연보를 미리 준비하게 하도록 권면하는 것이 필요한 줄 생각하였노니 이렇게 준비하여야 참 연보답고 억지가 아니니라',28961),
('2co-9-6','2co','고린도후서',9,6,'이것이 곧 적게 심는 자는 적게 거두고 많이 심는 자는 많이 거둔다 하는 말이로다',28962),
('2co-9-7','2co','고린도후서',9,7,'각각 그 마음에 정한 대로 할 것이요 인색함으로나 억지로 하지 말지니 하나님은 즐겨 내는 자를 사랑하시느니라',28963),
('2co-9-8','2co','고린도후서',9,8,'하나님이 능히 모든 은혜를 너희에게 넘치게 하시나니 이는 너희로 모든 일에 항상 모든 것이 넉넉하여 모든 착한 일을 넘치게 하게 하려 하심이라',28964),
('2co-9-9','2co','고린도후서',9,9,'기록된 바 그가 흩어 가난한 자들에게 주었으니 그의 의가 영원토록 있느니라 함과 같으니라',28965),
('2co-9-10','2co','고린도후서',9,10,'심는 자에게 씨와 먹을 양식을 주시는 이가 너희 심을 것을 주사 풍성하게 하시고 너희 의의 열매를 더하게 하시리니',28966),
('2co-9-11','2co','고린도후서',9,11,'너희가 모든 일에 넉넉하여 너그럽게 연보를 함은 그들이 우리로 말미암아 하나님께 감사하게 하는 것이라',28967),
('2co-9-12','2co','고린도후서',9,12,'이 봉사의 직무가 성도들의 부족한 것을 보충할 뿐 아니라 사람들이 하나님께 드리는 많은 감사로 말미암아 넘쳤느니라',28968),
('2co-9-13','2co','고린도후서',9,13,'이 직무로 증거를 삼아 너희가 그리스도의 복음을 진실히 믿고 복종하는 것과 그들과 모든 사람을 섬기는 너희의 후한 연보로 말미암아 하나님께 영광을 돌리고',28969),
('2co-9-14','2co','고린도후서',9,14,'또 그들이 너희를 위하여 간구하며 하나님이 너희에게 주신 지극한 은혜로 말미암아 너희를 사모하느니라',28970),
('2co-9-15','2co','고린도후서',9,15,'말할 수 없는 그의 은사로 말미암아 하나님께 감사하노라',28971),
('2co-10-1','2co','고린도후서',10,1,'너희를 대면하면 유순하고 떠나 있으면 너희에 대하여 담대한 나 바울은 이제 그리스도의 온유와 관용으로 친히 너희를 권하고',28972),
('2co-10-2','2co','고린도후서',10,2,'또한 우리를 육신에 따라 행하는 자로 여기는 자들에 대하여 내가 담대히 대하는 것 같이 너희와 함께 있을 때에 나로 하여금 이 담대한 태도로 대하지 않게 하기를 구하노라',28973),
('2co-10-3','2co','고린도후서',10,3,'우리가 육신으로 행하나 육신에 따라 싸우지 아니하노니',28974),
('2co-10-4','2co','고린도후서',10,4,'우리의 싸우는 무기는 육신에 속한 것이 아니요 오직 어떤 견고한 진도 무너뜨리는 하나님의 능력이라 모든 이론을 무너뜨리며',28975),
('2co-10-5','2co','고린도후서',10,5,'하나님 아는 것을 대적하여 높아진 것을 다 무너뜨리고 모든 생각을 사로잡아 그리스도에게 복종하게 하니',28976),
('2co-10-6','2co','고린도후서',10,6,'너희의 복종이 온전하게 될 때에 모든 복종하지 않는 것을 벌하려고 준비하는 중에 있노라',28977),
('2co-10-7','2co','고린도후서',10,7,'너희는 외모만 보는도다 만일 사람이 자기가 그리스도에게 속한 줄을 믿을진대 자기가 그리스도에게 속한 것 같이 우리도 그러한 줄을 자기 속으로 다시 생각할 것이라',28978),
('2co-10-8','2co','고린도후서',10,8,'주께서 주신 권세는 너희를 무너뜨리려고 하신 것이 아니요 세우려고 하신 것이니 내가 이에 대하여 지나치게 자랑하여도 부끄럽지 아니하리라',28979),
('2co-10-9','2co','고린도후서',10,9,'이는 내가 편지들로 너희를 놀라게 하려는 것 같이 생각하지 않게 함이라',28980),
('2co-10-10','2co','고린도후서',10,10,'그들의 말이 그의 편지들은 무게가 있고 힘이 있으나 그가 몸으로 대할 때는 약하고 그 말도 시원하지 않다 하니',28981),
('2co-10-11','2co','고린도후서',10,11,'이런 사람은 우리가 떠나 있을 때에 편지들로 말하는 것과 함께 있을 때에 행하는 일이 같은 것임을 알지라',28982),
('2co-10-12','2co','고린도후서',10,12,'우리는 자기를 칭찬하는 어떤 자와 더불어 감히 짝하며 비교할 수 없노라 그러나 그들이 자기로써 자기를 헤아리고 자기로써 자기를 비교하니 지혜가 없도다',28983),
('2co-10-13','2co','고린도후서',10,13,'그러나 우리는 분수 이상의 자랑을 하지 않고 오직 하나님이 우리에게 나누어 주신 그 범위의 한계를 따라 하노니 곧 너희에게까지 이른 것이라',28984),
('2co-10-14','2co','고린도후서',10,14,'우리가 너희에게 미치지 못할 자로서 스스로 지나쳐 나아간 것이 아니요 그리스도의 복음으로 너희에게까지 이른 것이라',28985),
('2co-10-15','2co','고린도후서',10,15,'우리는 남의 수고를 가지고 분수 이상의 자랑을 하는 것이 아니라 오직 너희 믿음이 자랄수록 우리의 규범을 따라 너희 가운데서 더욱 풍성하여지기를 바라노라',28986),
('2co-10-16','2co','고린도후서',10,16,'이는 남의 규범으로 이루어 놓은 것으로 자랑하지 아니하고 너희 지역을 넘어 복음을 전하려 함이라',28987),
('2co-10-17','2co','고린도후서',10,17,'자랑하는 자는 주 안에서 자랑할지니라',28988),
('2co-10-18','2co','고린도후서',10,18,'옳다 인정함을 받는 자는 자기를 칭찬하는 자가 아니요 오직 주께서 칭찬하시는 자니라',28989),
('2co-11-1','2co','고린도후서',11,1,'원하건대 너희는 나의 좀 어리석은 것을 용납하라 청하건대 나를 용납하라',28990),
('2co-11-2','2co','고린도후서',11,2,'내가 하나님의 열심으로 너희를 위하여 열심을 내노니 내가 너희를 정결한 처녀로 한 남편인 그리스도께 드리려고 중매함이로다 그러나 나는',28991),
('2co-11-3','2co','고린도후서',11,3,'뱀이 그 간계로 하와를 미혹한 것 같이 너희 마음이 그리스도를 향하는 진실함과 깨끗함에서 떠나 부패할까 두려워하노라',28992),
('2co-11-4','2co','고린도후서',11,4,'만일 누가 가서 우리가 전파하지 아니한 다른 예수를 전파하거나 혹은 너희가 받지 아니한 다른 영을 받게 하거나 혹은 너희가 받지 아니한 다른 복음을 받게 할 때에는 너희가 잘 용납하는구나',28993),
('2co-11-5','2co','고린도후서',11,5,'나는 지극히 크다는 사도들보다 부족한 것이 조금도 없는 줄로 생각하노라',28994),
('2co-11-6','2co','고린도후서',11,6,'내가 비록 말에는 부족하나 지식에는 그렇지 아니하니 이것을 우리가 모든 사람 가운데서 모든 일로 너희에게 나타내었노라',28995),
('2co-11-7','2co','고린도후서',11,7,'내가 너희를 높이려고 나를 낮추어 하나님의 복음을 값없이 너희에게 전함으로 죄를 지었느냐',28996),
('2co-11-8','2co','고린도후서',11,8,'내가 너희를 섬기기 위하여 다른 여러 교회에서 비용을 받은 것은 탈취한 것이라',28997),
('2co-11-9','2co','고린도후서',11,9,'또 내가 너희와 함께 있을 때 비용이 부족하였으되 아무에게도 누를 끼치지 아니하였음은 마게도냐에서 온 형제들이 나의 부족한 것을 보충하였음이라 내가 모든 일에 너희에게 폐를 끼치지 않기 위하여 스스로 조심하였고 또 조심하리라',28998),
('2co-11-10','2co','고린도후서',11,10,'그리스도의 진리가 내 속에 있으니 아가야 지방에서 나의 이 자랑이 막히지 아니하리라',28999),
('2co-11-11','2co','고린도후서',11,11,'어떠한 까닭이냐 내가 너희를 사랑하지 아니함이냐 하나님이 아시느니라',29000),
('2co-11-12','2co','고린도후서',11,12,'나는 내가 해 온 그대로 앞으로도 하리니 기회를 찾는 자들이 그 자랑하는 일로 우리와 같이 인정 받으려는 그 기회를 끊으려 함이라',29001),
('2co-11-13','2co','고린도후서',11,13,'그런 사람들은 거짓 사도요 속이는 일꾼이니 자기를 그리스도의 사도로 가장하는 자들이니라',29002),
('2co-11-14','2co','고린도후서',11,14,'이것은 이상한 일이 아니니라 사탄도 자기를 광명의 천사로 가장하나니',29003),
('2co-11-15','2co','고린도후서',11,15,'그러므로 사탄의 일꾼들도 자기를 의의 일꾼으로 가장하는 것이 또한 대단한 일이 아니니라 그들의 마지막은 그 행위대로 되리라',29004),
('2co-11-16','2co','고린도후서',11,16,'내가 다시 말하노니 누구든지 나를 어리석은 자로 여기지 말라 만일 그러하더라도 내가 조금 자랑할 수 있도록 어리석은 자로 받으라',29005),
('2co-11-17','2co','고린도후서',11,17,'내가 말하는 것은 주를 따라 하는 말이 아니요 오직 어리석은 자와 같이 기탄 없이 자랑하노라',29006),
('2co-11-18','2co','고린도후서',11,18,'여러 사람이 육신을 따라 자랑하니 나도 자랑하겠노라',29007),
('2co-11-19','2co','고린도후서',11,19,'너희는 지혜로운 자로서 어리석은 자들을 기쁘게 용납하는구나',29008),
('2co-11-20','2co','고린도후서',11,20,'누가 너희를 종으로 삼거나 잡아먹거나 빼앗거나 스스로 높이거나 뺨을 칠지라도 너희가 용납하는도다',29009),
('2co-11-21','2co','고린도후서',11,21,'나는 우리가 약한 것 같이 욕되게 말하노라 그러나 누가 무슨 일에 담대하면 어리석은 말이나마 나도 담대하리라',29010),
('2co-11-22','2co','고린도후서',11,22,'그들이 히브리인이냐 나도 그러하며 그들이 이스라엘인이냐 나도 그러하며 그들이 아브라함의 후손이냐 나도 그러하며',29011),
('2co-11-23','2co','고린도후서',11,23,'그들이 그리스도의 일꾼이냐 정신 없는 말을 하거니와 나는 더욱 그러하도다 내가 수고를 넘치도록 하고 옥에 갇히기도 더 많이 하고 매도 수없이 맞고 여러 번 죽을 뻔하였으니',29012),
('2co-11-24','2co','고린도후서',11,24,'유대인들에게 사십에서 하나 감한 매를 다섯 번 맞았으며',29013),
('2co-11-25','2co','고린도후서',11,25,'세 번 태장으로 맞고 한 번 돌로 맞고 세 번 파선하고 일 주야를 깊은 바다에서 지냈으며',29014),
('2co-11-26','2co','고린도후서',11,26,'여러 번 여행하면서 강의 위험과 강도의 위험과 동족의 위험과 이방인의 위험과 시내의 위험과 광야의 위험과 바다의 위험과 거짓 형제 중의 위험을 당하고',29015),
('2co-11-27','2co','고린도후서',11,27,'또 수고하며 애쓰고 여러 번 자지 못하고 주리며 목마르고 여러 번 굶고 춥고 헐벗었노라',29016),
('2co-11-28','2co','고린도후서',11,28,'이 외의 일은 고사하고 아직도 날마다 내 속에 눌리는 일이 있으니 곧 모든 교회를 위하여 염려하는 것이라',29017),
('2co-11-29','2co','고린도후서',11,29,'누가 약하면 내가 약하지 아니하며 누가 실족하게 되면 내가 애타지 아니하더냐',29018),
('2co-11-30','2co','고린도후서',11,30,'내가 부득불 자랑할진대 내가 약한 것을 자랑하리라',29019),
('2co-11-31','2co','고린도후서',11,31,'주 예수의 아버지 영원히 찬송할 하나님이 내가 거짓말 아니하는 것을 아시느니라',29020),
('2co-11-32','2co','고린도후서',11,32,'다메섹에서 아레다 왕의 고관이 나를 잡으려고 다메섹 성을 지켰으나',29021),
('2co-11-33','2co','고린도후서',11,33,'나는 광주리를 타고 들창문으로 성벽을 내려가 그 손에서 벗어났노라',29022),
('2co-12-1','2co','고린도후서',12,1,'무익하나마 내가 부득불 자랑하노니 주의 환상과 계시를 말하리라',29023),
('2co-12-2','2co','고린도후서',12,2,'내가 그리스도 안에 있는 한 사람을 아노니 그는 십사 년 전에 셋째 하늘에 이끌려 간 자라 (그가 몸 안에 있었는지 몸 밖에 있었는지 나는 모르거니와 하나님은 아시느니라)',29024),
('2co-12-3','2co','고린도후서',12,3,'내가 이런 사람을 아노니 (그가 몸 안에 있었는지 몸 밖에 있었는지 나는 모르거니와 하나님은 아시느니라)',29025),
('2co-12-4','2co','고린도후서',12,4,'그가 낙원으로 이끌려 가서 말로 표현할 수 없는 말을 들었으니 사람이 가히 이르지 못할 말이로다',29026),
('2co-12-5','2co','고린도후서',12,5,'내가 이런 사람을 위하여 자랑하겠으나 나를 위하여는 약한 것들 외에 자랑하지 아니하리라',29027),
('2co-12-6','2co','고린도후서',12,6,'내가 만일 자랑하고자 하여도 어리석은 자가 되지 아니할 것은 내가 참말을 함이라 그러나 누가 나를 보는 바와 내게 듣는 바에 지나치게 생각할까 두려워하여 그만두노라',29028),
('2co-12-7','2co','고린도후서',12,7,'여러 계시를 받은 것이 지극히 크므로 너무 자만하지 않게 하시려고 내 육체에 가시 곧 사탄의 사자를 주셨으니 이는 나를 쳐서 너무 자만하지 않게 하려 하심이라',29029),
('2co-12-8','2co','고린도후서',12,8,'이것이 내게서 떠나가게 하기 위하여 내가 세 번 주께 간구하였더니',29030),
('2co-12-9','2co','고린도후서',12,9,'나에게 이르시기를 내 은혜가 네게 족하도다 이는 내 능력이 약한 데서 온전하여짐이라 하신지라 그러므로 도리어 크게 기뻐함으로 나의 여러 약한 것들에 대하여 자랑하리니 이는 그리스도의 능력이 내게 머물게 하려 함이라',29031),
('2co-12-10','2co','고린도후서',12,10,'그러므로 내가 그리스도를 위하여 약한 것들과 능욕과 궁핍과 박해와 곤고를 기뻐하노니 이는 내가 약한 그 때에 강함이라',29032),
('2co-12-11','2co','고린도후서',12,11,'내가 어리석은 자가 되었으나 너희가 억지로 시킨 것이니 나는 너희에게 칭찬을 받아야 마땅하도다 내가 아무 것도 아니나 지극히 크다는 사도들보다 조금도 부족하지 아니하니라',29033),
('2co-12-12','2co','고린도후서',12,12,'사도의 표가 된 것은 내가 너희 가운데서 모든 참음과 표적과 기사와 능력을 행한 것이라',29034),
('2co-12-13','2co','고린도후서',12,13,'내 자신이 너희에게 폐를 끼치지 아니한 일밖에 다른 교회보다 부족하게 한 것이 무엇이 있느냐 너희는 나의 이 공평하지 못한 것을 용서하라',29035),
('2co-12-14','2co','고린도후서',12,14,'보라 내가 이제 세 번째 너희에게 가기를 준비하였으나 너희에게 폐를 끼치지 아니하리라 내가 구하는 것은 너희의 재물이 아니요 오직 너희니라 어린 아이가 부모를 위하여 재물을 저축하는 것이 아니요 부모가 어린 아이를 위하여 하느니라',29036),
('2co-12-15','2co','고린도후서',12,15,'내가 너희 영혼을 위하여 크게 기뻐하므로 재물을 사용하고 또 내 자신까지도 내어 주리니 너희를 더욱 사랑할수록 나는 사랑을 덜 받겠느냐',29037),
('2co-12-16','2co','고린도후서',12,16,'하여간 어떤 이의 말이 내가 너희에게 짐을 지우지는 아니하였을지라도 교활한 자가 되어 너희를 속임수로 취하였다 하니',29038),
('2co-12-17','2co','고린도후서',12,17,'내가 너희에게 보낸 자 중에 누구로 너희의 이득을 취하더냐',29039),
('2co-12-18','2co','고린도후서',12,18,'내가 디도를 권하고 함께 한 형제를 보내었으니 디도가 너희의 이득을 취하더냐 우리가 동일한 성령으로 행하지 아니하더냐 동일한 보조로 하지 아니하더냐',29040),
('2co-12-19','2co','고린도후서',12,19,'너희는 이 때까지 우리가 자기 변명을 하는 줄로 생각하는구나 우리는 그리스도 안에서 하나님 앞에 말하노라 사랑하는 자들아 이 모든 것은 너희의 덕을 세우기 위함이니라',29041),
('2co-12-20','2co','고린도후서',12,20,'내가 갈 때에 너희를 내가 원하는 것과 같이 보지 못하고 또 내가 너희에게 너희가 원하지 않는 것과 같이 보일까 두려워하며 또 다툼과 시기와 분냄과 당 짓는 것과 비방과 수군거림과 거만함과 혼란이 있을까 두려워하고',29042),
('2co-12-21','2co','고린도후서',12,21,'또 내가 다시 갈 때에 내 하나님이 나를 너희 앞에서 낮추실까 두려워하고 또 내가 전에 죄를 지은 여러 사람의 그 행한 바 더러움과 음란함과 호색함을 회개하지 아니함 때문에 슬퍼할까 두려워하노라',29043),
('2co-13-1','2co','고린도후서',13,1,'내가 이제 세 번째 너희에게 가리니 두세 증인의 입으로 말마다 확정하리라',29044),
('2co-13-2','2co','고린도후서',13,2,'내가 이미 말하였거니와 지금 떠나 있으나 두 번째 대면하였을 때와 같이 전에 죄 지은 자들과 그 남은 모든 사람에게 미리 말하노니 내가 다시 가면 용서하지 아니하리라',29045),
('2co-13-3','2co','고린도후서',13,3,'이는 그리스도께서 내 안에서 말씀하시는 증거를 너희가 구함이니 그는 너희에게 대하여 약하지 않고 도리어 너희 안에서 강하시니라',29046),
('2co-13-4','2co','고린도후서',13,4,'그리스도께서 약하심으로 십자가에 못 박히셨으나 하나님의 능력으로 살아 계시니 우리도 그 안에서 약하나 너희에게 대하여 하나님의 능력으로 그와 함께 살리라',29047),
('2co-13-5','2co','고린도후서',13,5,'너희는 믿음 안에 있는가 너희 자신을 시험하고 너희 자신을 확증하라 예수 그리스도께서 너희 안에 계신 줄을 너희가 스스로 알지 못하느냐 그렇지 않으면 너희는 버림 받은 자니라',29048),
('2co-13-6','2co','고린도후서',13,6,'우리가 버림 받은 자 되지 아니한 것을 너희가 알기를 내가 바라고',29049),
('2co-13-7','2co','고린도후서',13,7,'우리가 하나님께서 너희로 악을 조금도 행하지 않게 하시기를 구하노니 이는 우리가 옳은 자임을 나타내고자 함이 아니라 오직 우리는 버림 받은 자 같을지라도 너희는 선을 행하게 하고자 함이라',29050),
('2co-13-8','2co','고린도후서',13,8,'우리는 진리를 거슬러 아무 것도 할 수 없고 오직 진리를 위할 뿐이니',29051),
('2co-13-9','2co','고린도후서',13,9,'우리가 약할 때에 너희가 강한 것을 기뻐하고 또 이것을 위하여 구하니 곧 너희가 온전하게 되는 것이라',29052),
('2co-13-10','2co','고린도후서',13,10,'그러므로 내가 떠나 있을 때에 이렇게 쓰는 것은 대면할 때에 주께서 너희를 넘어뜨리려 하지 않고 세우려 하여 내게 주신 그 권한을 따라 엄하지 않게 하려 함이라',29053),
('2co-13-11','2co','고린도후서',13,11,'마지막으로 말하노니 형제들아 기뻐하라 온전하게 되며 위로를 받으며 마음을 같이하며 평안할지어다 또 사랑과 평강의 하나님이 너희와 함께 계시리라 거룩하게 입맞춤으로 서로 문안하라',29054),
('2co-13-12','2co','고린도후서',13,12,'모든 성도가 너희에게 문안하느니라',29055),
('2co-13-13','2co','고린도후서',13,13,'주 예수 그리스도의 은혜와 하나님의 사랑과 성령의 교통하심이 너희 무리와 함께 있을지어다',29056),
('gal-1-1','gal','갈라디아서',1,1,'사람들에게서 난 것도 아니요 사람으로 말미암은 것도 아니요 오직 예수 그리스도와 그를 죽은 자 가운데서 살리신 하나님 아버지로 말미암아 사도 된 바울은',29057),
('gal-1-2','gal','갈라디아서',1,2,'함께 있는 모든 형제와 더불어 갈라디아 여러 교회들에게',29058),
('gal-1-3','gal','갈라디아서',1,3,'우리 하나님 아버지와 주 예수 그리스도로부터 은혜와 평강이 있기를 원하노라',29059),
('gal-1-4','gal','갈라디아서',1,4,'그리스도께서 하나님 곧 우리 아버지의 뜻을 따라 이 악한 세대에서 우리를 건지시려고 우리 죄를 대속하기 위하여 자기 몸을 주셨으니',29060),
('gal-1-5','gal','갈라디아서',1,5,'영광이 그에게 세세토록 있을지어다 아멘',29061),
('gal-1-6','gal','갈라디아서',1,6,'그리스도의 은혜로 너희를 부르신 이를 이같이 속히 떠나 다른 복음을 따르는 것을 내가 이상하게 여기노라',29062),
('gal-1-7','gal','갈라디아서',1,7,'다른 복음은 없나니 다만 어떤 사람들이 너희를 교란하여 그리스도의 복음을 변하게 하려 함이라',29063),
('gal-1-8','gal','갈라디아서',1,8,'그러나 우리나 혹은 하늘로부터 온 천사라도 우리가 너희에게 전한 복음 외에 다른 복음을 전하면 저주를 받을지어다',29064),
('gal-1-9','gal','갈라디아서',1,9,'우리가 전에 말하였거니와 내가 지금 다시 말하노니 만일 누구든지 너희가 받은 것 외에 다른 복음을 전하면 저주를 받을지어다',29065),
('gal-1-10','gal','갈라디아서',1,10,'이제 내가 사람들에게 좋게 하랴 하나님께 좋게 하랴 사람들에게 기쁨을 구하랴 내가 지금까지 사람들의 기쁨을 구하였다면 그리스도의 종이 아니니라',29066),
('gal-1-11','gal','갈라디아서',1,11,'형제들아 내가 너희에게 알게 하노니 내가 전한 복음은 사람의 뜻을 따라 된 것이 아니니라',29067),
('gal-1-12','gal','갈라디아서',1,12,'이는 내가 사람에게서 받은 것도 아니요 배운 것도 아니요 오직 예수 그리스도의 계시로 말미암은 것이라',29068),
('gal-1-13','gal','갈라디아서',1,13,'내가 이전에 유대교에 있을 때에 행한 일을 너희가 들었거니와 하나님의 교회를 심히 박해하여 멸하고',29069),
('gal-1-14','gal','갈라디아서',1,14,'내가 내 동족 중 여러 연갑자보다 유대교를 지나치게 믿어 내 조상의 전통에 대하여 더욱 열심이 있었으나',29070),
('gal-1-15','gal','갈라디아서',1,15,'그러나 내 어머니의 태로부터 나를 택정하시고 그의 은혜로 나를 부르신 이가',29071),
('gal-1-16','gal','갈라디아서',1,16,'그의 아들을 이방에 전하기 위하여 그를 내 속에 나타내시기를 기뻐하셨을 때에 내가 곧 혈육과 의논하지 아니하고',29072),
('gal-1-17','gal','갈라디아서',1,17,'또 나보다 먼저 사도 된 자들을 만나려고 예루살렘으로 가지 아니하고 아라비아로 갔다가 다시 다메섹으로 돌아갔노라',29073),
('gal-1-18','gal','갈라디아서',1,18,'그 후 삼 년 만에 내가 게바를 방문하려고 예루살렘에 올라가서 그와 함께 십오 일을 머무는 동안',29074),
('gal-1-19','gal','갈라디아서',1,19,'주의 형제 야고보 외에 다른 사도들을 보지 못하였노라',29075),
('gal-1-20','gal','갈라디아서',1,20,'보라 내가 너희에게 쓰는 것은 하나님 앞에서 거짓말이 아니로다',29076),
('gal-1-21','gal','갈라디아서',1,21,'그 후에 내가 수리아와 길리기아 지방에 이르렀으나',29077),
('gal-1-22','gal','갈라디아서',1,22,'그리스도 안에 있는 유대의 교회들이 나를 얼굴로는 알지 못하고',29078),
('gal-1-23','gal','갈라디아서',1,23,'다만 우리를 박해하던 자가 전에 멸하려던 그 믿음을 지금 전한다 함을 듣고',29079),
('gal-1-24','gal','갈라디아서',1,24,'나로 말미암아 하나님께 영광을 돌리니라',29080),
('gal-2-1','gal','갈라디아서',2,1,'십사 년 후에 내가 바나바와 함께 디도를 데리고 다시 예루살렘에 올라갔나니',29081),
('gal-2-2','gal','갈라디아서',2,2,'계시를 따라 올라가 내가 이방 가운데서 전파하는 복음을 그들에게 제시하되 유력한 자들에게 사사로이 한 것은 내가 달음질하는 것이나 달음질한 것이 헛되지 않게 하려 함이라',29082),
('gal-2-3','gal','갈라디아서',2,3,'그러나 나와 함께 있는 헬라인 디도까지도 억지로 할례를 받게 하지 아니하였으니',29083),
('gal-2-4','gal','갈라디아서',2,4,'이는 가만히 들어온 거짓 형제들 때문이라 그들이 가만히 들어온 것은 그리스도 예수 안에서 우리가 가진 자유를 엿보고 우리를 종으로 삼고자 함이로되',29084),
('gal-2-5','gal','갈라디아서',2,5,'그들에게 우리가 한시도 복종하지 아니하였으니 이는 복음의 진리가 항상 너희 가운데 있게 하려 함이라',29085),
('gal-2-6','gal','갈라디아서',2,6,'유력하다는 이들 중에 (본래 어떤 이들이든지 내게 상관이 없으며 하나님은 사람을 외모로 취하지 아니하시나니) 저 유력한 이들은 내게 의무를 더하여 준 것이 없고',29086),
('gal-2-7','gal','갈라디아서',2,7,'도리어 그들은 내가 무할례자에게 복음 전함을 맡은 것이 베드로가 할례자에게 맡음과 같은 것을 보았고',29087),
('gal-2-8','gal','갈라디아서',2,8,'베드로에게 역사하사 그를 할례자의 사도로 삼으신 이가 또한 내게 역사하사 나를 이방인의 사도로 삼으셨느니라',29088),
('gal-2-9','gal','갈라디아서',2,9,'또 기둥 같이 여기는 야고보와 게바와 요한도 내게 주신 은혜를 알므로 나와 바나바에게 친교의 악수를 하였으니 우리는 이방인에게로, 그들은 할례자에게로 가게 하려 함이라',29089),
('gal-2-10','gal','갈라디아서',2,10,'다만 우리에게 가난한 자들을 기억하도록 부탁하였으니 이것은 나도 본래부터 힘써 행하여 왔노라',29090),
('gal-2-11','gal','갈라디아서',2,11,'게바가 안디옥에 이르렀을 때에 책망 받을 일이 있기로 내가 그를 대면하여 책망하였노라',29091),
('gal-2-12','gal','갈라디아서',2,12,'야고보에게서 온 어떤 이들이 이르기 전에 게바가 이방인과 함께 먹다가 그들이 오매 그가 할례자들을 두려워하여 떠나 물러가매',29092),
('gal-2-13','gal','갈라디아서',2,13,'남은 유대인들도 그와 같이 외식하므로 바나바도 그들의 외식에 유혹되었느니라',29093),
('gal-2-14','gal','갈라디아서',2,14,'그러므로 나는 그들이 복음의 진리를 따라 바르게 행하지 아니함을 보고 모든 자 앞에서 게바에게 이르되 네가 유대인으로서 이방인을 따르고 유대인답게 살지 아니하면서 어찌하여 억지로 이방인을 유대인답게 살게 하려느냐 하였노라',29094),
('gal-2-15','gal','갈라디아서',2,15,'우리는 본래 유대인이요 이방 죄인이 아니로되',29095),
('gal-2-16','gal','갈라디아서',2,16,'사람이 의롭게 되는 것은 율법의 행위로 말미암음이 아니요 오직 예수 그리스도를 믿음으로 말미암는 줄 알므로 우리도 그리스도 예수를 믿나니 이는 우리가 율법의 행위로써가 아니고 그리스도를 믿음으로써 의롭다 함을 얻으려 함이라 율법의 행위로써는 의롭다 함을 얻을 육체가 없느니라',29096),
('gal-2-17','gal','갈라디아서',2,17,'만일 우리가 그리스도 안에서 의롭게 되려 하다가 죄인으로 드러나면 그리스도께서 죄를 짓게 하는 자냐 결코 그럴 수 없느니라',29097),
('gal-2-18','gal','갈라디아서',2,18,'만일 내가 헐었던 것을 다시 세우면 내가 나를 범법한 자로 만드는 것이라',29098),
('gal-2-19','gal','갈라디아서',2,19,'내가 율법으로 말미암아 율법에 대하여 죽었나니 이는 하나님에 대하여 살려 함이라',29099),
('gal-2-20','gal','갈라디아서',2,20,'내가 그리스도와 함께 십자가에 못 박혔나니 그런즉 이제는 내가 사는 것이 아니요 오직 내 안에 그리스도께서 사시는 것이라 이제 내가 육체 가운데 사는 것은 나를 사랑하사 나를 위하여 자기 자신을 버리신 하나님의 아들을 믿는 믿음 안에서 사는 것이라',29100),
('gal-2-21','gal','갈라디아서',2,21,'내가 하나님의 은혜를 폐하지 아니하노니 만일 의롭게 되는 것이 율법으로 말미암으면 그리스도께서 헛되이 죽으셨느니라',29101),
('gal-3-1','gal','갈라디아서',3,1,'어리석도다 갈라디아 사람들아 예수 그리스도께서 십자가에 못 박히신 것이 너희 눈 앞에 밝히 보이거늘 누가 너희를 꾀더냐',29102),
('gal-3-2','gal','갈라디아서',3,2,'내가 너희에게서 다만 이것을 알려 하노니 너희가 성령을 받은 것이 율법의 행위로냐 혹은 듣고 믿음으로냐',29103),
('gal-3-3','gal','갈라디아서',3,3,'너희가 이같이 어리석으냐 성령으로 시작하였다가 이제는 육체로 마치겠느냐',29104),
('gal-3-4','gal','갈라디아서',3,4,'너희가 이같이 많은 괴로움을 헛되이 받았느냐 과연 헛되냐',29105),
('gal-3-5','gal','갈라디아서',3,5,'너희에게 성령을 주시고 너희 가운데서 능력을 행하시는 이의 일이 율법의 행위에서냐 혹은 듣고 믿음에서냐',29106),
('gal-3-6','gal','갈라디아서',3,6,'아브라함이 하나님을 믿으매 그것을 그에게 의로 정하셨다 함과 같으니라',29107),
('gal-3-7','gal','갈라디아서',3,7,'그런즉 믿음으로 말미암은 자들은 아브라함의 자손인 줄 알지어다',29108),
('gal-3-8','gal','갈라디아서',3,8,'또 하나님이 이방을 믿음으로 말미암아 의로 정하실 것을 성경이 미리 알고 먼저 아브라함에게 복음을 전하되 모든 이방인이 너로 말미암아 복을 받으리라 하였느니라',29109),
('gal-3-9','gal','갈라디아서',3,9,'그러므로 믿음으로 말미암은 자는 믿음이 있는 아브라함과 함께 복을 받느니라',29110),
('gal-3-10','gal','갈라디아서',3,10,'무릇 율법 행위에 속한 자들은 저주 아래에 있나니 기록된 바 누구든지 율법 책에 기록된 대로 모든 일을 항상 행하지 아니하는 자는 저주 아래에 있는 자라 하였음이라',29111),
('gal-3-11','gal','갈라디아서',3,11,'또 하나님 앞에서 아무도 율법으로 말미암아 의롭게 되지 못할 것이 분명하니 이는 의인은 믿음으로 살리라 하였음이라',29112),
('gal-3-12','gal','갈라디아서',3,12,'율법은 믿음에서 난 것이 아니니 율법을 행하는 자는 그 가운데서 살리라 하였느니라',29113),
('gal-3-13','gal','갈라디아서',3,13,'그리스도께서 우리를 위하여 저주를 받은 바 되사 율법의 저주에서 우리를 속량하셨으니 기록된 바 나무에 달린 자마다 저주 아래에 있는 자라 하였음이라',29114),
('gal-3-14','gal','갈라디아서',3,14,'이는 그리스도 예수 안에서 아브라함의 복이 이방인에게 미치게 하고 또 우리로 하여금 믿음으로 말미암아 성령의 약속을 받게 하려 함이라',29115),
('gal-3-15','gal','갈라디아서',3,15,'형제들아 내가 사람의 예대로 말하노니 사람의 언약이라도 정한 후에는 아무도 폐하거나 더하거나 하지 못하느니라',29116),
('gal-3-16','gal','갈라디아서',3,16,'이 약속들은 아브라함과 그 자손에게 말씀하신 것인데 여럿을 가리켜 그 자손들이라 하지 아니하시고 오직 한 사람을 가리켜 네 자손이라 하셨으니 곧 그리스도라',29117),
('gal-3-17','gal','갈라디아서',3,17,'내가 이것을 말하노니 하나님께서 미리 정하신 언약을 사백삼십 년 후에 생긴 율법이 폐기하지 못하고 그 약속을 헛되게 하지 못하리라',29118),
('gal-3-18','gal','갈라디아서',3,18,'만일 그 유업이 율법에서 난 것이면 약속에서 난 것이 아니리라 그러나 하나님이 약속으로 말미암아 아브라함에게 주신 것이라',29119),
('gal-3-19','gal','갈라디아서',3,19,'그런즉 율법은 무엇이냐 범법하므로 더하여진 것이라 천사들을 통하여 한 중보자의 손으로 베푸신 것인데 약속하신 자손이 오시기까지 있을 것이라',29120),
('gal-3-20','gal','갈라디아서',3,20,'그 중보자는 한 편만 위한 자가 아니나 하나님은 한 분이시니라',29121),
('gal-3-21','gal','갈라디아서',3,21,'그러면 율법이 하나님의 약속들과 반대되는 것이냐 결코 그럴 수 없느니라 만일 능히 살게 하는 율법을 주셨더라면 의가 반드시 율법으로 말미암았으리라',29122),
