('gal-6-10','gal','갈라디아서',6,10,'그러므로 우리는 기회 있는 대로 모든 이에게 착한 일을 하되 더욱 믿음의 가정들에게 할지니라',29197),
('gal-6-11','gal','갈라디아서',6,11,'내 손으로 너희에게 이렇게 큰 글자로 쓴 것을 보라',29198),
('gal-6-12','gal','갈라디아서',6,12,'무릇 육체의 모양을 내려 하는 자들이 억지로 너희에게 할례를 받게 함은 그들이 그리스도의 십자가로 말미암아 박해를 면하려 함뿐이라',29199),
('gal-6-13','gal','갈라디아서',6,13,'할례를 받은 그들이라도 스스로 율법은 지키지 아니하고 너희에게 할례를 받게 하려 하는 것은 그들이 너희의 육체로 자랑하려 함이라',29200),
('gal-6-14','gal','갈라디아서',6,14,'그러나 내게는 우리 주 예수 그리스도의 십자가 외에 결코 자랑할 것이 없으니 그리스도로 말미암아 세상이 나를 대하여 십자가에 못 박히고 내가 또한 세상을 대하여 그러하니라',29201),
('gal-6-15','gal','갈라디아서',6,15,'할례나 무할례가 아무 것도 아니로되 오직 새로 지으심을 받는 것만이 중요하니라',29202),
('gal-6-16','gal','갈라디아서',6,16,'무릇 이 규례를 행하는 자에게와 하나님의 이스라엘에게 평강과 긍휼이 있을지어다',29203),
('gal-6-17','gal','갈라디아서',6,17,'이후로는 누구든지 나를 괴롭게 하지 말라 내가 내 몸에 예수의 흔적을 지니고 있노라',29204),
('gal-6-18','gal','갈라디아서',6,18,'형제들아 우리 주 예수 그리스도의 은혜가 너희 심령에 있을지어다 아멘',29205),
('eph-1-1','eph','에베소서',1,1,'하나님의 뜻으로 말미암아 그리스도 예수의 사도 된 바울은 에베소에 있는 성도들과 그리스도 예수 안에 있는 신실한 자들에게 편지하노니',29206),
('eph-1-2','eph','에베소서',1,2,'하나님 우리 아버지와 주 예수 그리스도로부터 은혜와 평강이 너희에게 있을지어다',29207),
('eph-1-3','eph','에베소서',1,3,'찬송하리로다 하나님 곧 우리 주 예수 그리스도의 아버지께서 그리스도 안에서 하늘에 속한 모든 신령한 복을 우리에게 주시되',29208),
('eph-1-4','eph','에베소서',1,4,'곧 창세 전에 그리스도 안에서 우리를 택하사 우리로 사랑 안에서 그 앞에 거룩하고 흠이 없게 하시려고',29209),
('eph-1-5','eph','에베소서',1,5,'그 기쁘신 뜻대로 우리를 예정하사 예수 그리스도로 말미암아 자기의 아들들이 되게 하셨으니',29210),
('eph-1-6','eph','에베소서',1,6,'이는 그가 사랑하시는 자 안에서 우리에게 거저 주시는 바 그의 은혜의 영광을 찬송하게 하려는 것이라',29211),
('eph-1-7','eph','에베소서',1,7,'우리는 그리스도 안에서 그의 은혜의 풍성함을 따라 그의 피로 말미암아 속량 곧 죄 사함을 받았느니라',29212),
('eph-1-8','eph','에베소서',1,8,'이는 그가 모든 지혜와 총명을 우리에게 넘치게 하사',29213),
('eph-1-9','eph','에베소서',1,9,'그 뜻의 비밀을 우리에게 알리신 것이요 그의 기뻐하심을 따라 그리스도 안에서 때가 찬 경륜을 위하여 예정하신 것이니',29214),
('eph-1-10','eph','에베소서',1,10,'하늘에 있는 것이나 땅에 있는 것이 다 그리스도 안에서 통일되게 하려 하심이라',29215),
('eph-1-11','eph','에베소서',1,11,'모든 일을 그의 뜻의 결정대로 일하시는 이의 계획을 따라 우리가 예정을 입어 그 안에서 기업이 되었으니',29216),
('eph-1-12','eph','에베소서',1,12,'이는 우리가 그리스도 안에서 전부터 바라던 그의 영광의 찬송이 되게 하려 하심이라',29217),
('eph-1-13','eph','에베소서',1,13,'그 안에서 너희도 진리의 말씀 곧 너희의 구원의 복음을 듣고 그 안에서 또한 믿어 약속의 성령으로 인치심을 받았으니',29218),
('eph-1-14','eph','에베소서',1,14,'이는 우리 기업의 보증이 되사 그 얻으신 것을 속량하시고 그의 영광을 찬송하게 하려 하심이라',29219),
('eph-1-15','eph','에베소서',1,15,'이로 말미암아 주 예수 안에서 너희 믿음과 모든 성도를 향한 사랑을 나도 듣고',29220),
('eph-1-16','eph','에베소서',1,16,'내가 기도할 때에 기억하며 너희로 말미암아 감사하기를 그치지 아니하고',29221),
('eph-1-17','eph','에베소서',1,17,'우리 주 예수 그리스도의 하나님, 영광의 아버지께서 지혜와 계시의 영을 너희에게 주사 하나님을 알게 하시고',29222),
('eph-1-18','eph','에베소서',1,18,'너희 마음의 눈을 밝히사 그의 부르심의 소망이 무엇이며 성도 안에서 그 기업의 영광의 풍성함이 무엇이며',29223),
('eph-1-19','eph','에베소서',1,19,'그의 힘의 위력으로 역사하심을 따라 믿는 우리에게 베푸신 능력의 지극히 크심이 어떠한 것을 너희로 알게 하시기를 구하노라',29224),
('eph-1-20','eph','에베소서',1,20,'그의 능력이 그리스도 안에서 역사하사 죽은 자들 가운데서 다시 살리시고 하늘에서 자기의 오른편에 앉히사',29225),
('eph-1-21','eph','에베소서',1,21,'모든 통치와 권세와 능력과 주권과 이 세상뿐 아니라 오는 세상에 일컫는 모든 이름 위에 뛰어나게 하시고',29226),
('eph-1-22','eph','에베소서',1,22,'또 만물을 그의 발 아래에 복종하게 하시고 그를 만물 위에 교회의 머리로 삼으셨느니라',29227),
('eph-1-23','eph','에베소서',1,23,'교회는 그의 몸이니 만물 안에서 만물을 충만하게 하시는 이의 충만함이니라',29228),
('eph-2-1','eph','에베소서',2,1,'그는 허물과 죄로 죽었던 너희를 살리셨도다',29229),
('eph-2-2','eph','에베소서',2,2,'그 때에 너희는 그 가운데서 행하여 이 세상 풍조를 따르고 공중의 권세 잡은 자를 따랐으니 곧 지금 불순종의 아들들 가운데서 역사하는 영이라',29230),
('eph-2-3','eph','에베소서',2,3,'전에는 우리도 다 그 가운데서 우리 육체의 욕심을 따라 지내며 육체와 마음의 원하는 것을 하여 다른 이들과 같이 본질상 진노의 자녀이었더니',29231),
('eph-2-4','eph','에베소서',2,4,'긍휼이 풍성하신 하나님이 우리를 사랑하신 그 큰 사랑을 인하여',29232),
('eph-2-5','eph','에베소서',2,5,'허물로 죽은 우리를 그리스도와 함께 살리셨고 (너희는 은혜로 구원을 받은 것이라)',29233),
('eph-2-6','eph','에베소서',2,6,'또 함께 일으키사 그리스도 예수 안에서 함께 하늘에 앉히시니',29234),
('eph-2-7','eph','에베소서',2,7,'이는 그리스도 예수 안에서 우리에게 자비하심으로써 그 은혜의 지극히 풍성함을 오는 여러 세대에 나타내려 하심이라',29235),
('eph-2-8','eph','에베소서',2,8,'너희는 그 은혜에 의하여 믿음으로 말미암아 구원을 받았으니 이것은 너희에게서 난 것이 아니요 하나님의 선물이라',29236),
('eph-2-9','eph','에베소서',2,9,'행위에서 난 것이 아니니 이는 누구든지 자랑하지 못하게 함이라',29237),
('eph-2-10','eph','에베소서',2,10,'우리는 그가 만드신 바라 그리스도 예수 안에서 선한 일을 위하여 지으심을 받은 자니 이 일은 하나님이 전에 예비하사 우리로 그 가운데서 행하게 하려 하심이니라',29238),
('eph-2-11','eph','에베소서',2,11,'그러므로 생각하라 너희는 그 때에 육체로는 이방인이요 손으로 육체에 행한 할례를 받은 무리라 칭하는 자들로부터 할례를 받지 않은 무리라 칭함을 받는 자들이라',29239),
('eph-2-12','eph','에베소서',2,12,'그 때에 너희는 그리스도 밖에 있었고 이스라엘 나라 밖의 사람이라 약속의 언약들에 대하여는 외인이요 세상에서 소망이 없고 하나님도 없는 자이더니',29240),
('eph-2-13','eph','에베소서',2,13,'이제는 전에 멀리 있던 너희가 그리스도 예수 안에서 그리스도의 피로 가까워졌느니라',29241),
('eph-2-14','eph','에베소서',2,14,'그는 우리의 화평이신지라 둘로 하나를 만드사 원수 된 것 곧 중간에 막힌 담을 자기 육체로 허시고',29242),
('eph-2-15','eph','에베소서',2,15,'법조문으로 된 계명의 율법을 폐하셨으니 이는 이 둘로 자기 안에서 한 새 사람을 지어 화평하게 하시고',29243),
('eph-2-16','eph','에베소서',2,16,'또 십자가로 이 둘을 한 몸으로 하나님과 화목하게 하려 하심이라 원수 된 것을 십자가로 소멸하시고',29244),
('eph-2-17','eph','에베소서',2,17,'또 오셔서 먼 데 있는 너희에게 평안을 전하시고 가까운 데 있는 자들에게 평안을 전하셨으니',29245),
('eph-2-18','eph','에베소서',2,18,'이는 그로 말미암아 우리 둘이 한 성령 안에서 아버지께 나아감을 얻게 하려 하심이라',29246),
('eph-2-19','eph','에베소서',2,19,'그러므로 이제부터 너희는 외인도 아니요 나그네도 아니요 오직 성도들과 동일한 시민이요 하나님의 권속이라',29247),
('eph-2-20','eph','에베소서',2,20,'너희는 사도들과 선지자들의 터 위에 세우심을 입은 자라 그리스도 예수께서 친히 모퉁잇돌이 되셨느니라',29248),
('eph-2-21','eph','에베소서',2,21,'그의 안에서 건물마다 서로 연결하여 주 안에서 성전이 되어 가고',29249),
('eph-2-22','eph','에베소서',2,22,'너희도 성령 안에서 하나님이 거하실 처소가 되기 위하여 그리스도 예수 안에서 함께 지어져 가느니라',29250),
('eph-3-1','eph','에베소서',3,1,'이러므로 그리스도 예수의 일로 너희 이방인을 위하여 갇힌 자 된 나 바울이 말하거니와',29251),
('eph-3-2','eph','에베소서',3,2,'너희를 위하여 내게 주신 하나님의 그 은혜의 경륜을 너희가 들었을 터이라',29252),
('eph-3-3','eph','에베소서',3,3,'곧 계시로 내게 비밀을 알게 하신 것은 내가 먼저 간단히 기록함과 같으니',29253),
('eph-3-4','eph','에베소서',3,4,'그것을 읽으면 내가 그리스도의 비밀을 깨달은 것을 너희가 알 수 있으리라',29254),
('eph-3-5','eph','에베소서',3,5,'이제 그의 거룩한 사도들과 선지자들에게 성령으로 나타내신 것 같이 다른 세대에서는 사람의 아들들에게 알리지 아니하셨으니',29255),
('eph-3-6','eph','에베소서',3,6,'이는 이방인들이 복음으로 말미암아 그리스도 예수 안에서 함께 상속자가 되고 함께 지체가 되고 함께 약속에 참여하는 자가 됨이라',29256),
('eph-3-7','eph','에베소서',3,7,'이 복음을 위하여 그의 능력이 역사하시는 대로 내게 주신 하나님의 은혜의 선물을 따라 내가 일꾼이 되었노라',29257),
('eph-3-8','eph','에베소서',3,8,'모든 성도 중에 지극히 작은 자보다 더 작은 나에게 이 은혜를 주신 것은 측량할 수 없는 그리스도의 풍성함을 이방인에게 전하게 하시고',29258),
('eph-3-9','eph','에베소서',3,9,'영원부터 만물을 창조하신 하나님 속에 감추어졌던 비밀의 경륜이 어떠한 것을 드러내게 하려 하심이라',29259),
('eph-3-10','eph','에베소서',3,10,'이는 이제 교회로 말미암아 하늘에 있는 통치자들과 권세들에게 하나님의 각종 지혜를 알게 하려 하심이니',29260),
('eph-3-11','eph','에베소서',3,11,'곧 영원부터 우리 주 그리스도 예수 안에서 예정하신 뜻대로 하신 것이라',29261),
('eph-3-12','eph','에베소서',3,12,'우리가 그 안에서 그를 믿음으로 말미암아 담대함과 확신을 가지고 하나님께 나아감을 얻느니라',29262),
('eph-3-13','eph','에베소서',3,13,'그러므로 너희에게 구하노니 너희를 위한 나의 여러 환난에 대하여 낙심하지 말라 이는 너희의 영광이니라',29263),
('eph-3-14','eph','에베소서',3,14,'이러므로 내가 하늘과 땅에 있는 각 족속에게',29264),
('eph-3-15','eph','에베소서',3,15,'이름을 주신 아버지 앞에 무릎을 꿇고 비노니',29265),
('eph-3-16','eph','에베소서',3,16,'그의 영광의 풍성함을 따라 그의 성령으로 말미암아 너희 속사람을 능력으로 강건하게 하시오며',29266),
('eph-3-17','eph','에베소서',3,17,'믿음으로 말미암아 그리스도께서 너희 마음에 계시게 하시옵고 너희가 사랑 가운데서 뿌리가 박히고 터가 굳어져서',29267),
('eph-3-18','eph','에베소서',3,18,'능히 모든 성도와 함께 지식에 넘치는 그리스도의 사랑을 알고',29268),
('eph-3-19','eph','에베소서',3,19,'그 너비와 길이와 높이와 깊이가 어떠함을 깨달아 하나님의 모든 충만하신 것으로 너희에게 충만하게 하시기를 구하노라',29269),
('eph-3-20','eph','에베소서',3,20,'우리 가운데서 역사하시는 능력대로 우리가 구하거나 생각하는 모든 것에 더 넘치도록 능히 하실 이에게',29270),
('eph-3-21','eph','에베소서',3,21,'교회 안에서와 그리스도 예수 안에서 영광이 대대로 영원무궁하기를 원하노라 아멘',29271),
