('col-2-15','col','골로새서',2,15,'통치자들과 권세들을 무력화하여 드러내어 구경거리로 삼으시고 십자가로 그들을 이기셨느니라',29508),
('col-2-16','col','골로새서',2,16,'그러므로 먹고 마시는 것과 절기나 초하루나 안식일을 이유로 누구든지 너희를 비판하지 못하게 하라',29509),
('col-2-17','col','골로새서',2,17,'이것들은 장래 일의 그림자이나 몸은 그리스도의 것이니라',29510),
('col-2-18','col','골로새서',2,18,'아무도 꾸며낸 겸손과 천사 숭배를 이유로 너희를 정죄하지 못하게 하라 그가 그 본 것에 의지하여 그 육신의 생각을 따라 헛되이 과장하고',29511),
