('col-2-20','col','골로새서',2,20,'너희가 세상의 초등학문에서 그리스도와 함께 죽었거든 어찌하여 세상에 사는 것과 같이 규례에 순종하느냐',29513),
('col-2-21','col','골로새서',2,21,'(곧 붙잡지도 말고 맛보지도 말고 만지지도 말라 하는 것이니',29514),
