('col-3-25','col','골로새서',3,25,'불의를 행하는 자는 불의의 보응을 받으리니 주는 사람을 외모로 취하심이 없느니라',29541),
('col-4-1','col','골로새서',4,1,'상전들아 의와 공평을 종들에게 베풀지니 너희에게도 하늘에 상전이 계심을 알지어다',29542),
