('col-4-12','col','골로새서',4,12,'그리스도 예수의 종인 너희에게서 온 에바브라가 너희에게 문안하느니라 그가 항상 너희를 위하여 애써 기도하여 너희로 하나님의 모든 뜻 가운데서 완전하고 확신 있게 서기를 구하나니',29553),
('col-4-13','col','골로새서',4,13,'그가 너희와 라오디게아에 있는 자들과 히에라볼리에 있는 자들을 위하여 많이 수고하는 것을 내가 증언하노라',29554),
('col-4-14','col','골로새서',4,14,'사랑을 받는 의사 누가와 또 데마가 너희에게 문안하느니라',29555),
