('col-4-16','col','골로새서',4,16,'이 편지를 너희에게서 읽은 후에 라오디게아인의 교회에서도 읽게 하고 또 라오디게아로부터 오는 편지를 너희도 읽으라',29557),
('col-4-17','col','골로새서',4,17,'아킵보에게 이르기를 주 안에서 받은 직분을 삼가 이루라고 하라',29558),
('col-4-18','col','골로새서',4,18,'나 바울은 친필로 문안하노니 내가 매인 것을 생각하라 은혜가 너희에게 있을지어다',29559),
('1th-1-1','1th','데살로니가전서',1,1,'바울과 실루아노와 디모데는 하나님 아버지와 주 예수 그리스도 안에 있는 데살로니가인의 교회에 편지하노니 은혜와 평강이 너희에게 있을지어다',29560),
('1th-1-2','1th','데살로니가전서',1,2,'우리가 너희 모두로 말미암아 항상 하나님께 감사하며 기도할 때에 너희를 기억함은',29561),
('1th-1-3','1th','데살로니가전서',1,3,'너희의 믿음의 역사와 사랑의 수고와 우리 주 예수 그리스도에 대한 소망의 인내를 우리 하나님 아버지 앞에서 끊임없이 기억함이니',29562),
('1th-1-4','1th','데살로니가전서',1,4,'하나님의 사랑하심을 받은 형제들아 너희를 택하심을 아노라',29563),
('1th-1-5','1th','데살로니가전서',1,5,'이는 우리 복음이 너희에게 말로만 이른 것이 아니라 또한 능력과 성령과 큰 확신으로 된 것임이라 우리가 너희 가운데서 너희를 위하여 어떤 사람이 된 것은 너희가 아는 바와 같으니라',29564),
('1th-1-6','1th','데살로니가전서',1,6,'또 너희는 많은 환난 가운데서 성령의 기쁨으로 말씀을 받아 우리와 주를 본받은 자가 되었으니',29565),
('1th-1-7','1th','데살로니가전서',1,7,'그러므로 너희가 마게도냐와 아가야에 있는 모든 믿는 자의 본이 되었느니라',29566),
('1th-1-8','1th','데살로니가전서',1,8,'주의 말씀이 너희에게로부터 마게도냐와 아가야에만 들릴 뿐 아니라 하나님을 향하는 너희 믿음의 소문이 각처에 퍼졌으므로 우리는 아무 말도 할 것이 없노라',29567),
('1th-1-9','1th','데살로니가전서',1,9,'그들이 우리에 대하여 스스로 말하기를 우리가 어떻게 너희 가운데에 들어갔는지와 너희가 어떻게 우상을 버리고 하나님께로 돌아와서 살아 계시고 참되신 하나님을 섬기는지와',29568),
('1th-1-10','1th','데살로니가전서',1,10,'또 죽은 자들 가운데서 다시 살리신 그의 아들이 하늘로부터 강림하실 것을 너희가 어떻게 기다리는지를 말하니 이는 장래의 노하심에서 우리를 건지시는 예수시니라',29569),
('1th-2-1','1th','데살로니가전서',2,1,'형제들아 우리가 너희 가운데 들어간 것이 헛되지 않은 줄을 너희가 친히 아나니',29570),
('1th-2-2','1th','데살로니가전서',2,2,'너희가 아는 바와 같이 우리가 먼저 빌립보에서 고난과 능욕을 당하였으나 우리 하나님을 힘입어 많은 싸움 중에 하나님의 복음을 너희에게 전하였노라',29571),
('1th-2-3','1th','데살로니가전서',2,3,'우리의 권면은 간사함이나 부정에서 난 것이 아니요 속임수로 하는 것도 아니라',29572),
('1th-2-4','1th','데살로니가전서',2,4,'오직 하나님께 옳게 여기심을 입어 복음을 위탁 받았으니 우리가 이와 같이 말함은 사람을 기쁘게 하려 함이 아니요 오직 우리 마음을 감찰하시는 하나님을 기쁘시게 하려 함이라',29573),
('1th-2-5','1th','데살로니가전서',2,5,'너희도 알거니와 우리가 아무 때에도 아첨하는 말이나 탐심의 탈을 쓰지 아니한 것을 하나님이 증언하시느니라',29574),
('1th-2-6','1th','데살로니가전서',2,6,'또한 우리는 너희에게서든지 다른 이에게서든지 사람에게서는 영광을 구하지 아니하였노라',29575),
('1th-2-7','1th','데살로니가전서',2,7,'우리는 그리스도의 사도로서 마땅히 권위를 주장할 수 있으나 도리어 너희 가운데서 유순한 자가 되어 유모가 자기 자녀를 기름과 같이 하였으니',29576),
('1th-2-8','1th','데살로니가전서',2,8,'우리가 이같이 너희를 사모하여 하나님의 복음뿐 아니라 우리의 목숨까지도 너희에게 주기를 기뻐함은 너희가 우리의 사랑하는 자 됨이라',29577),
('1th-2-9','1th','데살로니가전서',2,9,'형제들아 우리의 수고와 애쓴 것을 너희가 기억하리니 너희 아무에게도 폐를 끼치지 아니하려고 밤낮으로 일하면서 너희에게 하나님의 복음을 전하였노라',29578),
('1th-2-10','1th','데살로니가전서',2,10,'우리가 너희 믿는 자들을 향하여 어떻게 거룩하고 옳고 흠 없이 행하였는지에 대하여 너희가 증인이요 하나님도 그러하시도다',29579),
('1th-2-11','1th','데살로니가전서',2,11,'너희도 아는 바와 같이 우리가 너희 각 사람에게 아버지가 자기 자녀에게 하듯 권면하고 위로하고 경계하노니',29580),
('1th-2-12','1th','데살로니가전서',2,12,'이는 너희를 부르사 자기 나라와 영광에 이르게 하시는 하나님께 합당히 행하게 하려 함이라',29581),
('1th-2-13','1th','데살로니가전서',2,13,'이러므로 우리가 하나님께 끊임없이 감사함은 너희가 우리에게 들은 바 하나님의 말씀을 받을 때에 사람의 말로 받지 아니하고 하나님의 말씀으로 받음이니 진실로 그러하도다 이 말씀이 또한 너희 믿는 자 가운데에서 역사하느니라',29582),
('1th-2-14','1th','데살로니가전서',2,14,'형제들아 너희가 그리스도 예수 안에서 유대에 있는 하나님의 교회들을 본받은 자 되었으니 그들이 유대인들에게 고난을 받음과 같이 너희도 너희 동족에게서 동일한 고난을 받았느니라',29583),
('1th-2-15','1th','데살로니가전서',2,15,'유대인은 주 예수와 선지자들을 죽이고 우리를 쫓아내고 하나님을 기쁘시게 하지 아니하고 모든 사람에게 대적이 되어',29584),
('1th-2-16','1th','데살로니가전서',2,16,'우리가 이방인에게 말하여 구원받게 함을 그들이 금하여 자기 죄를 항상 채우매 노하심이 끝까지 그들에게 임하였느니라',29585),
('1th-2-17','1th','데살로니가전서',2,17,'형제들아 우리가 잠시 너희를 떠난 것은 얼굴이요 마음은 아니니 너희 얼굴 보기를 열정으로 더욱 힘썼노라',29586),
('1th-2-18','1th','데살로니가전서',2,18,'그러므로 나 바울은 한번 두번 너희에게 가고자 하였으나 사탄이 우리를 막았도다',29587),
('1th-2-19','1th','데살로니가전서',2,19,'우리의 소망이나 기쁨이나 자랑의 면류관이 무엇이냐 그가 강림하실 때 우리 주 예수 앞에 너희가 아니냐',29588),
('1th-2-20','1th','데살로니가전서',2,20,'너희는 우리의 영광이요 기쁨이니라',29589),
('1th-3-1','1th','데살로니가전서',3,1,'이러므로 우리가 참다 못하여 우리만 아덴에 머물기를 좋게 생각하고',29590),
('1th-3-2','1th','데살로니가전서',3,2,'우리 형제 곧 그리스도의 복음을 전하는 하나님의 일꾼인 디모데를 보내노니 이는 너희를 굳건하게 하고 너희 믿음에 대하여 위로함으로',29591),
('1th-3-3','1th','데살로니가전서',3,3,'아무도 이 여러 환난 중에 흔들리지 않게 하려 함이라 우리가 이것을 위하여 세움 받은 줄을 너희가 친히 알리라',29592),
('1th-3-4','1th','데살로니가전서',3,4,'우리가 너희와 함께 있을 때에 장차 받을 환난을 너희에게 미리 말하였는데 과연 그렇게 된 것을 너희가 아느니라',29593),
('1th-3-5','1th','데살로니가전서',3,5,'이러므로 나도 참다 못하여 너희 믿음을 알기 위하여 그를 보내었노니 이는 혹 시험하는 자가 너희를 시험하여 우리 수고를 헛되게 할까 함이니',29594),
('1th-3-6','1th','데살로니가전서',3,6,'지금은 디모데가 너희에게로부터 와서 너희 믿음과 사랑의 기쁜 소식을 우리에게 전하고 또 너희가 항상 우리를 잘 생각하여 우리가 너희를 간절히 보고자 함과 같이 너희도 우리를 간절히 보고자 한다 하니',29595),
('1th-3-7','1th','데살로니가전서',3,7,'이러므로 형제들아 우리가 모든 궁핍과 환난 가운데서 너희 믿음으로 말미암아 너희에게 위로를 받았노라',29596),
('1th-3-8','1th','데살로니가전서',3,8,'그러므로 너희가 주 안에 굳게 선즉 우리가 이제는 살리라',29597),
('1th-3-9','1th','데살로니가전서',3,9,'우리가 우리 하나님 앞에서 너희로 말미암아 모든 기쁨으로 기뻐하니 너희를 위하여 능히 어떠한 감사로 하나님께 보답할까',29598),
('1th-3-10','1th','데살로니가전서',3,10,'주야로 심히 간구함은 너희 얼굴을 보고 너희 믿음이 부족한 것을 보충하게 하려 함이라',29599),
('1th-3-11','1th','데살로니가전서',3,11,'하나님 우리 아버지와 우리 주 예수는 우리 길을 너희에게로 갈 수 있게 하시오며',29600),
('1th-3-12','1th','데살로니가전서',3,12,'또 주께서 우리가 너희를 사랑함과 같이 너희도 피차간과 모든 사람에 대한 사랑이 더욱 많아 넘치게 하사',29601),
('1th-3-13','1th','데살로니가전서',3,13,'너희 마음을 굳건하게 하시고 우리 주 예수께서 그의 모든 성도와 함께 강림하실 때에 하나님 우리 아버지 앞에서 거룩함에 흠이 없게 하시기를 원하노라',29602),
('1th-4-1','1th','데살로니가전서',4,1,'그러므로 형제들아 우리가 끝으로 주 예수 안에서 너희에게 구하고 권면하노니 너희가 마땅히 어떻게 행하며 하나님을 기쁘시게 할 수 있는지를 우리에게 배웠으니 곧 너희가 행하는 바라 더욱 많이 힘쓰라',29603),
('1th-4-2','1th','데살로니가전서',4,2,'우리가 주 예수로 말미암아 너희에게 무슨 명령으로 준 것을 너희가 아느니라',29604),
('1th-4-3','1th','데살로니가전서',4,3,'하나님의 뜻은 이것이니 너희의 거룩함이라 곧 음란을 버리고',29605),
('1th-4-4','1th','데살로니가전서',4,4,'각각 거룩함과 존귀함으로 자기의 아내 대할 줄을 알고',29606),
('1th-4-5','1th','데살로니가전서',4,5,'하나님을 모르는 이방인과 같이 색욕을 따르지 말고',29607),
('1th-4-6','1th','데살로니가전서',4,6,'이 일에 분수를 넘어서 형제를 해하지 말라 이는 우리가 너희에게 미리 말하고 증언한 것과 같이 이 모든 일에 주께서 신원하여 주심이라',29608),
('1th-4-7','1th','데살로니가전서',4,7,'하나님이 우리를 부르심은 부정하게 하심이 아니요 거룩하게 하심이니',29609),
('1th-4-8','1th','데살로니가전서',4,8,'그러므로 저버리는 자는 사람을 저버림이 아니요 너희에게 그의 성령을 주신 하나님을 저버림이니라',29610),
('1th-4-9','1th','데살로니가전서',4,9,'형제 사랑에 관하여는 너희에게 쓸 것이 없음은 너희들 자신이 하나님의 가르치심을 받아 서로 사랑함이라',29611),
('1th-4-10','1th','데살로니가전서',4,10,'너희가 온 마게도냐 모든 형제에 대하여 과연 이것을 행하도다 형제들아 권하노니 더욱 그렇게 행하고',29612),
('1th-4-11','1th','데살로니가전서',4,11,'또 너희에게 명한 것 같이 조용히 자기 일을 하고 너희 손으로 일하기를 힘쓰라',29613),
('1th-4-12','1th','데살로니가전서',4,12,'이는 외인에 대하여 단정히 행하고 또한 아무 궁핍함이 없게 하려 함이라',29614),
('1th-4-13','1th','데살로니가전서',4,13,'형제들아 자는 자들에 관하여는 너희가 알지 못함을 우리가 원하지 아니하노니 이는 소망 없는 다른 이와 같이 슬퍼하지 않게 하려 함이라',29615),
('1th-4-14','1th','데살로니가전서',4,14,'우리가 예수께서 죽으셨다가 다시 살아나심을 믿을진대 이와 같이 예수 안에서 자는 자들도 하나님이 그와 함께 데리고 오시리라',29616),
('1th-4-15','1th','데살로니가전서',4,15,'우리가 주의 말씀으로 너희에게 이것을 말하노니 주께서 강림하실 때까지 우리 살아 남아 있는 자도 자는 자보다 결코 앞서지 못하리라',29617),
('1th-4-16','1th','데살로니가전서',4,16,'주께서 호령과 천사장의 소리와 하나님의 나팔 소리로 친히 하늘로부터 강림하시리니 그리스도 안에서 죽은 자들이 먼저 일어나고',29618),
('1th-4-17','1th','데살로니가전서',4,17,'그 후에 우리 살아 남은 자들도 그들과 함께 구름 속으로 끌어 올려 공중에서 주를 영접하게 하시리니 그리하여 우리가 항상 주와 함께 있으리라',29619),
('1th-4-18','1th','데살로니가전서',4,18,'그러므로 이러한 말로 서로 위로하라',29620),
('1th-5-1','1th','데살로니가전서',5,1,'형제들아 때와 시기에 관하여는 너희에게 쓸 것이 없음은',29621),
('1th-5-2','1th','데살로니가전서',5,2,'주의 날이 밤에 도둑 같이 이를 줄을 너희 자신이 자세히 알기 때문이라',29622),
('1th-5-3','1th','데살로니가전서',5,3,'그들이 평안하다, 안전하다 할 그 때에 임신한 여자에게 해산의 고통이 이름과 같이 멸망이 갑자기 그들에게 이르리니 결코 피하지 못하리라',29623),
('1th-5-4','1th','데살로니가전서',5,4,'형제들아 너희는 어둠에 있지 아니하매 그 날이 도둑 같이 너희에게 임하지 못하리니',29624),
('1th-5-5','1th','데살로니가전서',5,5,'너희는 다 빛의 아들이요 낮의 아들이라 우리가 밤이나 어둠에 속하지 아니하나니',29625),
('1th-5-6','1th','데살로니가전서',5,6,'그러므로 우리는 다른 이들과 같이 자지 말고 오직 깨어 정신을 차릴지라',29626),
('1th-5-7','1th','데살로니가전서',5,7,'자는 자들은 밤에 자고 취하는 자들은 밤에 취하되',29627),
('1th-5-8','1th','데살로니가전서',5,8,'우리는 낮에 속하였으니 정신을 차리고 믿음과 사랑의 호심경을 붙이고 구원의 소망의 투구를 쓰자',29628),
('1th-5-9','1th','데살로니가전서',5,9,'하나님이 우리를 세우심은 노하심에 이르게 하심이 아니요 오직 우리 주 예수 그리스도로 말미암아 구원을 받게 하심이라',29629),
('1th-5-10','1th','데살로니가전서',5,10,'예수께서 우리를 위하여 죽으사 우리로 하여금 깨어 있든지 자든지 자기와 함께 살게 하려 하셨느니라',29630),
('1th-5-11','1th','데살로니가전서',5,11,'그러므로 피차 권면하고 서로 덕을 세우기를 너희가 하는 것 같이 하라',29631),
('1th-5-12','1th','데살로니가전서',5,12,'형제들아 우리가 너희에게 구하노니 너희 가운데서 수고하고 주 안에서 너희를 다스리며 권하는 자들을 너희가 알고',29632),
('1th-5-13','1th','데살로니가전서',5,13,'그들의 역사로 말미암아 사랑 안에서 가장 귀히 여기며 너희끼리 화목하라',29633),
('1th-5-14','1th','데살로니가전서',5,14,'또 형제들아 너희를 권면하노니 게으른 자들을 권계하며 마음이 약한 자들을 격려하고 힘이 없는 자들을 붙들어 주며 모든 사람에게 오래 참으라',29634),
('1th-5-15','1th','데살로니가전서',5,15,'삼가 누가 누구에게든지 악으로 악을 갚지 말게 하고 서로 대하든지 모든 사람을 대하든지 항상 선을 따르라',29635),
('1th-5-16','1th','데살로니가전서',5,16,'항상 기뻐하라',29636),
('1th-5-17','1th','데살로니가전서',5,17,'쉬지 말고 기도하라',29637),
('1th-5-18','1th','데살로니가전서',5,18,'범사에 감사하라 이것이 그리스도 예수 안에서 너희를 향하신 하나님의 뜻이니라',29638),
('1th-5-19','1th','데살로니가전서',5,19,'성령을 소멸하지 말며',29639),
('1th-5-20','1th','데살로니가전서',5,20,'예언을 멸시하지 말고',29640),
('1th-5-21','1th','데살로니가전서',5,21,'범사에 헤아려 좋은 것을 취하고',29641),
('1th-5-22','1th','데살로니가전서',5,22,'악은 어떤 모양이라도 버리라',29642),
('1th-5-23','1th','데살로니가전서',5,23,'평강의 하나님이 친히 너희를 온전히 거룩하게 하시고 또 너희의 온 영과 혼과 몸이 우리 주 예수 그리스도께서 강림하실 때에 흠 없게 보전되기를 원하노라',29643),
('1th-5-24','1th','데살로니가전서',5,24,'너희를 부르시는 이는 미쁘시니 그가 또한 이루시리라',29644),
('1th-5-25','1th','데살로니가전서',5,25,'형제들아 우리를 위하여 기도하라',29645),
('1th-5-26','1th','데살로니가전서',5,26,'거룩하게 입맞춤으로 모든 형제에게 문안하라',29646),
('1th-5-27','1th','데살로니가전서',5,27,'내가 주를 힘입어 너희를 명하노니 모든 형제에게 이 편지를 읽어 주라',29647),
('1th-5-28','1th','데살로니가전서',5,28,'우리 주 예수 그리스도의 은혜가 너희에게 있을지어다',29648),
('2th-1-1','2th','데살로니가후서',1,1,'바울과 실루아노와 디모데는 하나님 우리 아버지와 주 예수 그리스도 안에 있는 데살로니가인의 교회에 편지하노니',29649),
('2th-1-2','2th','데살로니가후서',1,2,'하나님 아버지와 주 예수 그리스도로부터 은혜와 평강이 너희에게 있을지어다',29650),
('2th-1-3','2th','데살로니가후서',1,3,'형제들아 우리가 너희를 위하여 항상 하나님께 감사할지니 이것이 당연함은 너희의 믿음이 더욱 자라고 너희가 다 각기 서로 사랑함이 풍성함이니',29651),
('2th-1-4','2th','데살로니가후서',1,4,'그러므로 너희가 견디고 있는 모든 박해와 환난 중에서 너희 인내와 믿음으로 말미암아 하나님의 여러 교회에서 우리가 친히 자랑하노라',29652),
('2th-1-5','2th','데살로니가후서',1,5,'이는 하나님의 공의로운 심판의 표요 너희로 하여금 하나님의 나라에 합당한 자로 여김을 받게 하려 함이니 그 나라를 위하여 너희가 또한 고난을 받느니라',29653),
('2th-1-6','2th','데살로니가후서',1,6,'너희로 환난을 받게 하는 자들에게는 환난으로 갚으시고',29654),
('2th-1-7','2th','데살로니가후서',1,7,'환난을 받는 너희에게는 우리와 함께 안식으로 갚으시는 것이 하나님의 공의시니 주 예수께서 자기의 능력의 천사들과 함께 하늘로부터 불꽃 가운데에 나타나실 때에',29655),
('2th-1-8','2th','데살로니가후서',1,8,'하나님을 모르는 자들과 우리 주 예수의 복음에 복종하지 않는 자들에게 형벌을 내리시리니',29656),
('2th-1-9','2th','데살로니가후서',1,9,'이런 자들은 주의 얼굴과 그의 힘의 영광을 떠나 영원한 멸망의 형벌을 받으리로다',29657),
('2th-1-10','2th','데살로니가후서',1,10,'그 날에 그가 강림하사 그의 성도들에게서 영광을 받으시고 모든 믿는 자들에게서 놀랍게 여김을 얻으시리니 이는 (우리의 증거가 너희에게 믿어졌음이라)',29658),
('2th-1-11','2th','데살로니가후서',1,11,'이러므로 우리도 항상 너희를 위하여 기도함은 우리 하나님이 너희를 그 부르심에 합당한 자로 여기시고 모든 선을 기뻐함과 믿음의 역사를 능력으로 이루게 하시고',29659),
('2th-1-12','2th','데살로니가후서',1,12,'우리 하나님과 주 예수 그리스도의 은혜대로 우리 주 예수의 이름이 너희 가운데서 영광을 받으시고 너희도 그 안에서 영광을 받게 하려 함이라',29660),
('2th-2-1','2th','데살로니가후서',2,1,'형제들아 우리가 너희에게 구하는 것은 우리 주 예수 그리스도의 강림하심과 우리가 그 앞에 모임에 관하여',29661),
('2th-2-2','2th','데살로니가후서',2,2,'영으로나 또는 말로나 또는 우리에게서 받았다 하는 편지로나 주의 날이 이르렀다고 해서 쉽게 마음이 흔들리거나 두려워하거나 하지 말아야 한다는 것이라',29662),
('2th-2-3','2th','데살로니가후서',2,3,'누가 어떻게 하여도 너희가 미혹되지 말라 먼저 배교하는 일이 있고 저 불법의 사람 곧 멸망의 아들이 나타나기 전에는 그 날이 이르지 아니하리니',29663),
('2th-2-4','2th','데살로니가후서',2,4,'그는 대적하는 자라 신이라고 불리는 모든 것과 숭배함을 받는 것에 대항하여 그 위에 자기를 높이고 하나님의 성전에 앉아 자기를 하나님이라고 내세우느니라',29664),
('2th-2-5','2th','데살로니가후서',2,5,'내가 너희와 함께 있을 때에 이 일을 너희에게 말한 것을 기억하지 못하느냐',29665),
('2th-2-6','2th','데살로니가후서',2,6,'너희는 지금 그로 하여금 그의 때에 나타나게 하려 하여 막는 것이 있는 것을 아나니',29666),
('2th-2-7','2th','데살로니가후서',2,7,'불법의 비밀이 이미 활동하였으나 지금은 그것을 막는 자가 있어 그 중에서 옮겨질 때까지 하리라',29667),
('2th-2-8','2th','데살로니가후서',2,8,'그 때에 불법한 자가 나타나리니 주 예수께서 그 입의 기운으로 그를 죽이시고 강림하여 나타나심으로 폐하시리라',29668),
('2th-2-9','2th','데살로니가후서',2,9,'악한 자의 나타남은 사탄의 활동을 따라 모든 능력과 표적과 거짓 기적과',29669),
('2th-2-10','2th','데살로니가후서',2,10,'불의의 모든 속임으로 멸망하는 자들에게 있으리니 이는 그들이 진리의 사랑을 받지 아니하여 구원함을 받지 못함이라',29670),
('2th-2-11','2th','데살로니가후서',2,11,'이러므로 하나님이 미혹의 역사를 그들에게 보내사 거짓 것을 믿게 하심은',29671),
('2th-2-12','2th','데살로니가후서',2,12,'진리를 믿지 않고 불의를 좋아하는 모든 자들로 하여금 심판을 받게 하려 하심이라',29672),
('2th-2-13','2th','데살로니가후서',2,13,'주께서 사랑하시는 형제들아 우리가 항상 너희에 관하여 마땅히 하나님께 감사할 것은 하나님이 처음부터 너희를 택하사 성령의 거룩하게 하심과 진리를 믿음으로 구원을 받게 하심이니',29673),
('2th-2-14','2th','데살로니가후서',2,14,'이를 위하여 우리의 복음으로 너희를 부르사 우리 주 예수 그리스도의 영광을 얻게 하려 하심이니라',29674),
('2th-2-15','2th','데살로니가후서',2,15,'그러므로 형제들아 굳건하게 서서 말로나 우리의 편지로 가르침을 받은 전통을 지키라',29675),
('2th-2-16','2th','데살로니가후서',2,16,'우리 주 예수 그리스도와 우리를 사랑하시고 영원한 위로와 좋은 소망을 은혜로 주신 하나님 우리 아버지께서',29676),
('2th-2-17','2th','데살로니가후서',2,17,'너희 마음을 위로하시고 모든 선한 일과 말에 굳건하게 하시기를 원하노라',29677),
('2th-3-1','2th','데살로니가후서',3,1,'끝으로 형제들아 너희는 우리를 위하여 기도하기를 주의 말씀이 너희 가운데서와 같이 퍼져 나가 영광스럽게 되고',29678),
('2th-3-2','2th','데살로니가후서',3,2,'또한 우리를 부당하고 악한 사람들에게서 건지시옵소서 하라 믿음은 모든 사람의 것이 아니니라',29679),
('2th-3-3','2th','데살로니가후서',3,3,'주는 미쁘사 너희를 굳건하게 하시고 악한 자에게서 지키시리라',29680),
('2th-3-4','2th','데살로니가후서',3,4,'너희에 대하여는 우리가 명한 것을 너희가 행하고 또 행할 줄을 우리가 주 안에서 확신하노니',29681),
('2th-3-5','2th','데살로니가후서',3,5,'주께서 너희 마음을 인도하여 하나님의 사랑과 그리스도의 인내에 들어가게 하시기를 원하노라',29682),
('2th-3-6','2th','데살로니가후서',3,6,'형제들아 우리 주 예수 그리스도의 이름으로 너희를 명하노니 게으르게 행하고 우리에게서 받은 전통대로 행하지 아니하는 모든 형제에게서 떠나라',29683),
('2th-3-7','2th','데살로니가후서',3,7,'어떻게 우리를 본받아야 할지를 너희가 스스로 아나니 우리가 너희 가운데서 무질서하게 행하지 아니하며',29684),
('2th-3-8','2th','데살로니가후서',3,8,'누구에게서든지 음식을 값없이 먹지 않고 오직 수고하고 애써 주야로 일함은 너희 아무에게도 폐를 끼치지 아니하려 함이니',29685),
('2th-3-9','2th','데살로니가후서',3,9,'우리에게 권리가 없는 것이 아니요 오직 스스로 너희에게 본을 보여 우리를 본받게 하려 함이니라',29686),
('2th-3-10','2th','데살로니가후서',3,10,'우리가 너희와 함께 있을 때에도 너희에게 명하기를 누구든지 일하기 싫어하거든 먹지도 말게 하라 하였더니',29687),
('2th-3-11','2th','데살로니가후서',3,11,'우리가 들은즉 너희 가운데 게으르게 행하여 도무지 일하지 아니하고 일을 만들기만 하는 자들이 있다 하니',29688),
('2th-3-12','2th','데살로니가후서',3,12,'이런 자들에게 우리가 명하고 주 예수 그리스도 안에서 권하기를 조용히 일하여 자기 양식을 먹으라 하노라',29689),
('2th-3-13','2th','데살로니가후서',3,13,'형제들아 너희는 선을 행하다가 낙심하지 말라',29690),
('2th-3-14','2th','데살로니가후서',3,14,'누가 이 편지에 한 우리 말을 순종하지 아니하거든 그 사람을 지목하여 사귀지 말고 그로 하여금 부끄럽게 하라',29691),
('2th-3-15','2th','데살로니가후서',3,15,'그러나 원수와 같이 생각하지 말고 형제 같이 권면하라',29692),
('2th-3-16','2th','데살로니가후서',3,16,'평강의 주께서 친히 때마다 일마다 너희에게 평강을 주시고 주께서 너희 모든 사람과 함께 하시기를 원하노라',29693),
('2th-3-17','2th','데살로니가후서',3,17,'나 바울은 친필로 문안하노니 이는 편지마다 표시로서 이렇게 쓰노라',29694),
('2th-3-18','2th','데살로니가후서',3,18,'우리 주 예수 그리스도의 은혜가 너희 무리에게 있을지어다',29695),
('1ti-1-1','1ti','디모데전서',1,1,'우리 구주 하나님과 우리의 소망이신 그리스도 예수의 명령을 따라 그리스도 예수의 사도 된 바울은',29696),
('1ti-1-2','1ti','디모데전서',1,2,'믿음 안에서 참 아들 된 디모데에게 편지하노니 하나님 아버지와 그리스도 예수 우리 주께로부터 은혜와 긍휼과 평강이 네게 있을지어다',29697),
('1ti-1-3','1ti','디모데전서',1,3,'내가 마게도냐로 갈 때에 너를 권하여 에베소에 머물라 한 것은 어떤 사람들을 명하여 다른 교훈을 가르치지 말며',29698),
('1ti-1-4','1ti','디모데전서',1,4,'신화와 족보에 끝없이 몰두하지 말게 하려 함이라 이런 것은 믿음 안에 있는 하나님의 경륜을 이룸보다 도리어 변론을 내는 것이라',29699),
('1ti-1-5','1ti','디모데전서',1,5,'이 교훈의 목적은 청결한 마음과 선한 양심과 거짓이 없는 믿음에서 나오는 사랑이거늘',29700),
('1ti-1-6','1ti','디모데전서',1,6,'사람들이 이에서 벗어나 헛된 말에 빠져',29701),
('1ti-1-7','1ti','디모데전서',1,7,'율법의 선생이 되려 하나 자기가 말하는 것이나 자기가 확증하는 것도 깨닫지 못하는도다',29702),
('1ti-1-8','1ti','디모데전서',1,8,'그러나 율법은 사람이 그것을 적법하게만 쓰면 선한 것임을 우리는 아노라',29703),
('1ti-1-9','1ti','디모데전서',1,9,'알 것은 이것이니 율법은 옳은 사람을 위하여 세운 것이 아니요 오직 불법한 자와 복종하지 아니하는 자와 경건하지 아니한 자와 죄인과 거룩하지 아니한 자와 망령된 자와 아버지를 죽이는 자와 어머니를 죽이는 자와 살인하는 자며',29704),
('1ti-1-10','1ti','디모데전서',1,10,'음행하는 자와 남색하는 자와 인신 매매를 하는 자와 거짓말하는 자와 거짓맹세하는 자와 기타 바른 교훈을 거스르는 자를 위함이니',29705),
('1ti-1-11','1ti','디모데전서',1,11,'이 교훈은 내게 맡기신 바 복되신 하나님의 영광의 복음을 따름이니라',29706),
('1ti-1-12','1ti','디모데전서',1,12,'나를 능하게 하신 그리스도 예수 우리 주께 내가 감사함은 나를 충성되이 여겨 내게 직분을 맡기심이니',29707),
('1ti-1-13','1ti','디모데전서',1,13,'내가 전에는 비방자요 박해자요 폭행자였으나 도리어 긍휼을 입은 것은 내가 믿지 아니할 때에 알지 못하고 행하였음이라',29708),
('1ti-1-14','1ti','디모데전서',1,14,'우리 주의 은혜가 그리스도 예수 안에 있는 믿음과 사랑과 함께 넘치도록 풍성하였도다',29709),
('1ti-1-15','1ti','디모데전서',1,15,'미쁘다 모든 사람이 받을 만한 이 말이여 그리스도 예수께서 죄인을 구원하시려고 세상에 임하셨다 하였도다 죄인 중에 내가 괴수니라',29710),
('1ti-1-16','1ti','디모데전서',1,16,'그러나 내가 긍휼을 입은 까닭은 예수 그리스도께서 내게 먼저 일체 오래 참으심을 보이사 후에 주를 믿어 영생 얻는 자들에게 본이 되게 하려 하심이라',29711),
('1ti-1-17','1ti','디모데전서',1,17,'영원하신 왕 곧 썩지 아니하고 보이지 아니하고 홀로 하나이신 하나님께 존귀와 영광이 영원무궁하도록 있을지어다 아멘',29712),
('1ti-1-18','1ti','디모데전서',1,18,'아들 디모데야 내가 네게 이 교훈으로써 명하노니 전에 너를 지도한 예언을 따라 그것으로 선한 싸움을 싸우며',29713),
('1ti-1-19','1ti','디모데전서',1,19,'믿음과 착한 양심을 가지라 어떤 이들은 이 양심을 버렸고 그 믿음에 관하여는 파선하였느니라',29714),
('1ti-1-20','1ti','디모데전서',1,20,'그 가운데 후메내오와 알렉산더가 있으니 내가 사탄에게 내준 것은 그들로 훈계를 받아 신성을 모독하지 못하게 하려 함이라',29715),
('1ti-2-1','1ti','디모데전서',2,1,'그러므로 내가 첫째로 권하노니 모든 사람을 위하여 간구와 기도와 도고와 감사를 하되',29716),
('1ti-2-2','1ti','디모데전서',2,2,'임금들과 높은 지위에 있는 모든 사람을 위하여 하라 이는 우리가 모든 경건과 단정함으로 고요하고 평안한 생활을 하려 함이라',29717),
('1ti-2-3','1ti','디모데전서',2,3,'이것이 우리 구주 하나님 앞에 선하고 받으실 만한 것이니',29718),
('1ti-2-4','1ti','디모데전서',2,4,'하나님은 모든 사람이 구원을 받으며 진리를 아는 데에 이르기를 원하시느니라',29719),
('1ti-2-5','1ti','디모데전서',2,5,'하나님은 한 분이시요 또 하나님과 사람 사이에 중보자도 한 분이시니 곧 사람이신 그리스도 예수라',29720),
('1ti-2-6','1ti','디모데전서',2,6,'그가 모든 사람을 위하여 자기를 대속물로 주셨으니 기약이 이르러 주신 증거니라',29721),
('1ti-2-7','1ti','디모데전서',2,7,'이를 위하여 내가 전파하는 자와 사도로 세움을 입은 것은 참말이요 거짓말이 아니니 믿음과 진리 안에서 내가 이방인의 스승이 되었노라',29722),
('1ti-2-8','1ti','디모데전서',2,8,'그러므로 각처에서 남자들이 분노와 다툼이 없이 거룩한 손을 들어 기도하기를 원하노라',29723),
('1ti-2-9','1ti','디모데전서',2,9,'또 이와 같이 여자들도 단정하게 옷을 입으며 소박함과 정절로써 자기를 단장하고 땋은 머리와 금이나 진주나 값진 옷으로 하지 말고',29724),
('1ti-2-10','1ti','디모데전서',2,10,'오직 선행으로 하기를 원하노라 이것이 하나님을 경외한다 하는 자들에게 마땅한 것이니라',29725),
('1ti-2-11','1ti','디모데전서',2,11,'여자는 일체 순종함으로 조용히 배우라',29726),
('1ti-2-12','1ti','디모데전서',2,12,'여자가 가르치는 것과 남자를 주관하는 것을 허락하지 아니하노니 오직 조용할지니라',29727),
('1ti-2-13','1ti','디모데전서',2,13,'이는 아담이 먼저 지음을 받고 하와가 그 후며',29728),
('1ti-2-14','1ti','디모데전서',2,14,'아담이 속은 것이 아니고 여자가 속아 죄에 빠졌음이라',29729),
('1ti-2-15','1ti','디모데전서',2,15,'그러나 여자들이 만일 정숙함으로써 믿음과 사랑과 거룩함에 거하면 그의 해산함으로 구원을 얻으리라',29730),
('1ti-3-1','1ti','디모데전서',3,1,'미쁘다 이 말이여, 곧 사람이 감독의 직분을 얻으려 함은 선한 일을 사모하는 것이라 함이로다',29731),
('1ti-3-2','1ti','디모데전서',3,2,'그러므로 감독은 책망할 것이 없으며 한 아내의 남편이 되며 절제하며 신중하며 단정하며 나그네를 대접하며 가르치기를 잘하며',29732),
('1ti-3-3','1ti','디모데전서',3,3,'술을 즐기지 아니하며 구타하지 아니하며 오직 관용하며 다투지 아니하며 돈을 사랑하지 아니하며',29733),
('1ti-3-4','1ti','디모데전서',3,4,'자기 집을 잘 다스려 자녀들로 모든 공손함으로 복종하게 하는 자라야 할지며',29734),
('1ti-3-5','1ti','디모데전서',3,5,'(사람이 자기 집을 다스릴 줄 알지 못하면 어찌 하나님의 교회를 돌보리요)',29735),
('1ti-3-6','1ti','디모데전서',3,6,'새로 입교한 자도 말지니 교만하여져서 마귀를 정죄하는 그 정죄에 빠질까 함이요',29736),
('1ti-3-7','1ti','디모데전서',3,7,'또한 외인에게서도 선한 증거를 얻은 자라야 할지니 비방과 마귀의 올무에 빠질까 염려하라',29737),
('1ti-3-8','1ti','디모데전서',3,8,'이와 같이 집사들도 정중하고 일구이언을 하지 아니하고 술에 인박히지 아니하고 더러운 이를 탐하지 아니하고',29738),
('1ti-3-9','1ti','디모데전서',3,9,'깨끗한 양심에 믿음의 비밀을 가진 자라야 할지니',29739),
('1ti-3-10','1ti','디모데전서',3,10,'이에 이 사람들을 먼저 시험하여 보고 그 후에 책망할 것이 없으면 집사의 직분을 맡게 할 것이요',29740),
('1ti-3-11','1ti','디모데전서',3,11,'여자들도 이와 같이 정숙하고 모함하지 아니하며 절제하며 모든 일에 충성된 자라야 할지니라',29741),
('1ti-3-12','1ti','디모데전서',3,12,'집사들은 한 아내의 남편이 되어 자녀와 자기 집을 잘 다스리는 자일지니',29742),
('1ti-3-13','1ti','디모데전서',3,13,'집사의 직분을 잘한 자들은 아름다운 지위와 그리스도 예수 안에 있는 믿음에 큰 담력을 얻느니라',29743),
('1ti-3-14','1ti','디모데전서',3,14,'내가 속히 네게 가기를 바라나 이것을 네게 쓰는 것은',29744),
('1ti-3-15','1ti','디모데전서',3,15,'만일 내가 지체하면 너로 하여금 하나님의 집에서 어떻게 행하여야 할지를 알게 하려 함이니 이 집은 살아 계신 하나님의 교회요 진리의 기둥과 터니라',29745),
('1ti-3-16','1ti','디모데전서',3,16,'크도다 경건의 비밀이여, 그렇지 않다 하는 이 없도다. 그는 육신으로 나타난 바 되시고 영으로 의롭다 하심을 받으시고 천사들에게 보이시고 만국에서 전파되시고 세상에서 믿은 바 되시고 영광 가운데서 올려지셨느니라',29746),
('1ti-4-1','1ti','디모데전서',4,1,'그러나 성령이 밝히 말씀하시기를 후일에 어떤 사람들이 믿음에서 떠나 미혹하는 영과 귀신의 가르침을 따르리라 하셨으니',29747),
('1ti-4-2','1ti','디모데전서',4,2,'자기 양심이 화인을 맞아서 외식함으로 거짓말하는 자들이라',29748),
('1ti-4-3','1ti','디모데전서',4,3,'혼인을 금하고 어떤 음식물은 먹지 말라고 할 터이나 음식물은 하나님이 지으신 바니 믿는 자들과 진리를 아는 자들이 감사함으로 받을 것이니라',29749),
('1ti-4-4','1ti','디모데전서',4,4,'하나님께서 지으신 모든 것이 선하매 감사함으로 받으면 버릴 것이 없나니',29750),
('1ti-4-5','1ti','디모데전서',4,5,'하나님의 말씀과 기도로 거룩하여짐이라',29751),
('1ti-4-6','1ti','디모데전서',4,6,'네가 이것으로 형제를 깨우치면 그리스도 예수의 좋은 일꾼이 되어 믿음의 말씀과 네가 따르는 좋은 교훈으로 양육을 받으리라',29752),
('1ti-4-7','1ti','디모데전서',4,7,'망령되고 허탄한 신화를 버리고 경건에 이르도록 네 자신을 연단하라',29753),
('1ti-4-8','1ti','디모데전서',4,8,'육체의 연단은 약간의 유익이 있으나 경건은 범사에 유익하니 금생과 내생에 약속이 있느니라',29754),
('1ti-4-9','1ti','디모데전서',4,9,'미쁘다 이 말이여 모든 사람들이 받을 만하도다',29755),
('1ti-4-10','1ti','디모데전서',4,10,'이를 위하여 우리가 수고하고 힘쓰는 것은 우리 소망을 살아 계신 하나님께 둠이니 곧 모든 사람 특히 믿는 자들의 구주시라',29756),
('1ti-4-11','1ti','디모데전서',4,11,'너는 이것들을 명하고 가르치라',29757),
