('1ti-4-13','1ti','디모데전서',4,13,'내가 이를 때까지 읽는 것과 권하는 것과 가르치는 것에 전념하라',29759),
('1ti-4-14','1ti','디모데전서',4,14,'네 속에 있는 은사 곧 장로의 회에서 안수 받을 때에 예언을 통하여 받은 것을 가볍게 여기지 말며',29760),
('1ti-4-15','1ti','디모데전서',4,15,'이 모든 일에 전심 전력하여 너의 성숙함을 모든 사람에게 나타나게 하라',29761),
('1ti-4-16','1ti','디모데전서',4,16,'네가 네 자신과 가르침을 살펴 이 일을 계속하라 이것을 행함으로 네 자신과 네게 듣는 자를 구원하리라',29762),
('1ti-5-1','1ti','디모데전서',5,1,'늙은이를 꾸짖지 말고 권하되 아버지에게 하듯 하며 젊은이에게는 형제에게 하듯 하고',29763),
('1ti-5-2','1ti','디모데전서',5,2,'늙은 여자에게는 어머니에게 하듯 하며 젊은 여자에게는 온전히 깨끗함으로 자매에게 하듯 하라',29764),
