('1ti-5-5','1ti','디모데전서',5,5,'참 과부로서 외로운 자는 하나님께 소망을 두어 주야로 항상 간구와 기도를 하거니와',29767),
('1ti-5-6','1ti','디모데전서',5,6,'향락을 좋아하는 자는 살았으나 죽었느니라',29768),
