('1ti-5-9','1ti','디모데전서',5,9,'과부로 명부에 올릴 자는 나이가 육십이 덜 되지 아니하고 한 남편의 아내였던 자로서',29771),
('1ti-5-10','1ti','디모데전서',5,10,'선한 행실의 증거가 있어 혹은 자녀를 양육하며 혹은 나그네를 대접하며 혹은 성도들의 발을 씻으며 혹은 환난 당한 자들을 구제하며 혹은 모든 선한 일을 행한 자라야 할 것이요',29772),
('1ti-5-11','1ti','디모데전서',5,11,'젊은 과부는 올리지 말지니 이는 정욕으로 그리스도를 배반할 때에 시집 가고자 함이니',29773),
('1ti-5-12','1ti','디모데전서',5,12,'처음 믿음을 저버렸으므로 정죄를 받느니라',29774),
('1ti-5-13','1ti','디모데전서',5,13,'또 그들은 게으름을 익혀 집집으로 돌아 다니고 게으를 뿐 아니라 쓸데없는 말을 하며 일을 만들며 마땅히 아니할 말을 하나니',29775),
('1ti-5-14','1ti','디모데전서',5,14,'그러므로 젊은이는 시집 가서 아이를 낳고 집을 다스리고 대적에게 비방할 기회를 조금도 주지 말기를 원하노라',29776),
('1ti-5-15','1ti','디모데전서',5,15,'이미 사탄에게 돌아간 자들도 있도다',29777),
('1ti-5-16','1ti','디모데전서',5,16,'만일 믿는 여자에게 과부 친척이 있거든 자기가 도와 주고 교회가 짐지지 않게 하라 이는 참 과부를 도와 주게 하려 함이라',29778),
('1ti-5-17','1ti','디모데전서',5,17,'잘 다스리는 장로들은 배나 존경할 자로 알되 말씀과 가르침에 수고하는 이들에게는 더욱 그리할 것이니라',29779),
('1ti-5-18','1ti','디모데전서',5,18,'성경에 일렀으되 곡식을 밟아 떠는 소의 입에 망을 씌우지 말라 하였고 또 일꾼이 그 삯을 받는 것은 마땅하다 하였느니라',29780),
('1ti-5-19','1ti','디모데전서',5,19,'장로에 대한 고발은 두세 증인이 없으면 받지 말 것이요',29781),
('1ti-5-20','1ti','디모데전서',5,20,'범죄한 자들을 모든 사람 앞에서 꾸짖어 나머지 사람들로 두려워하게 하라',29782),
('1ti-5-21','1ti','디모데전서',5,21,'하나님과 그리스도 예수와 택하심을 받은 천사들 앞에서 내가 엄히 명하노니 너는 편견이 없이 이것들을 지켜 아무 일도 불공평하게 하지 말며',29783),
('1ti-5-22','1ti','디모데전서',5,22,'아무에게나 경솔히 안수하지 말고 다른 사람의 죄에 간섭하지 말며 네 자신을 지켜 정결하게 하라',29784),
('1ti-5-23','1ti','디모데전서',5,23,'이제부터는 물만 마시지 말고 네 위장과 자주 나는 병을 위하여는 포도주를 조금씩 쓰라',29785),
('1ti-5-24','1ti','디모데전서',5,24,'어떤 사람들의 죄는 밝히 드러나 먼저 심판에 나아가고 어떤 사람들의 죄는 그 뒤를 따르나니',29786),
('1ti-5-25','1ti','디모데전서',5,25,'이와 같이 선행도 밝히 드러나고 그렇지 아니한 것도 숨길 수 없느니라',29787),
('1ti-6-1','1ti','디모데전서',6,1,'무릇 멍에 아래에 있는 종들은 자기 상전들을 범사에 마땅히 공경할 자로 알지니 이는 하나님의 이름과 교훈으로 비방을 받지 않게 하려 함이라',29788),
('1ti-6-2','1ti','디모데전서',6,2,'믿는 상전이 있는 자들은 그 상전을 형제라고 가볍게 여기지 말고 더 잘 섬기게 하라 이는 유익을 받는 자들이 믿는 자요 사랑을 받는 자임이라 너는 이것들을 가르치고 권하라',29789),
('1ti-6-3','1ti','디모데전서',6,3,'누구든지 다른 교훈을 하며 바른 말 곧 우리 주 예수 그리스도의 말씀과 경건에 관한 교훈을 따르지 아니하면',29790),
('1ti-6-4','1ti','디모데전서',6,4,'그는 교만하여 아무 것도 알지 못하고 변론과 언쟁을 좋아하는 자니 이로써 투기와 분쟁과 비방과 악한 생각이 나며',29791),
('1ti-6-5','1ti','디모데전서',6,5,'마음이 부패하여지고 진리를 잃어 버려 경건을 이익의 방도로 생각하는 자들의 다툼이 일어나느니라',29792),
('1ti-6-6','1ti','디모데전서',6,6,'그러나 자족하는 마음이 있으면 경건은 큰 이익이 되느니라',29793),
('1ti-6-7','1ti','디모데전서',6,7,'우리가 세상에 아무 것도 가지고 온 것이 없으매 또한 아무 것도 가지고 가지 못하리니',29794),
('1ti-6-8','1ti','디모데전서',6,8,'우리가 먹을 것과 입을 것이 있은즉 족한 줄로 알 것이니라',29795),
('1ti-6-9','1ti','디모데전서',6,9,'부하려 하는 자들은 시험과 올무와 여러 가지 어리석고 해로운 욕심에 떨어지나니 곧 사람으로 파멸과 멸망에 빠지게 하는 것이라',29796),
('1ti-6-10','1ti','디모데전서',6,10,'돈을 사랑함이 일만 악의 뿌리가 되나니 이것을 탐내는 자들은 미혹을 받아 믿음에서 떠나 많은 근심으로써 자기를 찔렀도다',29797),
('1ti-6-11','1ti','디모데전서',6,11,'오직 너 하나님의 사람아 이것들을 피하고 의와 경건과 믿음과 사랑과 인내와 온유를 따르며',29798),
('1ti-6-12','1ti','디모데전서',6,12,'믿음의 선한 싸움을 싸우라 영생을 취하라 이를 위하여 네가 부르심을 받았고 많은 증인 앞에서 선한 증언을 하였도다',29799),
('1ti-6-13','1ti','디모데전서',6,13,'만물을 살게 하신 하나님 앞과 본디오 빌라도를 향하여 선한 증언을 하신 그리스도 예수 앞에서 내가 너를 명하노니',29800),
('1ti-6-14','1ti','디모데전서',6,14,'우리 주 예수 그리스도께서 나타나실 때까지 흠도 없고 책망 받을 것도 없이 이 명령을 지키라',29801),
('1ti-6-15','1ti','디모데전서',6,15,'기약이 이르면 하나님이 그의 나타나심을 보이시리니 하나님은 복되시고 유일하신 주권자이시며 만왕의 왕이시며 만주의 주시요',29802),
('1ti-6-16','1ti','디모데전서',6,16,'오직 그에게만 죽지 아니함이 있고 가까이 가지 못할 빛에 거하시고 어떤 사람도 보지 못하였고 또 볼 수 없는 이시니 그에게 존귀와 영원한 권능을 돌릴지어다 아멘',29803),
('1ti-6-17','1ti','디모데전서',6,17,'네가 이 세대에서 부한 자들을 명하여 마음을 높이지 말고 정함이 없는 재물에 소망을 두지 말고 오직 우리에게 모든 것을 후히 주사 누리게 하시는 하나님께 두며',29804),
('1ti-6-18','1ti','디모데전서',6,18,'선을 행하고 선한 사업을 많이 하고 나누어 주기를 좋아하며 너그러운 자가 되게 하라',29805),
('1ti-6-19','1ti','디모데전서',6,19,'이것이 장래에 자기를 위하여 좋은 터를 쌓아 참된 생명을 취하는 것이니라',29806),
('1ti-6-20','1ti','디모데전서',6,20,'디모데야 망령되고 헛된 말과 거짓된 지식의 반론을 피함으로 네게 부탁한 것을 지키라',29807),
('1ti-6-21','1ti','디모데전서',6,21,'이것을 따르는 사람들이 있어 믿음에서 벗어났느니라 은혜가 너희와 함께 있을지어다',29808),
('2ti-1-1','2ti','디모데후서',1,1,'하나님의 뜻으로 말미암아 그리스도 예수 안에 있는 생명의 약속대로 그리스도 예수의 사도 된 바울은',29809),
('2ti-1-2','2ti','디모데후서',1,2,'사랑하는 아들 디모데에게 편지하노니 하나님 아버지와 그리스도 예수 우리 주께로부터 은혜와 긍휼과 평강이 네게 있을지어다',29810),
('2ti-1-3','2ti','디모데후서',1,3,'내가 밤낮 간구하는 가운데 쉬지 않고 너를 생각하여 청결한 양심으로 조상적부터 섬겨 오는 하나님께 감사하고',29811),
('2ti-1-4','2ti','디모데후서',1,4,'네 눈물을 생각하여 너 보기를 원함은 내 기쁨이 가득하게 하려 함이니',29812),
('2ti-1-5','2ti','디모데후서',1,5,'이는 네 속에 거짓이 없는 믿음이 있음을 생각함이라 이 믿음은 먼저 네 외조모 로이스와 네 어머니 유니게 속에 있더니 네 속에도 있는 줄을 확신하노라',29813),
('2ti-1-6','2ti','디모데후서',1,6,'그러므로 내가 나의 안수함으로 네 속에 있는 하나님의 은사를 다시 불일듯 하게 하기 위하여 너로 생각하게 하노니',29814),
('2ti-1-7','2ti','디모데후서',1,7,'하나님이 우리에게 주신 것은 두려워하는 마음이 아니요 오직 능력과 사랑과 절제하는 마음이니',29815),
('2ti-1-8','2ti','디모데후서',1,8,'그러므로 너는 내가 우리 주를 증언함과 또는 주를 위하여 갇힌 자 된 나를 부끄러워하지 말고 오직 하나님의 능력을 따라 복음과 함께 고난을 받으라',29816),
('2ti-1-9','2ti','디모데후서',1,9,'하나님이 우리를 구원하사 거룩하신 소명으로 부르심은 우리의 행위대로 하심이 아니요 오직 자기의 뜻과 영원 전부터 그리스도 예수 안에서 우리에게 주신 은혜대로 하심이라',29817),
('2ti-1-10','2ti','디모데후서',1,10,'이제는 우리 구주 그리스도 예수의 나타나심으로 말미암아 나타났으니 그는 사망을 폐하시고 복음으로써 생명과 썩지 아니할 것을 드러내신지라',29818),
('2ti-1-11','2ti','디모데후서',1,11,'내가 이 복음을 위하여 선포자와 사도와 교사로 세우심을 입었노라',29819),
('2ti-1-12','2ti','디모데후서',1,12,'이로 말미암아 내가 또 이 고난을 받되 부끄러워하지 아니함은 내가 믿는 자를 내가 알고 또한 내가 의탁한 것을 그 날까지 그가 능히 지키실 줄을 확신함이라',29820),
('2ti-1-13','2ti','디모데후서',1,13,'너는 그리스도 예수 안에 있는 믿음과 사랑으로써 내게 들은 바 바른 말을 본받아 지키고',29821),
('2ti-1-14','2ti','디모데후서',1,14,'우리 안에 거하시는 성령으로 말미암아 네게 부탁한 아름다운 것을 지키라',29822),
('2ti-1-15','2ti','디모데후서',1,15,'아시아에 있는 모든 사람이 나를 버린 이 일을 네가 아나니 그 중에는 부겔로와 허모게네도 있느니라',29823),
('2ti-1-16','2ti','디모데후서',1,16,'원하건대 주께서 오네시보로의 집에 긍휼을 베푸시옵소서 그가 나를 자주 격려해 주고 내가 사슬에 매인 것을 부끄러워하지 아니하고',29824),
('2ti-1-17','2ti','디모데후서',1,17,'로마에 있을 때에 나를 부지런히 찾아와 만났음이라',29825),
('2ti-1-18','2ti','디모데후서',1,18,'(원하건대 주께서 그로 하여금 그 날에 주의 긍휼을 입게 하여 주옵소서) 또 그가 에베소에서 많이 봉사한 것을 네가 잘 아느니라',29826),
('2ti-2-1','2ti','디모데후서',2,1,'내 아들아 그러므로 너는 그리스도 예수 안에 있는 은혜 가운데서 강하고',29827),
('2ti-2-2','2ti','디모데후서',2,2,'또 네가 많은 증인 앞에서 내게 들은 바를 충성된 사람들에게 부탁하라 그들이 또 다른 사람들을 가르칠 수 있으리라',29828),
('2ti-2-3','2ti','디모데후서',2,3,'너는 그리스도 예수의 좋은 병사로 나와 함께 고난을 받으라',29829),
('2ti-2-4','2ti','디모데후서',2,4,'병사로 복무하는 자는 자기 생활에 얽매이는 자가 하나도 없나니 이는 병사로 모집한 자를 기쁘게 하려 함이라',29830),
('2ti-2-5','2ti','디모데후서',2,5,'경기하는 자가 법대로 경기하지 아니하면 승리자의 관을 얻지 못할 것이며',29831),
('2ti-2-6','2ti','디모데후서',2,6,'수고하는 농부가 곡식을 먼저 받는 것이 마땅하니라',29832),
('2ti-2-7','2ti','디모데후서',2,7,'내가 말하는 것을 생각해 보라 주께서 범사에 네게 총명을 주시리라',29833),
('2ti-2-8','2ti','디모데후서',2,8,'내가 전한 복음대로 다윗의 씨로 죽은 자 가운데서 다시 살아나신 예수 그리스도를 기억하라',29834),
('2ti-2-9','2ti','디모데후서',2,9,'복음으로 말미암아 내가 죄인과 같이 매이는 데까지 고난을 받았으나 하나님의 말씀은 매이지 아니하니라',29835),
('2ti-2-10','2ti','디모데후서',2,10,'그러므로 내가 택함 받은 자들을 위하여 모든 것을 참음은 그들도 그리스도 예수 안에 있는 구원을 영원한 영광과 함께 받게 하려 함이라',29836),
('2ti-2-11','2ti','디모데후서',2,11,'미쁘다 이 말이여 우리가 주와 함께 죽었으면 또한 함께 살 것이요',29837),
('2ti-2-12','2ti','디모데후서',2,12,'참으면 또한 함께 왕 노릇 할 것이요 우리가 주를 부인하면 주도 우리를 부인하실 것이라',29838),
('2ti-2-13','2ti','디모데후서',2,13,'우리는 미쁨이 없을지라도 주는 항상 미쁘시니 자기를 부인하실 수 없으시리라',29839),
('2ti-2-14','2ti','디모데후서',2,14,'너는 그들로 이 일을 기억하게 하여 말다툼을 하지 말라고 하나님 앞에서 엄히 명하라 이는 유익이 하나도 없고 도리어 듣는 자들을 망하게 함이라',29840),
('2ti-2-15','2ti','디모데후서',2,15,'너는 진리의 말씀을 옳게 분별하며 부끄러울 것이 없는 일꾼으로 인정된 자로 자신을 하나님 앞에 드리기를 힘쓰라',29841),
('2ti-2-16','2ti','디모데후서',2,16,'망령되고 헛된 말을 버리라 그들은 경건하지 아니함에 점점 나아가나니',29842),
('2ti-2-17','2ti','디모데후서',2,17,'그들의 말은 악성 종양이 퍼져나감과 같은데 그 중에 후메내오와 빌레도가 있느니라',29843),
('2ti-2-18','2ti','디모데후서',2,18,'진리에 관하여는 그들이 그릇되었도다 부활이 이미 지나갔다 함으로 어떤 사람들의 믿음을 무너뜨리느니라',29844),
