('2ti-4-18','2ti','디모데후서',4,18,'주께서 나를 모든 악한 일에서 건져내시고 또 그의 천국에 들어가도록 구원하시리니 그에게 영광이 세세무궁토록 있을지어다 아멘',29887),
('2ti-4-19','2ti','디모데후서',4,19,'브리스가와 아굴라와 및 오네시보로의 집에 문안하라',29888),
