('tit-1-4','tit','디도서',1,4,'같은 믿음을 따라 나의 참 아들 된 디도에게 편지하노니 하나님 아버지와 그리스도 예수 우리 구주로부터 은혜와 평강이 네게 있을지어다',29895),
('tit-1-5','tit','디도서',1,5,'내가 너를 그레데에 남겨 둔 이유는 남은 일을 정리하고 내가 명한 대로 각 성에 장로들을 세우게 하려 함이니',29896),
('tit-1-6','tit','디도서',1,6,'책망할 것이 없고 한 아내의 남편이며 방탕하다는 비난을 받거나 불순종하는 일이 없는 믿는 자녀를 둔 자라야 할지라',29897),
('tit-1-7','tit','디도서',1,7,'감독은 하나님의 청지기로서 책망할 것이 없고 제 고집대로 하지 아니하며 급히 분내지 아니하며 술을 즐기지 아니하며 구타하지 아니하며 더러운 이득을 탐하지 아니하며',29898),
('tit-1-8','tit','디도서',1,8,'오직 나그네를 대접하며 선행을 좋아하며 신중하며 의로우며 거룩하며 절제하며',29899),
('tit-1-9','tit','디도서',1,9,'미쁜 말씀의 가르침을 그대로 지켜야 하리니 이는 능히 바른 교훈으로 권면하고 거슬러 말하는 자들을 책망하게 하려 함이라',29900),
('tit-1-10','tit','디도서',1,10,'불순종하고 헛된 말을 하며 속이는 자가 많은 중 할례파 가운데 특히 그러하니',29901),
('tit-1-11','tit','디도서',1,11,'그들의 입을 막을 것이라 이런 자들이 더러운 이득을 취하려고 마땅하지 아니한 것을 가르쳐 가정들을 온통 무너뜨리는도다',29902),
('tit-1-12','tit','디도서',1,12,'그레데인 중의 어떤 선지자가 말하되 그레데인들은 항상 거짓말쟁이며 악한 짐승이며 배만 위하는 게으름뱅이라 하니',29903),
('tit-1-13','tit','디도서',1,13,'이 증언이 참되도다 그러므로 네가 그들을 엄히 꾸짖으라 이는 그들로 하여금 믿음을 온전하게 하고',29904),
('tit-1-14','tit','디도서',1,14,'유대인의 허탄한 이야기와 진리를 배반하는 사람들의 명령을 따르지 않게 하려 함이라',29905),
('tit-1-15','tit','디도서',1,15,'깨끗한 자들에게는 모든 것이 깨끗하나 더럽고 믿지 아니하는 자들에게는 아무 것도 깨끗한 것이 없고 오직 그들의 마음과 양심이 더러운지라',29906),
('tit-1-16','tit','디도서',1,16,'그들이 하나님을 시인하나 행위로는 부인하니 가증한 자요 복종하지 아니하는 자요 모든 선한 일을 버리는 자니라',29907),
