('tit-2-3','tit','디도서',2,3,'늙은 여자로는 이와 같이 행실이 거룩하며 모함하지 말며 많은 술의 종이 되지 아니하며 선한 것을 가르치는 자들이 되고',29910),
('tit-2-4','tit','디도서',2,4,'그들로 젊은 여자들을 교훈하되 그 남편과 자녀를 사랑하며',29911),
