('tit-2-7','tit','디도서',2,7,'범사에 네 자신이 선한 일의 본을 보이며 교훈에 부패하지 아니함과 단정함과',29914),
('tit-2-8','tit','디도서',2,8,'책망할 것이 없는 바른 말을 하게 하라 이는 대적하는 자로 하여금 부끄러워 우리를 악하다 할 것이 없게 하려 함이라',29915),
('tit-2-9','tit','디도서',2,9,'종들은 자기 상전들에게 범사에 순종하여 기쁘게 하고 거슬러 말하지 말며',29916),
('tit-2-10','tit','디도서',2,10,'훔치지 말고 오히려 모든 참된 신실성을 나타내게 하라 이는 범사에 우리 구주 하나님의 교훈을 빛나게 하려 함이라',29917),
('tit-2-11','tit','디도서',2,11,'모든 사람에게 구원을 주시는 하나님의 은혜가 나타나',29918),
('tit-2-12','tit','디도서',2,12,'우리를 양육하시되 경건하지 않은 것과 이 세상 정욕을 다 버리고 신중함과 의로움과 경건함으로 이 세상에 살고',29919),
('tit-2-13','tit','디도서',2,13,'복스러운 소망과 우리의 크신 하나님 구주 예수 그리스도의 영광이 나타나심을 기다리게 하셨으니',29920),
('tit-2-14','tit','디도서',2,14,'그가 우리를 대신하여 자신을 주심은 모든 불법에서 우리를 속량하시고 우리를 깨끗하게 하사 선한 일을 열심히 하는 자기 백성이 되게 하려 하심이라',29921),
('tit-2-15','tit','디도서',2,15,'너는 이것을 말하고 권면하며 모든 권위로 책망하여 누구에게서든지 업신여김을 받지 말라',29922),
('tit-3-1','tit','디도서',3,1,'너는 그들로 하여금 통치자들과 권세 잡은 자들에게 복종하며 순종하며 모든 선한 일 행하기를 준비하게 하며',29923),
('tit-3-2','tit','디도서',3,2,'아무도 비방하지 말며 다투지 말며 관용하며 범사에 온유함을 모든 사람에게 나타낼 것을 기억하게 하라',29924),
('tit-3-3','tit','디도서',3,3,'우리도 전에는 어리석은 자요 순종하지 아니한 자요 속은 자요 여러 가지 정욕과 행락에 종 노릇 한 자요 악독과 투기를 일삼은 자요 가증스러운 자요 피차 미워한 자였으나',29925),
('tit-3-4','tit','디도서',3,4,'우리 구주 하나님의 자비와 사람 사랑하심이 나타날 때에',29926),
('tit-3-5','tit','디도서',3,5,'우리를 구원하시되 우리가 행한 바 의로운 행위로 말미암지 아니하고 오직 그의 긍휼하심을 따라 중생의 씻음과 성령의 새롭게 하심으로 하셨나니',29927),
('tit-3-6','tit','디도서',3,6,'우리 구주 예수 그리스도로 말미암아 우리에게 그 성령을 풍성히 부어 주사',29928),
('tit-3-7','tit','디도서',3,7,'우리로 그의 은혜를 힘입어 의롭다 하심을 얻어 영생의 소망을 따라 상속자가 되게 하려 하심이라',29929),
('tit-3-8','tit','디도서',3,8,'이 말이 미쁘도다 원하건대 너는 이 여러 것에 대하여 굳세게 말하라 이는 하나님을 믿는 자들로 하여금 조심하여 선한 일을 힘쓰게 하려 함이라 이것은 아름다우며 사람들에게 유익하니라',29930),
('tit-3-9','tit','디도서',3,9,'그러나 어리석은 변론과 족보 이야기와 분쟁과 율법에 대한 다툼은 피하라 이것은 무익한 것이요 헛된 것이니라',29931),
('tit-3-10','tit','디도서',3,10,'이단에 속한 사람을 한두 번 훈계한 후에 멀리하라',29932),
('tit-3-11','tit','디도서',3,11,'이러한 사람은 네가 아는 바와 같이 부패하여 스스로 정죄한 자로서 죄를 짓느니라',29933),
('tit-3-12','tit','디도서',3,12,'내가 아데마나 두기고를 네게 보내리니 그 때에 네가 급히 니고볼리로 내게 오라 내가 거기서 겨울을 지내기로 작정하였노라',29934),
('tit-3-13','tit','디도서',3,13,'율법교사 세나와 및 아볼로를 급히 먼저 보내어 그들로 부족함이 없게 하고',29935),
('tit-3-14','tit','디도서',3,14,'또 우리 사람들도 열매 없는 자가 되지 않게 하기 위하여 필요한 것을 준비하는 좋은 일에 힘 쓰기를 배우게 하라',29936),
('tit-3-15','tit','디도서',3,15,'나와 함께 있는 자가 다 네게 문안하니 믿음 안에서 우리를 사랑하는 자들에게 너도 문안하라 은혜가 너희 무리에게 있을지어다',29937),
('phm-1-1','phm','빌레몬서',1,1,'그리스도 예수를 위하여 갇힌 자 된 바울과 및 형제 디모데는 우리의 사랑을 받는 자요 동역자인 빌레몬과',29938),
('phm-1-2','phm','빌레몬서',1,2,'자매 압비아와 우리와 함께 병사 된 아킵보와 네 집에 있는 교회에 편지하노니',29939),
('phm-1-3','phm','빌레몬서',1,3,'하나님 우리 아버지와 주 예수 그리스도로부터 은혜와 평강이 너희에게 있을지어다',29940),
('phm-1-4','phm','빌레몬서',1,4,'내가 항상 내 하나님께 감사하고 기도할 때에 너를 말함은',29941),
('phm-1-5','phm','빌레몬서',1,5,'주 예수와 및 모든 성도에 대한 네 사랑과 믿음이 있음을 들음이니',29942),
('phm-1-6','phm','빌레몬서',1,6,'이로써 네 믿음의 교제가 우리 가운데 있는 선을 알게 하고 그리스도께 이르도록 역사하느니라',29943),
('phm-1-7','phm','빌레몬서',1,7,'형제여 성도들의 마음이 너로 말미암아 평안함을 얻었으니 내가 너의 사랑으로 많은 기쁨과 위로를 받았노라',29944),
('phm-1-8','phm','빌레몬서',1,8,'이러므로 내가 그리스도 안에서 아주 담대하게 네게 마땅한 일로 명할 수도 있으나',29945),
('phm-1-9','phm','빌레몬서',1,9,'도리어 사랑으로써 간구하노라 나이가 많은 나 바울은 지금 또 예수 그리스도를 위하여 갇힌 자 되어',29946),
('phm-1-10','phm','빌레몬서',1,10,'갇힌 중에서 낳은 아들 오네시모를 위하여 네게 간구하노라',29947),
('phm-1-11','phm','빌레몬서',1,11,'그가 전에는 네게 무익하였으나 이제는 나와 네게 유익하므로',29948),
('phm-1-12','phm','빌레몬서',1,12,'네게 그를 돌려 보내노니 그는 내 심복이라',29949),
('phm-1-13','phm','빌레몬서',1,13,'그를 내게 머물러 있게 하여 내 복음을 위하여 갇힌 중에서 네 대신 나를 섬기게 하고자 하나',29950),
('phm-1-14','phm','빌레몬서',1,14,'다만 네 승낙이 없이는 내가 아무 것도 하기를 원하지 아니하노니 이는 너의 선한 일이 억지 같이 되지 아니하고 자의로 되게 하려 함이라',29951),
('phm-1-15','phm','빌레몬서',1,15,'아마 그가 잠시 떠나게 된 것은 너로 하여금 그를 영원히 두게 함이리니',29952),
('phm-1-16','phm','빌레몬서',1,16,'이후로는 종과 같이 대하지 아니하고 종 이상으로 곧 사랑 받는 형제로 둘 자라 내게 특별히 그러하거든 하물며 육신과 주 안에서 상관된 네게랴',29953),
('phm-1-17','phm','빌레몬서',1,17,'그러므로 네가 나를 동역자로 알진대 그를 영접하기를 내게 하듯 하고',29954),
('phm-1-18','phm','빌레몬서',1,18,'그가 만일 네게 불의를 하였거나 네게 빚진 것이 있으면 그것을 내 앞으로 계산하라',29955),
('phm-1-19','phm','빌레몬서',1,19,'나 바울이 친필로 쓰노니 내가 갚으려니와 네가 이 외에 네 자신이 내게 빚진 것은 내가 말하지 아니하노라',29956),
('phm-1-20','phm','빌레몬서',1,20,'오 형제여 나로 주 안에서 너로 말미암아 기쁨을 얻게 하고 내 마음이 그리스도 안에서 평안하게 하라',29957),
('phm-1-21','phm','빌레몬서',1,21,'나는 네가 순종할 것을 확신하므로 네게 썼노니 네가 내가 말한 것보다 더 행할 줄을 아노라',29958),
('phm-1-22','phm','빌레몬서',1,22,'오직 너는 나를 위하여 숙소를 마련하라 너희 기도로 내가 너희에게 나아갈 수 있기를 바라노라',29959),
('phm-1-23','phm','빌레몬서',1,23,'그리스도 예수 안에서 나와 함께 갇힌 자 에바브라와',29960),
('phm-1-24','phm','빌레몬서',1,24,'또한 나의 동역자 마가, 아리스다고, 데마, 누가가 문안하느니라',29961),
('phm-1-25','phm','빌레몬서',1,25,'우리 주 예수 그리스도의 은혜가 너희 심령과 함께 있을지어다',29962),
('heb-1-1','heb','히브리서',1,1,'옛적에 선지자들을 통하여 여러 부분과 여러 모양으로 우리 조상들에게 말씀하신 하나님이',29963),
('heb-1-2','heb','히브리서',1,2,'이 모든 날 마지막에는 아들을 통하여 우리에게 말씀하셨으니 이 아들을 만유의 상속자로 세우시고 또 그로 말미암아 모든 세계를 지으셨느니라',29964),
('heb-1-3','heb','히브리서',1,3,'이는 하나님의 영광의 광채시요 그 본체의 형상이시라 그의 능력의 말씀으로 만물을 붙드시며 죄를 정결하게 하는 일을 하시고 높은 곳에 계신 지극히 크신 이의 우편에 앉으셨느니라',29965),
('heb-1-4','heb','히브리서',1,4,'그가 천사보다 훨씬 뛰어남은 그들보다 더욱 아름다운 이름을 기업으로 얻으심이니',29966),
('heb-1-5','heb','히브리서',1,5,'하나님께서 어느 때에 천사 중 누구에게 너는 내 아들이라 오늘 내가 너를 낳았다 하셨으며 또 다시 나는 그에게 아버지가 되고 그는 내게 아들이 되리라 하셨느냐',29967),
('heb-1-6','heb','히브리서',1,6,'또 그가 맏아들을 이끌어 세상에 다시 들어오게 하실 때에 하나님의 모든 천사들은 그에게 경배할지어다 말씀하시며',29968),
('heb-1-7','heb','히브리서',1,7,'또 천사들에 관하여는 그는 그의 천사들을 바람으로, 그의 사역자들을 불꽃으로 삼으시느니라 하셨으되',29969),
('heb-1-8','heb','히브리서',1,8,'아들에 관하여는 하나님이여 주의 보좌는 영영하며 주의 나라의 규는 공평한 규이니이다',29970),
('heb-1-9','heb','히브리서',1,9,'주께서 의를 사랑하시고 불법을 미워하셨으니 그러므로 하나님 곧 주의 하나님이 즐거움의 기름을 주께 부어 주를 동류들보다 뛰어나게 하셨도다 하였고',29971),
('heb-1-10','heb','히브리서',1,10,'또 주여 태초에 주께서 땅의 기초를 두셨으며 하늘도 주의 손으로 지으신 바라',29972),
('heb-1-11','heb','히브리서',1,11,'그것들은 멸망할 것이나 오직 주는 영존할 것이요 그것들은 다 옷과 같이 낡아지리니',29973),
('heb-1-12','heb','히브리서',1,12,'의복처럼 갈아입을 것이요 그것들은 옷과 같이 변할 것이나 주는 여전하여 연대가 다함이 없으리라 하였으나',29974),
('heb-1-13','heb','히브리서',1,13,'어느 때에 천사 중 누구에게 내가 네 원수로 네 발등상이 되게 하기까지 너는 내 우편에 앉아 있으라 하셨느냐',29975),
('heb-1-14','heb','히브리서',1,14,'모든 천사들은 섬기는 영으로서 구원 받을 상속자들을 위하여 섬기라고 보내심이 아니냐',29976),
('heb-2-1','heb','히브리서',2,1,'그러므로 우리는 들은 것에 더욱 유념함으로 우리가 흘러 떠내려가지 않도록 함이 마땅하니라',29977),
('heb-2-2','heb','히브리서',2,2,'천사들을 통하여 하신 말씀이 견고하게 되어 모든 범죄함과 순종하지 아니한 자들이 공정한 보응을 받았거든',29978),
('heb-2-3','heb','히브리서',2,3,'우리가 이같이 큰 구원을 등한히 여기면 어찌 그 보응을 피하리요 이 구원은 처음에 주로 말씀하신 바요 들은 자들이 우리에게 확증한 바니',29979),
('heb-2-4','heb','히브리서',2,4,'하나님도 표적들과 기사들과 여러 가지 능력과 및 자기의 뜻을 따라 성령이 나누어 주신 것으로써 그들과 함께 증언하셨느니라',29980),
('heb-2-5','heb','히브리서',2,5,'하나님이 우리가 말하는 바 장차 올 세상을 천사들에게 복종하게 하심이 아니니라',29981),
('heb-2-6','heb','히브리서',2,6,'그러나 누구인가가 어디에서 증언하여 이르되 사람이 무엇이기에 주께서 그를 생각하시며 인자가 무엇이기에 주께서 그를 돌보시나이까',29982),
('heb-2-7','heb','히브리서',2,7,'그를 잠시 동안 천사보다 못하게 하시며 영광과 존귀로 관을 씌우시며3)',29983),
('heb-2-8','heb','히브리서',2,8,'만물을 그 발 아래에 복종하게 하셨느니라 하였으니 만물로 그에게 복종하게 하셨은즉 복종하지 않은 것이 하나도 없어야 하겠으나 지금 우리가 만물이 아직 그에게 복종하고 있는 것을 보지 못하고',29984),
('heb-2-9','heb','히브리서',2,9,'오직 우리가 천사들보다 잠시 동안 못하게 하심을 입은 자 곧 죽음의 고난 받으심으로 말미암아 영광과 존귀로 관을 쓰신 예수를 보니 이를 행하심은 하나님의 은혜로 말미암아 모든 사람을 위하여 죽음을 맛보려 하심이라',29985),
('heb-2-10','heb','히브리서',2,10,'그러므로 만물이 그를 위하고 또한 그로 말미암은 이가 많은 아들들을 이끌어 영광에 들어가게 하시는 일에 그들의 구원의 창시자를 고난을 통하여 온전하게 하심이 합당하도다',29986),
('heb-2-11','heb','히브리서',2,11,'거룩하게 하시는 이와 거룩하게 함을 입은 자들이 다 한 근원에서 난지라 그러므로 형제라 부르시기를 부끄러워하지 아니하시고',29987),
('heb-2-12','heb','히브리서',2,12,'이르시되 내가 주의 이름을 내 형제들에게 선포하고 내가 주를 교회 중에서 찬송하리라 하셨으며',29988),
('heb-2-13','heb','히브리서',2,13,'또 다시 내가 그를 의지하리라 하시고 또 다시 볼지어다 나와 및 하나님께서 내게 주신 자녀라 하셨으니',29989),
('heb-2-14','heb','히브리서',2,14,'자녀들은 혈과 육에 속하였으매 그도 또한 같은 모양으로 혈과 육을 함께 지니심은 죽음을 통하여 죽음의 세력을 잡은 자 곧 마귀를 멸하시며',29990),
('heb-2-15','heb','히브리서',2,15,'또 죽기를 무서워하므로 한평생 매여 종 노릇 하는 모든 자들을 놓아 주려 하심이니',29991),
('heb-2-16','heb','히브리서',2,16,'이는 확실히 천사들을 붙들어 주려 하심이 아니요 오직 아브라함의 자손을 붙들어 주려 하심이라',29992),
('heb-2-17','heb','히브리서',2,17,'그러므로 그가 범사에 형제들과 같이 되심이 마땅하도다 이는 하나님의 일에 자비하고 신실한 대제사장이 되어 백성의 죄를 속량하려 하심이라',29993),
('heb-2-18','heb','히브리서',2,18,'그가 시험을 받아 고난을 당하셨은즉 시험 받는 자들을 능히 도우실 수 있느니라',29994),
('heb-3-1','heb','히브리서',3,1,'그러므로 함께 하늘의 부르심을 받은 거룩한 형제들아 우리가 믿는 도리의 사도이시며 대제사장이신 예수를 깊이 생각하라',29995),
('heb-3-2','heb','히브리서',3,2,'그는 자기를 세우신 이에게 신실하시기를 모세가 하나님의 온 집에서 한 것과 같이 하셨으니',29996),
('heb-3-3','heb','히브리서',3,3,'그는 모세보다 더욱 영광을 받을 만한 것이 마치 집 지은 자가 그 집보다 더욱 존귀함 같으니라',29997),
('heb-3-4','heb','히브리서',3,4,'집마다 지은 이가 있으니 만물을 지으신 이는 하나님이시라',29998),
('heb-3-5','heb','히브리서',3,5,'또한 모세는 장래에 말할 것을 증언하기 위하여 하나님의 온 집에서 종으로서 신실하였고',29999),
('heb-3-6','heb','히브리서',3,6,'그리스도는 하나님의 집을 맡은 아들로서 그와 같이 하셨으니 우리가 소망의 확신과 자랑을 끝까지 굳게 잡고 있으면 우리는 그의 집이라',30000),
('heb-3-7','heb','히브리서',3,7,'그러므로 성령이 이르신 바와 같이 오늘 너희가 그의 음성을 듣거든',30001),
('heb-3-8','heb','히브리서',3,8,'광야에서 시험하던 날에 거역하던 것 같이 너희 마음을 완고하게 하지 말라',30002),
('heb-3-9','heb','히브리서',3,9,'거기서 너희 열조가 나를 시험하여 증험하고 사십 년 동안 나의 행사를 보았느니라',30003),
('heb-3-10','heb','히브리서',3,10,'그러므로 내가 이 세대에게 노하여 이르기를 그들이 항상 마음이 미혹되어 내 길을 알지 못하는도다 하였고',30004),
('heb-3-11','heb','히브리서',3,11,'내가 노하여 맹세한 바와 같이 그들은 내 안식에 들어오지 못하리라 하였다 하였느니라',30005),
('heb-3-12','heb','히브리서',3,12,'형제들아 너희는 삼가 혹 너희 중에 누가 믿지 아니하는 악한 마음을 품고 살아 계신 하나님에게서 떨어질까 조심할 것이요',30006),
('heb-3-13','heb','히브리서',3,13,'오직 오늘이라 일컫는 동안에 매일 피차 권면하여 너희 중에 누구든지 죄의 유혹으로 완고하게 되지 않도록 하라',30007),
('heb-3-14','heb','히브리서',3,14,'우리가 시작할 때에 확신한 것을 끝까지 견고히 잡고 있으면 그리스도와 함께 참여한 자가 되리라',30008),
('heb-3-15','heb','히브리서',3,15,'성경에 일렀으되 오늘 너희가 그의 음성을 듣거든 격노하시게 하던 것 같이 너희 마음을 완고하게 하지 말라 하였으니',30009),
('heb-3-16','heb','히브리서',3,16,'듣고 격노하시게 하던 자가 누구냐 모세를 따라 애굽에서 나온 모든 사람이 아니냐',30010),
('heb-3-17','heb','히브리서',3,17,'또 하나님이 사십 년 동안 누구에게 노하셨느냐 그들의 시체가 광야에 엎드러진 범죄한 자들에게가 아니냐',30011),
('heb-3-18','heb','히브리서',3,18,'또 하나님이 누구에게 맹세하사 그의 안식에 들어오지 못하리라 하셨느냐 곧 순종하지 아니하던 자들에게가 아니냐',30012),
('heb-3-19','heb','히브리서',3,19,'이로 보건대 그들이 믿지 아니하므로 능히 들어가지 못한 것이라',30013),
('heb-4-1','heb','히브리서',4,1,'그러므로 우리는 두려워할지니 그의 안식에 들어갈 약속이 남아 있을지라도 너희 중에는 혹 이르지 못할 자가 있을까 함이라',30014),
('heb-4-2','heb','히브리서',4,2,'그들과 같이 우리도 복음 전함을 받은 자이나 들은 바 그 말씀이 그들에게 유익하지 못한 것은 듣는 자가 믿음과 결부시키지 아니함이라',30015),
('heb-4-3','heb','히브리서',4,3,'이미 믿는 우리들은 저 안식에 들어가는도다 그가 말씀하신 바와 같으니 내가 노하여 맹세한 바와 같이 그들이 내 안식에 들어오지 못하리라 하셨다 하였으나 세상을 창조할 때부터 그 일이 이루어졌느니라',30016),
('heb-4-4','heb','히브리서',4,4,'제칠일에 관하여는 어딘가에 이렇게 일렀으되 하나님은 제칠일에 그의 모든 일을 쉬셨다 하였으며',30017),
('heb-4-5','heb','히브리서',4,5,'또 다시 거기에 그들이 내 안식에 들어오지 못하리라 하였으니',30018),
('heb-4-6','heb','히브리서',4,6,'그러면 거기에 들어갈 자들이 남아 있거니와 복음 전함을 먼저 받은 자들은 순종하지 아니함으로 말미암아 들어가지 못하였으므로',30019),
('heb-4-7','heb','히브리서',4,7,'오랜 후에 다윗의 글에 다시 어느 날을 정하여 오늘이라고 미리 이같이 일렀으되 오늘 너희가 그의 음성을 듣거든 너희 마음을 완고하게 하지 말라 하였나니',30020),
('heb-4-8','heb','히브리서',4,8,'만일 여호수아가 그들에게 안식을 주었더라면 그 후에 다른 날을 말씀하지 아니하셨으리라',30021),
('heb-4-9','heb','히브리서',4,9,'그런즉 안식할 때가 하나님의 백성에게 남아 있도다',30022),
('heb-4-10','heb','히브리서',4,10,'이미 그의 안식에 들어간 자는 하나님이 자기의 일을 쉬심과 같이 그도 자기의 일을 쉬느니라',30023),
('heb-4-11','heb','히브리서',4,11,'그러므로 우리가 저 안식에 들어가기를 힘쓸지니 이는 누구든지 저 순종하지 아니하는 본에 빠지지 않게 하려 함이라',30024),
('heb-4-12','heb','히브리서',4,12,'하나님의 말씀은 살아 있고 활력이 있어 좌우에 날선 어떤 검보다도 예리하여 혼과 영과 및 관절과 골수를 찔러 쪼개기까지 하며 또 마음의 생각과 뜻을 판단하나니',30025),
('heb-4-13','heb','히브리서',4,13,'지으신 것이 하나도 그 앞에 나타나지 않음이 없고 우리의 결산을 받으실 이의 눈 앞에 만물이 벌거벗은 것 같이 드러나느니라',30026),
('heb-4-14','heb','히브리서',4,14,'그러므로 우리에게 큰 대제사장이 계시니 승천하신 이 곧 하나님의 아들 예수시라 우리가 믿는 도리를 굳게 잡을지어다',30027),
('heb-4-15','heb','히브리서',4,15,'우리에게 있는 대제사장은 우리의 연약함을 동정하지 못하실 이가 아니요 모든 일에 우리와 똑같이 시험을 받으신 이로되 죄는 없으시니라',30028),
('heb-4-16','heb','히브리서',4,16,'그러므로 우리는 긍휼하심을 받고 때를 따라 돕는 은혜를 얻기 위하여 은혜의 보좌 앞에 담대히 나아갈 것이니라',30029),
('heb-5-1','heb','히브리서',5,1,'대제사장마다 사람 가운데서 택한 자이므로 하나님께 속한 일에 사람을 위하여 예물과 속죄하는 제사를 드리게 하나니',30030),
('heb-5-2','heb','히브리서',5,2,'그가 무식하고 미혹된 자를 능히 용납할 수 있는 것은 자기도 연약에 휩싸여 있음이라',30031),
('heb-5-3','heb','히브리서',5,3,'그러므로 백성을 위하여 속죄제를 드림과 같이 또한 자신을 위하여도 드리는 것이 마땅하니라',30032),
('heb-5-4','heb','히브리서',5,4,'이 존귀는 아무도 스스로 취하지 못하고 오직 아론과 같이 하나님의 부르심을 받은 자라야 할 것이니라',30033),
('heb-5-5','heb','히브리서',5,5,'또한 이와 같이 그리스도께서 대제사장 되심도 스스로 영광을 취하심이 아니요 오직 말씀하신 이가 그에게 이르시되 너는 내 아들이니 내가 오늘 너를 낳았다 하셨고',30034),
('heb-5-6','heb','히브리서',5,6,'또한 이와 같이 다른 데서 말씀하시되 네가 영원히 멜기세덱의 반차를 따르는 제사장이라 하셨으니',30035),
('heb-5-7','heb','히브리서',5,7,'그는 육체에 계실 때에 자기를 죽음에서 능히 구원하실 이에게 심한 통곡과 눈물로 간구와 소원을 올렸고 그의 경건하심으로 말미암아 들으심을 얻었느니라',30036),
('heb-5-8','heb','히브리서',5,8,'그가 아들이시면서도 받으신 고난으로 순종함을 배워서',30037),
('heb-5-9','heb','히브리서',5,9,'온전하게 되셨은즉 자기에게 순종하는 모든 자에게 영원한 구원의 근원이 되시고',30038),
('heb-5-10','heb','히브리서',5,10,'하나님께 멜기세덱의 반차를 따른 대제사장이라 칭하심을 받으셨느니라',30039),
('heb-5-11','heb','히브리서',5,11,'멜기세덱에 관하여는 우리가 할 말이 많으나 너희가 듣는 것이 둔하므로 설명하기 어려우니라',30040),
('heb-5-12','heb','히브리서',5,12,'때가 오래 되었으므로 너희가 마땅히 선생이 되었을 터인데 너희가 다시 하나님의 말씀의 초보에 대하여 누구에게서 가르침을 받아야 할 처지이니 단단한 음식은 못 먹고 젖이나 먹어야 할 자가 되었도다',30041),
('heb-5-13','heb','히브리서',5,13,'이는 젖을 먹는 자마다 어린 아이니 의의 말씀을 경험하지 못한 자요',30042),
('heb-5-14','heb','히브리서',5,14,'단단한 음식은 장성한 자의 것이니 그들은 지각을 사용함으로 연단을 받아 선악을 분별하는 자들이니라',30043),
('heb-6-1','heb','히브리서',6,1,'그러므로 우리가 그리스도의 도의 초보를 버리고 죽은 행실을 회개함과 하나님께 대한 신앙과',30044),
('heb-6-2','heb','히브리서',6,2,'세례들과 안수와 죽은 자의 부활과 영원한 심판에 관한 교훈의 터를 다시 닦지 말고 완전한 데로 나아갈지니라',30045),
('heb-6-3','heb','히브리서',6,3,'하나님께서 허락하시면 우리가 이것을 하리라',30046),
('heb-6-4','heb','히브리서',6,4,'한 번 빛을 받고 하늘의 은사를 맛보고 성령에 참여한 바 되고',30047),
('heb-6-5','heb','히브리서',6,5,'하나님의 선한 말씀과 내세의 능력을 맛보고도',30048),
('heb-6-6','heb','히브리서',6,6,'타락한 자들은 다시 새롭게 하여 회개하게 할 수 없나니 이는 그들이 하나님의 아들을 다시 십자가에 못 박아 드러내 놓고 욕되게 함이라',30049),
('heb-6-7','heb','히브리서',6,7,'땅이 그 위에 자주 내리는 비를 흡수하여 밭 가는 자들이 쓰기에 합당한 채소를 내면 하나님께 복을 받고',30050),
('heb-6-8','heb','히브리서',6,8,'만일 가시와 엉겅퀴를 내면 버림을 당하고 저주함에 가까워 그 마지막은 불사름이 되리라',30051),
('heb-6-9','heb','히브리서',6,9,'사랑하는 자들아 우리가 이같이 말하나 너희에게는 이보다 더 좋은 것 곧 구원에 속한 것이 있음을 확신하노라',30052),
('heb-6-10','heb','히브리서',6,10,'하나님은 불의하지 아니하사 너희 행위와 그의 이름을 위하여 나타낸 사랑으로 이미 성도를 섬긴 것과 이제도 섬기고 있는 것을 잊어버리지 아니하시느니라',30053),
('heb-6-11','heb','히브리서',6,11,'우리가 간절히 원하는 것은 너희 각 사람이 동일한 부지런함을 나타내어 끝까지 소망의 풍성함에 이르러',30054),
('heb-6-12','heb','히브리서',6,12,'게으르지 아니하고 믿음과 오래 참음으로 말미암아 약속들을 기업으로 받는 자들을 본받는 자 되게 하려는 것이니라',30055),
('heb-6-13','heb','히브리서',6,13,'하나님이 아브라함에게 약속하실 때에 가리켜 맹세할 자가 자기보다 더 큰 이가 없으므로 자기를 가리켜 맹세하여',30056),
('heb-6-14','heb','히브리서',6,14,'이르시되 내가 반드시 너에게 복 주고 복 주며 너를 번성하게 하고 번성하게 하리라 하셨더니',30057),
('heb-6-15','heb','히브리서',6,15,'그가 이같이 오래 참아 약속을 받았느니라',30058),
('heb-6-16','heb','히브리서',6,16,'사람들은 자기보다 더 큰 자를 가리켜 맹세하나니 맹세는 그들이 다투는 모든 일의 최후 확정이니라',30059),
('heb-6-17','heb','히브리서',6,17,'하나님은 약속을 기업으로 받는 자들에게 그 뜻이 변하지 아니함을 충분히 나타내시려고 그 일을 맹세로 보증하셨나니',30060),
('heb-6-18','heb','히브리서',6,18,'이는 하나님이 거짓말을 하실 수 없는 이 두 가지 변하지 못할 사실로 말미암아 앞에 있는 소망을 얻으려고 피난처를 찾은 우리에게 큰 안위를 받게 하려 하심이라',30061),
('heb-6-19','heb','히브리서',6,19,'우리가 이 소망을 가지고 있는 것은 영혼의 닻 같아서 튼튼하고 견고하여 휘장 안에 들어 가나니',30062),
('heb-6-20','heb','히브리서',6,20,'그리로 앞서 가신 예수께서 멜기세덱의 반차를 따라 영원히 대제사장이 되어 우리를 위하여 들어 가셨느니라',30063),
('heb-7-1','heb','히브리서',7,1,'이 멜기세덱은 살렘 왕이요 지극히 높으신 하나님의 제사장이라 여러 왕을 쳐서 죽이고 돌아오는 아브라함을 만나 복을 빈 자라',30064),
('heb-7-2','heb','히브리서',7,2,'아브라함이 모든 것의 십분의 일을 그에게 나누어 주니라 그 이름을 해석하면 먼저는 의의 왕이요 그 다음은 살렘 왕이니 곧 평강의 왕이요',30065),
('heb-7-3','heb','히브리서',7,3,'아버지도 없고 어머니도 없고 족보도 없고 시작한 날도 없고 생명의 끝도 없어 하나님의 아들과 닮아서 항상 제사장으로 있느니라',30066),
('heb-7-4','heb','히브리서',7,4,'이 사람이 얼마나 높은가를 생각해 보라 조상 아브라함도 노략물 중 십분의 일을 그에게 주었느니라',30067),
('heb-7-5','heb','히브리서',7,5,'레위의 아들들 가운데 제사장의 직분을 받은 자들은 율법을 따라 아브라함의 허리에서 난 자라도 자기 형제인 백성에게서 십분의 일을 취하라는 명령을 받았으나',30068),
('heb-7-6','heb','히브리서',7,6,'레위 족보에 들지 아니한 멜기세덱은 아브라함에게서 십분의 일을 취하고 약속을 받은 그를 위하여 복을 빌었나니',30069),
('heb-7-7','heb','히브리서',7,7,'논란의 여지 없이 낮은 자가 높은 자에게서 축복을 받느니라',30070),
('heb-7-8','heb','히브리서',7,8,'또 여기는 죽을 자들이 십분의 일을 받으나 저기는 산다고 증거를 얻은 자가 받았느니라',30071),
('heb-7-9','heb','히브리서',7,9,'또한 십분의 일을 받는 레위도 아브라함으로 말미암아 십분의 일을 바쳤다고 할 수 있나니',30072),
('heb-7-10','heb','히브리서',7,10,'이는 멜기세덱이 아브라함을 만날 때에 레위는 이미 자기 조상의 허리에 있었음이라',30073),
('heb-7-11','heb','히브리서',7,11,'레위 계통의 제사 직분으로 말미암아 온전함을 얻을 수 있었으면 (백성이 그 아래에서 율법을 받았으니) 어찌하여 아론의 반차를 따르지 않고 멜기세덱의 반차를 따르는 다른 한 제사장을 세울 필요가 있느냐',30074),
('heb-7-12','heb','히브리서',7,12,'제사 직분이 바꾸어졌은즉 율법도 반드시 바꾸어지리니',30075),
('heb-7-13','heb','히브리서',7,13,'이것은 한 사람도 제단 일을 받들지 않는 다른 지파에 속한 자를 가리켜 말한 것이라',30076),
('heb-7-14','heb','히브리서',7,14,'우리 주께서는 유다로부터 나신 것이 분명하도다 이 지파에는 모세가 제사장들에 관하여 말한 것이 하나도 없고',30077),
('heb-7-15','heb','히브리서',7,15,'멜기세덱과 같은 별다른 한 제사장이 일어난 것을 보니 더욱 분명하도다',30078),
('heb-7-16','heb','히브리서',7,16,'그는 육신에 속한 한 계명의 법을 따르지 아니하고 오직 불멸의 생명의 능력을 따라 되었으니',30079),
('heb-7-17','heb','히브리서',7,17,'증언하기를 네가 영원히 멜기세덱의 반차를 따르는 제사장이라 하였도다',30080),
('heb-7-18','heb','히브리서',7,18,'전에 있던 계명은 연약하고 무익하므로 폐하고',30081),
('heb-7-19','heb','히브리서',7,19,'(율법은 아무 것도 온전하게 못할지라) 이에 더 좋은 소망이 생기니 이것으로 우리가 하나님께 가까이 가느니라',30082),
('heb-7-20','heb','히브리서',7,20,'또 예수께서 제사장이 되신 것은 맹세 없이 된 것이 아니니',30083),
('heb-7-21','heb','히브리서',7,21,'(그들은 맹세 없이 제사장이 되었으되 오직 예수는 자기에게 말씀하신 이로 말미암아 맹세로 되신 것이라 주께서 맹세하시고 뉘우치지 아니하시리니 네가 영원히 제사장이라 하셨도다)',30084),
('heb-7-22','heb','히브리서',7,22,'이와 같이 예수는 더 좋은 언약의 보증이 되셨느니라',30085),
('heb-7-23','heb','히브리서',7,23,'제사장 된 그들의 수효가 많은 것은 죽음으로 말미암아 항상 있지 못함이로되',30086),
('heb-7-24','heb','히브리서',7,24,'예수는 영원히 계시므로 그 제사장 직분도 갈리지 아니하느니라',30087),
('heb-7-25','heb','히브리서',7,25,'그러므로 자기를 힘입어 하나님께 나아가는 자들을 온전히 구원하실 수 있으니 이는 그가 항상 살아 계셔서 그들을 위하여 간구하심이라',30088),
('heb-7-26','heb','히브리서',7,26,'이러한 대제사장은 우리에게 합당하니 거룩하고 악이 없고 더러움이 없고 죄인에게서 떠나 계시고 하늘보다 높이 되신 이라',30089),
('heb-7-27','heb','히브리서',7,27,'그는 저 대제사장들이 먼저 자기 죄를 위하고 다음에 백성의 죄를 위하여 날마다 제사 드리는 것과 같이 할 필요가 없으니 이는 그가 단번에 자기를 드려 이루셨음이라',30090),
('heb-7-28','heb','히브리서',7,28,'율법은 약점을 가진 사람들을 제사장으로 세웠거니와 율법 후에 하신 맹세의 말씀은 영원히 온전하게 되신 아들을 세우셨느니라',30091),
('heb-8-1','heb','히브리서',8,1,'지금 우리가 하는 말의 요점은 이러한 대제사장이 우리에게 있다는 것이라 그는 하늘에서 지극히 크신 이의 보좌 우편에 앉으셨으니',30092),
('heb-8-2','heb','히브리서',8,2,'성소와 참 장막에서 섬기는 이시라 이 장막은 주께서 세우신 것이요 사람이 세운 것이 아니니라',30093),
('heb-8-3','heb','히브리서',8,3,'대제사장마다 예물과 제사 드림을 위하여 세운 자니 그러므로 그도 무엇인가 드릴 것이 있어야 할지니라',30094),
('heb-8-4','heb','히브리서',8,4,'예수께서 만일 땅에 계셨더라면 제사장이 되지 아니하셨을 것이니 이는 율법을 따라 예물을 드리는 제사장이 있음이라',30095),
('heb-8-5','heb','히브리서',8,5,'그들이 섬기는 것은 하늘에 있는 것의 모형과 그림자라 모세가 장막을 지으려 할 때에 지시하심을 얻음과 같으니 이르시되 삼가 모든 것을 산에서 네게 보이던 본을 따라 지으라 하셨느니라',30096),
('heb-8-6','heb','히브리서',8,6,'그러나 이제 그는 더 아름다운 직분을 얻으셨으니 그는 더 좋은 약속으로 세우신 더 좋은 언약의 중보자시라',30097),
('heb-8-7','heb','히브리서',8,7,'저 첫 언약이 무흠하였더라면 둘째 것을 요구할 일이 없었으려니와',30098),
('heb-8-8','heb','히브리서',8,8,'그들의 잘못을 지적하여 말씀하시되 주께서 이르시되 볼지어다 날이 이르리니 내가 이스라엘 집과 유다 집과 더불어 새 언약을 맺으리라',30099),
('heb-8-9','heb','히브리서',8,9,'또 주께서 이르시기를 이 언약은 내가 그들의 열조의 손을 잡고 애굽 땅에서 인도하여 내던 날에 그들과 맺은 언약과 같지 아니하도다 그들은 내 언약 안에 머물러 있지 아니하므로 내가 그들을 돌보지 아니하였노라',30100),
('heb-8-10','heb','히브리서',8,10,'또 주께서 이르시되 그 날 후에 내가 이스라엘 집과 맺을 언약은 이것이니 내 법을 그들의 생각에 두고 그들의 마음에 이것을 기록하리라 나는 그들에게 하나님이 되고 그들은 내게 백성이 되리라',30101),
('heb-8-11','heb','히브리서',8,11,'또 각각 자기 나라 사람과 각각 자기 형제를 가르쳐 이르기를 주를 알라 하지 아니할 것은 그들이 작은 자로부터 큰 자까지 다 나를 앎이라',30102),
('heb-8-12','heb','히브리서',8,12,'내가 그들의 불의를 긍휼히 여기고 그들의 죄를 다시 기억하지 아니하리라 하셨느니라',30103),
('heb-8-13','heb','히브리서',8,13,'새 언약이라 말씀하셨으매 첫 것은 낡아지게 하신 것이니 낡아지고 쇠하는 것은 없어져 가는 것이니라',30104),
('heb-9-1','heb','히브리서',9,1,'첫 언약에도 섬기는 예법과 세상에 속한 성소가 있더라',30105),
('heb-9-2','heb','히브리서',9,2,'예비한 첫 장막이 있고 그 안에 등잔대와 상과 진설병이 있으니 이는 성소라 일컫고',30106),
('heb-9-3','heb','히브리서',9,3,'또 둘째 휘장 뒤에 있는 장막을 지성소라 일컫나니',30107),
('heb-9-4','heb','히브리서',9,4,'금 향로와 사면을 금으로 싼 언약궤가 있고 그 안에 만나를 담은 금 항아리와 아론의 싹난 지팡이와 언약의 돌판들이 있고',30108),
('heb-9-5','heb','히브리서',9,5,'그 위에 속죄소를 덮는 영광의 그룹들이 있으니 이것들에 관하여는 이제 낱낱이 말할 수 없노라',30109),
('heb-9-6','heb','히브리서',9,6,'이 모든 것을 이같이 예비하였으니 제사장들이 항상 첫 장막에 들어가 섬기는 예식을 행하고',30110),
('heb-9-7','heb','히브리서',9,7,'오직 둘째 장막은 대제사장이 홀로 일 년에 한 번 들어가되 자기와 백성의 허물을 위하여 드리는 피 없이는 아니하나니',30111),
('heb-9-8','heb','히브리서',9,8,'성령이 이로써 보이신 것은 첫 장막이 서 있을 동안에는 성소에 들어가는 길이 아직 나타나지 아니한 것이라',30112),
('heb-9-9','heb','히브리서',9,9,'이 장막은 현재까지의 비유니 이에 따라 드리는 예물과 제사는 섬기는 자를 그 양심상 온전하게 할 수 없나니',30113),
('heb-9-10','heb','히브리서',9,10,'이런 것은 먹고 마시는 것과 여러 가지 씻는 것과 함께 육체의 예법일 뿐이며 개혁할 때까지 맡겨 둔 것이니라',30114),
('heb-9-11','heb','히브리서',9,11,'그리스도께서는 장래 좋은 일의 대제사장으로 오사 손으로 짓지 아니한 것 곧 이 창조에 속하지 아니한 더 크고 온전한 장막으로 말미암아',30115),
('heb-9-12','heb','히브리서',9,12,'염소와 송아지의 피로 하지 아니하고 오직 자기의 피로 영원한 속죄를 이루사 단번에 성소에 들어가셨느니라',30116),
('heb-9-13','heb','히브리서',9,13,'염소와 황소의 피와 및 암송아지의 재를 부정한 자에게 뿌려 그 육체를 정결하게 하여 거룩하게 하거든',30117),
('heb-9-14','heb','히브리서',9,14,'하물며 영원하신 성령으로 말미암아 흠 없는 자기를 하나님께 드린 그리스도의 피가 어찌 너희 양심을 죽은 행실에서 깨끗하게 하고 살아 계신 하나님을 섬기게 하지 못하겠느냐',30118),
('heb-9-15','heb','히브리서',9,15,'이로 말미암아 그는 새 언약의 중보자시니 이는 첫 언약 때에 범한 죄에서 속량하려고 죽으사 부르심을 입은 자로 하여금 영원한 기업의 약속을 얻게 하려 하심이라',30119),
('heb-9-16','heb','히브리서',9,16,'유언은 유언한 자가 죽어야 되나니',30120),
('heb-9-17','heb','히브리서',9,17,'유언은 그 사람이 죽은 후에야 유효한즉 유언한 자가 살아 있는 동안에는 효력이 없느니라',30121),
('heb-9-18','heb','히브리서',9,18,'이러므로 첫 언약도 피 없이 세운 것이 아니니',30122),
('heb-9-19','heb','히브리서',9,19,'모세가 율법대로 모든 계명을 온 백성에게 말한 후에 송아지와 염소의 피 및 물과 붉은 양털과 우슬초를 취하여 그 두루마리와 온 백성에게 뿌리며',30123),
('heb-9-20','heb','히브리서',9,20,'이르되 이는 하나님이 너희에게 명하신 언약의 피라 하고',30124),
('heb-9-21','heb','히브리서',9,21,'또한 이와 같이 피를 장막과 섬기는 일에 쓰는 모든 그릇에 뿌렸느니라',30125),
('heb-9-22','heb','히브리서',9,22,'율법을 따라 거의 모든 물건이 피로써 정결하게 되나니 피흘림이 없은즉 사함이 없느니라',30126),
('heb-9-23','heb','히브리서',9,23,'그러므로 하늘에 있는 것들의 모형은 이런 것들로써 정결하게 할 필요가 있었으나 하늘에 있는 그것들은 이런 것들보다 더 좋은 제물로 할지니라',30127),
('heb-9-24','heb','히브리서',9,24,'그리스도께서는 참 것의 그림자인 손으로 만든 성소에 들어가지 아니하시고 바로 그 하늘에 들어가사 이제 우리를 위하여 하나님 앞에 나타나시고',30128),
('heb-9-25','heb','히브리서',9,25,'대제사장이 해마다 다른 것의 피로써 성소에 들어가는 것 같이 자주 자기를 드리려고 아니하실지니',30129),
('heb-9-26','heb','히브리서',9,26,'그리하면 그가 세상을 창조한 때부터 자주 고난을 받았어야 할 것이로되 이제 자기를 단번에 제물로 드려 죄를 없이 하시려고 세상 끝에 나타나셨느니라',30130),
('heb-9-27','heb','히브리서',9,27,'한번 죽는 것은 사람에게 정해진 것이요 그 후에는 심판이 있으리니',30131),
('heb-9-28','heb','히브리서',9,28,'이와 같이 그리스도도 많은 사람의 죄를 담당하시려고 단번에 드리신 바 되셨고 구원에 이르게 하기 위하여 죄와 상관 없이 자기를 바라는 자들에게 두 번째 나타나시리라',30132),
('heb-10-1','heb','히브리서',10,1,'율법은 장차 올 좋은 일의 그림자일 뿐이요 참 형상이 아니므로 해마다 늘 드리는 같은 제사로는 나아오는 자들을 언제나 온전하게 할 수 없느니라',30133),
('heb-10-2','heb','히브리서',10,2,'그렇지 아니하면 섬기는 자들이 단번에 정결하게 되어 다시 죄를 깨닫는 일이 없으리니 어찌 제사 드리는 일을 그치지 아니하였으리요',30134),
('heb-10-3','heb','히브리서',10,3,'그러나 이 제사들에는 해마다 죄를 기억하게 하는 것이 있나니',30135),
('heb-10-4','heb','히브리서',10,4,'이는 황소와 염소의 피가 능히 죄를 없이 하지 못함이라',30136),
('heb-10-5','heb','히브리서',10,5,'그러므로 주께서 세상에 임하실 때에 이르시되 하나님이 제사와 예물을 원하지 아니하시고 오직 나를 위하여 한 몸을 예비하셨도다',30137),
('heb-10-6','heb','히브리서',10,6,'번제와 속죄제는 기뻐하지 아니하시나니',30138),
('heb-10-7','heb','히브리서',10,7,'이에 내가 말하기를 하나님이여 보시옵소서 두루마리 책에 나를 가리켜 기록된 것과 같이 하나님의 뜻을 행하러 왔나이다 하셨느니라',30139),
('heb-10-8','heb','히브리서',10,8,'위에 말씀하시기를 주께서는 제사와 예물과 번제와 속죄제는 원하지도 아니하고 기뻐하지도 아니하신다 하셨고 (이는 다 율법을 따라 드리는 것이라)',30140),
('heb-10-9','heb','히브리서',10,9,'그 후에 말씀하시기를 보시옵소서 내가 하나님의 뜻을 행하러 왔나이다 하셨으니 그 첫째 것을 폐하심은 둘째 것을 세우려 하심이라',30141),
('heb-10-10','heb','히브리서',10,10,'이 뜻을 따라 예수 그리스도의 몸을 단번에 드리심으로 말미암아 우리가 거룩함을 얻었노라',30142),
('heb-10-11','heb','히브리서',10,11,'제사장마다 매일 서서 섬기며 자주 같은 제사를 드리되 이 제사는 언제나 죄를 없게 하지 못하거니와',30143),
('heb-10-12','heb','히브리서',10,12,'오직 그리스도는 죄를 위하여 한 영원한 제사를 드리시고 하나님 우편에 앉으사',30144),
('heb-10-13','heb','히브리서',10,13,'그 후에 자기 원수들을 자기 발등상이 되게 하실 때까지 기다리시나니',30145),
('heb-10-14','heb','히브리서',10,14,'그가 거룩하게 된 자들을 한 번의 제사로 영원히 온전하게 하셨느니라',30146),
('heb-10-15','heb','히브리서',10,15,'또한 성령이 우리에게 증언하시되',30147),
('heb-10-16','heb','히브리서',10,16,'주께서 이르시되 그 날 후로는 그들과 맺을 언약이 이것이라 하시고 내 법을 그들의 마음에 두고 그들의 생각에 기록하리라 하신 후에',30148),
('heb-10-17','heb','히브리서',10,17,'또 그들의 죄와 그들의 불법을 내가 다시 기억하지 아니하리라 하셨으니',30149),
('heb-10-18','heb','히브리서',10,18,'이것들을 사하셨은즉 다시 죄를 위하여 제사 드릴 것이 없느니라',30150),
('heb-10-19','heb','히브리서',10,19,'그러므로 형제들아 우리가 예수의 피를 힘입어 성소에 들어갈 담력을 얻었나니',30151),
('heb-10-20','heb','히브리서',10,20,'그 길은 우리를 위하여 휘장 가운데로 열어 놓으신 새로운 살 길이요 휘장은 곧 그의 육체니라',30152),
('heb-10-21','heb','히브리서',10,21,'또 하나님의 집 다스리는 큰 제사장이 계시매',30153),
('heb-10-22','heb','히브리서',10,22,'우리가 마음에 뿌림을 받아 악한 양심으로부터 벗어나고 몸은 맑은 물로 씻음을 받았으니 참 마음과 온전한 믿음으로 하나님께 나아가자',30154),
('heb-10-23','heb','히브리서',10,23,'또 약속하신 이는 미쁘시니 우리가 믿는 도리의 소망을 움직이지 말며 굳게 잡고',30155),
('heb-10-24','heb','히브리서',10,24,'서로 돌아보아 사랑과 선행을 격려하며',30156),
('heb-10-25','heb','히브리서',10,25,'모이기를 폐하는 어떤 사람들의 습관과 같이 하지 말고 오직 권하여 그 날이 가까움을 볼수록 더욱 그리하자',30157),
('heb-10-26','heb','히브리서',10,26,'우리가 진리를 아는 지식을 받은 후 짐짓 죄를 범한즉 다시 속죄하는 제사가 없고',30158),
('heb-10-27','heb','히브리서',10,27,'오직 무서운 마음으로 심판을 기다리는 것과 대적하는 자를 태울 맹렬한 불만 있으리라',30159),
('heb-10-28','heb','히브리서',10,28,'모세의 법을 폐한 자도 두세 증인으로 말미암아 불쌍히 여김을 받지 못하고 죽었거든',30160),
('heb-10-29','heb','히브리서',10,29,'하물며 하나님의 아들을 짓밟고 자기를 거룩하게 한 언약의 피를 부정한 것으로 여기고 은혜의 성령을 욕되게 하는 자가 당연히 받을 형벌은 얼마나 더 무겁겠느냐 너희는 생각하라',30161),
('heb-10-30','heb','히브리서',10,30,'원수 갚는 것이 내게 있으니 내가 갚으리라 하시고 또 다시 주께서 그의 백성을 심판하리라 말씀하신 것을 우리가 아노니',30162),
('heb-10-31','heb','히브리서',10,31,'살아 계신 하나님의 손에 빠져 들어가는 것이 무서울진저',30163),
('heb-10-32','heb','히브리서',10,32,'전날에 너희가 빛을 받은 후에 고난의 큰 싸움을 견디어 낸 것을 생각하라',30164),
('heb-10-33','heb','히브리서',10,33,'혹은 비방과 환난으로써 사람에게 구경거리가 되고 혹은 이런 형편에 있는 자들과 사귀는 자가 되었으니',30165),
('heb-10-34','heb','히브리서',10,34,'너희가 갇힌 자를 동정하고 너희 소유를 빼앗기는 것도 기쁘게 당한 것은 더 낫고 영구한 소유가 있는 줄 앎이라',30166),
('heb-10-35','heb','히브리서',10,35,'그러므로 너희 담대함을 버리지 말라 이것이 큰 상을 얻게 하느니라',30167),
('heb-10-36','heb','히브리서',10,36,'너희에게 인내가 필요함은 너희가 하나님의 뜻을 행한 후에 약속하신 것을 받기 위함이라',30168),
('heb-10-37','heb','히브리서',10,37,'잠시 잠깐 후면 오실 이가 오시리니 지체하지 아니하시리라',30169),
('heb-10-38','heb','히브리서',10,38,'나의 의인은 믿음으로 말미암아 살리라 또한 뒤로 물러가면 내 마음이 그를 기뻐하지 아니하리라 하셨느니라',30170),
('heb-10-39','heb','히브리서',10,39,'우리는 뒤로 물러가 멸망할 자가 아니요 오직 영혼을 구원함에 이르는 믿음을 가진 자니라',30171),
('heb-11-1','heb','히브리서',11,1,'믿음은 바라는 것들의 실상이요 보이지 않는 것들의 증거니',30172),
('heb-11-2','heb','히브리서',11,2,'선진들이 이로써 증거를 얻었느니라',30173),
('heb-11-3','heb','히브리서',11,3,'믿음으로 모든 세계가 하나님의 말씀으로 지어진 줄을 우리가 아나니 보이는 것은 나타난 것으로 말미암아 된 것이 아니니라',30174),
('heb-11-4','heb','히브리서',11,4,'믿음으로 아벨은 가인보다 더 나은 제사를 하나님께 드림으로 의로운 자라 하시는 증거를 얻었으니 하나님이 그 예물에 대하여 증언하심이라 그가 죽었으나 그 믿음으로써 지금도 말하느니라',30175),
('heb-11-5','heb','히브리서',11,5,'믿음으로 에녹은 죽음을 보지 않고 옮겨졌으니 하나님이 그를 옮기심으로 다시 보이지 아니하였느니라 그는 옮겨지기 전에 하나님을 기쁘시게 하는 자라 하는 증거를 받았느니라',30176),
('heb-11-6','heb','히브리서',11,6,'믿음이 없이는 하나님을 기쁘시게 하지 못하나니 하나님께 나아가는 자는 반드시 그가 계신 것과 또한 그가 자기를 찾는 자들에게 상 주시는 이심을 믿어야 할지니라',30177),
('heb-11-7','heb','히브리서',11,7,'믿음으로 노아는 아직 보이지 않는 일에 경고하심을 받아 경외함으로 방주를 준비하여 그 집을 구원하였으니 이로 말미암아 세상을 정죄하고 믿음을 따르는 의의 상속자가 되었느니라',30178),
('heb-11-8','heb','히브리서',11,8,'믿음으로 아브라함은 부르심을 받았을 때에 순종하여 장래의 유업으로 받을 땅에 나아갈새 갈 바를 알지 못하고 나아갔으며',30179),
('heb-11-9','heb','히브리서',11,9,'믿음으로 그가 이방의 땅에 있는 것 같이 약속의 땅에 거류하여 동일한 약속을 유업으로 함께 받은 이삭 및 야곱과 더불어 장막에 거하였으니',30180),
('heb-11-10','heb','히브리서',11,10,'이는 그가 하나님이 계획하시고 지으실 터가 있는 성을 바랐음이라',30181),
('heb-11-11','heb','히브리서',11,11,'믿음으로 사라 자신도 나이가 많아 단산하였으나 잉태할 수 있는 힘을 얻었으니 이는 약속하신 이를 미쁘신 줄 알았음이라',30182),
('heb-11-12','heb','히브리서',11,12,'이러므로 죽은 자와 같은 한 사람으로 말미암아 하늘의 허다한 별과 또 해변의 무수한 모래와 같이 많은 후손이 생육하였느니라',30183),
('heb-11-13','heb','히브리서',11,13,'이 사람들은 다 믿음을 따라 죽었으며 약속을 받지 못하였으되 그것들을 멀리서 보고 환영하며 또 땅에서는 외국인과 나그네임을 증언하였으니',30184),
('heb-11-14','heb','히브리서',11,14,'그들이 이같이 말하는 것은 자기들이 본향 찾는 자임을 나타냄이라',30185),
('heb-11-15','heb','히브리서',11,15,'그들이 나온 바 본향을 생각하였더라면 돌아갈 기회가 있었으려니와',30186),
('heb-11-16','heb','히브리서',11,16,'그들이 이제는 더 나은 본향을 사모하니 곧 하늘에 있는 것이라 이러므로 하나님이 그들의 하나님이라 일컬음 받으심을 부끄러워하지 아니하시고 그들을 위하여 한 성을 예비하셨느니라',30187),
('heb-11-17','heb','히브리서',11,17,'아브라함은 시험을 받을 때에 믿음으로 이삭을 드렸으니 그는 약속들을 받은 자로되 그 외아들을 드렸느니라',30188),
('heb-11-18','heb','히브리서',11,18,'그에게 이미 말씀하시기를 네 자손이라 칭할 자는 이삭으로 말미암으리라 하셨으니',30189),
('heb-11-19','heb','히브리서',11,19,'그가 하나님이 능히 이삭을 죽은 자 가운데서 다시 살리실 줄로 생각한지라 비유컨대 그를 죽은 자 가운데서 도로 받은 것이니라',30190),
('heb-11-20','heb','히브리서',11,20,'믿음으로 이삭은 장차 있을 일에 대하여 야곱과 에서에게 축복하였으며',30191),
('heb-11-21','heb','히브리서',11,21,'믿음으로 야곱은 죽을 때에 요셉의 각 아들에게 축복하고 그 지팡이 머리에 의지하여 경배하였으며',30192),
('heb-11-22','heb','히브리서',11,22,'믿음으로 요셉은 임종시에 이스라엘 자손들이 떠날 것을 말하고 또 자기 뼈를 위하여 명하였으며',30193),
('heb-11-23','heb','히브리서',11,23,'믿음으로 모세가 났을 때에 그 부모가 아름다운 아이임을 보고 석 달 동안 숨겨 왕의 명령을 무서워하지 아니하였으며',30194),
('heb-11-24','heb','히브리서',11,24,'믿음으로 모세는 장성하여 바로의 공주의 아들이라 칭함 받기를 거절하고',30195),
('heb-11-25','heb','히브리서',11,25,'도리어 하나님의 백성과 함께 고난 받기를 잠시 죄악의 낙을 누리는 것보다 더 좋아하고',30196),
('heb-11-26','heb','히브리서',11,26,'그리스도를 위하여 받는 수모를 애굽의 모든 보화보다 더 큰 재물로 여겼으니 이는 상 주심을 바라봄이라',30197),
('heb-11-27','heb','히브리서',11,27,'믿음으로 애굽을 떠나 왕의 노함을 무서워하지 아니하고 곧 보이지 아니하는 자를 보는 것 같이 하여 참았으며',30198),
('heb-11-28','heb','히브리서',11,28,'믿음으로 유월절과 피 뿌리는 예식을 정하였으니 이는 장자를 멸하는 자로 그들을 건드리지 않게 하려 한 것이며',30199),
('heb-11-29','heb','히브리서',11,29,'믿음으로 그들은 홍해를 육지 같이 건넜으나 애굽 사람들은 이것을 시험하다가 빠져 죽었으며',30200),
('heb-11-30','heb','히브리서',11,30,'믿음으로 칠 일 동안 여리고를 도니 성이 무너졌으며',30201),
('heb-11-31','heb','히브리서',11,31,'믿음으로 기생 라합은 정탐꾼을 평안히 영접하였으므로 순종하지 아니한 자와 함께 멸망하지 아니하였도다',30202),
('heb-11-32','heb','히브리서',11,32,'내가 무슨 말을 더 하리요 기드온, 바락, 삼손, 입다, 다윗 및 사무엘과 선지자들의 일을 말하려면 내게 시간이 부족하리로다',30203),
('heb-11-33','heb','히브리서',11,33,'그들은 믿음으로 나라들을 이기기도 하며 의를 행하기도 하며 약속을 받기도 하며 사자들의 입을 막기도 하며',30204),
('heb-11-34','heb','히브리서',11,34,'불의 세력을 멸하기도 하며 칼날을 피하기도 하며 연약한 가운데서 강하게 되기도 하며 전쟁에 용감하게 되어 이방 사람들의 진을 물리치기도 하며',30205),
('heb-11-35','heb','히브리서',11,35,'여자들은 자기의 죽은 자들을 부활로 받아들이기도 하며 또 어떤 이들은 더 좋은 부활을 얻고자 하여 심한 고문을 받되 구차히 풀려나기를 원하지 아니하였으며',30206),
('heb-11-36','heb','히브리서',11,36,'또 어떤 이들은 조롱과 채찍질뿐 아니라 결박과 옥에 갇히는 시련도 받았으며',30207),
('heb-11-37','heb','히브리서',11,37,'돌로 치는 것과 톱으로 켜는 것과 시험과 칼로 죽임을 당하고 양과 염소의 가죽을 입고 유리하여 궁핍과 환난과 학대를 받았으니',30208),
('heb-11-38','heb','히브리서',11,38,'(이런 사람은 세상이 감당하지 못하느니라) 그들이 광야와 산과 동굴과 토굴에 유리하였느니라',30209),
('heb-11-39','heb','히브리서',11,39,'이 사람들은 다 믿음으로 말미암아 증거를 받았으나 약속된 것을 받지 못하였으니',30210),
('heb-11-40','heb','히브리서',11,40,'이는 하나님이 우리를 위하여 더 좋은 것을 예비하셨은즉 우리가 아니면 그들로 온전함을 이루지 못하게 하려 하심이라',30211),
('heb-12-1','heb','히브리서',12,1,'이러므로 우리에게 구름 같이 둘러싼 허다한 증인들이 있으니 모든 무거운 것과 얽매이기 쉬운 죄를 벗어 버리고 인내로써 우리 앞에 당한 경주를 하며',30212),
('heb-12-2','heb','히브리서',12,2,'믿음의 주요 또 온전하게 하시는 이인 예수를 바라보자 그는 그 앞에 있는 기쁨을 위하여 십자가를 참으사 부끄러움을 개의치 아니하시더니 하나님 보좌 우편에 앉으셨느니라',30213),
('heb-12-3','heb','히브리서',12,3,'너희가 피곤하여 낙심하지 않기 위하여 죄인들이 이같이 자기에게 거역한 일을 참으신 이를 생각하라',30214),
('heb-12-4','heb','히브리서',12,4,'너희가 죄와 싸우되 아직 피흘리기까지는 대항하지 아니하고',30215),
('heb-12-5','heb','히브리서',12,5,'또 아들들에게 권하는 것 같이 너희에게 권면하신 말씀도 잊었도다 일렀으되 내 아들아 주의 징계하심을 경히 여기지 말며 그에게 꾸지람을 받을 때에 낙심하지 말라',30216),
('heb-12-6','heb','히브리서',12,6,'주께서 그 사랑하시는 자를 징계하시고 그가 받아들이시는 아들마다 채찍질하심이라 하였으니',30217),
('heb-12-7','heb','히브리서',12,7,'너희가 참음은 징계를 받기 위함이라 하나님이 아들과 같이 너희를 대우하시나니 어찌 아버지가 징계하지 않는 아들이 있으리요',30218),
('heb-12-8','heb','히브리서',12,8,'징계는 다 받는 것이거늘 너희에게 없으면 사생자요 친아들이 아니니라',30219),
('heb-12-9','heb','히브리서',12,9,'또 우리 육신의 아버지가 우리를 징계하여도 공경하였거든 하물며 모든 영의 아버지께 더욱 복종하며 살려 하지 않겠느냐',30220),
('heb-12-10','heb','히브리서',12,10,'그들은 잠시 자기의 뜻대로 우리를 징계하였거니와 오직 하나님은 우리의 유익을 위하여 그의 거룩하심에 참여하게 하시느니라',30221),
('heb-12-11','heb','히브리서',12,11,'무릇 징계가 당시에는 즐거워 보이지 않고 슬퍼 보이나 후에 그로 말미암아 연단 받은 자들은 의와 평강의 열매를 맺느니라',30222),
('heb-12-12','heb','히브리서',12,12,'그러므로 피곤한 손과 연약한 무릎을 일으켜 세우고',30223),
('heb-12-13','heb','히브리서',12,13,'너희 발을 위하여 곧은 길을 만들어 저는 다리로 하여금 어그러지지 않고 고침을 받게 하라',30224),
('heb-12-14','heb','히브리서',12,14,'모든 사람과 더불어 화평함과 거룩함을 따르라 이것이 없이는 아무도 주를 보지 못하리라',30225),
('heb-12-15','heb','히브리서',12,15,'너희는 하나님의 은혜에 이르지 못하는 자가 없도록 하고 또 쓴 뿌리가 나서 괴롭게 하여 많은 사람이 이로 말미암아 더럽게 되지 않게 하며',30226),
('heb-12-16','heb','히브리서',12,16,'음행하는 자와 혹 한 그릇 음식을 위하여 장자의 명분을 판 에서와 같이 망령된 자가 없도록 살피라',30227),
('heb-12-17','heb','히브리서',12,17,'너희가 아는 바와 같이 그가 그 후에 축복을 이어받으려고 눈물을 흘리며 구하되 버린 바가 되어 회개할 기회를 얻지 못하였느니라',30228),
('heb-12-18','heb','히브리서',12,18,'너희는 만질 수 있고 불이 붙는 산과 침침함과 흑암과 폭풍과',30229),
('heb-12-19','heb','히브리서',12,19,'나팔 소리와 말하는 소리가 있는 곳에 이른 것이 아니라 그 소리를 듣는 자들은 더 말씀하지 아니하시기를 구하였으니',30230),
('heb-12-20','heb','히브리서',12,20,'이는 짐승이라도 그 산에 들어가면 돌로 침을 당하리라 하신 명령을 그들이 견디지 못함이라',30231),
('heb-12-21','heb','히브리서',12,21,'그 보이는 바가 이렇듯 무섭기로 모세도 이르되 내가 심히 두렵고 떨린다 하였느니라',30232),
('heb-12-22','heb','히브리서',12,22,'그러나 너희가 이른 곳은 시온 산과 살아 계신 하나님의 도성인 하늘의 예루살렘과 천만 천사와',30233),
('heb-12-23','heb','히브리서',12,23,'하늘에 기록된 장자들의 모임과 교회와 만민의 심판자이신 하나님과 및 온전하게 된 의인의 영들과',30234),
('heb-12-24','heb','히브리서',12,24,'새 언약의 중보자이신 예수와 및 아벨의 피보다 더 나은 것을 말하는 뿌린 피니라',30235),
('heb-12-25','heb','히브리서',12,25,'너희는 삼가 말씀하신 이를 거역하지 말라 땅에서 경고하신 이를 거역한 그들이 피하지 못하였거든 하물며 하늘로부터 경고하신 이를 배반하는 우리일까보냐',30236),
('heb-12-26','heb','히브리서',12,26,'그 때에는 그 소리가 땅을 진동하였거니와 이제는 약속하여 이르시되 내가 또 한 번 땅만 아니라 하늘도 진동하리라 하셨느니라',30237),
('heb-12-27','heb','히브리서',12,27,'이 또 한 번이라 하심은 진동하지 아니하는 것을 영존하게 하기 위하여 진동할 것들 곧 만드신 것들이 변동될 것을 나타내심이라',30238),
('heb-12-28','heb','히브리서',12,28,'그러므로 우리가 흔들리지 않는 나라를 받았은즉 은혜를 받자 이로 말미암아 경건함과 두려움으로 하나님을 기쁘시게 섬길지니',30239),
('heb-12-29','heb','히브리서',12,29,'우리 하나님은 소멸하는 불이심이라',30240),
('heb-13-1','heb','히브리서',13,1,'형제 사랑하기를 계속하고',30241),
('heb-13-2','heb','히브리서',13,2,'손님 대접하기를 잊지 말라 이로써 부지중에 천사들을 대접한 이들이 있었느니라',30242),
('heb-13-3','heb','히브리서',13,3,'너희도 함께 갇힌 것 같이 갇힌 자를 생각하고 너희도 몸을 가졌은즉 학대 받는 자를 생각하라',30243),
('heb-13-4','heb','히브리서',13,4,'모든 사람은 결혼을 귀히 여기고 침소를 더럽히지 않게 하라 음행하는 자들과 간음하는 자들을 하나님이 심판하시리라',30244),
('heb-13-5','heb','히브리서',13,5,'돈을 사랑하지 말고 있는 바를 족한 줄로 알라 그가 친히 말씀하시기를 내가 결코 너희를 버리지 아니하고 너희를 떠나지 아니하리라 하셨느니라',30245),
('heb-13-6','heb','히브리서',13,6,'그러므로 우리가 담대히 말하되 주는 나를 돕는 이시니 내가 무서워하지 아니하겠노라 사람이 내게 어찌하리요 하노라',30246),
('heb-13-7','heb','히브리서',13,7,'하나님의 말씀을 너희에게 일러 주고 너희를 인도하던 자들을 생각하며 그들의 행실의 결말을 주의하여 보고 그들의 믿음을 본받으라',30247),
('heb-13-8','heb','히브리서',13,8,'예수 그리스도는 어제나 오늘이나 영원토록 동일하시니라',30248),
('heb-13-9','heb','히브리서',13,9,'여러 가지 다른 교훈에 끌리지 말라 마음은 은혜로써 굳게 함이 아름답고 음식으로써 할 것이 아니니 음식으로 말미암아 행한 자는 유익을 얻지 못하였느니라',30249),
('heb-13-10','heb','히브리서',13,10,'우리에게 제단이 있는데 장막에서 섬기는 자들은 그 제단에서 먹을 권한이 없나니',30250),
('heb-13-11','heb','히브리서',13,11,'이는 죄를 위한 짐승의 피는 대제사장이 가지고 성소에 들어가고 그 육체는 영문 밖에서 불사름이라',30251),
('heb-13-12','heb','히브리서',13,12,'그러므로 예수도 자기 피로써 백성을 거룩하게 하려고 성문 밖에서 고난을 받으셨느니라',30252),
('heb-13-13','heb','히브리서',13,13,'그런즉 우리도 그의 치욕을 짊어지고 영문 밖으로 그에게 나아가자',30253),
('heb-13-14','heb','히브리서',13,14,'우리가 여기에는 영구한 도성이 없으므로 장차 올 것을 찾나니',30254),
('heb-13-15','heb','히브리서',13,15,'그러므로 우리는 예수로 말미암아 항상 찬송의 제사를 하나님께 드리자 이는 그 이름을 증언하는 입술의 열매니라',30255),
('heb-13-16','heb','히브리서',13,16,'오직 선을 행함과 서로 나누어 주기를 잊지 말라 하나님은 이같은 제사를 기뻐하시느니라',30256),
('heb-13-17','heb','히브리서',13,17,'너희를 인도하는 자들에게 순종하고 복종하라 그들은 너희 영혼을 위하여 경성하기를 자신들이 청산할 자인 것 같이 하느니라 그들로 하여금 즐거움으로 이것을 하게 하고 근심으로 하게 하지 말라 그렇지 않으면 너희에게 유익이 없느니라',30257),
('heb-13-18','heb','히브리서',13,18,'우리를 위하여 기도하라 우리가 모든 일에 선하게 행하려 하므로 우리에게 선한 양심이 있는 줄을 확신하노니',30258),
('heb-13-19','heb','히브리서',13,19,'내가 더 속히 너희에게 돌아가기 위하여 너희가 기도하기를 더욱 원하노라',30259),
('heb-13-20','heb','히브리서',13,20,'양들의 큰 목자이신 우리 주 예수를 영원한 언약의 피로 죽은 자 가운데서 이끌어 내신 평강의 하나님이',30260),
('heb-13-21','heb','히브리서',13,21,'모든 선한 일에 너희를 온전하게 하사 자기 뜻을 행하게 하시고 그 앞에 즐거운 것을 예수 그리스도로 말미암아 우리 가운데서 이루시기를 원하노라 영광이 그에게 세세무궁토록 있을지어다 아멘',30261),
('heb-13-22','heb','히브리서',13,22,'형제들아 내가 너희를 권하노니 권면의 말을 용납하라 내가 간단히 너희에게 썼느니라',30262),
('heb-13-23','heb','히브리서',13,23,'우리 형제 디모데가 놓인 것을 너희가 알라 그가 속히 오면 내가 그와 함께 가서 너희를 보리라',30263),
('heb-13-24','heb','히브리서',13,24,'너희를 인도하는 자들과 및 모든 성도들에게 문안하라 이달리야에서 온 자들도 너희에게 문안하느니라',30264),
('heb-13-25','heb','히브리서',13,25,'은혜가 너희 모든 사람에게 있을지어다2)',30265),
('jas-1-1','jas','야고보서',1,1,'하나님과 주 예수 그리스도의 종 야고보는 흩어져 있는 열두 지파에게 문안하노라',30266),
('jas-1-2','jas','야고보서',1,2,'내 형제들아 너희가 여러 가지 시험을 당하거든 온전히 기쁘게 여기라',30267),
('jas-1-3','jas','야고보서',1,3,'이는 너희 믿음의 시련이 인내를 만들어 내는 줄 너희가 앎이라',30268),
('jas-1-4','jas','야고보서',1,4,'인내를 온전히 이루라 이는 너희로 온전하고 구비하여 조금도 부족함이 없게 하려 함이라',30269),
('jas-1-5','jas','야고보서',1,5,'너희 중에 누구든지 지혜가 부족하거든 모든 사람에게 후히 주시고 꾸짖지 아니하시는 하나님께 구하라 그리하면 주시리라',30270),
('jas-1-6','jas','야고보서',1,6,'오직 믿음으로 구하고 조금도 의심하지 말라 의심하는 자는 마치 바람에 밀려 요동하는 바다 물결 같으니',30271),
('jas-1-7','jas','야고보서',1,7,'이런 사람은 무엇이든지 주께 얻기를 생각하지 말라',30272),
('jas-1-8','jas','야고보서',1,8,'두 마음을 품어 모든 일에 정함이 없는 자로다',30273),
('jas-1-9','jas','야고보서',1,9,'낮은 형제는 자기의 높음을 자랑하고',30274),
('jas-1-10','jas','야고보서',1,10,'부한 자는 자기의 낮아짐을 자랑할지니 이는 그가 풀의 꽃과 같이 지나감이라',30275),
('jas-1-11','jas','야고보서',1,11,'해가 돋고 뜨거운 바람이 불어 풀을 말리면 꽃이 떨어져 그 모양의 아름다움이 없어지나니 부한 자도 그 행하는 일에 이와 같이 쇠잔하리라',30276),
('jas-1-12','jas','야고보서',1,12,'시험을 참는 자는 복이 있나니 이는 시련을 견디어 낸 자가 주께서 자기를 사랑하는 자들에게 약속하신 생명의 면류관을 얻을 것이기 때문이라',30277),
('jas-1-13','jas','야고보서',1,13,'사람이 시험을 받을 때에 내가 하나님께 시험을 받는다 하지 말지니 하나님은 악에게 시험을 받지도 아니하시고 친히 아무도 시험하지 아니하시느니라',30278),
('jas-1-14','jas','야고보서',1,14,'오직 각 사람이 시험을 받는 것은 자기 욕심에 끌려 미혹됨이니',30279),
('jas-1-15','jas','야고보서',1,15,'욕심이 잉태한즉 죄를 낳고 죄가 장성한즉 사망을 낳느니라',30280),
('jas-1-16','jas','야고보서',1,16,'내 사랑하는 형제들아 속지 말라',30281),
('jas-1-17','jas','야고보서',1,17,'온갖 좋은 은사와 온전한 선물이 다 위로부터 빛들의 아버지께로부터 내려오나니 그는 변함도 없으시고 회전하는 그림자도 없으시니라',30282),
('jas-1-18','jas','야고보서',1,18,'그가 그 피조물 중에 우리로 한 첫 열매가 되게 하시려고 자기의 뜻을 따라 진리의 말씀으로 우리를 낳으셨느니라',30283),
('jas-1-19','jas','야고보서',1,19,'내 사랑하는 형제들아 너희가 알지니 사람마다 듣기는 속히 하고 말하기는 더디 하며 성내기도 더디 하라',30284),
('jas-1-20','jas','야고보서',1,20,'사람이 성내는 것이 하나님의 의를 이루지 못함이라',30285),
('jas-1-21','jas','야고보서',1,21,'그러므로 모든 더러운 것과 넘치는 악을 내버리고 너희 영혼을 능히 구원할 바 마음에 심어진 말씀을 온유함으로 받으라',30286),
('jas-1-22','jas','야고보서',1,22,'너희는 말씀을 행하는 자가 되고 듣기만 하여 자신을 속이는 자가 되지 말라',30287),
('jas-1-23','jas','야고보서',1,23,'누구든지 말씀을 듣고 행하지 아니하면 그는 거울로 자기의 생긴 얼굴을 보는 사람과 같아서',30288),
('jas-1-24','jas','야고보서',1,24,'제 자신을 보고 가서 그 모습이 어떠했는지를 곧 잊어버리거니와',30289),
('jas-1-25','jas','야고보서',1,25,'자유롭게 하는 온전한 율법을 들여다보고 있는 자는 듣고 잊어버리는 자가 아니요 실천하는 자니 이 사람은 그 행하는 일에 복을 받으리라',30290),
('jas-1-26','jas','야고보서',1,26,'누구든지 스스로 경건하다 생각하며 자기 혀를 재갈 물리지 아니하고 자기 마음을 속이면 이 사람의 경건은 헛것이라',30291),
('jas-1-27','jas','야고보서',1,27,'하나님 아버지 앞에서 정결하고 더러움이 없는 경건은 곧 고아와 과부를 그 환난중에 돌보고 또 자기를 지켜 세속에 물들지 아니하는 그것이니라',30292),
('jas-2-1','jas','야고보서',2,1,'내 형제들아 영광의 주 곧 우리 주 예수 그리스도에 대한 믿음을 너희가 가졌으니 사람을 차별하여 대하지 말라',30293),
('jas-2-2','jas','야고보서',2,2,'만일 너희 회당에 금 가락지를 끼고 아름다운 옷을 입은 사람이 들어오고 또 남루한 옷을 입은 가난한 사람이 들어올 때에',30294),
('jas-2-3','jas','야고보서',2,3,'너희가 아름다운 옷을 입은 자를 눈여겨 보고 말하되 여기 좋은 자리에 앉으소서 하고 또 가난한 자에게 말하되 너는 거기 서 있든지 내 발등상 아래에 앉으라 하면',30295),
('jas-2-4','jas','야고보서',2,4,'너희끼리 서로 차별하며 악한 생각으로 판단하는 자가 되는 것이 아니냐',30296),
('jas-2-5','jas','야고보서',2,5,'내 사랑하는 형제들아 들을지어다 하나님이 세상에서 가난한 자를 택하사 믿음에 부요하게 하시고 또 자기를 사랑하는 자들에게 약속하신 나라를 상속으로 받게 하지 아니하셨느냐',30297),
('jas-2-6','jas','야고보서',2,6,'너희는 도리어 가난한 자를 업신여겼도다 부자는 너희를 억압하며 법정으로 끌고 가지 아니하느냐',30298),
('jas-2-7','jas','야고보서',2,7,'그들은 너희에게 대하여 일컫는 바 그 아름다운 이름을 비방하지 아니하느냐',30299),
('jas-2-8','jas','야고보서',2,8,'너희가 만일 성경에 기록된 대로 네 이웃 사랑하기를 네 몸과 같이 하라 하신 최고의 법을 지키면 잘하는 것이거니와',30300),
('jas-2-9','jas','야고보서',2,9,'만일 너희가 사람을 차별하여 대하면 죄를 짓는 것이니 율법이 너희를 범법자로 정죄하리라',30301),
('jas-2-10','jas','야고보서',2,10,'누구든지 온 율법을 지키다가 그 하나를 범하면 모두 범한 자가 되나니',30302),
('jas-2-11','jas','야고보서',2,11,'간음하지 말라 하신 이가 또한 살인하지 말라 하셨은즉 네가 비록 간음하지 아니하여도 살인하면 율법을 범한 자가 되느니라',30303),
('jas-2-12','jas','야고보서',2,12,'너희는 자유의 율법대로 심판 받을 자처럼 말도 하고 행하기도 하라',30304),
('jas-2-13','jas','야고보서',2,13,'긍휼을 행하지 아니하는 자에게는 긍휼 없는 심판이 있으리라 긍휼은 심판을 이기고 자랑하느니라',30305),
('jas-2-14','jas','야고보서',2,14,'내 형제들아 만일 사람이 믿음이 있노라 하고 행함이 없으면 무슨 유익이 있으리요 그 믿음이 능히 자기를 구원하겠느냐',30306),
('jas-2-15','jas','야고보서',2,15,'만일 형제나 자매가 헐벗고 일용할 양식이 없는데',30307),
('jas-2-16','jas','야고보서',2,16,'너희 중에 누구든지 그에게 이르되 평안히 가라, 덥게 하라, 배부르게 하라 하며 그 몸에 쓸 것을 주지 아니하면 무슨 유익이 있으리요',30308),
('jas-2-17','jas','야고보서',2,17,'이와 같이 행함이 없는 믿음은 그 자체가 죽은 것이라',30309),
('jas-2-18','jas','야고보서',2,18,'어떤 사람은 말하기를 너는 믿음이 있고 나는 행함이 있으니 행함이 없는 네 믿음을 내게 보이라 나는 행함으로 내 믿음을 네게 보이리라 하리라',30310),
('jas-2-19','jas','야고보서',2,19,'네가 하나님은 한 분이신 줄을 믿느냐 잘하는도다 귀신들도 믿고 떠느니라',30311),
('jas-2-20','jas','야고보서',2,20,'아아 허탄한 사람아 행함이 없는 믿음이 헛것인 줄을 알고자 하느냐',30312),
('jas-2-21','jas','야고보서',2,21,'우리 조상 아브라함이 그 아들 이삭을 제단에 바칠 때에 행함으로 의롭다 하심을 받은 것이 아니냐',30313),
('jas-2-22','jas','야고보서',2,22,'네가 보거니와 믿음이 그의 행함과 함께 일하고 행함으로 믿음이 온전하게 되었느니라',30314),
('jas-2-23','jas','야고보서',2,23,'이에 성경에 이른 바 아브라함이 하나님을 믿으니 이것을 의로 여기셨다는 말씀이 이루어졌고 그는 하나님의 벗이라 칭함을 받았나니',30315),
('jas-2-24','jas','야고보서',2,24,'이로 보건대 사람이 행함으로 의롭다 하심을 받고 믿음으로만은 아니니라',30316),
('jas-2-25','jas','야고보서',2,25,'또 이와 같이 기생 라합이 사자들을 접대하여 다른 길로 나가게 할 때에 행함으로 의롭다 하심을 받은 것이 아니냐',30317),
('jas-2-26','jas','야고보서',2,26,'영혼 없는 몸이 죽은 것 같이 행함이 없는 믿음은 죽은 것이니라',30318),
('jas-3-1','jas','야고보서',3,1,'내 형제들아 너희는 선생된 우리가 더 큰 심판을 받을 줄 알고 선생이 많이 되지 말라',30319),
('jas-3-2','jas','야고보서',3,2,'우리가 다 실수가 많으니 만일 말에 실수가 없는 자라면 곧 온전한 사람이라 능히 온 몸도 굴레 씌우리라',30320),
('jas-3-3','jas','야고보서',3,3,'우리가 말들의 입에 재갈 물리는 것은 우리에게 순종하게 하려고 그 온 몸을 제어하는 것이라',30321),
('jas-3-4','jas','야고보서',3,4,'또 배를 보라 그렇게 크고 광풍에 밀려가는 것들을 지극히 작은 키로써 사공의 뜻대로 운행하나니',30322),
('jas-3-5','jas','야고보서',3,5,'이와 같이 혀도 작은 지체로되 큰 것을 자랑하도다 보라 얼마나 작은 불이 얼마나 많은 나무를 태우는가',30323),
('jas-3-6','jas','야고보서',3,6,'혀는 곧 불이요 불의의 세계라 혀는 우리 지체 중에서 온 몸을 더럽히고 삶의 수레바퀴를 불사르나니 그 사르는 것이 지옥 불에서 나느니라',30324),
('jas-3-7','jas','야고보서',3,7,'여러 종류의 짐승과 새와 벌레와 바다의 생물은 다 사람이 길들일 수 있고 길들여 왔거니와',30325),
('jas-3-8','jas','야고보서',3,8,'혀는 능히 길들일 사람이 없나니 쉬지 아니하는 악이요 죽이는 독이 가득한 것이라',30326),
('jas-3-9','jas','야고보서',3,9,'이것으로 우리가 주 아버지를 찬송하고 또 이것으로 하나님의 형상대로 지음을 받은 사람을 저주하나니',30327),
('jas-3-10','jas','야고보서',3,10,'한 입에서 찬송과 저주가 나오는도다 내 형제들아 이것이 마땅하지 아니하니라',30328),
('jas-3-11','jas','야고보서',3,11,'샘이 한 구멍으로 어찌 단 물과 쓴 물을 내겠느냐',30329),
('jas-3-12','jas','야고보서',3,12,'내 형제들아 어찌 무화과나무가 감람 열매를, 포도나무가 무화과를 맺겠느냐 이와 같이 짠 물이 단 물을 내지 못하느니라',30330),
('jas-3-13','jas','야고보서',3,13,'너희 중에 지혜와 총명이 있는 자가 누구냐 그는 선행으로 말미암아 지혜의 온유함으로 그 행함을 보일지니라',30331),
('jas-3-14','jas','야고보서',3,14,'그러나 너희 마음 속에 독한 시기와 다툼이 있으면 자랑하지 말라 진리를 거슬러 거짓말하지 말라',30332),
('jas-3-15','jas','야고보서',3,15,'이러한 지혜는 위로부터 내려온 것이 아니요 땅 위의 것이요 정욕의 것이요 귀신의 것이니',30333),
('jas-3-16','jas','야고보서',3,16,'시기와 다툼이 있는 곳에는 혼란과 모든 악한 일이 있음이라',30334),
('jas-3-17','jas','야고보서',3,17,'오직 위로부터 난 지혜는 첫째 성결하고 다음에 화평하고 관용하고 양순하며 긍휼과 선한 열매가 가득하고 편견과 거짓이 없나니',30335),
('jas-3-18','jas','야고보서',3,18,'화평하게 하는 자들은 화평으로 심어 의의 열매를 거두느니라',30336),
('jas-4-1','jas','야고보서',4,1,'너희 중에 싸움이 어디로부터 다툼이 어디로부터 나느냐 너희 지체 중에서 싸우는 정욕으로부터 나는 것이 아니냐',30337),
('jas-4-2','jas','야고보서',4,2,'너희는 욕심을 내어도 얻지 못하여 살인하며 시기하여도 능히 취하지 못하므로 다투고 싸우는도다 너희가 얻지 못함은 구하지 아니하기 때문이요',30338),
('jas-4-3','jas','야고보서',4,3,'구하여도 받지 못함은 정욕으로 쓰려고 잘못 구하기 때문이라',30339),
('jas-4-4','jas','야고보서',4,4,'간음한 여인들아 세상과 벗된 것이 하나님과 원수 됨을 알지 못하느냐 그런즉 누구든지 세상과 벗이 되고자 하는 자는 스스로 하나님과 원수 되는 것이니라',30340),
('jas-4-5','jas','야고보서',4,5,'너희는 하나님이 우리 속에 거하게 하신 성령이 시기하기까지 사모한다 하신 말씀을 헛된 줄로 생각하느냐',30341),
('jas-4-6','jas','야고보서',4,6,'그러나 더욱 큰 은혜를 주시나니 그러므로 일렀으되 하나님이 교만한 자를 물리치시고 겸손한 자에게 은혜를 주신다 하였느니라',30342),
('jas-4-7','jas','야고보서',4,7,'그런즉 너희는 하나님께 복종할지어다 마귀를 대적하라 그리하면 너희를 피하리라',30343),
('jas-4-8','jas','야고보서',4,8,'하나님을 가까이하라 그리하면 너희를 가까이하시리라 죄인들아 손을 깨끗이 하라 두 마음을 품은 자들아 마음을 성결하게 하라',30344),
('jas-4-9','jas','야고보서',4,9,'슬퍼하며 애통하며 울지어다 너희 웃음을 애통으로, 너희 즐거움을 근심으로 바꿀지어다',30345),
('jas-4-10','jas','야고보서',4,10,'주 앞에서 낮추라 그리하면 주께서 너희를 높이시리라',30346),
('jas-4-11','jas','야고보서',4,11,'형제들아 서로 비방하지 말라 형제를 비방하는 자나 형제를 판단하는 자는 곧 율법을 비방하고 율법을 판단하는 것이라 네가 만일 율법을 판단하면 율법의 준행자가 아니요 재판관이로다',30347),
('jas-4-12','jas','야고보서',4,12,'입법자와 재판관은 오직 한 분이시니 능히 구원하기도 하시며 멸하기도 하시느니라 너는 누구이기에 이웃을 판단하느냐',30348),
('jas-4-13','jas','야고보서',4,13,'들으라 너희 중에 말하기를 오늘이나 내일이나 우리가 어떤 도시에 가서 거기서 일 년을 머물며 장사하여 이익을 보리라 하는 자들아',30349),
('jas-4-14','jas','야고보서',4,14,'내일 일을 너희가 알지 못하는도다 너희 생명이 무엇이냐 너희는 잠깐 보이다가 없어지는 안개니라',30350),
('jas-4-15','jas','야고보서',4,15,'너희가 도리어 말하기를 주의 뜻이면 우리가 살기도 하고 이것이나 저것을 하리라 할 것이거늘',30351),
('jas-4-16','jas','야고보서',4,16,'이제도 너희가 허탄한 자랑을 하니 그러한 자랑은 다 악한 것이라',30352),
('jas-4-17','jas','야고보서',4,17,'그러므로 사람이 선을 행할 줄 알고도 행하지 아니하면 죄니라',30353),
('jas-5-1','jas','야고보서',5,1,'들으라 부한 자들아 너희에게 임할 고생으로 말미암아 울고 통곡하라',30354),
('jas-5-2','jas','야고보서',5,2,'너희 재물은 썩었고 너희 옷은 좀먹었으며',30355),
('jas-5-3','jas','야고보서',5,3,'너희 금과 은은 녹이 슬었으니 이 녹이 너희에게 증거가 되며 불 같이 너희 살을 먹으리라 너희가 말세에 재물을 쌓았도다',30356),
('jas-5-4','jas','야고보서',5,4,'보라 너희 밭에서 추수한 품꾼에게 주지 아니한 삯이 소리 지르며 그 추수한 자의 우는 소리가 만군의 주의 귀에 들렸느니라',30357),
('jas-5-5','jas','야고보서',5,5,'너희가 땅에서 사치하고 방종하여 살륙의 날에 너희 마음을 살찌게 하였도다',30358),
('jas-5-6','jas','야고보서',5,6,'너희는 의인을 정죄하고 죽였으나 그는 너희에게 대항하지 아니하였느니라',30359),
('jas-5-7','jas','야고보서',5,7,'그러므로 형제들아 주께서 강림하시기까지 길이 참으라 보라 농부가 땅에서 나는 귀한 열매를 바라고 길이 참아 이른 비와 늦은 비를 기다리나니',30360),
('jas-5-8','jas','야고보서',5,8,'너희도 길이 참고 마음을 굳건하게 하라 주의 강림이 가까우니라',30361),
('jas-5-9','jas','야고보서',5,9,'형제들아 서로 원망하지 말라 그리하여야 심판을 면하리라 보라 심판주가 문 밖에 서 계시니라',30362),
('jas-5-10','jas','야고보서',5,10,'형제들아 주의 이름으로 말한 선지자들을 고난과 오래 참음의 본으로 삼으라',30363),
('jas-5-11','jas','야고보서',5,11,'보라 인내하는 자를 우리가 복되다 하나니 너희가 욥의 인내를 들었고 주께서 주신 결말을 보았거니와 주는 가장 자비하시고 긍휼히 여기시는 이시니라',30364),
('jas-5-12','jas','야고보서',5,12,'내 형제들아 무엇보다도 맹세하지 말지니 하늘로나 땅으로나 아무 다른 것으로도 맹세하지 말고 오직 너희가 그렇다고 생각하는 것은 그렇다 하고 아니라고 생각하는 것은 아니라 하여 정죄 받음을 면하라',30365),
('jas-5-13','jas','야고보서',5,13,'너희 중에 고난 당하는 자가 있느냐 그는 기도할 것이요 즐거워하는 자가 있느냐 그는 찬송할지니라',30366),
('jas-5-14','jas','야고보서',5,14,'너희 중에 병든 자가 있느냐 그는 교회의 장로들을 청할 것이요 그들은 주의 이름으로 기름을 바르며 그를 위하여 기도할지니라',30367),
('jas-5-15','jas','야고보서',5,15,'믿음의 기도는 병든 자를 구원하리니 주께서 그를 일으키시리라 혹시 죄를 범하였을지라도 사하심을 받으리라',30368),
('jas-5-16','jas','야고보서',5,16,'그러므로 너희 죄를 서로 고백하며 병이 낫기를 위하여 서로 기도하라 의인의 간구는 역사하는 힘이 큼이니라',30369),
('jas-5-17','jas','야고보서',5,17,'엘리야는 우리와 성정이 같은 사람이로되 그가 비가 오지 않기를 간절히 기도한즉 삼 년 육 개월 동안 땅에 비가 오지 아니하고',30370),
('jas-5-18','jas','야고보서',5,18,'다시 기도하니 하늘이 비를 주고 땅이 열매를 맺었느니라',30371),
('jas-5-19','jas','야고보서',5,19,'내 형제들아 너희 중에 미혹되어 진리를 떠난 자를 누가 돌아서게 하면',30372),
('jas-5-20','jas','야고보서',5,20,'너희가 알 것은 죄인을 미혹된 길에서 돌아서게 하는 자가 그의 영혼을 사망에서 구원할 것이며 허다한 죄를 덮을 것임이라',30373),
('1pe-1-1','1pe','베드로전서',1,1,'예수 그리스도의 사도 베드로는 본도, 갈라디아, 갑바도기아, 아시아와 비두니아에 흩어진 나그네',30374),
('1pe-1-2','1pe','베드로전서',1,2,'곧 하나님 아버지의 미리 아심을 따라 성령이 거룩하게 하심으로 순종하고 예수 그리스도의 피 뿌림을 얻기 위하여 택하심을 받은 자들에게 편지하노니 은혜와 평강이 너희에게 더욱 많을지어다',30375),
('1pe-1-3','1pe','베드로전서',1,3,'우리 주 예수 그리스도의 아버지 하나님을 찬송하리로다 그의 많으신 긍휼대로 예수 그리스도를 죽은 자 가운데서 부활하게 하심으로 말미암아 우리를 거듭나게 하사 산 소망이 있게 하시며',30376),
('1pe-1-4','1pe','베드로전서',1,4,'썩지 않고 더럽지 않고 쇠하지 아니하는 유업을 잇게 하시나니 곧 너희를 위하여 하늘에 간직하신 것이라',30377),
('1pe-1-5','1pe','베드로전서',1,5,'너희는 말세에 나타내기로 예비하신 구원을 얻기 위하여 믿음으로 말미암아 하나님의 능력으로 보호하심을 받았느니라',30378),
('1pe-1-6','1pe','베드로전서',1,6,'그러므로 너희가 이제 여러 가지 시험으로 말미암아 잠깐 근심하게 되지 않을 수 없으나 오히려 크게 기뻐하는도다',30379),
('1pe-1-7','1pe','베드로전서',1,7,'너희 믿음의 확실함은 불로 연단하여도 없어질 금보다 더 귀하여 예수 그리스도께서 나타나실 때에 칭찬과 영광과 존귀를 얻게 할 것이니라',30380),
('1pe-1-8','1pe','베드로전서',1,8,'예수를 너희가 보지 못하였으나 사랑하는도다 이제도 보지 못하나 믿고 말할 수 없는 영광스러운 즐거움으로 기뻐하니',30381),
('1pe-1-9','1pe','베드로전서',1,9,'믿음의 결국 곧 영혼의 구원을 받음이라',30382),
('1pe-1-10','1pe','베드로전서',1,10,'이 구원에 대하여는 너희에게 임할 은혜를 예언하던 선지자들이 연구하고 부지런히 살펴서',30383),
('1pe-1-11','1pe','베드로전서',1,11,'자기 속에 계신 그리스도의 영이 그 받으실 고난과 후에 받으실 영광을 미리 증언하여 누구를 또는 어떠한 때를 지시하시는지 상고하니라',30384),
('1pe-1-12','1pe','베드로전서',1,12,'이 섬긴 바가 자기를 위한 것이 아니요 너희를 위한 것임이 계시로 알게 되었으니 이것은 하늘로부터 보내신 성령을 힘입어 복음을 전하는 자들로 이제 너희에게 알린 것이요 천사들도 살펴 보기를 원하는 것이니라',30385),
('1pe-1-13','1pe','베드로전서',1,13,'그러므로 너희 마음의 허리를 동이고 근신하여 예수 그리스도께서 나타나실 때에 너희에게 가져다 주실 은혜를 온전히 바랄지어다',30386),
('1pe-1-14','1pe','베드로전서',1,14,'너희가 순종하는 자식처럼 전에 알지 못할 때에 따르던 너희 사욕을 본받지 말고',30387),
('1pe-1-15','1pe','베드로전서',1,15,'오직 너희를 부르신 거룩한 이처럼 너희도 모든 행실에 거룩한 자가 되라',30388),
('1pe-1-16','1pe','베드로전서',1,16,'기록되었으되 내가 거룩하니 너희도 거룩할지어다 하셨느니라',30389),
('1pe-1-17','1pe','베드로전서',1,17,'외모로 보시지 않고 각 사람의 행위대로 심판하시는 이를 너희가 아버지라 부른즉 너희가 나그네로 있을 때를 두려움으로 지내라',30390),
('1pe-1-18','1pe','베드로전서',1,18,'너희가 알거니와 너희 조상이 물려 준 헛된 행실에서 대속함을 받은 것은 은이나 금 같이 없어질 것으로 된 것이 아니요',30391),
('1pe-1-19','1pe','베드로전서',1,19,'오직 흠 없고 점 없는 어린 양 같은 그리스도의 보배로운 피로 된 것이니라',30392),
('1pe-1-20','1pe','베드로전서',1,20,'그는 창세 전부터 미리 알린 바 되신 이나 이 말세에 너희를 위하여 나타내신 바 되었으니',30393),
('1pe-1-21','1pe','베드로전서',1,21,'너희는 그를 죽은 자 가운데서 살리시고 영광을 주신 하나님을 그리스도로 말미암아 믿는 자니 너희 믿음과 소망이 하나님께 있게 하셨느니라',30394),
('1pe-1-22','1pe','베드로전서',1,22,'너희가 진리를 순종함으로 너희 영혼을 깨끗하게 하여 거짓이 없이 형제를 사랑하기에 이르렀으니 마음으로 뜨겁게 서로 사랑하라',30395),
('1pe-1-23','1pe','베드로전서',1,23,'너희가 거듭난 것은 썩어질 씨로 된 것이 아니요 썩지 아니할 씨로 된 것이니 살아 있고 항상 있는 하나님의 말씀으로 되었느니라',30396),
('1pe-1-24','1pe','베드로전서',1,24,'그러므로 모든 육체는 풀과 같고 그 모든 영광은 풀의 꽃과 같으니 풀은 마르고 꽃은 떨어지되',30397),
('1pe-1-25','1pe','베드로전서',1,25,'오직 주의 말씀은 세세토록 있도다 하였으니 너희에게 전한 복음이 곧 이 말씀이니라',30398),
('1pe-2-1','1pe','베드로전서',2,1,'그러므로 모든 악독과 모든 기만과 외식과 시기와 모든 비방하는 말을 버리고',30399),
('1pe-2-2','1pe','베드로전서',2,2,'갓난 아기들 같이 순전하고 신령한 젖을 사모하라 이는 그로 말미암아 너희로 구원에 이르도록 자라게 하려 함이라',30400),
('1pe-2-3','1pe','베드로전서',2,3,'너희가 주의 인자하심을 맛보았으면 그리하라',30401),
('1pe-2-4','1pe','베드로전서',2,4,'사람에게는 버린 바가 되었으나 하나님께는 택하심을 입은 보배로운 산 돌이신 예수께 나아가',30402),
('1pe-2-5','1pe','베드로전서',2,5,'너희도 산 돌 같이 신령한 집으로 세워지고 예수 그리스도로 말미암아 하나님이 기쁘게 받으실 신령한 제사를 드릴 거룩한 제사장이 될지니라',30403),
('1pe-2-6','1pe','베드로전서',2,6,'성경에 기록되었으되 보라 내가 택한 보배로운 모퉁잇돌을 시온에 두노니 그를 믿는 자는 부끄러움을 당하지 아니하리라 하였으니',30404),
('1pe-2-7','1pe','베드로전서',2,7,'그러므로 믿는 너희에게는 보배이나 믿지 아니하는 자에게는 건축자들이 버린 그 돌이 모퉁이의 머릿돌이 되고',30405),
('1pe-2-8','1pe','베드로전서',2,8,'또한 부딪치는 돌과 걸려 넘어지게 하는 바위가 되었다 하였느니라 그들이 말씀을 순종하지 아니하므로 넘어지나니 이는 그들을 이렇게 정하신 것이라',30406),
