('1pe-2-10','1pe','베드로전서',2,10,'너희가 전에는 백성이 아니더니 이제는 하나님의 백성이요 전에는 긍휼을 얻지 못하였더니 이제는 긍휼을 얻은 자니라',30408),
('1pe-2-11','1pe','베드로전서',2,11,'사랑하는 자들아 거류민과 나그네 같은 너희를 권하노니 영혼을 거슬러 싸우는 육체의 정욕을 제어하라',30409),
