('1pe-5-9','1pe','베드로전서',5,9,'너희는 믿음을 굳건하게 하여 그를 대적하라 이는 세상에 있는 너희 형제들도 동일한 고난을 당하는 줄을 앎이라',30473),
('1pe-5-10','1pe','베드로전서',5,10,'모든 은혜의 하나님 곧 그리스도 안에서 너희를 부르사 자기의 영원한 영광에 들어가게 하신 이가 잠깐 고난을 당한 너희를 친히 온전하게 하시며 굳건하게 하시며 강하게 하시며 터를 견고하게 하시리라',30474),
('1pe-5-11','1pe','베드로전서',5,11,'권능이 세세무궁하도록 그에게 있을지어다 아멘',30475),
('1pe-5-12','1pe','베드로전서',5,12,'내가 신실한 형제로 아는 실루아노로 말미암아 너희에게 간단히 써서 권하고 이것이 하나님의 참된 은혜임을 증언하노니 너희는 이 은혜에 굳게 서라',30476),
('1pe-5-13','1pe','베드로전서',5,13,'택하심을 함께 받은 바벨론에 있는 교회가 너희에게 문안하고 내 아들 마가도 그리하느니라',30477),
('1pe-5-14','1pe','베드로전서',5,14,'너희는 사랑의 입맞춤으로 서로 문안하라 그리스도 안에 있는 너희 모든 이에게 평강이 있을지어다              ',30478),
('2pe-1-1','2pe','베드로후서',1,1,'예수 그리스도의 종이며 사도인 시몬 베드로는 우리 하나님과 구주 예수 그리스도의 의를 힘입어 동일하게 보배로운 믿음을 우리와 함께 받은 자들에게 편지하노니',30479),
('2pe-1-2','2pe','베드로후서',1,2,'하나님과 우리 주 예수를 앎으로 은혜와 평강이 너희에게 더욱 많을지어다',30480),
('2pe-1-3','2pe','베드로후서',1,3,'그의 신기한 능력으로 생명과 경건에 속한 모든 것을 우리에게 주셨으니 이는 자기의 영광과 덕으로써 우리를 부르신 이를 앎으로 말미암음이라',30481),
('2pe-1-4','2pe','베드로후서',1,4,'이로써 그 보배롭고 지극히 큰 약속을 우리에게 주사 이 약속으로 말미암아 너희가 정욕 때문에 세상에서 썩어질 것을 피하여 신성한 성품에 참여하는 자가 되게 하려 하셨느니라',30482),
('2pe-1-5','2pe','베드로후서',1,5,'그러므로 너희가 더욱 힘써 너희 믿음에 덕을, 덕에 지식을,',30483),
('2pe-1-6','2pe','베드로후서',1,6,'지식에 절제를, 절제에 인내를, 인내에 경건을,',30484),
('2pe-1-7','2pe','베드로후서',1,7,'경건에 형제 우애를, 형제 우애에 사랑을 더하라',30485),
('2pe-1-8','2pe','베드로후서',1,8,'이런 것이 너희에게 있어 흡족한즉 너희로 우리 주 예수 그리스도를 알기에 게으르지 않고 열매 없는 자가 되지 않게 하려니와',30486),
('2pe-1-9','2pe','베드로후서',1,9,'이런 것이 없는 자는 맹인이라 멀리 보지 못하고 그의 옛 죄가 깨끗하게 된 것을 잊었느니라',30487),
('2pe-1-10','2pe','베드로후서',1,10,'그러므로 형제들아 더욱 힘써 너희 부르심과 택하심을 굳게 하라 너희가 이것을 행한즉 언제든지 실족하지 아니하리라',30488),
('2pe-1-11','2pe','베드로후서',1,11,'이같이 하면 우리 주 곧 구주 예수 그리스도의 영원한 나라에 들어감을 넉넉히 너희에게 주시리라',30489),
('2pe-1-12','2pe','베드로후서',1,12,'그러므로 너희가 이것을 알고 이미 있는 진리에 서 있으나 내가 항상 너희에게 생각나게 하려 하노라',30490),
('2pe-1-13','2pe','베드로후서',1,13,'내가 이 장막에 있을 동안에 너희를 일깨워 생각나게 함이 옳은 줄로 여기노니',30491),
('2pe-1-14','2pe','베드로후서',1,14,'이는 우리 주 예수 그리스도께서 내게 지시하신 것 같이 나도 나의 장막을 벗어날 것이 임박한 줄을 앎이라',30492),
('2pe-1-15','2pe','베드로후서',1,15,'내가 힘써 너희로 하여금 내가 떠난 후에라도 어느 때나 이런 것을 생각나게 하려 하노라',30493),
('2pe-1-16','2pe','베드로후서',1,16,'우리 주 예수 그리스도의 능력과 강림하심을 너희에게 알게 한 것이 교묘히 만든 이야기를 따른 것이 아니요 우리는 그의 크신 위엄을 친히 본 자라',30494),
('2pe-1-17','2pe','베드로후서',1,17,'지극히 큰 영광 중에서 이러한 소리가 그에게 나기를 이는 내 사랑하는 아들이요 내 기뻐하는 자라 하실 때에 그가 하나님 아버지께 존귀와 영광을 받으셨느니라',30495),
('2pe-1-18','2pe','베드로후서',1,18,'이 소리는 우리가 그와 함께 거룩한 산에 있을 때에 하늘로부터 난 것을 들은 것이라',30496),
('2pe-1-19','2pe','베드로후서',1,19,'또 우리에게는 더 확실한 예언이 있어 어두운 데를 비추는 등불과 같으니 날이 새어 샛별이 너희 마음에 떠오르기까지 너희가 이것을 주의하는 것이 옳으니라',30497),
('2pe-1-20','2pe','베드로후서',1,20,'먼저 알 것은 성경의 모든 예언은 사사로이 풀 것이 아니니',30498),
('2pe-1-21','2pe','베드로후서',1,21,'예언은 언제든지 사람의 뜻으로 낸 것이 아니요 오직 성령의 감동하심을 받은 사람들이 하나님께 받아 말한 것임이라',30499),
('2pe-2-1','2pe','베드로후서',2,1,'그러나 백성 가운데 또한 거짓 선지자들이 일어났었나니 이와 같이 너희 중에도 거짓 선생들이 있으리라 그들은 멸망하게 할 이단을 가만히 끌어들여 자기들을 사신 주를 부인하고 임박한 멸망을 스스로 취하는 자들이라',30500),
('2pe-2-2','2pe','베드로후서',2,2,'여럿이 그들의 호색하는 것을 따르리니 이로 말미암아 진리의 도가 비방을 받을 것이요',30501),
('2pe-2-3','2pe','베드로후서',2,3,'그들이 탐심으로써 지어낸 말을 가지고 너희로 이득을 삼으니 그들의 심판은 옛적부터 지체하지 아니하며 그들의 멸망은 잠들지 아니하느니라',30502),
('2pe-2-4','2pe','베드로후서',2,4,'하나님이 범죄한 천사들을 용서하지 아니하시고 지옥에 던져 어두운 구덩이에 두어 심판 때까지 지키게 하셨으며',30503),
('2pe-2-5','2pe','베드로후서',2,5,'옛 세상을 용서하지 아니하시고 오직 의를 전파하는 노아와 그 일곱 식구를 보존하시고 경건하지 아니한 자들의 세상에 홍수를 내리셨으며',30504),
('2pe-2-6','2pe','베드로후서',2,6,'소돔과 고모라 성을 멸망하기로 정하여 재가 되게 하사 후세에 경건하지 아니할 자들에게 본을 삼으셨으며',30505),
('2pe-2-7','2pe','베드로후서',2,7,'무법한 자들의 음란한 행실로 말미암아 고통 당하는 의로운 롯을 건지셨으니',30506),
('2pe-2-8','2pe','베드로후서',2,8,'(이는 이 의인이 그들 중에 거하여 날마다 저 불법한 행실을 보고 들음으로 그 의로운 심령이 상함이라)',30507),
('2pe-2-9','2pe','베드로후서',2,9,'주께서 경건한 자는 시험에서 건지실 줄 아시고 불의한 자는 형벌 아래에 두어 심판 날까지 지키시며',30508),
('2pe-2-10','2pe','베드로후서',2,10,'특별히 육체를 따라 더러운 정욕 가운데서 행하며 주관하는 이를 멸시하는 자들에게는 형벌할 줄 아시느니라 이들은 당돌하고 자긍하며 떨지 않고 영광 있는 자들을 비방하거니와',30509),
('2pe-2-11','2pe','베드로후서',2,11,'더 큰 힘과 능력을 가진 천사들도 주 앞에서 그들을 거슬러 비방하는 고발을 하지 아니하느니라',30510),
('2pe-2-12','2pe','베드로후서',2,12,'그러나 이 사람들은 본래 잡혀 죽기 위하여 난 이성 없는 짐승 같아서 그 알지 못하는 것을 비방하고 그들의 멸망 가운데서 멸망을 당하며',30511),
('2pe-2-13','2pe','베드로후서',2,13,'불의의 값으로 불의를 당하며 낮에 즐기고 노는 것을 기쁘게 여기는 자들이니 점과 흠이라 너희와 함께 연회할 때에 그들의 속임수로 즐기고 놀며',30512),
('2pe-2-14','2pe','베드로후서',2,14,'음심이 가득한 눈을 가지고 범죄하기를 그치지 아니하고 굳세지 못한 영혼들을 유혹하며 탐욕에 연단된 마음을 가진 자들이니 저주의 자식이라',30513),
('2pe-2-15','2pe','베드로후서',2,15,'그들이 바른 길을 떠나 미혹되어 브올의 아들 발람의 길을 따르는도다 그는 불의의 삯을 사랑하다가',30514),
('2pe-2-16','2pe','베드로후서',2,16,'자기의 불법으로 말미암아 책망을 받되 말하지 못하는 나귀가 사람의 소리로 말하여 이 선지자의 미친 행동을 저지하였느니라',30515),
('2pe-2-17','2pe','베드로후서',2,17,'이 사람들은 물 없는 샘이요 광풍에 밀려 가는 안개니 그들을 위하여 캄캄한 어둠이 예비되어 있나니',30516),
('2pe-2-18','2pe','베드로후서',2,18,'그들이 허탄한 자랑의 말을 토하며 그릇되게 행하는 사람들에게서 겨우 피한 자들을 음란으로써 육체의 정욕 중에서 유혹하는도다',30517),
('2pe-2-19','2pe','베드로후서',2,19,'그들에게 자유를 준다 하여도 자신들은 멸망의 종들이니 누구든지 진 자는 이긴 자의 종이 됨이라',30518),
('2pe-2-20','2pe','베드로후서',2,20,'만일 그들이 우리 주 되신 구주 예수 그리스도를 앎으로 세상의 더러움을 피한 후에 다시 그 중에 얽매이고 지면 그 나중 형편이 처음보다 더 심하리니',30519),
('2pe-2-21','2pe','베드로후서',2,21,'의의 도를 안 후에 받은 거룩한 명령을 저버리는 것보다 알지 못하는 것이 도리어 그들에게 나으니라',30520),
('2pe-2-22','2pe','베드로후서',2,22,'참된 속담에 이르기를 개가 그 토하였던 것에 돌아가고 돼지가 씻었다가 더러운 구덩이에 도로 누웠다 하는 말이 그들에게 응하였도다',30521),
('2pe-3-1','2pe','베드로후서',3,1,'사랑하는 자들아 내가 이제 이 둘째 편지를 너희에게 쓰노니 이 두 편지로 너희의 진실한 마음을 일깨워 생각나게 하여',30522),
('2pe-3-2','2pe','베드로후서',3,2,'곧 거룩한 선지자들이 예언한 말씀과 주 되신 구주께서 너희의 사도들로 말미암아 명하신 것을 기억하게 하려 하노라',30523),
('2pe-3-3','2pe','베드로후서',3,3,'먼저 이것을 알지니 말세에 조롱하는 자들이 와서 자기의 정욕을 따라 행하며 조롱하여',30524),
('2pe-3-4','2pe','베드로후서',3,4,'이르되 주께서 강림하신다는 약속이 어디 있느냐 조상들이 잔 후로부터 만물이 처음 창조될 때와 같이 그냥 있다 하니',30525),
('2pe-3-5','2pe','베드로후서',3,5,'이는 하늘이 옛적부터 있는 것과 땅이 물에서 나와 물로 성립된 것도 하나님의 말씀으로 된 것을 그들이 일부러 잊으려 함이로다',30526),
('2pe-3-6','2pe','베드로후서',3,6,'이로 말미암아 그 때에 세상은 물이 넘침으로 멸망하였으되',30527),
('2pe-3-7','2pe','베드로후서',3,7,'이제 하늘과 땅은 그 동일한 말씀으로 불사르기 위하여 보호하신 바 되어 경건하지 아니한 사람들의 심판과 멸망의 날까지 보존하여 두신 것이니라',30528),
('2pe-3-8','2pe','베드로후서',3,8,'사랑하는 자들아 주께는 하루가 천 년 같고 천 년이 하루 같다는 이 한 가지를 잊지 말라',30529),
('2pe-3-9','2pe','베드로후서',3,9,'주의 약속은 어떤 이들이 더디다고 생각하는 것 같이 더딘 것이 아니라 오직 주께서는 너희를 대하여 오래 참으사 아무도 멸망하지 아니하고 다 회개하기에 이르기를 원하시느니라',30530),
('2pe-3-10','2pe','베드로후서',3,10,'그러나 주의 날이 도둑 같이 오리니 그 날에는 하늘이 큰 소리로 떠나가고 물질이 뜨거운 불에 풀어지고 땅과 그 중에 있는 모든 일이 드러나리로다',30531),
('2pe-3-11','2pe','베드로후서',3,11,'이 모든 것이 이렇게 풀어지리니 너희가 어떠한 사람이 되어야 마땅하냐 거룩한 행실과 경건함으로',30532),
('2pe-3-12','2pe','베드로후서',3,12,'하나님의 날이 임하기를 바라보고 간절히 사모하라 그 날에 하늘이 불에 타서 풀어지고 물질이 뜨거운 불에 녹아지려니와',30533),
('2pe-3-13','2pe','베드로후서',3,13,'우리는 그의 약속대로 의가 있는 곳인 새 하늘과 새 땅을 바라보도다',30534),
('2pe-3-14','2pe','베드로후서',3,14,'그러므로 사랑하는 자들아 너희가 이것을 바라보나니 주 앞에서 점도 없고 흠도 없이 평강 가운데서 나타나기를 힘쓰라',30535),
('2pe-3-15','2pe','베드로후서',3,15,'또 우리 주의 오래 참으심이 구원이 될 줄로 여기라 우리가 사랑하는 형제 바울도 그 받은 지혜대로 너희에게 이같이 썼고',30536),
('2pe-3-16','2pe','베드로후서',3,16,'또 그 모든 편지에도 이런 일에 관하여 말하였으되 그 중에 알기 어려운 것이 더러 있으니 무식한 자들과 굳세지 못한 자들이 다른 성경과 같이 그것도 억지로 풀다가 스스로 멸망에 이르느니라',30537),
('2pe-3-17','2pe','베드로후서',3,17,'그러므로 사랑하는 자들아 너희가 이것을 미리 알았은즉 무법한 자들의 미혹에 이끌려 너희가 굳센 데서 떨어질까 삼가라',30538),
('2pe-3-18','2pe','베드로후서',3,18,'오직 우리 주 곧 구주 예수 그리스도의 은혜와 그를 아는 지식에서 자라 가라 영광이 이제와 영원한 날까지 그에게 있을지어다3)',30539),
('1jn-1-1','1jn','요한일서',1,1,'태초부터 있는 생명의 말씀에 관하여는 우리가 들은 바요 눈으로 본 바요 자세히 보고 우리의 손으로 만진 바라',30540),
('1jn-1-2','1jn','요한일서',1,2,'이 생명이 나타내신 바 된지라 이 영원한 생명을 우리가 보았고 증언하여 너희에게 전하노니 이는 아버지와 함께 계시다가 우리에게 나타내신 바 된 이시니라',30541),
('1jn-1-3','1jn','요한일서',1,3,'우리가 보고 들은 바를 너희에게도 전함은 너희로 우리와 사귐이 있게 하려 함이니 우리의 사귐은 아버지와 그의 아들 예수 그리스도와 더불어 누림이라',30542),
('1jn-1-4','1jn','요한일서',1,4,'우리가 이것을 씀은 우리의 기쁨이 충만하게 하려 함이라',30543),
('1jn-1-5','1jn','요한일서',1,5,'우리가 그에게서 듣고 너희에게 전하는 소식은 이것이니 곧 하나님은 빛이시라 그에게는 어둠이 조금도 없으시다는 것이니라',30544),
('1jn-1-6','1jn','요한일서',1,6,'만일 우리가 하나님과 사귐이 있다 하고 어둠에 행하면 거짓말을 하고 진리를 행하지 아니함이거니와',30545),
('1jn-1-7','1jn','요한일서',1,7,'그가 빛 가운데 계신 것 같이 우리도 빛 가운데 행하면 우리가 서로 사귐이 있고 그 아들 예수의 피가 우리를 모든 죄에서 깨끗하게 하실 것이요',30546),
('1jn-1-8','1jn','요한일서',1,8,'만일 우리가 죄가 없다고 말하면 스스로 속이고 또 진리가 우리 속에 있지 아니할 것이요',30547),
('1jn-1-9','1jn','요한일서',1,9,'만일 우리가 우리 죄를 자백하면 그는 미쁘시고 의로우사 우리 죄를 사하시며 우리를 모든 불의에서 깨끗하게 하실 것이요',30548),
('1jn-1-10','1jn','요한일서',1,10,'만일 우리가 범죄하지 아니하였다 하면 하나님을 거짓말하는 이로 만드는 것이니 또한 그의 말씀이 우리 속에 있지 아니하니라',30549),
('1jn-2-1','1jn','요한일서',2,1,'나의 자녀들아 내가 이것을 너희에게 씀은 너희로 죄를 범하지 않게 하려 함이라 만일 누가 죄를 범하여도 아버지 앞에서 우리에게 대언자가 있으니 곧 의로우신 예수 그리스도시라',30550),
('1jn-2-2','1jn','요한일서',2,2,'그는 우리 죄를 위한 화목 제물이니 우리만 위할 뿐 아니요 온 세상의 죄를 위하심이라',30551),
('1jn-2-3','1jn','요한일서',2,3,'우리가 그의 계명을 지키면 이로써 우리가 그를 아는 줄로 알 것이요',30552),
('1jn-2-4','1jn','요한일서',2,4,'그를 아노라 하고 그의 계명을 지키지 아니하는 자는 거짓말하는 자요 진리가 그 속에 있지 아니하되',30553),
('1jn-2-5','1jn','요한일서',2,5,'누구든지 그의 말씀을 지키는 자는 하나님의 사랑이 참으로 그 속에서 온전하게 되었나니 이로써 우리가 그의 안에 있는 줄을 아노라',30554),
('1jn-2-6','1jn','요한일서',2,6,'그의 안에 산다고 하는 자는 그가 행하시는 대로 자기도 행할지니라',30555),
('1jn-2-7','1jn','요한일서',2,7,'사랑하는 자들아 내가 새 계명을 너희에게 쓰는 것이 아니라 너희가 처음부터 가진 옛 계명이니 이 옛 계명은 너희가 들은 바 말씀이거니와',30556),
('1jn-2-8','1jn','요한일서',2,8,'다시 내가 너희에게 새 계명을 쓰노니 그에게와 너희에게도 참된 것이라 이는 어둠이 지나가고 참빛이 벌써 비침이니라',30557),
('1jn-2-9','1jn','요한일서',2,9,'빛 가운데 있다 하면서 그 형제를 미워하는 자는 지금까지 어둠에 있는 자요',30558),
('1jn-2-10','1jn','요한일서',2,10,'그의 형제를 사랑하는 자는 빛 가운데 거하여 자기 속에 거리낌이 없으나',30559),
('1jn-2-11','1jn','요한일서',2,11,'그의 형제를 미워하는 자는 어둠에 있고 또 어둠에 행하며 갈 곳을 알지 못하나니 이는 그 어둠이 그의 눈을 멀게 하였음이라',30560),
('1jn-2-12','1jn','요한일서',2,12,'자녀들아 내가 너희에게 쓰는 것은 너희 죄가 그의 이름으로 말미암아 사함을 받았음이요',30561),
('1jn-2-13','1jn','요한일서',2,13,'아비들아 내가 너희에게 쓰는 것은 너희가 태초부터 계신 이를 알았음이요 청년들아 내가 너희에게 쓰는 것은 너희가 악한 자를 이기었음이라',30562),
('1jn-2-14','1jn','요한일서',2,14,'아이들아 내가 너희에게 쓴 것은 너희가 아버지를 알았음이요 아비들아 내가 너희에게 쓴 것은 너희가 태초부터 계신 이를 알았음이요 청년들아 내가 너희에게 쓴 것은 너희가 강하고 하나님의 말씀이 너희 안에 거하시며 너희가 흉악한 자를 이기었음이라',30563),
('1jn-2-15','1jn','요한일서',2,15,'이 세상이나 세상에 있는 것들을 사랑하지 말라 누구든지 세상을 사랑하면 아버지의 사랑이 그 안에 있지 아니하니',30564),
('1jn-2-16','1jn','요한일서',2,16,'이는 세상에 있는 모든 것이 육신의 정욕과 안목의 정욕과 이생의 자랑이니 다 아버지께로부터 온 것이 아니요 세상으로부터 온 것이라',30565),
('1jn-2-17','1jn','요한일서',2,17,'이 세상도, 그 정욕도 지나가되 오직 하나님의 뜻을 행하는 자는 영원히 거하느니라',30566),
('1jn-2-18','1jn','요한일서',2,18,'아이들아 지금은 마지막 때라 적그리스도가 오리라는 말을 너희가 들은 것과 같이 지금도 많은 적그리스도가 일어났으니 그러므로 우리가 마지막 때인 줄 아노라',30567),
('1jn-2-19','1jn','요한일서',2,19,'그들이 우리에게서 나갔으나 우리에게 속하지 아니하였나니 만일 우리에게 속하였더라면 우리와 함께 거하였으려니와 그들이 나간 것은 다 우리에게 속하지 아니함을 나타내려 함이니라',30568),
('1jn-2-20','1jn','요한일서',2,20,'너희는 거룩하신 자에게서 기름 부음을 받고 모든 것을 아느니라',30569),
('1jn-2-21','1jn','요한일서',2,21,'내가 너희에게 쓰는 것은 너희가 진리를 알지 못하기 때문이 아니라 알기 때문이요 또 모든 거짓은 진리에서 나지 않기 때문이라',30570),
('1jn-2-22','1jn','요한일서',2,22,'거짓말하는 자가 누구냐 예수께서 그리스도이심을 부인하는 자가 아니냐 아버지와 아들을 부인하는 그가 적그리스도니',30571),
('1jn-2-23','1jn','요한일서',2,23,'아들을 부인하는 자에게는 또한 아버지가 없으되 아들을 시인하는 자에게는 아버지도 있느니라',30572),
('1jn-2-24','1jn','요한일서',2,24,'너희는 처음부터 들은 것을 너희 안에 거하게 하라 처음부터 들은 것이 너희 안에 거하면 너희가 아들과 아버지 안에 거하리라',30573),
('1jn-2-25','1jn','요한일서',2,25,'그가 우리에게 약속하신 것은 이것이니 곧 영원한 생명이니라',30574),
('1jn-2-26','1jn','요한일서',2,26,'너희를 미혹하는 자들에 관하여 내가 이것을 너희에게 썼노라',30575),
('1jn-2-27','1jn','요한일서',2,27,'너희는 주께 받은 바 기름 부음이 너희 안에 거하나니 아무도 너희를 가르칠 필요가 없고 오직 그의 기름 부음이 모든 것을 너희에게 가르치며 또 참되고 거짓이 없으니 너희를 가르치신 그대로 주 안에 거하라',30576),
('1jn-2-28','1jn','요한일서',2,28,'자녀들아 이제 그의 안에 거하라 이는 주께서 나타내신 바 되면 그가 강림하실 때에 우리로 담대함을 얻어 그 앞에서 부끄럽지 않게 하려 함이라',30577),
('1jn-2-29','1jn','요한일서',2,29,'너희가 그가 의로우신 줄을 알면 의를 행하는 자마다 그에게서 난 줄을 알리라',30578),
('1jn-3-1','1jn','요한일서',3,1,'보라 아버지께서 어떠한 사랑을 우리에게 베푸사 하나님의 자녀라 일컬음을 받게 하셨는가, 우리가 그러하도다 그러므로 세상이 우리를 알지 못함은 그를 알지 못함이라',30579),
('1jn-3-2','1jn','요한일서',3,2,'사랑하는 자들아 우리가 지금은 하나님의 자녀라 장래에 어떻게 될지는 아직 나타나지 아니하였으나 그가 나타나시면 우리가 그와 같을 줄을 아는 것은 그의 참모습 그대로 볼 것이기 때문이니',30580),
('1jn-3-3','1jn','요한일서',3,3,'주를 향하여 이 소망을 가진 자마다 그의 깨끗하심과 같이 자기를 깨끗하게 하느니라',30581),
('1jn-3-4','1jn','요한일서',3,4,'죄를 짓는 자마다 불법을 행하나니 죄는 불법이라',30582),
('1jn-3-5','1jn','요한일서',3,5,'그가 우리 죄를 없애려고 나타나신 것을 너희가 아나니 그에게는 죄가 없느니라',30583),
('1jn-3-6','1jn','요한일서',3,6,'그 안에 거하는 자마다 범죄하지 아니하나니 범죄하는 자마다 그를 보지도 못하였고 그를 알지도 못하였느니라',30584),
('1jn-3-7','1jn','요한일서',3,7,'자녀들아 아무도 너희를 미혹하지 못하게 하라 의를 행하는 자는 그의 의로우심과 같이 의롭고',30585),
('1jn-3-8','1jn','요한일서',3,8,'죄를 짓는 자는 마귀에게 속하나니 마귀는 처음부터 범죄함이라 하나님의 아들이 나타나신 것은 마귀의 일을 멸하려 하심이라',30586),
('1jn-3-9','1jn','요한일서',3,9,'하나님께로부터 난 자마다 죄를 짓지 아니하나니 이는 하나님의 씨가 그의 속에 거함이요 그도 범죄하지 못하는 것은 하나님께로부터 났음이라',30587),
('1jn-3-10','1jn','요한일서',3,10,'이러므로 하나님의 자녀들과 마귀의 자녀들이 드러나나니 무릇 의를 행하지 아니하는 자나 또는 그 형제를 사랑하지 아니하는 자는 하나님께 속하지 아니하니라',30588),
('1jn-3-11','1jn','요한일서',3,11,'우리는 서로 사랑할지니 이는 너희가 처음부터 들은 소식이라',30589),
('1jn-3-12','1jn','요한일서',3,12,'가인 같이 하지 말라 그는 악한 자에게 속하여 그 아우를 죽였으니 어떤 이유로 죽였느냐 자기의 행위는 악하고 그의 아우의 행위는 의로움이라',30590),
('1jn-3-13','1jn','요한일서',3,13,'형제들아 세상이 너희를 미워하여도 이상히 여기지 말라',30591),
('1jn-3-14','1jn','요한일서',3,14,'우리는 형제를 사랑함으로 사망에서 옮겨 생명으로 들어간 줄을 알거니와 사랑하지 아니하는 자는 사망에 머물러 있느니라',30592),
('1jn-3-15','1jn','요한일서',3,15,'그 형제를 미워하는 자마다 살인하는 자니 살인하는 자마다 영생이 그 속에 거하지 아니하는 것을 너희가 아는 바라',30593),
('1jn-3-16','1jn','요한일서',3,16,'그가 우리를 위하여 목숨을 버리셨으니 우리가 이로써 사랑을 알고 우리도 형제들을 위하여 목숨을 버리는 것이 마땅하니라',30594),
('1jn-3-17','1jn','요한일서',3,17,'누가 이 세상의 재물을 가지고 형제의 궁핍함을 보고도 도와 줄 마음을 닫으면 하나님의 사랑이 어찌 그 속에 거하겠느냐',30595),
('1jn-3-18','1jn','요한일서',3,18,'자녀들아 우리가 말과 혀로만 사랑하지 말고 행함과 진실함으로 하자',30596),
('1jn-3-19','1jn','요한일서',3,19,'이로써 우리가 진리에 속한 줄을 알고 또 우리 마음을 주 앞에서 굳세게 하리니',30597),
('1jn-3-20','1jn','요한일서',3,20,'이는 우리 마음이 혹 우리를 책망할 일이 있어도 하나님은 우리 마음보다 크시고 모든 것을 아시기 때문이라',30598),
('1jn-3-21','1jn','요한일서',3,21,'사랑하는 자들아 만일 우리 마음이 우리를 책망할 것이 없으면 하나님 앞에서 담대함을 얻고',30599),
('1jn-3-22','1jn','요한일서',3,22,'무엇이든지 구하는 바를 그에게서 받나니 이는 우리가 그의 계명을 지키고 그 앞에서 기뻐하시는 것을 행함이라',30600),
('1jn-3-23','1jn','요한일서',3,23,'그의 계명은 이것이니 곧 그 아들 예수 그리스도의 이름을 믿고 그가 우리에게 주신 계명대로 서로 사랑할 것이니라',30601),
('1jn-3-24','1jn','요한일서',3,24,'그의 계명을 지키는 자는 주 안에 거하고 주는 그의 안에 거하시나니 우리에게 주신 성령으로 말미암아 그가 우리 안에 거하시는 줄을 우리가 아느니라',30602),
('1jn-4-1','1jn','요한일서',4,1,'사랑하는 자들아 영을 다 믿지 말고 오직 영들이 하나님께 속하였나 분별하라 많은 거짓 선지자가 세상에 나왔음이라',30603),
('1jn-4-2','1jn','요한일서',4,2,'이로써 너희가 하나님의 영을 알지니 곧 예수 그리스도께서 육체로 오신 것을 시인하는 영마다 하나님께 속한 것이요',30604),
('1jn-4-3','1jn','요한일서',4,3,'예수를 시인하지 아니하는 영마다 하나님께 속한 것이 아니니 이것이 곧 적그리스도의 영이니라 오리라 한 말을 너희가 들었거니와 지금 벌써 세상에 있느니라',30605),
('1jn-4-4','1jn','요한일서',4,4,'자녀들아 너희는 하나님께 속하였고 또 그들을 이기었나니 이는 너희 안에 계신 이가 세상에 있는 자보다 크심이라',30606),
('1jn-4-5','1jn','요한일서',4,5,'그들은 세상에 속한 고로 세상에 속한 말을 하매 세상이 그들의 말을 듣느니라',30607),
('1jn-4-6','1jn','요한일서',4,6,'우리는 하나님께 속하였으니 하나님을 아는 자는 우리의 말을 듣고 하나님께 속하지 아니한 자는 우리의 말을 듣지 아니하나니 진리의 영과 미혹의 영을 이로써 아느니라',30608),
('1jn-4-7','1jn','요한일서',4,7,'사랑하는 자들아 우리가 서로 사랑하자 사랑은 하나님께 속한 것이니 사랑하는 자마다 하나님으로부터 나서 하나님을 알고',30609),
('1jn-4-8','1jn','요한일서',4,8,'사랑하지 아니하는 자는 하나님을 알지 못하나니 이는 하나님은 사랑이심이라',30610),
('1jn-4-9','1jn','요한일서',4,9,'하나님의 사랑이 우리에게 이렇게 나타난 바 되었으니 하나님이 자기의 독생자를 세상에 보내심은 그로 말미암아 우리를 살리려 하심이라',30611),
('1jn-4-10','1jn','요한일서',4,10,'사랑은 여기 있으니 우리가 하나님을 사랑한 것이 아니요 하나님이 우리를 사랑하사 우리 죄를 속하기 위하여 화목 제물로 그 아들을 보내셨음이라',30612),
('1jn-4-11','1jn','요한일서',4,11,'사랑하는 자들아 하나님이 이같이 우리를 사랑하셨은즉 우리도 서로 사랑하는 것이 마땅하도다',30613),
('1jn-4-12','1jn','요한일서',4,12,'어느 때나 하나님을 본 사람이 없으되 만일 우리가 서로 사랑하면 하나님이 우리 안에 거하시고 그의 사랑이 우리 안에 온전히 이루어지느니라',30614),
('1jn-4-13','1jn','요한일서',4,13,'그의 성령을 우리에게 주시므로 우리가 그 안에 거하고 그가 우리 안에 거하시는 줄을 아느니라',30615),
('1jn-4-14','1jn','요한일서',4,14,'아버지가 아들을 세상의 구주로 보내신 것을 우리가 보았고 또 증언하노니',30616),
('1jn-4-15','1jn','요한일서',4,15,'누구든지 예수를 하나님의 아들이라 시인하면 하나님이 그의 안에 거하시고 그도 하나님 안에 거하느니라',30617),
('1jn-4-16','1jn','요한일서',4,16,'하나님이 우리를 사랑하시는 사랑을 우리가 알고 믿었노니 하나님은 사랑이시라 사랑 안에 거하는 자는 하나님 안에 거하고 하나님도 그의 안에 거하시느니라',30618),
('1jn-4-17','1jn','요한일서',4,17,'이로써 사랑이 우리에게 온전히 이루어진 것은 우리로 심판 날에 담대함을 가지게 하려 함이니 주께서 그러하심과 같이 우리도 이 세상에서 그러하니라',30619),
('1jn-4-18','1jn','요한일서',4,18,'사랑 안에 두려움이 없고 온전한 사랑이 두려움을 내쫓나니 두려움에는 형벌이 있음이라 두려워하는 자는 사랑 안에서 온전히 이루지 못하였느니라',30620),
('1jn-4-19','1jn','요한일서',4,19,'우리가 사랑함은 그가 먼저 우리를 사랑하셨음이라',30621),
('1jn-4-20','1jn','요한일서',4,20,'누구든지 하나님을 사랑하노라 하고 그 형제를 미워하면 이는 거짓말하는 자니 보는 바 그 형제를 사랑하지 아니하는 자는 보지 못하는 바 하나님을 사랑할 수 없느니라',30622),
('1jn-4-21','1jn','요한일서',4,21,'우리가 이 계명을 주께 받았나니 하나님을 사랑하는 자는 또한 그 형제를 사랑할지니라',30623),
('1jn-5-1','1jn','요한일서',5,1,'예수께서 그리스도이심을 믿는 자마다 하나님께로부터 난 자니 또한 낳으신 이를 사랑하는 자마다 그에게서 난 자를 사랑하느니라',30624),
('1jn-5-2','1jn','요한일서',5,2,'우리가 하나님을 사랑하고 그의 계명들을 지킬 때에 이로써 우리가 하나님의 자녀를 사랑하는 줄을 아느니라',30625),
('1jn-5-3','1jn','요한일서',5,3,'하나님을 사랑하는 것은 이것이니 우리가 그의 계명들을 지키는 것이라 그의 계명들은 무거운 것이 아니로다',30626),
('1jn-5-4','1jn','요한일서',5,4,'무릇 하나님께로부터 난 자마다 세상을 이기느니라 세상을 이기는 승리는 이것이니 우리의 믿음이니라',30627),
('1jn-5-5','1jn','요한일서',5,5,'예수께서 하나님의 아들이심을 믿는 자가 아니면 세상을 이기는 자가 누구냐',30628),
('1jn-5-6','1jn','요한일서',5,6,'이는 물과 피로 임하신 이시니 곧 예수 그리스도시라 물로만 아니요 물과 피로 임하셨고 증언하는 이는 성령이시니 성령은 진리니라',30629),
('1jn-5-7','1jn','요한일서',5,7,'증언하는 이가 셋이니',30630),
('1jn-5-8','1jn','요한일서',5,8,'성령과 물과 피라 또한 이 셋은 합하여 하나이니라',30631),
('1jn-5-9','1jn','요한일서',5,9,'만일 우리가 사람들의 증언을 받을진대 하나님의 증거는 더욱 크도다 하나님의 증거는 이것이니 그의 아들에 대하여 증언하신 것이니라',30632),
('1jn-5-10','1jn','요한일서',5,10,'하나님의 아들을 믿는 자는 자기 안에 증거가 있고 하나님을 믿지 아니하는 자는 하나님을 거짓말하는 자로 만드나니 이는 하나님께서 그 아들에 대하여 증언하신 증거를 믿지 아니하였음이라',30633),
('1jn-5-11','1jn','요한일서',5,11,'또 증거는 이것이니 하나님이 우리에게 영생을 주신 것과 이 생명이 그의 아들 안에 있는 그것이니라',30634),
('1jn-5-12','1jn','요한일서',5,12,'아들이 있는 자에게는 생명이 있고 하나님의 아들이 없는 자에게는 생명이 없느니라',30635),
('1jn-5-13','1jn','요한일서',5,13,'내가 하나님의 아들의 이름을 믿는 너희에게 이것을 쓰는 것은 너희로 하여금 너희에게 영생이 있음을 알게 하려 함이라',30636),
('1jn-5-14','1jn','요한일서',5,14,'그를 향하여 우리가 가진 바 담대함이 이것이니 그의 뜻대로 무엇을 구하면 들으심이라',30637),
('1jn-5-15','1jn','요한일서',5,15,'우리가 무엇이든지 구하는 바를 들으시는 줄을 안즉 우리가 그에게 구한 그것을 얻은 줄을 또한 아느니라',30638),
('1jn-5-16','1jn','요한일서',5,16,'누구든지 형제가 사망에 이르지 아니하는 죄 범하는 것을 보거든 구하라 그리하면 사망에 이르지 아니하는 범죄자들을 위하여 그에게 생명을 주시리라 사망에 이르는 죄가 있으니 이에 관하여 나는 구하라 하지 않노라',30639),
('1jn-5-17','1jn','요한일서',5,17,'모든 불의가 죄로되 사망에 이르지 아니하는 죄도 있도다',30640),
('1jn-5-18','1jn','요한일서',5,18,'하나님께로부터 난 자는 다 범죄하지 아니하는 줄을 우리가 아노라 하나님께로부터 나신 자가 그를 지키시매 악한 자가 그를 만지지도 못하느니라',30641),
('1jn-5-19','1jn','요한일서',5,19,'또 아는 것은 우리는 하나님께 속하고 온 세상은 악한 자 안에 처한 것이며',30642),
('1jn-5-20','1jn','요한일서',5,20,'또 아는 것은 하나님의 아들이 이르러 우리에게 지각을 주사 우리로 참된 자를 알게 하신 것과 또한 우리가 참된 자 곧 그의 아들 예수 그리스도 안에 있는 것이니 그는 참 하나님이시요 영생이시라',30643),
('1jn-5-21','1jn','요한일서',5,21,'자녀들아 너희 자신을 지켜 우상에게서 멀리하라',30644),
('2jn-1-1','2jn','요한이서',1,1,'장로인 나는 택하심을 받은 부녀와 그의 자녀들에게 편지하노니 내가 참으로 사랑하는 자요 나뿐 아니라 진리를 아는 모든 자도 그리하는 것은',30645),
('2jn-1-2','2jn','요한이서',1,2,'우리 안에 거하여 영원히 우리와 함께 할 진리로 말미암음이로다',30646),
('2jn-1-3','2jn','요한이서',1,3,'은혜와 긍휼과 평강이 하나님 아버지와 아버지의 아들 예수 그리스도께로부터 진리와 사랑 가운데서 우리와 함께 있으리라',30647),
('2jn-1-4','2jn','요한이서',1,4,'너의 자녀들 중에 우리가 아버지께 받은 계명대로 진리를 행하는 자를 내가 보니 심히 기쁘도다',30648),
('2jn-1-5','2jn','요한이서',1,5,'부녀여, 내가 이제 네게 구하노니 서로 사랑하자 이는 새 계명 같이 네게 쓰는 것이 아니요 처음부터 우리가 가진 것이라',30649),
('2jn-1-6','2jn','요한이서',1,6,'또 사랑은 이것이니 우리가 그 계명을 따라 행하는 것이요 계명은 이것이니 너희가 처음부터 들은 바와 같이 그 가운데서 행하라 하심이라',30650),
('2jn-1-7','2jn','요한이서',1,7,'미혹하는 자가 세상에 많이 나왔나니 이는 예수 그리스도께서 육체로 오심을 부인하는 자라 이런 자가 미혹하는 자요 적그리스도니',30651),
('2jn-1-8','2jn','요한이서',1,8,'너희는 스스로 삼가 우리가 일한 것을 잃지 말고 오직 온전한 상을 받으라',30652),
('2jn-1-9','2jn','요한이서',1,9,'지나쳐 그리스도의 교훈 안에 거하지 아니하는 자는 다 하나님을 모시지 못하되 교훈 안에 거하는 그 사람은 아버지와 아들을 모시느니라',30653),
('2jn-1-10','2jn','요한이서',1,10,'누구든지 이 교훈을 가지지 않고 너희에게 나아가거든 그를 집에 들이지도 말고 인사도 하지 말라',30654),
('2jn-1-11','2jn','요한이서',1,11,'그에게 인사하는 자는 그 악한 일에 참여하는 자임이라',30655),
('2jn-1-12','2jn','요한이서',1,12,'내가 너희에게 쓸 것이 많으나 종이와 먹으로 쓰기를 원하지 아니하고 오히려 너희에게 가서 대면하여 말하려 하니 이는 너희 기쁨을 충만하게 하려 함이라',30656),
('2jn-1-13','2jn','요한이서',1,13,'택하심을 받은 네 자매의 자녀들이 네게 문안하느니라',30657),
('3jn-1-1','3jn','요한삼서',1,1,'장로인 나는 사랑하는 가이오 곧 내가 참으로 사랑하는 자에게 편지하노라',30658),
('3jn-1-2','3jn','요한삼서',1,2,'사랑하는 자여 네 영혼이 잘됨 같이 네가 범사에 잘되고 강건하기를 내가 간구하노라',30659),
('3jn-1-3','3jn','요한삼서',1,3,'형제들이 와서 네게 있는 진리를 증언하되 네가 진리 안에서 행한다 하니 내가 심히 기뻐하노라',30660),
('3jn-1-4','3jn','요한삼서',1,4,'내가 내 자녀들이 진리 안에서 행한다 함을 듣는 것보다 더 기쁜 일이 없도다',30661),
('3jn-1-5','3jn','요한삼서',1,5,'사랑하는 자여 네가 무엇이든지 형제 곧 나그네 된 자들에게 행하는 것은 신실한 일이니',30662),
('3jn-1-6','3jn','요한삼서',1,6,'그들이 교회 앞에서 너의 사랑을 증언하였느니라 네가 하나님께 합당하게 그들을 전송하면 좋으리로다',30663),
('3jn-1-7','3jn','요한삼서',1,7,'이는 그들이 주의 이름을 위하여 나가서 이방인에게 아무 것도 받지 아니함이라',30664),
('3jn-1-8','3jn','요한삼서',1,8,'그러므로 우리가 이같은 자들을 영접하는 것이 마땅하니 이는 우리로 진리를 위하여 함께 일하는 자가 되게 하려 함이라',30665),
('3jn-1-9','3jn','요한삼서',1,9,'내가 두어 자를 교회에 썼으나 그들 중에 으뜸되기를 좋아하는 디오드레베가 우리를 맞아들이지 아니하니',30666),
('3jn-1-10','3jn','요한삼서',1,10,'그러므로 내가 가면 그 행한 일을 잊지 아니하리라 그가 악한 말로 우리를 비방하고도 오히려 부족하여 형제들을 맞아들이지도 아니하고 맞아들이고자 하는 자를 금하여 교회에서 내쫓는도다',30667),
('3jn-1-11','3jn','요한삼서',1,11,'사랑하는 자여 악한 것을 본받지 말고 선한 것을 본받으라 선을 행하는 자는 하나님께 속하고 악을 행하는 자는 하나님을 뵈옵지 못하였느니라',30668),
('3jn-1-12','3jn','요한삼서',1,12,'데메드리오는 뭇 사람에게도, 진리에게서도 증거를 받았으매 우리도 증언하노니 너는 우리의 증언이 참된 줄을 아느니라',30669),
('3jn-1-13','3jn','요한삼서',1,13,'내가 네게 쓸 것이 많으나 먹과 붓으로 쓰기를 원하지 아니하고',30670),
('3jn-1-14','3jn','요한삼서',1,14,'속히 보기를 바라노니 또한 우리가 대면하여 말하리라',30671),
('3jn-1-15','3jn','요한삼서',1,15,'평강이 네게 있을지어다 여러 친구가 네게 문안하느니라 너는 친구들의 이름을 들어 문안하라',30672),
('jud-1-1','jud','유다서',1,1,'예수 그리스도의 종이요 야고보의 형제인 유다는 부르심을 받은 자 곧 하나님 아버지 안에서 사랑을 얻고 예수 그리스도를 위하여 지키심을 받은 자들에게 편지하노라',30673),
('jud-1-2','jud','유다서',1,2,'긍휼과 평강과 사랑이 너희에게 더욱 많을지어다',30674),
('jud-1-3','jud','유다서',1,3,'사랑하는 자들아 우리가 일반으로 받은 구원에 관하여 내가 너희에게 편지하려는 생각이 간절하던 차에 성도에게 단번에 주신 믿음의 도를 위하여 힘써 싸우라는 편지로 너희를 권하여야 할 필요를 느꼈노니',30675),
('jud-1-4','jud','유다서',1,4,'이는 가만히 들어온 사람 몇이 있음이라 그들은 옛적부터 이 판결을 받기로 미리 기록된 자니 경건하지 아니하여 우리 하나님의 은혜를 도리어 방탕한 것으로 바꾸고 홀로 하나이신 주재 곧 우리 주 예수 그리스도를 부인하는 자니라',30676),
('jud-1-5','jud','유다서',1,5,'너희가 본래 모든 사실을 알고 있으나 내가 너희로 다시 생각나게 하고자 하노라 주께서 백성을 애굽에서 구원하여 내시고 후에 믿지 아니하는 자들을 멸하셨으며',30677),
('jud-1-6','jud','유다서',1,6,'또 자기 지위를 지키지 아니하고 자기 처소를 떠난 천사들을 큰 날의 심판까지 영원한 결박으로 흑암에 가두셨으며',30678),
('jud-1-7','jud','유다서',1,7,'소돔과 고모라와 그 이웃 도시들도 그들과 같은 행동으로 음란하며 다른 육체를 따라 가다가 영원한 불의 형벌을 받음으로 거울이 되었느니라',30679),
('jud-1-8','jud','유다서',1,8,'그러한데 꿈꾸는 이 사람들도 그와 같이 육체를 더럽히며 권위를 업신여기며 영광을 비방하는도다',30680),
('jud-1-9','jud','유다서',1,9,'천사장 미가엘이 모세의 시체에 관하여 마귀와 다투어 변론할 때에 감히 비방하는 판결을 내리지 못하고 다만 말하되 주께서 너를 꾸짖으시기를 원하노라 하였거늘',30681),
('jud-1-10','jud','유다서',1,10,'이 사람들은 무엇이든지 그 알지 못하는 것을 비방하는도다 또 그들은 이성 없는 짐승 같이 본능으로 아는 그것으로 멸망하느니라',30682),
('jud-1-11','jud','유다서',1,11,'화 있을진저 이 사람들이여, 가인의 길에 행하였으며 삯을 위하여 발람의 어그러진 길로 몰려 갔으며 고라의 패역을 따라 멸망을 받았도다',30683),
('jud-1-12','jud','유다서',1,12,'그들은 기탄 없이 너희와 함께 먹으니 너희의 애찬에 암초요 자기 몸만 기르는 목자요 바람에 불려가는 물 없는 구름이요 죽고 또 죽어 뿌리까지 뽑힌 열매 없는 가을 나무요',30684),
('jud-1-13','jud','유다서',1,13,'자기 수치의 거품을 뿜는 바다의 거친 물결이요 영원히 예비된 캄캄한 흑암으로 돌아갈 유리하는 별들이라',30685),
('jud-1-14','jud','유다서',1,14,'아담의 칠대 손 에녹이 이 사람들에 대하여도 예언하여 이르되 보라 주께서 그 수만의 거룩한 자와 함께 임하셨나니',30686),
('jud-1-15','jud','유다서',1,15,'이는 뭇 사람을 심판하사 모든 경건하지 않은 자가 경건하지 않게 행한 모든 경건하지 않은 일과 또 경건하지 않은 죄인들이 주를 거슬러 한 모든 완악한 말로 말미암아 그들을 정죄하려 하심이라 하였느니라',30687),
('jud-1-16','jud','유다서',1,16,'이 사람들은 원망하는 자며 불만을 토하는 자며 그 정욕대로 행하는 자라 그 입으로 자랑하는 말을 하며 이익을 위하여 아첨하느니라',30688),
('jud-1-17','jud','유다서',1,17,'사랑하는 자들아 너희는 우리 주 예수 그리스도의 사도들이 미리 한 말을 기억하라',30689),
('jud-1-18','jud','유다서',1,18,'그들이 너희에게 말하기를 마지막 때에 자기의 경건하지 않은 정욕대로 행하며 조롱하는 자들이 있으리라 하였나니',30690),
('jud-1-19','jud','유다서',1,19,'이 사람들은 분열을 일으키는 자며 육에 속한 자며 성령이 없는 자니라',30691),
('jud-1-20','jud','유다서',1,20,'사랑하는 자들아 너희는 너희의 지극히 거룩한 믿음 위에 자신을 세우며 성령으로 기도하며',30692),
('jud-1-21','jud','유다서',1,21,'하나님의 사랑 안에서 자신을 지키며 영생에 이르도록 우리 주 예수 그리스도의 긍휼을 기다리라',30693),
('jud-1-22','jud','유다서',1,22,'어떤 의심하는 자들을 긍휼히 여기라',30694),
('jud-1-23','jud','유다서',1,23,'또 어떤 자를 불에서 끌어내어 구원하라 또 어떤 자를 그 육체로 더럽힌 옷까지도 미워하되 두려움으로 긍휼히 여기라',30695),
('jud-1-24','jud','유다서',1,24,'능히 너희를 보호하사 거침이 없게 하시고 너희로 그 영광 앞에 흠이 없이 기쁨으로 서게 하실 이',30696),
('jud-1-25','jud','유다서',1,25,'곧 우리 구주 홀로 하나이신 하나님께 우리 주 예수 그리스도로 말미암아 영광과 위엄과 권력과 권세가 영원 전부터 이제와 영원토록 있을지어다 아멘',30697),
('rev-1-1','rev','요한계시록',1,1,'예수 그리스도의 계시라 이는 하나님이 그에게 주사 반드시 속히 일어날 일들을 그 종들에게 보이시려고 그의 천사를 그 종 요한에게 보내어 알게 하신 것이라',30698),
('rev-1-2','rev','요한계시록',1,2,'요한은 하나님의 말씀과 예수 그리스도의 증거 곧 자기가 본 것을 다 증언하였느니라',30699),
('rev-1-3','rev','요한계시록',1,3,'이 예언의 말씀을 읽는 자와 듣는 자와 그 가운데에 기록한 것을 지키는 자는 복이 있나니 때가 가까움이라',30700),
('rev-1-4','rev','요한계시록',1,4,'요한은 아시아에 있는 일곱 교회에 편지하노니 이제도 계시고 전에도 계셨고 장차 오실 이시며 그의 보좌 앞에 있는 일곱 영과',30701),
('rev-1-5','rev','요한계시록',1,5,'또 충성된 증인으로 죽은 자들 가운데에서 먼저 나시고 땅의 임금들의 머리가 되신 예수 그리스도로 말미암아 은혜와 평강이 너희에게 있기를 원하노라 우리를 사랑하사 그의 피로 우리 죄에서 우리를 해방하시고',30702),
('rev-1-6','rev','요한계시록',1,6,'그의 아버지 하나님을 위하여 우리를 나라와 제사장으로 삼으신 그에게 영광과 능력이 세세토록 있기를 원하노라 아멘',30703),
('rev-1-7','rev','요한계시록',1,7,'볼지어다 그가 구름을 타고 오시리라 각 사람의 눈이 그를 보겠고 그를 찌른 자들도 볼 것이요 땅에 있는 모든 족속이 그로 말미암아 애곡하리니 그러하리라 아멘',30704),
('rev-1-8','rev','요한계시록',1,8,'주 하나님이 이르시되 나는 알파와 오메가라 이제도 있고 전에도 있었고 장차 올 자요 전능한 자라 하시더라',30705),
('rev-1-9','rev','요한계시록',1,9,'나 요한은 너희 형제요 예수의 환난과 나라와 참음에 동참하는 자라 하나님의 말씀과 예수를 증언하였음으로 말미암아 밧모라 하는 섬에 있었더니',30706),
('rev-1-10','rev','요한계시록',1,10,'주의 날에 내가 성령에 감동되어 내 뒤에서 나는 나팔 소리 같은 큰 음성을 들으니',30707),
('rev-1-11','rev','요한계시록',1,11,'이르되 네가 보는 것을 두루마리에 써서 에베소, 서머나, 버가모, 두아디라, 사데, 빌라델비아, 라오디게아 등 일곱 교회에 보내라 하시기로',30708),
('rev-1-12','rev','요한계시록',1,12,'몸을 돌이켜 나에게 말한 음성을 알아 보려고 돌이킬 때에 일곱 금 촛대를 보았는데',30709),
('rev-1-13','rev','요한계시록',1,13,'촛대 사이에 인자 같은 이가 발에 끌리는 옷을 입고 가슴에 금띠를 띠고',30710),
('rev-1-14','rev','요한계시록',1,14,'그의 머리와 털의 희기가 흰 양털 같고 눈 같으며 그의 눈은 불꽃 같고',30711),
('rev-1-15','rev','요한계시록',1,15,'그의 발은 풀무불에 단련한 빛난 주석 같고 그의 음성은 많은 물 소리와 같으며',30712),
('rev-1-16','rev','요한계시록',1,16,'그의 오른손에 일곱 별이 있고 그의 입에서 좌우에 날선 검이 나오고 그 얼굴은 해가 힘있게 비치는 것 같더라',30713),
('rev-1-17','rev','요한계시록',1,17,'내가 볼 때에 그의 발 앞에 엎드러져 죽은 자 같이 되매 그가 오른손을 내게 얹고 이르시되 두려워하지 말라 나는 처음이요 마지막이니',30714),
('rev-1-18','rev','요한계시록',1,18,'곧 살아 있는 자라 내가 전에 죽었었노라 볼지어다 이제 세세토록 살아 있어 사망과 음부의 열쇠를 가졌노니',30715),
('rev-1-19','rev','요한계시록',1,19,'그러므로 네가 본 것과 지금 있는 일과 장차 될 일을 기록하라',30716),
('rev-1-20','rev','요한계시록',1,20,'네가 본 것은 내 오른손의 일곱 별의 비밀과 또 일곱 금 촛대라 일곱 별은 일곱 교회의 사자요 일곱 촛대는 일곱 교회니라',30717),
('rev-2-1','rev','요한계시록',2,1,'에베소 교회의 사자에게 편지하라 오른손에 있는 일곱 별을 붙잡고 일곱 금 촛대 사이를 거니시는 이가 이르시되',30718),
('rev-2-2','rev','요한계시록',2,2,'내가 네 행위와 수고와 네 인내를 알고 또 악한 자들을 용납하지 아니한 것과 자칭 사도라 하되 아닌 자들을 시험하여 그의 거짓된 것을 네가 드러낸 것과',30719),
('rev-2-3','rev','요한계시록',2,3,'또 네가 참고 내 이름을 위하여 견디고 게으르지 아니한 것을 아노라',30720),
('rev-2-4','rev','요한계시록',2,4,'그러나 너를 책망할 것이 있나니 너의 처음 사랑을 버렸느니라',30721),
('rev-2-5','rev','요한계시록',2,5,'그러므로 어디서 떨어졌는지를 생각하고 회개하여 처음 행위를 가지라 만일 그리하지 아니하고 회개하지 아니하면 내가 네게 가서 네 촛대를 그 자리에서 옮기리라',30722),
('rev-2-6','rev','요한계시록',2,6,'오직 네게 이것이 있으니 네가 니골라 당의 행위를 미워하는도다 나도 이것을 미워하노라',30723),
('rev-2-7','rev','요한계시록',2,7,'귀 있는 자는 성령이 교회들에게 하시는 말씀을 들을지어다 이기는 그에게는 내가 하나님의 낙원에 있는 생명나무의 열매를 주어 먹게 하리라',30724),
('rev-2-8','rev','요한계시록',2,8,'서머나 교회의 사자에게 편지하라 처음이며 마지막이요 죽었다가 살아나신 이가 이르시되',30725),
('rev-2-9','rev','요한계시록',2,9,'내가 네 환난과 궁핍을 알거니와 실상은 네가 부요한 자니라 자칭 유대인이라 하는 자들의 비방도 알거니와 실상은 유대인이 아니요 사탄의 회당이라',30726),
('rev-2-10','rev','요한계시록',2,10,'너는 장차 받을 고난을 두려워하지 말라 볼지어다 마귀가 장차 너희 가운데에서 몇 사람을 옥에 던져 시험을 받게 하리니 너희가 십 일 동안 환난을 받으리라 네가 죽도록 충성하라 그리하면 내가 생명의 관을 네게 주리라',30727),
('rev-2-11','rev','요한계시록',2,11,'귀 있는 자는 성령이 교회들에게 하시는 말씀을 들을지어다 이기는 자는 둘째 사망의 해를 받지 아니하리라',30728),
('rev-2-12','rev','요한계시록',2,12,'버가모 교회의 사자에게 편지하라 좌우에 날선 검을 가지신 이가 이르시되',30729),
('rev-2-13','rev','요한계시록',2,13,'네가 어디에 사는지를 내가 아노니 거기는 사탄의 권좌가 있는 데라 네가 내 이름을 굳게 잡아서 내 충성된 증인 안디바가 너희 가운데 곧 사탄이 사는 곳에서 죽임을 당할 때에도 나를 믿는 믿음을 저버리지 아니하였도다',30730),
('rev-2-14','rev','요한계시록',2,14,'그러나 네게 두어 가지 책망할 것이 있나니 거기 네게 발람의 교훈을 지키는 자들이 있도다 발람이 발락을 가르쳐 이스라엘 자손 앞에 걸림돌을 놓아 우상의 제물을 먹게 하였고 또 행음하게 하였느니라',30731),
('rev-2-15','rev','요한계시록',2,15,'이와 같이 네게도 니골라 당의 교훈을 지키는 자들이 있도다',30732),
('rev-2-16','rev','요한계시록',2,16,'그러므로 회개하라 그리하지 아니하면 내가 네게 속히 가서 내 입의 검으로 그들과 싸우리라',30733),
('rev-2-17','rev','요한계시록',2,17,'귀 있는 자는 성령이 교회들에게 하시는 말씀을 들을지어다 이기는 그에게는 내가 감추었던 만나를 주고 또 흰 돌을 줄 터인데 그 돌 위에 새 이름을 기록한 것이 있나니 받는 자 밖에는 그 이름을 알 사람이 없느니라',30734),
('rev-2-18','rev','요한계시록',2,18,'두아디라 교회의 사자에게 편지하라 그 눈이 불꽃 같고 그 발이 빛난 주석과 같은 하나님의 아들이 이르시되',30735),
('rev-2-19','rev','요한계시록',2,19,'내가 네 사업과 사랑과 믿음과 섬김과 인내를 아노니 네 나중 행위가 처음 것보다 많도다',30736),
('rev-2-20','rev','요한계시록',2,20,'그러나 네게 책망할 일이 있노라 자칭 선지자라 하는 여자 이세벨을 네가 용납함이니 그가 내 종들을 가르쳐 꾀어 행음하게 하고 우상의 제물을 먹게 하는도다',30737),
('rev-2-21','rev','요한계시록',2,21,'또 내가 그에게 회개할 기회를 주었으되 자기의 음행을 회개하고자 하지 아니하는도다',30738),
('rev-2-22','rev','요한계시록',2,22,'볼지어다 내가 그를 침상에 던질 터이요 또 그와 더불어 간음하는 자들도 만일 그의 행위를 회개하지 아니하면 큰 환난 가운데에 던지고',30739),
('rev-2-23','rev','요한계시록',2,23,'또 내가 사망으로 그의 자녀를 죽이리니 모든 교회가 나는 사람의 뜻과 마음을 살피는 자인 줄 알지라 내가 너희 각 사람의 행위대로 갚아 주리라',30740),
('rev-2-24','rev','요한계시록',2,24,'두아디라에 남아 있어 이 교훈을 받지 아니하고 소위 사탄의 깊은 것을 알지 못하는 너희에게 말하노니 다른 짐으로 너희에게 지울 것은 없노라',30741),
