('rev-3-2','rev','요한계시록',3,2,'너는 일깨어 그 남은 바 죽게 된 것을 굳건하게 하라 내 하나님 앞에 네 행위의 온전한 것을 찾지 못하였노니',30748),
('rev-3-3','rev','요한계시록',3,3,'그러므로 네가 어떻게 받았으며 어떻게 들었는지 생각하고 지켜 회개하라 만일 일깨지 아니하면 내가 도둑 같이 이르리니 어느 때에 네게 이를는지 네가 알지 못하리라',30749),
('rev-3-4','rev','요한계시록',3,4,'그러나 사데에 그 옷을 더럽히지 아니한 자 몇 명이 네게 있어 흰 옷을 입고 나와 함께 다니리니 그들은 합당한 자인 연고라',30750),
('rev-3-5','rev','요한계시록',3,5,'이기는 자는 이와 같이 흰 옷을 입을 것이요 내가 그 이름을 생명책에서 결코 지우지 아니하고 그 이름을 내 아버지 앞과 그의 천사들 앞에서 시인하리라',30751),
