('rev-3-7','rev','요한계시록',3,7,'빌라델비아 교회의 사자에게 편지하라 거룩하고 진실하사 다윗의 열쇠를 가지신 이 곧 열면 닫을 사람이 없고 닫으면 열 사람이 없는 그가 이르시되',30753),
('rev-3-8','rev','요한계시록',3,8,'볼지어다 내가 네 앞에 열린 문을 두었으되 능히 닫을 사람이 없으리라 내가 네 행위를 아노니 네가 작은 능력을 가지고서도 내 말을 지키며 내 이름을 배반하지 아니하였도다',30754),
('rev-3-9','rev','요한계시록',3,9,'보라 사탄의 회당 곧 자칭 유대인이라 하나 그렇지 아니하고 거짓말 하는 자들 중에서 몇을 네게 주어 그들로 와서 네 발 앞에 절하게 하고 내가 너를 사랑하는 줄을 알게 하리라',30755),
