('rev-4-1','rev','요한계시록',4,1,'이 일 후에 내가 보니 하늘에 열린 문이 있는데 내가 들은 바 처음에 내게 말하던 나팔 소리 같은 그 음성이 이르되 이리로 올라오라 이 후에 마땅히 일어날 일들을 내가 네게 보이리라 하시더라',30769),
('rev-4-2','rev','요한계시록',4,2,'내가 곧 성령에 감동되었더니 보라 하늘에 보좌를 베풀었고 그 보좌 위에 앉으신 이가 있는데',30770),
('rev-4-3','rev','요한계시록',4,3,'앉으신 이의 모양이 벽옥과 홍보석 같고 또 무지개가 있어 보좌에 둘렸는데 그 모양이 녹보석 같더라',30771),
('rev-4-4','rev','요한계시록',4,4,'또 보좌에 둘려 이십사 보좌들이 있고 그 보좌들 위에 이십사 장로들이 흰 옷을 입고 머리에 금관을 쓰고 앉았더라',30772),
('rev-4-5','rev','요한계시록',4,5,'보좌로부터 번개와 음성과 우렛소리가 나고 보좌 앞에 켠 등불 일곱이 있으니 이는 하나님의 일곱 영이라',30773),
('rev-4-6','rev','요한계시록',4,6,'보좌 앞에 수정과 같은 유리 바다가 있고 보좌 가운데와 보좌 주위에 네 생물이 있는데 앞뒤에 눈들이 가득하더라',30774),
('rev-4-7','rev','요한계시록',4,7,'그 첫째 생물은 사자 같고 그 둘째 생물은 송아지 같고 그 셋째 생물은 얼굴이 사람 같고 그 넷째 생물은 날아가는 독수리 같은데',30775),
('rev-4-8','rev','요한계시록',4,8,'네 생물은 각각 여섯 날개를 가졌고 그 안과 주위에는 눈들이 가득하더라 그들이 밤낮 쉬지 않고 이르기를 거룩하다 거룩하다 거룩하다 주 하나님 곧 전능하신 이여 전에도 계셨고 이제도 계시고 장차 오실 이시라 하고',30776),
('rev-4-9','rev','요한계시록',4,9,'그 생물들이 보좌에 앉으사 세세토록 살아 계시는 이에게 영광과 존귀와 감사를 돌릴 때에',30777),
('rev-4-10','rev','요한계시록',4,10,'이십사 장로들이 보좌에 앉으신 이 앞에 엎드려 세세토록 살아 계시는 이에게 경배하고 자기의 관을 보좌 앞에 드리며 이르되',30778),
('rev-4-11','rev','요한계시록',4,11,'우리 주 하나님이여 영광과 존귀와 권능을 받으시는 것이 합당하오니 주께서 만물을 지으신지라 만물이 주의 뜻대로 있었고 또 지으심을 받았나이다 하더라',30779),
('rev-5-1','rev','요한계시록',5,1,'내가 보매 보좌에 앉으신 이의 오른손에 두루마리가 있으니 안팎으로 썼고 일곱 인으로 봉하였더라',30780),
('rev-5-2','rev','요한계시록',5,2,'또 보매 힘있는 천사가 큰 음성으로 외치기를 누가 그 두루마리를 펴며 그 인을 떼기에 합당하냐 하나',30781),
('rev-5-3','rev','요한계시록',5,3,'하늘 위에나 땅 위에나 땅 아래에 능히 그 두루마리를 펴거나 보거나 할 자가 없더라',30782),
('rev-5-4','rev','요한계시록',5,4,'그 두루마리를 펴거나 보거나 하기에 합당한 자가 보이지 아니하기로 내가 크게 울었더니',30783),
('rev-5-5','rev','요한계시록',5,5,'장로 중의 한 사람이 내게 말하되 울지 말라 유대 지파의 사자 다윗의 뿌리가 이겼으니 그 두루마리와 그 일곱 인을 떼시리라 하더라',30784),
('rev-5-6','rev','요한계시록',5,6,'내가 또 보니 보좌와 네 생물과 장로들 사이에 한 어린 양이 서 있는데 일찍이 죽임을 당한 것 같더라 그에게 일곱 뿔과 일곱 눈이 있으니 이 눈들은 온 땅에 보내심을 받은 하나님의 일곱 영이더라',30785),
('rev-5-7','rev','요한계시록',5,7,'그 어린 양이 나아와서 보좌에 앉으신 이의 오른손에서 두루마리를 취하시니라',30786),
