('rev-5-11','rev','요한계시록',5,11,'내가 또 보고 들으매 보좌와 생물들과 장로들을 둘러 선 많은 천사의 음성이 있으니 그 수가 만만이요 천천이라',30790),
('rev-5-12','rev','요한계시록',5,12,'큰 음성으로 이르되 죽임을 당하신 어린 양은 능력과 부와 지혜와 힘과 존귀와 영광과 찬송을 받으시기에 합당하도다 하더라',30791),
('rev-5-13','rev','요한계시록',5,13,'내가 또 들으니 하늘 위에와 땅 위에와 땅 아래와 바다 위에와 또 그 가운데 모든 피조물이 이르되 보좌에 앉으신 이와 어린 양에게 찬송과 존귀와 영광과 권능을 세세토록 돌릴지어다 하니',30792),
('rev-5-14','rev','요한계시록',5,14,'네 생물이 이르되 아멘 하고 장로들은 엎드려 경배하더라',30793),
