('rev-6-2','rev','요한계시록',6,2,'이에 내가 보니 흰 말이 있는데 그 탄 자가 활을 가졌고 면류관을 받고 나아가서 이기고 또 이기려고 하더라',30795),
('rev-6-3','rev','요한계시록',6,3,'둘째 인을 떼실 때에 내가 들으니 둘째 생물이 말하되 오라 하니',30796),
