('rev-10-7','rev','요한계시록',10,7,'일곱째 천사가 소리 내는 날 그의 나팔을 불려고 할 때에 하나님이 그의 종 선지자들에게 전하신 복음과 같이 하나님의 그 비밀이 이루어지리라 하더라',30868),
