('rev-11-1','rev','요한계시록',11,1,'또 내게 지팡이 같은 갈대를 주며 말하기를 일어나서 하나님의 성전과 제단과 그 안에서 경배하는 자들을 측량하되',30873),
('rev-11-2','rev','요한계시록',11,2,'성전 바깥 마당은 측량하지 말고 그냥 두라 이것은 이방인에게 주었은즉 그들이 거룩한 성을 마흔두 달 동안 짓밟으리라',30874),
