('rev-12-4','rev','요한계시록',12,4,'그 꼬리가 하늘의 별 삼분의 일을 끌어다가 땅에 던지더라 용이 해산하려는 여자 앞에서 그가 해산하면 그 아이를 삼키고자 하더니',30895),
