('rev-12-12','rev','요한계시록',12,12,'그러므로 하늘과 그 가운데에 거하는 자들은 즐거워하라 그러나 땅과 바다는 화 있을진저 이는 마귀가 자기의 때가 얼마 남지 않은 줄을 알므로 크게 분내어 너희에게 내려갔음이라 하더라',30903),
('rev-12-13','rev','요한계시록',12,13,'용이 자기가 땅으로 내쫓긴 것을 보고 남자를 낳은 여자를 박해하는지라',30904),
