('rev-14-2','rev','요한계시록',14,2,'내가 하늘에서 나는 소리를 들으니 많은 물 소리와도 같고 큰 우렛소리와도 같은데 내가 들은 소리는 거문고 타는 자들이 그 거문고를 타는 것 같더라',30928),
('rev-14-3','rev','요한계시록',14,3,'그들이 보좌 앞과 네 생물과 장로들 앞에서 새 노래를 부르니 땅에서 속량함을 받은 십사만 사천 밖에는 능히 이 노래를 배울 자가 없더라',30929),
('rev-14-4','rev','요한계시록',14,4,'이 사람들은 여자와 더불어 더럽히지 아니하고 순결한 자라 어린 양이 어디로 인도하든지 따라가는 자며 사람 가운데에서 속량함을 받아 처음 익은 열매로 하나님과 어린 양에게 속한 자들이니',30930),
('rev-14-5','rev','요한계시록',14,5,'그 입에 거짓말이 없고 흠이 없는 자들이더라',30931),
('rev-14-6','rev','요한계시록',14,6,'또 보니 다른 천사가 공중에 날아가는데 땅에 거주하는 자들 곧 모든 민족과 종족과 방언과 백성에게 전할 영원한 복음을 가졌더라',30932),
('rev-14-7','rev','요한계시록',14,7,'그가 큰 음성으로 이르되 하나님을 두려워하며 그에게 영광을 돌리라 이는 그의 심판의 시간이 이르렀음이니 하늘과 땅과 바다와 물들의 근원을 만드신 이를 경배하라 하더라',30933),
('rev-14-8','rev','요한계시록',14,8,'또 다른 천사 곧 둘째가 그 뒤를 따라 말하되 무너졌도다 무너졌도다 큰 성 바벨론이여 모든 나라에게 그의 음행으로 말미암아 진노의 포도주를 먹이던 자로다 하더라',30934),
('rev-14-9','rev','요한계시록',14,9,'또 다른 천사 곧 셋째가 그 뒤를 따라 큰 음성으로 이르되 만일 누구든지 짐승과 그의 우상에게 경배하고 이마에나 손에 표를 받으면',30935),
('rev-14-10','rev','요한계시록',14,10,'그도 하나님의 진노의 포도주를 마시리니 그 진노의 잔에 섞인 것이 없이 부은 포도주라 거룩한 천사들 앞과 어린 양 앞에서 불과 유황으로 고난을 받으리니',30936),
('rev-14-11','rev','요한계시록',14,11,'그 고난의 연기가 세세토록 올라가리로다 짐승과 그의 우상에게 경배하고 그의 이름 표를 받는 자는 누구든지 밤낮 쉼을 얻지 못하리라 하더라',30937),
('rev-14-12','rev','요한계시록',14,12,'성도들의 인내가 여기 있나니 그들은 하나님의 계명과 예수에 대한 믿음을 지키는 자니라',30938),
('rev-14-13','rev','요한계시록',14,13,'또 내가 들으니 하늘에서 음성이 나서 이르되 기록하라 지금 이후로 주 안에서 죽는 자들은 복이 있도다 하시매 성령이 이르시되 그러하다 그들이 수고를 그치고 쉬리니 이는 그들의 행한 일이 따름이라 하시더라',30939),
('rev-14-14','rev','요한계시록',14,14,'또 내가 보니 흰 구름이 있고 구름 위에 인자와 같은 이가 앉으셨는데 그 머리에는 금 면류관이 있고 그 손에는 예리한 낫을 가졌더라',30940),
('rev-14-15','rev','요한계시록',14,15,'또 다른 천사가 성전으로부터 나와 구름 위에 앉은 이를 향하여 큰 음성으로 외쳐 이르되 당신의 낫을 휘둘러 거두소서 땅의 곡식이 다 익어 거둘 때가 이르렀음이니이다 하니',30941),
('rev-14-16','rev','요한계시록',14,16,'구름 위에 앉으신 이가 낫을 땅에 휘두르매 땅의 곡식이 거두어지니라',30942),
('rev-14-17','rev','요한계시록',14,17,'또 다른 천사가 하늘에 있는 성전에서 나오는데 역시 예리한 낫을 가졌더라',30943),
('rev-14-18','rev','요한계시록',14,18,'또 불을 다스리는 다른 천사가 제단으로부터 나와 예리한 낫 가진 자를 향하여 큰 음성으로 불러 이르되 네 예리한 낫을 휘둘러 땅의 포도송이를 거두라 그 포도가 익었느니라 하더라',30944),
('rev-14-19','rev','요한계시록',14,19,'천사가 낫을 땅에 휘둘러 땅의 포도를 거두어 하나님의 진노의 큰 포도주 틀에 던지매',30945),
('rev-14-20','rev','요한계시록',14,20,'성 밖에서 그 틀이 밟히니 틀에서 피가 나서 말 굴레에까지 닿았고 천육백 스다디온에 퍼졌더라',30946),
('rev-15-1','rev','요한계시록',15,1,'또 하늘에 크고 이상한 다른 이적을 보매 일곱 천사가 일곱 재앙을 가졌으니 곧 마지막 재앙이라 하나님의 진노가 이것으로 마치리로다',30947),
('rev-15-2','rev','요한계시록',15,2,'또 내가 보니 불이 섞인 유리 바다 같은 것이 있고 짐승과 그의 우상과 그의 이름의 수를 이기고 벗어난 자들이 유리 바다 가에 서서 하나님의 거문고를 가지고',30948),
('rev-15-3','rev','요한계시록',15,3,'하나님의 종 모세의 노래, 어린 양의 노래를 불러 이르되 주 하나님 곧 전능하신 이시여 하시는 일이 크고 놀라우시도다 만국의 왕이시여 주의 길이 의롭고 참되시도다',30949),
('rev-15-4','rev','요한계시록',15,4,'주여 누가 주의 이름을 두려워하지 아니하며 영화롭게 하지 아니하오리이까 오직 주만 거룩하시니이다 주의 의로우신 일이 나타났으매 만국이 와서 주께 경배하리이다 하더라',30950),
('rev-15-5','rev','요한계시록',15,5,'또 이 일 후에 내가 보니 하늘에 증거 장막의 성전이 열리며',30951),
