('rev-15-7','rev','요한계시록',15,7,'네 생물 중의 하나가 영원토록 살아 계신 하나님의 진노를 가득히 담은 금 대접 일곱을 그 일곱 천사들에게 주니',30953),
('rev-15-8','rev','요한계시록',15,8,'하나님의 영광과 능력으로 말미암아 성전에 연기가 가득 차매 일곱 천사의 일곱 재앙이 마치기까지는 성전에 능히 들어갈 자가 없더라',30954),
('rev-16-1','rev','요한계시록',16,1,'또 내가 들으니 성전에서 큰 음성이 나서 일곱 천사에게 말하되 너희는 가서 하나님의 진노의 일곱 대접을 땅에 쏟으라 하더라',30955),
('rev-16-2','rev','요한계시록',16,2,'첫째 천사가 가서 그 대접을 땅에 쏟으매 짐승의 표를 받은 사람들과 그 우상에게 경배하는 자들에게 악하고 독한 종기가 나더라',30956),
