('rev-16-4','rev','요한계시록',16,4,'셋째 천사가 그 대접을 강과 물 근원에 쏟으매 피가 되더라',30958),
('rev-16-5','rev','요한계시록',16,5,'내가 들으니 물을 차지한 천사가 이르되 전에도 계셨고 지금도 계신 거룩하신 이여 이렇게 심판하시니 의로우시도다',30959),
('rev-16-6','rev','요한계시록',16,6,'그들이 성도들과 선지자들의 피를 흘렸으므로 그들에게 피를 마시게 하신 것이 합당하니이다 하더라',30960),
('rev-16-7','rev','요한계시록',16,7,'또 내가 들으니 제단이 말하기를 그러하다 주 하나님 곧 전능하신 이시여 심판하시는 것이 참되시고 의로우시도다 하더라',30961),
