('rev-16-10','rev','요한계시록',16,10,'또 다섯째 천사가 그 대접을 짐승의 왕좌에 쏟으니 그 나라가 곧 어두워지며 사람들이 아파서 자기 혀를 깨물고',30964),
('rev-16-11','rev','요한계시록',16,11,'아픈 것과 종기로 말미암아 하늘의 하나님을 비방하고 그들의 행위를 회개하지 아니하더라',30965),
('rev-16-12','rev','요한계시록',16,12,'또 여섯째 천사가 그 대접을 큰 강 유브라데에 쏟으매 강물이 말라서 동방에서 오는 왕들의 길이 예비되었더라',30966),
('rev-16-13','rev','요한계시록',16,13,'또 내가 보매 개구리 같은 세 더러운 영이 용의 입과 짐승의 입과 거짓 선지자의 입에서 나오니',30967),
('rev-16-14','rev','요한계시록',16,14,'그들은 귀신의 영이라 이적을 행하여 온 천하 왕들에게 가서 하나님 곧 전능하신 이의 큰 날에 있을 전쟁을 위하여 그들을 모으더라',30968),
('rev-16-15','rev','요한계시록',16,15,'보라 내가 도둑 같이 오리니 누구든지 깨어 자기 옷을 지켜 벌거벗고 다니지 아니하며 자기의 부끄러움을 보이지 아니하는 자는 복이 있도다',30969),
('rev-16-16','rev','요한계시록',16,16,'세 영이 히브리어로 아마겟돈이라 하는 곳으로 왕들을 모으더라',30970),
