('rev-16-18','rev','요한계시록',16,18,'번개와 음성들과 우렛소리가 있고 또 큰 지진이 있어 얼마나 큰지 사람이 땅에 있어 온 이래로 이같이 큰 지진이 없었더라',30972),
('rev-16-19','rev','요한계시록',16,19,'큰 성이 세 갈래로 갈라지고 만국의 성들도 무너지니 큰 성 바벨론이 하나님 앞에 기억하신 바 되어 그의 맹렬한 진노의 포도주 잔을 받으매',30973),
('rev-16-20','rev','요한계시록',16,20,'각 섬도 없어지고 산악도 간 데 없더라',30974),
('rev-16-21','rev','요한계시록',16,21,'또 무게가 한 달란트나 되는 큰 우박이 하늘로부터 사람들에게 내리매 사람들이 그 우박의 재앙 때문에 하나님을 비방하니 그 재앙이 심히 큼이러라',30975),
('rev-17-1','rev','요한계시록',17,1,'또 일곱 대접을 가진 일곱 천사 중 하나가 와서 내게 말하여 이르되 이리로 오라 많은 물 위에 앉은 큰 음녀가 받을 심판을 네게 보이리라',30976),
('rev-17-2','rev','요한계시록',17,2,'땅의 임금들도 그와 더불어 음행하였고 땅에 사는 자들도 그 음행의 포도주에 취하였다 하고',30977),
('rev-17-3','rev','요한계시록',17,3,'곧 성령으로 나를 데리고 광야로 가니라 내가 보니 여자가 붉은 빛 짐승을 탔는데 그 짐승의 몸에 하나님을 모독하는 이름들이 가득하고 일곱 머리와 열 뿔이 있으며',30978),
('rev-17-4','rev','요한계시록',17,4,'그 여자는 자주 빛과 붉은 빛 옷을 입고 금과 보석과 진주로 꾸미고 손에 금 잔을 가졌는데 가증한 물건과 그의 음행의 더러운 것들이 가득하더라',30979),
('rev-17-5','rev','요한계시록',17,5,'그의 이마에 이름이 기록되었으니 비밀이라, 큰 바벨론이라, 땅의 음녀들과 가증한 것들의 어미라 하였더라',30980),
('rev-17-6','rev','요한계시록',17,6,'또 내가 보매 이 여자가 성도들의 피와 예수의 증인들의 피에 취한지라 내가 그 여자를 보고 놀랍게 여기고 크게 놀랍게 여기니',30981),
('rev-17-7','rev','요한계시록',17,7,'천사가 이르되 왜 놀랍게 여기느냐 내가 여자와 그가 탄 일곱 머리와 열 뿔 가진 짐승의 비밀을 네게 이르리라',30982),
('rev-17-8','rev','요한계시록',17,8,'네가 본 짐승은 전에 있었다가 지금은 없으나 장차 무저갱으로부터 올라와 멸망으로 들어갈 자니 땅에 사는 자들로서 창세 이후로 그 이름이 생명책에 기록되지 못한 자들이 이전에 있었다가 지금은 없으나 장차 나올 짐승을 보고 놀랍게 여기리라',30983),
('rev-17-9','rev','요한계시록',17,9,'지혜 있는 뜻이 여기 있으니 그 일곱 머리는 여자가 앉은 일곱 산이요',30984),
('rev-17-10','rev','요한계시록',17,10,'또 일곱 왕이라 다섯은 망하였고 하나는 있고 다른 하나는 아직 이르지 아니하였으나 이르면 반드시 잠시 동안 머무르리라',30985),
('rev-17-11','rev','요한계시록',17,11,'전에 있었다가 지금 없어진 짐승은 여덟째 왕이니 일곱 중에 속한 자라 그가 멸망으로 들어가리라',30986),
('rev-17-12','rev','요한계시록',17,12,'네가 보던 열 뿔은 열 왕이니 아직 나라를 얻지 못하였으나 다만 짐승과 더불어 임금처럼 한동안 권세를 받으리라',30987),
('rev-17-13','rev','요한계시록',17,13,'그들이 한 뜻을 가지고 자기의 능력과 권세를 짐승에게 주더라',30988),
('rev-17-14','rev','요한계시록',17,14,'그들이 어린 양과 더불어 싸우려니와 어린 양은 만주의 주시요 만왕의 왕이시므로 그들을 이기실 터이요 또 그와 함께 있는 자들 곧 부르심을 받고 택하심을 받은 진실한 자들도 이기리로다',30989),
('rev-17-15','rev','요한계시록',17,15,'또 천사가 내게 말하되 네가 본 바 음녀가 앉아 있는 물은 백성과 무리와 열국과 방언들이니라',30990),
('rev-17-16','rev','요한계시록',17,16,'네가 본 바 이 열 뿔과 짐승은 음녀를 미워하여 망하게 하고 벌거벗게 하고 그의 살을 먹고 불로 아주 사르리라',30991),
('rev-17-17','rev','요한계시록',17,17,'이는 하나님이 자기 뜻대로 할 마음을 그들에게 주사 한 뜻을 이루게 하시고 그들의 나라를 그 짐승에게 주게 하시되 하나님의 말씀이 응하기까지 하심이라',30992),
('rev-17-18','rev','요한계시록',17,18,'또 네가 본 그 여자는 땅의 왕들을 다스리는 큰 성이라 하더라',30993),
('rev-18-1','rev','요한계시록',18,1,'이 일 후에 다른 천사가 하늘에서 내려 오는 것을 보니 큰 권세를 가졌는데 그의 영광으로 땅이 환하여지더라',30994),
('rev-18-2','rev','요한계시록',18,2,'힘찬 음성으로 외쳐 이르되 무너졌도다 무너졌도다 큰 성 바벨론이여 귀신의 처소와 각종 더러운 영이 모이는 곳과 각종 더럽고 가증한 새들이 모이는 곳이 되었도다',30995),
('rev-18-3','rev','요한계시록',18,3,'그 음행의 진노의 포도주로 말미암아 만국이 무너졌으며 또 땅의 왕들이 그와 더불어 음행하였으며 땅의 상인들도 그 사치의 세력으로 치부하였도다 하더라',30996),
('rev-18-4','rev','요한계시록',18,4,'또 내가 들으니 하늘로부터 다른 음성이 나서 이르되 내 백성아, 거기서 나와 그의 죄에 참여하지 말고 그가 받을 재앙들을 받지 말라',30997),
('rev-18-5','rev','요한계시록',18,5,'그의 죄는 하늘에 사무쳤으며 하나님은 그의 불의한 일을 기억하신지라',30998),
('rev-18-6','rev','요한계시록',18,6,'그가 준 그대로 그에게 주고 그의 행위대로 갑절을 갚아 주고 그가 섞은 잔에도 갑절이나 섞어 그에게 주라',30999),
('rev-18-7','rev','요한계시록',18,7,'그가 얼마나 자기를 영화롭게 하였으며 사치하였든지 그만큼 고통과 애통함으로 갚아 주라 그가 마음에 말하기를 나는 여왕으로 앉은 자요 과부가 아니라 결단코 애통함을 당하지 아니하리라 하니',31000),
('rev-18-8','rev','요한계시록',18,8,'그러므로 하루 동안에 그 재앙들이 이르리니 곧 사망과 애통함과 흉년이라 그가 또한 불에 살라지리니 그를 심판하시는 주 하나님은 강하신 자이심이라',31001),
('rev-18-9','rev','요한계시록',18,9,'그와 함께 음행하고 사치하던 땅의 왕들이 그가 불타는 연기를 보고 위하여 울고 가슴을 치며',31002),
('rev-18-10','rev','요한계시록',18,10,'그의 고통을 무서워하여 멀리 서서 이르되 화 있도다 화 있도다 큰 성, 견고한 성 바벨론이여 한 시간에 네 심판이 이르렀다 하리로다',31003),
('rev-18-11','rev','요한계시록',18,11,'땅의 상인들이 그를 위하여 울고 애통하는 것은 다시 그들의 상품을 사는 자가 없음이라',31004),
('rev-18-12','rev','요한계시록',18,12,'그 상품은 금과 은과 보석과 진주와 세마포와 자주 옷감과 비단과 붉은 옷감이요 각종 향목과 각종 상아 그릇이요 값진 나무와 구리와 철과 대리석으로 만든 각종 그릇이요',31005),
('rev-18-13','rev','요한계시록',18,13,'계피와 향료와 향과 향유와 유향과 포도주와 감람유와 고운 밀가루와 밀이요 소와 양과 말과 수레와 종들과 사람의 영혼들이라',31006),
('rev-18-14','rev','요한계시록',18,14,'바벨론아 네 영혼이 탐하던 과일이 네게서 떠났으며 맛있는 것들과 빛난 것들이 다 없어졌으니 사람들이 결코 이것들을 다시 보지 못하리로다',31007),
('rev-18-15','rev','요한계시록',18,15,'바벨론으로 말미암아 치부한 이 상품의 상인들이 그의 고통을 무서워하여 멀리 서서 울고 애통하여',31008),
('rev-18-16','rev','요한계시록',18,16,'이르되 화 있도다 화 있도다 큰 성이여 세마포 옷과 자주 옷과 붉은 옷을 입고 금과 보석과 진주로 꾸민 것인데',31009),
('rev-18-17','rev','요한계시록',18,17,'그러한 부가 한 시간에 망하였도다 모든 선장과 각처를 다니는 선객들과 선원들과 바다에서 일하는 자들이 멀리 서서',31010),
('rev-18-18','rev','요한계시록',18,18,'그가 불타는 연기를 보고 외쳐 이르되 이 큰 성과 같은 성이 어디 있느냐 하며',31011),
('rev-18-19','rev','요한계시록',18,19,'티끌을 자기 머리에 뿌리고 울며 애통하여 외쳐 이르되 화 있도다 화 있도다 이 큰 성이여 바다에서 배 부리는 모든 자들이 너의 보배로운 상품으로 치부하였더니 한 시간에 망하였도다',31012),
('rev-18-20','rev','요한계시록',18,20,'하늘과 성도들과 사도들과 선지자들아, 그로 말미암아 즐거워하라 하나님이 너희를 위하여 그에게 심판을 행하셨음이라 하더라',31013),
('rev-18-21','rev','요한계시록',18,21,'이에 한 힘 센 천사가 큰 맷돌 같은 돌을 들어 바다에 던져 이르되 큰 성 바벨론이 이같이 비참하게 던져져 결코 다시 보이지 아니하리로다',31014),
('rev-18-22','rev','요한계시록',18,22,'또 거문고 타는 자와 풍류하는 자와 퉁소 부는 자와 나팔 부는 자들의 소리가 결코 다시 네 안에서 들리지 아니하고 어떠한 세공업자든지 결코 다시 네 안에서 보이지 아니하고 또 맷돌 소리가 결코 다시 네 안에서 들리지 아니하고',31015),
('rev-18-23','rev','요한계시록',18,23,'등불 빛이 결코 다시 네 안에서 비치지 아니하고 신랑과 신부의 음성이 결코 다시 네 안에서 들리지 아니하리로다 너의 상인들은 땅의 왕족들이라 네 복술로 말미암아 만국이 미혹되었도다',31016),
('rev-18-24','rev','요한계시록',18,24,'선지자들과 성도들과 및 땅 위에서 죽임을 당한 모든 자의 피가 그 성 중에서 발견되었느니라 하더라',31017),
('rev-19-1','rev','요한계시록',19,1,'이 일 후에 내가 들으니 하늘에 허다한 무리의 큰 음성 같은 것이 있어 이르되 할렐루야 구원과 영광과 능력이 우리 하나님께 있도다',31018),
('rev-19-2','rev','요한계시록',19,2,'그의 심판은 참되고 의로운지라 음행으로 땅을 더럽게 한 큰 음녀를 심판하사 자기 종들의 피를 그 음녀의 손에 갚으셨도다 하고',31019),
('rev-19-3','rev','요한계시록',19,3,'두 번째로 할렐루야 하니 그 연기가 세세토록 올라가더라',31020),
