('rev-19-5','rev','요한계시록',19,5,'보좌에서 음성이 나서 이르시되 하나님의 종들 곧 그를 경외하는 너희들아 작은 자나 큰 자나 다 우리 하나님께 찬송하라 하더라',31022),
('rev-19-6','rev','요한계시록',19,6,'또 내가 들으니 허다한 무리의 음성과도 같고 많은 물 소리와도 같고 큰 우렛소리와도 같은 소리로 이르되 할렐루야 주 우리 하나님 곧 전능하신 이가 통치하시도다',31023),
('rev-19-7','rev','요한계시록',19,7,'우리가 즐거워하고 크게 기뻐하며 그에게 영광을 돌리세 어린 양의 혼인 기약이 이르렀고 그의 아내가 자신을 준비하였으므로',31024),
('rev-19-8','rev','요한계시록',19,8,'그에게 빛나고 깨끗한 세마포 옷을 입도록 허락하셨으니 이 세마포 옷은 성도들의 옳은 행실이로다 하더라',31025),
('rev-19-9','rev','요한계시록',19,9,'천사가 내게 말하기를 기록하라 어린 양의 혼인 잔치에 청함을 받은 자들은 복이 있도다 하고 또 내게 말하되 이것은 하나님의 참되신 말씀이라 하기로',31026),
('rev-19-10','rev','요한계시록',19,10,'내가 그 발 앞에 엎드려 경배하려 하니 그가 나에게 말하기를 나는 너와 및 예수의 증언을 받은 네 형제들과 같이 된 종이니 삼가 그리하지 말고 오직 하나님께 경배하라 예수의 증언은 예언의 영이라 하더라',31027),
('rev-19-11','rev','요한계시록',19,11,'또 내가 하늘이 열린 것을 보니 보라 백마와 그것을 탄 자가 있으니 그 이름은 충신과 진실이라 그가 공의로 심판하며 싸우더라',31028),
('rev-19-12','rev','요한계시록',19,12,'그 눈은 불꽃 같고 그 머리에는 많은 관들이 있고 또 이름 쓴 것 하나가 있으니 자기밖에 아는 자가 없고',31029),
('rev-19-13','rev','요한계시록',19,13,'또 그가 피 뿌린 옷을 입었는데 그 이름은 하나님의 말씀이라 칭하더라',31030),
('rev-19-14','rev','요한계시록',19,14,'하늘에 있는 군대들이 희고 깨끗한 세마포 옷을 입고 백마를 타고 그를 따르더라',31031),
('rev-19-15','rev','요한계시록',19,15,'그의 입에서 예리한 검이 나오니 그것으로 만국을 치겠고 친히 그들을 철장으로 다스리며 또 친히 하나님 곧 전능하신 이의 맹렬한 진노의 포도주 틀을 밟겠고',31032),
('rev-19-16','rev','요한계시록',19,16,'그 옷과 그 다리에 이름을 쓴 것이 있으니 만왕의 왕이요 만주의 주라 하였더라',31033),
('rev-19-17','rev','요한계시록',19,17,'또 내가 보니 한 천사가 태양 안에 서서 공중에 나는 모든 새를 향하여 큰 음성으로 외쳐 이르되 와서 하나님의 큰 잔치에 모여',31034),
('rev-19-18','rev','요한계시록',19,18,'왕들의 살과 장군들의 살과 장사들의 살과 말들과 그것을 탄 자들의 살과 자유인들이나 종들이나 작은 자나 큰 자나 모든 자의 살을 먹으라 하더라',31035),
('rev-19-19','rev','요한계시록',19,19,'또 내가 보매 그 짐승과 땅의 임금들과 그들의 군대들이 모여 그 말 탄 자와 그의 군대와 더불어 전쟁을 일으키다가',31036),
('rev-19-20','rev','요한계시록',19,20,'짐승이 잡히고 그 앞에서 표적을 행하던 거짓 선지자도 함께 잡혔으니 이는 짐승의 표를 받고 그의 우상에게 경배하던 자들을 표적으로 미혹하던 자라 이 둘이 산 채로 유황불 붙는 못에 던져지고',31037),
