('rev-20-9','rev','요한계시록',20,9,'그들이 지면에 널리 퍼져 성도들의 진과 사랑하시는 성을 두르매 하늘에서 불이 내려와 그들을 태워버리고',31047),
('rev-20-10','rev','요한계시록',20,10,'또 그들을 미혹하는 마귀가 불과 유황 못에 던져지니 거기는 그 짐승과 거짓 선지자도 있어 세세토록 밤낮 괴로움을 받으리라',31048),
('rev-20-11','rev','요한계시록',20,11,'또 내가 크고 흰 보좌와 그 위에 앉으신 이를 보니 땅과 하늘이 그 앞에서 피하여 간 데 없더라',31049),
('rev-20-12','rev','요한계시록',20,12,'또 내가 보니 죽은 자들이 큰 자나 작은 자나 그 보좌 앞에 서 있는데 책들이 펴 있고 또 다른 책이 펴졌으니 곧 생명책이라 죽은 자들이 자기 행위를 따라 책들에 기록된 대로 심판을 받으니',31050),
('rev-20-13','rev','요한계시록',20,13,'바다가 그 가운데에서 죽은 자들을 내주고 또 사망과 음부도 그 가운데에서 죽은 자들을 내주매 각 사람이 자기의 행위대로 심판을 받고',31051),
('rev-20-14','rev','요한계시록',20,14,'사망과 음부도 불못에 던져지니 이것은 둘째 사망 곧 불못이라',31052),
('rev-20-15','rev','요한계시록',20,15,'누구든지 생명책에 기록되지 못한 자는 불못에 던져지더라',31053),
('rev-21-1','rev','요한계시록',21,1,'또 내가 새 하늘과 새 땅을 보니 처음 하늘과 처음 땅이 없어졌고 바다도 다시 있지 않더라',31054),
('rev-21-2','rev','요한계시록',21,2,'또 내가 보매 거룩한 성 새 예루살렘이 하나님께로부터 하늘에서 내려오니 그 준비한 것이 신부가 남편을 위하여 단장한 것 같더라',31055),
('rev-21-3','rev','요한계시록',21,3,'내가 들으니 보좌에서 큰 음성이 나서 이르되 보라 하나님의 장막이 사람들과 함께 있으매 하나님이 그들과 함께 계시리니 그들은 하나님의 백성이 되고 하나님은 친히 그들과 함께 계셔서',31056),
('rev-21-4','rev','요한계시록',21,4,'모든 눈물을 그 눈에서 닦아 주시니 다시는 사망이 없고 애통하는 것이나 곡하는 것이나 아픈 것이 다시 있지 아니하리니 처음 것들이 다 지나갔음이러라',31057),
('rev-21-5','rev','요한계시록',21,5,'보좌에 앉으신 이가 이르시되 보라 내가 만물을 새롭게 하노라 하시고 또 이르시되 이 말은 신실하고 참되니 기록하라 하시고',31058),
('rev-21-6','rev','요한계시록',21,6,'또 내게 말씀하시되 이루었도다 나는 알파와 오메가요 처음과 마지막이라 내가 생명수 샘물을 목마른 자에게 값없이 주리니',31059),
('rev-21-7','rev','요한계시록',21,7,'이기는 자는 이것들을 상속으로 받으리라 나는 그의 하나님이 되고 그는 내 아들이 되리라',31060),
('rev-21-8','rev','요한계시록',21,8,'그러나 두려워하는 자들과 믿지 아니하는 자들과 흉악한 자들과 살인자들과 음행하는 자들과 점술가들과 우상 숭배자들과 거짓말하는 모든 자들은 불과 유황으로 타는 못에 던져지리니 이것이 둘째 사망이라',31061),
('rev-21-9','rev','요한계시록',21,9,'일곱 대접을 가지고 마지막 일곱 재앙을 담은 일곱 천사 중 하나가 나아와서 내게 말하여 이르되 이리 오라 내가 신부 곧 어린 양의 아내를 네게 보이리라 하고',31062),
('rev-21-10','rev','요한계시록',21,10,'성령으로 나를 데리고 크고 높은 산으로 올라가 하나님께로부터 하늘에서 내려오는 거룩한 성 예루살렘을 보이니',31063),
('rev-21-11','rev','요한계시록',21,11,'하나님의 영광이 있어 그 성의 빛이 지극히 귀한 보석 같고 벽옥과 수정 같이 맑더라',31064),
('rev-21-12','rev','요한계시록',21,12,'크고 높은 성곽이 있고 열두 문이 있는데 문에 열두 천사가 있고 그 문들 위에 이름을 썼으니 이스라엘 자손 열두 지파의 이름들이라',31065),
('rev-21-13','rev','요한계시록',21,13,'동쪽에 세 문, 북쪽에 세 문, 남쪽에 세 문, 서쪽에 세 문이니',31066),
('rev-21-14','rev','요한계시록',21,14,'그 성의 성곽에는 열두 기초석이 있고 그 위에는 어린 양의 열두 사도의 열두 이름이 있더라',31067),
('rev-21-15','rev','요한계시록',21,15,'내게 말하는 자가 그 성과 그 문들과 성곽을 측량하려고 금 갈대 자를 가졌더라',31068),
('rev-21-16','rev','요한계시록',21,16,'그 성은 네모가 반듯하여 길이와 너비가 같은지라 그 갈대 자로 그 성을 측량하니 만 이천 스다디온이요 길이와 너비와 높이가 같더라',31069),
('rev-21-17','rev','요한계시록',21,17,'그 성곽을 측량하매 백사십사 규빗이니 사람의 측량 곧 천사의 측량이라',31070),
('rev-21-18','rev','요한계시록',21,18,'그 성곽은 벽옥으로 쌓였고 그 성은 정금인데 맑은 유리 같더라',31071),
('rev-21-19','rev','요한계시록',21,19,'그 성의 성곽의 기초석은 각색 보석으로 꾸몄는데 첫째 기초석은 벽옥이요 둘째는 남보석이요 셋째는 옥수요 넷째는 녹보석이요',31072),
('rev-21-20','rev','요한계시록',21,20,'다섯째는 홍마노요 여섯째는 홍보석이요 일곱째는 황옥이요 여덟째는 녹옥이요 아홉째는 담황옥이요 열째는 비취옥이요 열한째는 청옥이요 열두째는 자수정이라',31073),
('rev-21-21','rev','요한계시록',21,21,'그 열두 문은 열두 진주니 각 문마다 한 개의 진주로 되어 있고 성의 길은 맑은 유리 같은 정금이더라',31074),
('rev-21-22','rev','요한계시록',21,22,'성 안에서 내가 성전을 보지 못하였으니 이는 주 하나님 곧 전능하신 이와 및 어린 양이 그 성전이심이라',31075),
